INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要三工程图。", "corrected_sentence": "我们需要三张工程图。", "error_description": "量词漏掉了。数词“三”不能直接修饰“工程图”，中间要加量词“张”，说「三张工程图」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
