INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看着字，用嘴读出来。", "primary_collocate": null, "pronunciation": "niàn", "ipa": "njɛn˥˩", "syllable_count": 1, "sentences": [{"text": "老师让我们念课文。", "target_word": "念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你念一下这个字。", "target_word": "念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字怎么念？", "target_word": "念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不会念这个词，我来教他。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明看着黑板念生字。", "target_word": "念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每天早上大声念十分钟英语单词。", "target_word": "念", "complexity_tier": "T3", "furigana": "wǒ měi tiān zǎo shang dà shēng niàn shí fēn zhōng yīng yǔ dān cí.", "sentence_source": "generated"}, {"text": "她念错了一个字，大家都笑了。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先念一遍，你再跟我念。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着书，一个字一个字地念。", "target_word": "念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字太难了，我不会念。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "念了", "label": "完成体"}, {"form": "念过", "label": "经历体"}, {"form": "念着", "label": "持续体"}, {"form": "念念", "label": "重叠"}], "register": "中性", "sense_fingerprint": "念：看着文字，用嘴把字音读出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "念", "is_correct": true, "explanation": "念（niàn）：看着文字，用嘴把字音读出来，是目标词。"}, {"text": "年", "is_correct": false, "explanation": "nián（第二声）与 niàn（第四声）声调不同，意思是年份。"}, {"text": "恋", "is_correct": false, "explanation": "liàn 与 niàn 声母不同（l 与 n），意思是恋爱。"}, {"text": "碾", "is_correct": false, "explanation": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用碾子把东西压碎。"}, {"text": "酿", "is_correct": false, "explanation": "niàng 与 niàn 韵母不同（iang 与 ian），意思是用粮食发酵做酒。"}], "explanations": {"念": "念（niàn）：看着文字，用嘴把字音读出来，是目标词。", "年": "nián（第二声）与 niàn（第四声）声调不同，意思是年份。", "恋": "liàn 与 niàn 声母不同（l 与 n），意思是恋爱。", "碾": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用碾子把东西压碎。", "酿": "niàng 与 niàn 韵母不同（iang 与 ian），意思是用粮食发酵做酒。"}, "sentence_index": null, "correct_answer": "念"}, "level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "念：看着课文把字音读出来，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只用于歌曲，课文不能唱，句子不通。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指把衣物穿在身上，课文不能穿，句意不通。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能带“课文”作宾语，句子不成立。"}], "explanations": {"念": "念：看着课文把字音读出来，符合句意。", "唱": "搭配：“唱”只用于歌曲，课文不能唱，句子不通。", "穿": "语义：“穿”指把衣物穿在身上，课文不能穿，句意不通。", "跳": "搭配：“跳”不能带“课文”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在舞台上念了一首流行歌。", "explanation": "这里应该用〈唱〉。流行歌是唱的，“念”只表示把文字读出声，不说“念歌”。"}, {"text": "我每天晚上念电影到十二点。", "explanation": "这里应该用〈看〉。电影是看的，“念”只表示照着文字出声读，不能指看电影。"}, {"text": "我每天回家先念饺子，再吃饭。", "explanation": "这里应该用〈包〉。饺子是包的，“念”不表示做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89881, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "念", "is_correct": true, "explanation": "念（niàn）：看着文字，用嘴把字音读出来，是目标词。"}, {"text": "黏", "is_correct": false, "explanation": "nián（第二声）与 niàn（第四声）声调不同，意思是黏住、有黏性。"}, {"text": "蔫", "is_correct": false, "explanation": "niān（第一声）与 niàn（第四声）声调不同，意思是植物枯萎、没有精神。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 niàn 声母不同（l 与 n），意思是练习。"}, {"text": "捻", "is_correct": false, "explanation": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用手指搓转。"}], "explanations": {"念": "念（niàn）：看着文字，用嘴把字音读出来，是目标词。", "黏": "nián（第二声）与 niàn（第四声）声调不同，意思是黏住、有黏性。", "蔫": "niān（第一声）与 niàn（第四声）声调不同，意思是植物枯萎、没有精神。", "练": "liàn 与 niàn 声母不同（l 与 n），意思是练习。", "捻": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用手指搓转。"}, "sentence_index": null, "correct_answer": "念"}, "level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "念：看着字把读音读出来，读错了字音，符合句意。"}, {"text": "做", "is_correct": false, "explanation": "搭配：“做错”一般搭配事情、题目，不说“做错了一个字”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是用刀把东西分开，不能用来指读字出错。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，字不能吃，句子不通。"}], "explanations": {"念": "念：看着字把读音读出来，读错了字音，符合句意。", "做": "搭配：“做错”一般搭配事情、题目，不说“做错了一个字”。", "切": "语义：“切”是用刀把东西分开，不能用来指读字出错。", "吃": "语义：“吃”指进食，字不能吃，句子不通。"}, "sentence_index": 6, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈耐心地给我念了一碗面。", "explanation": "这里应该用〈煮〉。面是煮的，“念”没有做饭的意思。"}, {"text": "奶奶总是念着一把伞出门。", "explanation": "这里应该用〈带〉。伞是带的，“念”不表示手里带着东西。"}, {"text": "他昨晚念了一个奇怪的梦。", "explanation": "这里应该用〈做〉。梦是做的，不说“念梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他念了完课文，就去睡觉了。", "corrected_sentence": "他念完了课文，就去睡觉了。", "error_description": "错误形式：“念了完”（补语“完”插在“了”后面）；正确形式：“念完了”。结果补语“完”必须紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个字他对念了。", "corrected_sentence": "这个字他念对了。", "error_description": "错误形式：“对念了”；正确形式：“念对了”。结果补语“对”必须放在动词“念”的后面，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
