INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "诵读；出声地读。", "primary_collocate": null, "pronunciation": "niàn", "ipa": "njɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他站起来念了一首诗。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天晚上给我念故事。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这封信念给大家听。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上念了一份通知。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，我念报纸给她听。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师念了一段课文，同学们认真听。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿起稿子，大声念了起来。", "target_word": "念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上，新郎念了一封信。", "target_word": "念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸坐在床边，轻声念着一本书。", "target_word": "念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把写好的话念给朋友听。", "target_word": "念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "念了", "label": "完成体"}, {"form": "念过", "label": "经历体"}, {"form": "念着", "label": "持续体"}, {"form": "念念", "label": "重叠"}], "register": "中性", "sense_fingerprint": "念：把诗、信、文章等出声地诵读，常读给别人听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "念", "is_correct": true, "explanation": "念：把诗、信、文章等出声地诵读，常读给别人听，是目标词。"}, {"text": "碾", "is_correct": false, "explanation": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用碾子压碎。"}, {"text": "酿", "is_correct": false, "explanation": "niàng 与 niàn 韵母不同（iang 与 ian），意思是用粮食发酵做酒。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 niàn 声母不同（l 与 n），意思是练习。"}], "explanations": {"念": "念：把诗、信、文章等出声地诵读，常读给别人听，是目标词。", "碾": "niǎn（第三声）与 niàn（第四声）声调不同，意思是用碾子压碎。", "酿": "niàng 与 niàn 韵母不同（iang 与 ian），意思是用粮食发酵做酒。", "练": "liàn 与 niàn 声母不同（l 与 n），意思是练习。"}, "sentence_index": null, "correct_answer": "念"}, "level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "念：出声地诵读一首诗，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，诗不能吃，句子不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”只搭配首饰、帽子等，不能与“诗”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、器具等，不说“洗一首诗”。"}], "explanations": {"念": "念：出声地诵读一首诗，符合句意。", "吃": "语义：“吃”指进食，诗不能吃，句子不通。", "戴": "搭配：“戴”只搭配首饰、帽子等，不能与“诗”搭配。", "洗": "搭配：“洗”的对象是衣物、器具等，不说“洗一首诗”。"}, "sentence_index": 0, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在晚会上念了一首情歌。", "explanation": "这里应该用〈唱〉。情歌要唱，“念”指照着文字出声读，不说“念情歌”。"}, {"text": "他在茶馆里念了一幅画。", "explanation": "这里应该用〈看〉。画是看的，“念”指照着文字出声读，不说“念画”。"}, {"text": "他在北京念了一个电话，每天很忙。", "explanation": "这里应该用〈打〉。打电话要用“打”，“念”不能表示打电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "念", "is_correct": true, "explanation": "念：出声地诵读，常读给别人听，是目标词。"}, {"text": "年", "is_correct": false, "explanation": "nián（第二声）与 niàn（第四声）声调不同，意思是年份。"}, {"text": "恋", "is_correct": false, "explanation": "liàn 与 niàn 声母不同（l 与 n），意思是恋爱。"}, {"text": "蔫", "is_correct": false, "explanation": "niān（第一声）与 niàn（第四声）声调不同，意思是植物枯萎。"}], "explanations": {"念": "念：出声地诵读，常读给别人听，是目标词。", "年": "nián（第二声）与 niàn（第四声）声调不同，意思是年份。", "恋": "liàn 与 niàn 声母不同（l 与 n），意思是恋爱。", "蔫": "niān（第一声）与 niàn（第四声）声调不同，意思是植物枯萎。"}, "sentence_index": null, "correct_answer": "念"}, "level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "念：大声把稿子上的字读出来，符合句意。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是用刀分开东西，不能用来指读稿子的动作。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理、修改，与“大声”的动作不相符，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，“稿子”不能煮，句子不成立。"}], "explanations": {"念": "念：大声把稿子上的字读出来，符合句意。", "切": "语义：“切”是用刀分开东西，不能用来指读稿子的动作。", "修": "语义：“修”指修理、修改，与“大声”的动作不相符，句子不通。", "煮": "搭配：“煮”的对象是食物，“稿子”不能煮，句子不成立。"}, "sentence_index": 6, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈耐心地给我念了一件毛衣。", "explanation": "这里应该用〈织〉。毛衣是织的，“念”不表示编织。"}, {"text": "奶奶总是念着一篮水果出门。", "explanation": "这里应该用〈提〉。篮子是提的，“念”不表示手里拿着东西。"}, {"text": "他昨晚念了一个奇怪的梦。", "explanation": "这里应该用〈做〉。梦是做的，不说“念梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这首诗念对孩子们听。", "corrected_sentence": "他把这首诗念给孩子们听。", "error_description": "错误形式：“念对孩子们听”；正确形式：“念给孩子们听”。表示读给某人听，要用介词“给”，不能用“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一口气把信完念了。", "corrected_sentence": "他一口气把信念完了。", "error_description": "错误形式：“完念了”；正确形式：“念完了”。结果补语“完”必须放在动词“念”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
