INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "资格是能做某件事要有的条件。", "primary_collocate": null, "pronunciation": "zī gé", "ipa": "tsɿ˥˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他有资格参加这次比赛。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没有资格这样说他。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要当老师，先得有教师资格。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为迟到，失去了考试的资格。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "满十八岁才有资格开车。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店还没有资格卖酒。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩不好，没有资格拿奖学金。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想取得比赛资格，你得先赢三场。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有学生才有资格进这个图书馆。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队拿到了参加决赛的资格。", "target_word": "资格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資格", "label": "繁体"}, {"form": "资格证", "label": "复合"}, {"form": "资格赛", "label": "复合"}, {"form": "资格考试", "label": "复合"}], "register": "中性", "sense_fingerprint": "做某件事必须具备的条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资格", "is_correct": true, "explanation": "正确：“有资格参加”指具备参赛的条件，与句意相符。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表不是人或队伍，不能作为“参加比赛”的主体，“他有手表参加比赛”不成立。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：体型只是外形特征，不是参赛的条件，不能说“有体型参加比赛”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与能否参加比赛无关，“有颜色参加比赛”不通。"}], "explanations": {"资格": "正确：“有资格参加”指具备参赛的条件，与句意相符。", "手表": "语义：手表不是人或队伍，不能作为“参加比赛”的主体，“他有手表参加比赛”不成立。", "体型": "体貌：体型只是外形特征，不是参赛的条件，不能说“有体型参加比赛”。", "颜色": "语义：颜色与能否参加比赛无关，“有颜色参加比赛”不通。"}, "sentence_index": 0, "correct_answer": "资格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的资格很便宜。", "explanation": "这里应该用〈价格〉。两词都带“格”，但“资格”指条件，不指价钱；“这件衣服的价格很便宜”才自然。"}, {"text": "他的资格太胖了，这条裤子穿不下。", "explanation": "这里应该用〈身材〉。“资格”指做某事要有的条件，不能用“胖”来形容；“他的身材太胖了”才自然。"}, {"text": "他的资格很执着，从不放弃。", "explanation": "这里应该用〈态度〉。“资格”不能用来形容执着；“他的态度很执着”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资格", "is_correct": true, "explanation": "正确：“没有资格拿奖学金”说明不具备获奖的条件，与句中成绩不好的语境相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形特征，与能否拿奖学金无关，不能说“没有身材拿奖学金”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，和奖学金的获得无关，这样说不通。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量与奖学金的获得无关，句子讲的是成绩，这样说不通。"}], "explanations": {"资格": "正确：“没有资格拿奖学金”说明不具备获奖的条件，与句中成绩不好的语境相符。", "身材": "体貌：身材是外形特征，与能否拿奖学金无关，不能说“没有身材拿奖学金”。", "钢笔": "语义：钢笔是书写工具，和奖学金的获得无关，这样说不通。", "饭量": "语义：饭量与奖学金的获得无关，句子讲的是成绩，这样说不通。"}, "sentence_index": 6, "correct_answer": "资格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位队员的资格很快乐。", "explanation": "这里应该用〈心情〉。“资格”指条件，不能用来形容情绪；“这位队员的心情很快乐”才自然。"}, {"text": "我们队吃掉了参加决赛的资格。", "explanation": "这里应该用〈拿到〉。“吃掉”不能与“资格”搭配；“我们队拿到了参加决赛的资格”才自然。"}, {"text": "教练在比赛中发挥了很大的资格。", "explanation": "这里应该用〈作用〉。“发挥……的作用”是固定搭配；资格指条件或身份，不能被发挥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是资格参加决赛。", "corrected_sentence": "他有资格参加决赛。", "error_description": "错误：动词用错。“资格”前应用“有”，说“有资格”表示具备参加的条件；“是”不能直接接“资格”。正确说法：他有资格参加决赛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队拿到了一只参加决赛的资格。", "corrected_sentence": "我们队拿到了一项参加决赛的资格。", "error_description": "错误：量词用错。“资格”前应用“项”（或“个”），“只”用于动物或成对的东西，不能用于“资格”。正确说法：一项参加决赛的资格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
