INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "常态是平常的样子，每天都这样。", "primary_collocate": null, "pronunciation": "cháng tài", "ipa": "tʂʰɑŋ˧˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "早起跑步是我的常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家吃饭晚是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，忙是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们吵闹是常态，我已经习惯了。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天十二点睡觉，成了他的常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末睡懒觉是我的生活常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每天都很热闹，这是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加班对他来说是常态，不是例外。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天做饭，这是家里的常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天八点到公司，这已经成了常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "平常的样子，每天都这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常态", "is_correct": true, "explanation": "正确。常态指平常的样子、每天都这样，早起跑步是我每天的样子。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“早起跑步”不是午饭，两者不能等同。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物件，“早起跑步”是动作，不能构成“是我的……”的判断。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物件，“早起跑步”是动作，不能构成“是我的……”的判断。"}], "explanations": {"常态": "正确。常态指平常的样子、每天都这样，早起跑步是我每天的样子。", "午饭": "语义：“早起跑步”不是午饭，两者不能等同。", "雨伞": "语义：“雨伞”是物件，“早起跑步”是动作，不能构成“是我的……”的判断。", "黑板": "语义：“黑板”是物件，“早起跑步”是动作，不能构成“是我的……”的判断。"}, "sentence_index": 0, "correct_answer": "常态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们突然吵成一片，这是一种常态，我很害怕。", "explanation": "这里应该用〈反常〉。常态指每天都这样的平常样子，突然吵成一片属于反常，不能说常态。"}, {"text": "孩子们只吵闹了一次，这是常态。", "explanation": "这里应该用〈偶然〉。常态指每天都这样，只发生一次的吵闹属于偶然，不能说常态。"}, {"text": "这次相遇是常态，我们都很惊讶。", "explanation": "这里应该用〈偶然〉。常态指经常的情形，不常见的相遇要用偶然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常态", "is_correct": true, "explanation": "正确。这里每天都很热闹，这是常态，指这种情形一般如此。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆一般安静，与“每天都很热闹”冲突。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠荒凉，与“热闹”冲突。"}, {"text": "墓地", "is_correct": false, "explanation": "搭配：“热闹”描写人声和场面，“墓地”不能作“这是……”的判断词，与句意冲突。"}], "explanations": {"常态": "正确。这里每天都很热闹，这是常态，指这种情形一般如此。", "图书馆": "语义：图书馆一般安静，与“每天都很热闹”冲突。", "沙漠": "语义：沙漠荒凉，与“热闹”冲突。", "墓地": "搭配：“热闹”描写人声和场面，“墓地”不能作“这是……”的判断词，与句意冲突。"}, "sentence_index": 6, "correct_answer": "常态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他第一次八点到公司，这已经成了他的常态。", "explanation": "这里应该用〈例外〉。常态指经常如此的情形，只发生一次的事不能称常态。"}, {"text": "这次八点到公司纯属意外，却成了他的常态。", "explanation": "这里应该用〈意外〉。常态指经常的情形，“意外”的事不能称常态。"}, {"text": "这次吵闹很少见，却已经是常态。", "explanation": "这里应该用〈个例〉。常态指每天都这样，很少见的吵闹只是个例，不能称常态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末晚起已经成了她常态。", "corrected_sentence": "周末晚起已经成了她的常态。", "error_description": "“她”与“常态”之间漏了“的”。名词前有修饰语时要加“的”，应说“她的常态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这已经成了我们得常态。", "corrected_sentence": "这已经成了我们的常态。", "error_description": "结构助词用错。名词“常态”前的定语要用“的”，不能用“得”，应说“我们的常态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
