INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "正常的状态，一般的情形。", "primary_collocate": null, "pronunciation": "cháng tài", "ipa": "tʂʰɑŋ˧˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "加班在这家公司是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天堵车已经成了常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里春天多雨是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天的样子，不是常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好以后，一切都恢复了常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的心跳已经回到常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种变化不是常态，只是偶然。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小城里，慢生活是一种常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连着三天下雨，在这个季节已经不算常态了。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西，已经是生活的常态。", "target_word": "常态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "正常的状态，一般的情形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常态", "is_correct": true, "explanation": "正确。常态指正常的状态或一般的情形，加班在这家公司就是这样。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是喜庆的日子，加班不能与之等同。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期是休息的时间，与“加班”正相反。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“是”后接的词要能与“加班”构成判断，“食堂”是场所，不能这样构成判断。"}], "explanations": {"常态": "正确。常态指正常的状态或一般的情形，加班在这家公司就是这样。", "节日": "语义：节日是喜庆的日子，加班不能与之等同。", "假期": "语义：假期是休息的时间，与“加班”正相反。", "食堂": "搭配：“是”后接的词要能与“加班”构成判断，“食堂”是场所，不能这样构成判断。"}, "sentence_index": 0, "correct_answer": "常态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大雨来得很突然，是一种常态。", "explanation": "这里应该用〈意外〉。常态指经常的情形，突然来的大雨属于意外，不能称常态。"}, {"text": "他第一次这样说话，是一种常态。", "explanation": "这里应该用〈个例〉。常态指经常的情形，第一次这样只是个例，不能称常态。"}, {"text": "心跳出现了常态，需要马上治疗。", "explanation": "这里应该用〈异常〉。常态指正常的情形，心跳出现问题应说异常，不能说常态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常态", "is_correct": true, "explanation": "正确。这种变化不是常态，只是偶然，“常态”指正常的情形。"}, {"text": "人物", "is_correct": false, "explanation": "语义：“这种变化”是变化，不是人，与“人物”的判断冲突。"}, {"text": "动物", "is_correct": false, "explanation": "语义：变化不是动物，与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”是事物的属性，不能与“变化”构成“不是……”的判断。"}], "explanations": {"常态": "正确。这种变化不是常态，只是偶然，“常态”指正常的情形。", "人物": "语义：“这种变化”是变化，不是人，与“人物”的判断冲突。", "动物": "语义：变化不是动物，与句意不符。", "颜色": "搭配：“颜色”是事物的属性，不能与“变化”构成“不是……”的判断。"}, "sentence_index": 6, "correct_answer": "常态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一次停电，已经是生活的常态。", "explanation": "这里应该用〈例外〉。常态指经常的情形，偶尔发生的停电不能说常态。"}, {"text": "这次纯属偶然的降价，已经成了网上购物的常态。", "explanation": "这里应该用〈偶然现象〉。常态指经常的情形，“纯属偶然”的降价不能称常态。"}, {"text": "他第一次去外地出差，这已经成了生活的常态。", "explanation": "这里应该用〈例外〉。常态指经常如此的情形，第一次出差只是例外，不能称常态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熬夜是他常态。", "corrected_sentence": "熬夜是他的常态。", "error_description": "“他”与“常态”之间漏了“的”。名词前有修饰语时要加“的”，应说“他的常态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一切终于回在了常态。", "corrected_sentence": "一切终于回到了常态。", "error_description": "介词用错。“回到”表示回归某种状态，应用“到”，不能用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
