INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89888, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "（方言）整天；终日。", "primary_collocate": null, "pronunciation": "chéng rì", "ipa": "ʈʂʰɤŋ˧˥ ʐɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你成日加班，身体会受不了的。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成日不见人，不知道在忙什么。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿明成日请假，同事都不高兴了。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈成日叫我早点睡觉。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的狗成日叫，吵得我睡不着。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要成日看电视，去外面走走吧。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成日说想去旅行，可是一直没去。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成日喝茶聊天，什么事也不做。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟成日玩游戏，成绩下降了。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆成日坐在门口等我回家。", "target_word": "成日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "方言", "sense_fingerprint": "方言词，整天、终日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb81bd1-7443-4fba-9b2e-42070bd1a607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成日", "is_correct": true, "explanation": "正确答案：成日 chéng rì，整天、终日。"}, {"text": "城市", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是城市。"}, {"text": "成立", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），意思是成立。"}, {"text": "诚实", "is_correct": false, "explanation": "shí（第二声）与 rì（第四声）声母和声调都不同，意思是诚实。"}, {"text": "乘机", "is_correct": false, "explanation": "jī（第一声）与 rì（第四声）声母和声调都不同，意思是乘机。"}], "explanations": {"成日": "正确答案：成日 chéng rì，整天、终日。", "城市": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是城市。", "成立": "lì 与 rì 声母不同（l 与 r），意思是成立。", "诚实": "shí（第二声）与 rì（第四声）声母和声调都不同，意思是诚实。", "乘机": "jī（第一声）与 rì（第四声）声母和声调都不同，意思是乘机。"}, "sentence_index": null, "correct_answer": "成日"}, "level_3": {"options": [{"text": "成日", "is_correct": true, "explanation": "成日：整天、终日都这样，与“身体会受不了”所说的长期劳累相合。"}, {"text": "很", "is_correct": false, "explanation": "词性：“很”一般修饰形容词，不直接修饰“加班”这类动作动词，句子不通。"}, {"text": "马上", "is_correct": false, "explanation": "语义：马上指即将发生，句子说的是经常性的加班，意思不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻指紧接着发生，与“身体会受不了”的长期影响矛盾。"}], "explanations": {"成日": "成日：整天、终日都这样，与“身体会受不了”所说的长期劳累相合。", "很": "词性：“很”一般修饰形容词，不直接修饰“加班”这类动作动词，句子不通。", "马上": "语义：马上指即将发生，句子说的是经常性的加班，意思不合。", "立刻": "语义：立刻指紧接着发生，与“身体会受不了”的长期影响矛盾。"}, "sentence_index": 0, "correct_answer": "成日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们成日一起吃了一顿午饭。", "explanation": "这里误把〈成日〉当作〈一次〉。“成日”指整天、终日不断，不能修饰只发生一次的“吃了一顿午饭”。"}, {"text": "他偶尔成日去跑步。", "explanation": "“偶尔”表示次数很少，“成日”表示整天、终日都这样，两者语义矛盾，不能同用。"}, {"text": "我成日睡了一小时的觉。", "explanation": "这里误把〈成日〉当作〈很久〉。“成日”指整天、终日，不能修饰“一小时”这样的短时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89888, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成日", "is_correct": true, "explanation": "正确答案：成日 chéng rì，整天、终日。"}, {"text": "成事", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是成事。"}, {"text": "生日", "is_correct": false, "explanation": "shēng（第一声）与 chéng（第二声）声母和声调都不同，意思是生日。"}, {"text": "成绩", "is_correct": false, "explanation": "jì 与 rì 声母不同（j 与 r），意思是成绩。"}, {"text": "城里", "is_correct": false, "explanation": "lǐ（第三声）与 rì（第四声）声母和声调都不同，意思是城里。"}], "explanations": {"成日": "正确答案：成日 chéng rì，整天、终日。", "成事": "shì 与 rì 声母不同（sh 与 r），声调相同，意思是成事。", "生日": "shēng（第一声）与 chéng（第二声）声母和声调都不同，意思是生日。", "成绩": "jì 与 rì 声母不同（j 与 r），意思是成绩。", "城里": "lǐ（第三声）与 rì（第四声）声母和声调都不同，意思是城里。"}, "sentence_index": null, "correct_answer": "成日"}, "level_3": {"options": [{"text": "成日", "is_correct": true, "explanation": "成日：整天、终日都这样，与“说想去旅行，可是一直没去”所说的习惯相合。"}, {"text": "很", "is_correct": false, "explanation": "词性：“很”一般修饰形容词，不直接修饰“说”，句子不通。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是程度副词，修饰形容词，不能直接修饰动词“说”，句子不通。"}, {"text": "太", "is_correct": false, "explanation": "词性：“太”是程度副词，一般修饰形容词，不能直接修饰“说”，句子不通。"}], "explanations": {"成日": "成日：整天、终日都这样，与“说想去旅行，可是一直没去”所说的习惯相合。", "很": "词性：“很”一般修饰形容词，不直接修饰“说”，句子不通。", "非常": "词性：“非常”是程度副词，修饰形容词，不能直接修饰动词“说”，句子不通。", "太": "词性：“太”是程度副词，一般修饰形容词，不能直接修饰“说”，句子不通。"}, "sentence_index": 6, "correct_answer": "成日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "表哥成日来过我家一次。", "explanation": "这里误把〈成日〉当作〈偶然〉。“成日”指整天、终日不断，不能与只发生一次的“来过一次”搭配。"}, {"text": "我成日头一回去了长城。", "explanation": "这里误把〈成日〉当作〈首次〉。“成日”指整天、终日不断，不能修饰只发生一次的“头一回去了长城”。"}, {"text": "他成日在六月毕业。", "explanation": "“毕业”是只发生一次的事，不能用表示整天、终日都这样的“成日”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "堂弟成日的在网吧打游戏。", "corrected_sentence": "堂弟成日在网吧打游戏。", "error_description": "“成日”是副词，后面不能加“的”。应说“堂弟成日在网吧打游戏”，去掉“成日”后多出的“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舅舅很成日在院子里浇花，很开心。", "corrected_sentence": "舅舅成日在院子里浇花，很开心。", "error_description": "“很”不能修饰副词“成日”，应删去“很”，写作“舅舅成日在院子里浇花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b32cf57d-1d96-4f3a-9fe1-d98bd81906a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
