INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89889, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超级是比一般的更厉害,更大。", "primary_collocate": null, "pronunciation": "chāo jí", "ipa": "tʂʰaʊ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这家商店超级大。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的月亮超级大。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个西瓜超级甜。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有超级好的记忆力。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影超级好看。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的雨超级大。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间超级干净。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得超级快。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有一个超级聪明的孩子。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路超级长。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超級", "label": "繁体"}], "register": "口语", "sense_fingerprint": "超级:比一般的更厉害更大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6007777f-108d-4907-92d2-9664a290c7b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超级", "is_correct": true, "explanation": "“超级”作程度副词修饰“大”，说明商店比一般的大得多，句子通顺。"}, {"text": "微", "is_correct": false, "explanation": "搭配：「微」多修饰「小、弱」等，不说「微大」。"}, {"text": "曾", "is_correct": false, "explanation": "语义：「曾」表示过去的经历，不能直接修饰形容词，「这家商店曾大」不通。"}, {"text": "忽", "is_correct": false, "explanation": "语义：「忽」表示突然，不表示程度，「这家商店忽大」语义不通。"}], "explanations": {"超级": "“超级”作程度副词修饰“大”，说明商店比一般的大得多，句子通顺。", "微": "搭配：「微」多修饰「小、弱」等，不说「微大」。", "曾": "语义：「曾」表示过去的经历，不能直接修饰形容词，「这家商店曾大」不通。", "忽": "语义：「忽」表示突然，不表示程度，「这家商店忽大」语义不通。"}, "sentence_index": 0, "correct_answer": "超级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛超级结束了。", "explanation": "「超级」表示程度很高，不能修饰「结束」这样一次性完成、没有程度差别的动作，这个用法不成立。"}, {"text": "这两个数字超级相等。", "explanation": "「相等」表示两者完全一样，没有程度差别，不能受「超级」这样表示程度很高的副词修饰。"}, {"text": "她超级结婚了。", "explanation": "「超级」表示程度很高，不能修饰「结婚」这样的一次性动作，句子语义不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猛", "is_correct": false, "explanation": "搭配：「猛」多修饰动作，表示用力或突然，「这个房间猛干净」不自然。"}, {"text": "超级", "is_correct": true, "explanation": "“超级”作程度副词修饰“干净”，表示房间非常干净，句子通顺。"}, {"text": "并", "is_correct": false, "explanation": "搭配：「并」一般与「不」连用，如「并不干净」，不能直接修饰形容词。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，句中没有对比的内容，「这个房间却干净」语义不通。"}], "explanations": {"猛": "搭配：「猛」多修饰动作，表示用力或突然，「这个房间猛干净」不自然。", "超级": "“超级”作程度副词修饰“干净”，表示房间非常干净，句子通顺。", "并": "搭配：「并」一般与「不」连用，如「并不干净」，不能直接修饰形容词。", "却": "语义：「却」表示转折，句中没有对比的内容，「这个房间却干净」语义不通。"}, "sentence_index": 6, "correct_answer": "超级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他超级离开了学校。", "explanation": "「超级」表示程度很高，不能修饰「离开」这样一次性的动作，句子语义不成立。"}, {"text": "这场雨超级停了。", "explanation": "「超级」表示程度很高，不能修饰「停」这种有无之分的变化，句子不通。"}, {"text": "这条路超级比较长。", "explanation": "「超级」表示程度极高，而“相对而言”的比较修饰与之叠加，语义冲突，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
