INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆车最超级贵。", "corrected_sentence": "那辆车超级贵。", "error_description": "错误形式：「最超级贵」；正确形式：「超级贵」。「超级」本身已表示程度很高，前面不能再加「最」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
