INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89890, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超出一般的;程度非常高的。", "primary_collocate": null, "pronunciation": "chāo jí", "ipa": "tʂʰaʊ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "今天的天气超级热。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜超级好吃。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天超级高兴。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题超级难。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近超级忙。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子超级可爱。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋子超级便宜。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里的人超级多。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得超级好。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对我们超级好。", "target_word": "超级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超級", "label": "繁体"}], "register": "口语", "sense_fingerprint": "超级:超出一般,程度非常高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6007777f-108d-4907-92d2-9664a290c7b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曾", "is_correct": false, "explanation": "语义：「曾」表示过去的经历，不直接修饰形容词，「今天的天气曾热」不通。"}, {"text": "并", "is_correct": false, "explanation": "搭配：「并」须与「不」连用，不能直接修饰形容词，「今天的天气并热」不通。"}, {"text": "超级", "is_correct": true, "explanation": "“超级”作程度副词修饰“热”，表示天气非常热，句子通顺。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，句中没有对比的内容，「今天的天气却热」语义不通。"}], "explanations": {"曾": "语义：「曾」表示过去的经历，不直接修饰形容词，「今天的天气曾热」不通。", "并": "搭配：「并」须与「不」连用，不能直接修饰形容词，「今天的天气并热」不通。", "超级": "“超级”作程度副词修饰“热”，表示天气非常热，句子通顺。", "却": "语义：「却」表示转折，句中没有对比的内容，「今天的天气却热」语义不通。"}, "sentence_index": 0, "correct_answer": "超级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天超级出发。", "explanation": "「超级」表示程度很高，不能修饰「出发」这样一次性的动作。"}, {"text": "这两份报告的字数超级相同。", "explanation": "「相同」表示完全一样，没有程度差别，「超级」表示程度很高，两者搭配不当。"}, {"text": "我超级睡着了。", "explanation": "「超级」表示程度很高，不能修饰「睡着」这种有无之分的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猛", "is_correct": false, "explanation": "搭配：「猛」多修饰动作，表示用力或突然，「这双鞋子猛便宜」不自然。"}, {"text": "忽", "is_correct": false, "explanation": "语义：「忽」表示突然，不表示程度，「这双鞋子忽便宜」语义不通。"}, {"text": "超级", "is_correct": true, "explanation": "“超级”作程度副词修饰“便宜”，表示非常便宜，句子通顺。"}, {"text": "微", "is_correct": false, "explanation": "搭配：「微」多修饰「小、弱」等，不说「微便宜」。"}], "explanations": {"猛": "搭配：「猛」多修饰动作，表示用力或突然，「这双鞋子猛便宜」不自然。", "忽": "语义：「忽」表示突然，不表示程度，「这双鞋子忽便宜」语义不通。", "超级": "“超级”作程度副词修饰“便宜”，表示非常便宜，句子通顺。", "微": "搭配：「微」多修饰「小、弱」等，不说「微便宜」。"}, "sentence_index": 6, "correct_answer": "超级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书超级出版了。", "explanation": "「超级」表示程度很高，不能修饰「出版」这样一次性的动作，句子语义不通。"}, {"text": "这个房间超级存在。", "explanation": "「超级」表示程度很高，不能修饰「存在」这样非程度性的状态。"}, {"text": "老师对我们比较超级好。", "explanation": "「超级」表示程度极高，而“相对而言”的比较修饰与之叠加，语义冲突，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市最超级热闹。", "corrected_sentence": "这座城市超级热闹。", "error_description": "错误形式：「最超级热闹」；正确形式：「超级热闹」。「超级」已表示程度很高，前面不能再加「最」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试超级的难。", "corrected_sentence": "这次考试超级难。", "error_description": "错误形式：「超级的难」；正确形式：「超级难」。程度副词「超级」后面不加「的」，直接修饰形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
