INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89891, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "康复是生病或受伤以后，身体慢慢好起来。", "primary_collocate": null, "pronunciation": "kāng fù", "ipa": "kʰɑŋ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他受伤以后，慢慢康复了。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做完手术，正在医院康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多休息，才能早点康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿伤康复得很快。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，我下个月就能康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病以后，他每天锻炼，想早点康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出院后，在家里康复了一个月。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体还没有完全康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的运动员还在康复，不能比赛。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大病以后，他用了半年才康复。", "target_word": "康复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "康复了", "label": "体标（了）"}, {"form": "康复过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "生病或受伤后身体慢慢好起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "康复", "is_correct": true, "explanation": "康复：受伤以后身体慢慢好起来，与“受伤以后”“慢慢”的语境相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与受伤后的身体变化无关。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指成立婚姻关系，与句中的伤病语境不合。"}, {"text": "长大", "is_correct": false, "explanation": "搭配：“长大”指年龄增长、身体发育，不能用于受伤后的变化。"}], "explanations": {"康复": "康复：受伤以后身体慢慢好起来，与“受伤以后”“慢慢”的语境相符。", "毕业": "语义：“毕业”指完成学业，与受伤后的身体变化无关。", "结婚": "语义：“结婚”指成立婚姻关系，与句中的伤病语境不合。", "长大": "搭配：“长大”指年龄增长、身体发育，不能用于受伤后的变化。"}, "sentence_index": 0, "correct_answer": "康复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电话信号终于康复了。", "explanation": "这里应该用〈恢复〉。康复只用于人或动物的身体，电话信号等要用恢复。"}, {"text": "这幅古画终于康复了。", "explanation": "这里应该用〈复原〉。康复只用于人或动物的身体，古画等物品要用复原。"}, {"text": "这条公路终于康复了。", "explanation": "这里应该用〈修复〉。康复只用于人或动物的身体，公路等设施要用修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "康复", "is_correct": true, "explanation": "康复：出院后在家恢复身体，与“出院后”“一个月”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指婴儿来到世上，不能用于出院后的成年人。"}, {"text": "退学", "is_correct": false, "explanation": "语义：“退学”指离开学校，与“爸爸”出院后在家的语境不合。"}, {"text": "入伍", "is_correct": false, "explanation": "搭配：“入伍”指参军，不能与“出院后在家”搭配。"}], "explanations": {"康复": "康复：出院后在家恢复身体，与“出院后”“一个月”的语境相符。", "出生": "语义：“出生”指婴儿来到世上，不能用于出院后的成年人。", "退学": "语义：“退学”指离开学校，与“爸爸”出院后在家的语境不合。", "入伍": "搭配：“入伍”指参军，不能与“出院后在家”搭配。"}, "sentence_index": 6, "correct_answer": "康复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生终于康复了他的病。", "explanation": "这里应该用〈治愈〉。康复是不及物动词，不能带“病”作宾语；治愈可以带宾语，表示把病治好。"}, {"text": "这家公司的业绩终于康复了。", "explanation": "这里应该用〈好转〉。康复只用于人或动物的身体，业绩等情况要用好转。"}, {"text": "这个国家的市场终于康复了。", "explanation": "这里应该用〈复苏〉。康复只用于人或动物的身体，市场等要用复苏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的腿伤被康复了。", "corrected_sentence": "他的腿伤已经康复了。", "error_description": "错误在“被康复”：康复是不及物动词，不能用“被”字句。正确形式是“康复了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的身体很康复了。", "corrected_sentence": "妈妈的身体已经康复了。", "error_description": "错误在“很康复”：“很”一般修饰形容词，不能直接修饰动词“康复”。正确形式是“已经康复”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
