INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89893, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一堆一堆的东西或人，数的时候用它。", "primary_collocate": null, "pronunciation": "pī", "ipa": "pʰi˥", "syllable_count": 1, "sentences": [{"text": "仓库里新到了一批货。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一批学生已经坐车走了。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买了一批新书放在图书馆。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批水果很新鲜，卖得很快。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司招了一批年轻人。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一批游客正在山下拍照。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那批旧衣服送给了朋友。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批桌子明天要送到厂里。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校昨天来了一批客人。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货分三天运完。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批批", "label": "重叠"}], "register": "通用", "sense_fingerprint": "批：量词，数成堆、成组一起出现的货物或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批", "is_correct": true, "explanation": "正确答案：批（pī，第一声）是量词，用于成批的货物或人。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，意思是皮（皮肤、皮革）。"}, {"text": "匹", "is_correct": false, "explanation": "pǐ（第三声）与 pī（第一声）声调不同，意思是量词“匹”，用于马、布等。"}, {"text": "逼", "is_correct": false, "explanation": "bī 与 pī 只有声母不同（b 与 p），声调相同，意思是逼迫。"}, {"text": "僻", "is_correct": false, "explanation": "pì（第四声）与 pī（第一声）声调不同，意思是偏僻。"}], "explanations": {"批": "正确答案：批（pī，第一声）是量词，用于成批的货物或人。", "皮": "pí（第二声）与 pī（第一声）声调不同，意思是皮（皮肤、皮革）。", "匹": "pǐ（第三声）与 pī（第一声）声调不同，意思是量词“匹”，用于马、布等。", "逼": "bī 与 pī 只有声母不同（b 与 p），声调相同，意思是逼迫。", "僻": "pì（第四声）与 pī（第一声）声调不同，意思是偏僻。"}, "sentence_index": null, "correct_answer": "批"}, "level_3": {"options": [{"text": "批", "is_correct": true, "explanation": "正确：「一批货」指成批的货物，符合句中“新到了”的语境。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于单个动物或成对物品中的一个，货物成批到达，不能用“只”计量。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”用于计量有身份的人，货物不能用“位”计量。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，如纸、桌子，货物不能用“张”计量。"}], "explanations": {"批": "正确：「一批货」指成批的货物，符合句中“新到了”的语境。", "只": "搭配：“只”用于单个动物或成对物品中的一个，货物成批到达，不能用“只”计量。", "位": "语义：“位”用于计量有身份的人，货物不能用“位”计量。", "张": "搭配：“张”用于平面的东西，如纸、桌子，货物不能用“张”计量。"}, "sentence_index": 0, "correct_answer": "批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她昨晚做了一批好梦。", "explanation": "这里应该用〈场〉。梦按“场”计量，说“做了一场好梦”；“批”用于成批的货物或人，不能计量梦。"}, {"text": "院子里堆了一批雪。", "explanation": "这里应该用〈层〉。地上的雪按“层”计量，说“堆了一层雪”；“批”用于成批的货物或人，不用于计量雪。"}, {"text": "他脸上露出一批笑容。", "explanation": "这里应该用〈丝〉。笑容按“丝”计量，说“露出一丝笑容”；“批”用于成批的货物或人，不能计量笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89893, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "批", "is_correct": true, "explanation": "正确答案：批（pī，第一声）是量词，用于成批的货物或人。"}, {"text": "拼", "is_correct": false, "explanation": "pīn 与 pī 只有韵尾不同（n 与零韵尾），声调相同，意思是拼合。"}, {"text": "疲", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，意思是疲劳、累。"}, {"text": "痞", "is_correct": false, "explanation": "pǐ（第三声）与 pī（第一声）声调不同，意思是痞子、无赖。"}, {"text": "屁", "is_correct": false, "explanation": "pì（第四声）与 pī（第一声）声调不同，意思是屁、放屁。"}], "explanations": {"批": "正确答案：批（pī，第一声）是量词，用于成批的货物或人。", "拼": "pīn 与 pī 只有韵尾不同（n 与零韵尾），声调相同，意思是拼合。", "疲": "pí（第二声）与 pī（第一声）声调不同，意思是疲劳、累。", "痞": "pǐ（第三声）与 pī（第一声）声调不同，意思是痞子、无赖。", "屁": "pì（第四声）与 pī（第一声）声调不同，意思是屁、放屁。"}, "sentence_index": null, "correct_answer": "批"}, "level_3": {"options": [{"text": "批", "is_correct": true, "explanation": "正确：「那批旧衣服」指成批的旧衣服，符合句中“送给了朋友”的语境。"}, {"text": "双", "is_correct": false, "explanation": "搭配：“双”用于成对的物品，如鞋、袜，衣服不能用“双”计量。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书册，衣服不是书，不能用“本”计量。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、设备，不用于衣服。"}], "explanations": {"批": "正确：「那批旧衣服」指成批的旧衣服，符合句中“送给了朋友”的语境。", "双": "搭配：“双”用于成对的物品，如鞋、袜，衣服不能用“双”计量。", "本": "语义：“本”用于书册，衣服不是书，不能用“本”计量。", "台": "搭配：“台”用于机器、设备，不用于衣服。"}, "sentence_index": 6, "correct_answer": "批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喝了一批水。", "explanation": "这里应该用〈杯〉。水是液体，要用“杯”“瓶”之类的容器计量；“批”用于成批的货物或人，不能计量水。"}, {"text": "他吃了一批饭。", "explanation": "这里应该用〈碗〉。饭按“碗”计量，说“一碗饭”；“批”用于成批的货物或人，这里不这么用。"}, {"text": "我深深地吸了一批空气。", "explanation": "这里应该用〈口〉。吸气按“口”计量，说“吸了一口空气”；“批”不能用来计量空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司昨天进了一个批新电脑。", "corrected_sentence": "我们公司昨天进了一批新电脑。", "error_description": "错误形式“一个批”，正确形式“一批”。“批”本身是量词，不能再与“个”并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天商店运来了一批的饮料。", "corrected_sentence": "昨天商店运来了一批饮料。", "error_description": "错误形式“一批的饮料”，正确形式“一批饮料”。量词“批”与后面的名词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
