INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89894, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于成组的人或物。", "primary_collocate": null, "pronunciation": "pī", "ipa": "pʰi˥", "syllable_count": 1, "sentences": [{"text": "第二批志愿者明天到山里。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂今年做了三批新车。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院收到一批药品。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批电脑是去年买的。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是第一批去国外学习的学生。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口又来了一批人。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批画明天要送去展览。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了看新到的那批鞋。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一批老工人今年退休了。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，商店会进一批新年礼物。", "target_word": "批", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批批", "label": "重叠"}], "register": "通用", "sense_fingerprint": "批：量词，用于分次出现、成组的人或物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89894, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批", "is_correct": true, "explanation": "正确答案：批（pī，第一声）是量词，用于分次出现、成组的人或物。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，意思是皮（皮肤、皮革）。"}, {"text": "匹", "is_correct": false, "explanation": "pǐ（第三声）与 pī（第一声）声调不同，意思是量词“匹”，用于马、布等。"}, {"text": "逼", "is_correct": false, "explanation": "bī 与 pī 只有声母不同（b 与 p），声调相同，意思是逼迫。"}], "explanations": {"批": "正确答案：批（pī，第一声）是量词，用于分次出现、成组的人或物。", "皮": "pí（第二声）与 pī（第一声）声调不同，意思是皮（皮肤、皮革）。", "匹": "pǐ（第三声）与 pī（第一声）声调不同，意思是量词“匹”，用于马、布等。", "逼": "bī 与 pī 只有声母不同（b 与 p），声调相同，意思是逼迫。"}, "sentence_index": null, "correct_answer": "批"}, "level_3": {"options": [{"text": "批", "is_correct": true, "explanation": "正确：「第二批志愿者」指分次出现的一组志愿者，符合句中“明天到山里”的语境。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于单个动物或成对物品中的一个，不用于志愿者这类人。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书册，志愿者不是书，不能用“本”计量。"}, {"text": "台", "is_correct": false, "explanation": "语义：“台”用于机器、设备，志愿者是人，不能用“台”计量。"}], "explanations": {"批": "正确：「第二批志愿者」指分次出现的一组志愿者，符合句中“明天到山里”的语境。", "只": "搭配：“只”用于单个动物或成对物品中的一个，不用于志愿者这类人。", "本": "语义：“本”用于书册，志愿者不是书，不能用“本”计量。", "台": "语义：“台”用于机器、设备，志愿者是人，不能用“台”计量。"}, "sentence_index": 0, "correct_answer": "批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的眼睛里闪过一批光。", "explanation": "这里应该用〈道〉。光按“道”计量，说“闪过一道光”；“批”用于成组的人或物，不能计量光。"}, {"text": "他是一批医生。", "explanation": "这里应该用〈位〉。说一个人用“位”，如“他是一位医生”；“批”指成批的人，不能用来计量一个人。"}, {"text": "今晚天上有一批月亮。", "explanation": "这里应该用〈个〉或〈轮〉。月亮只有一个，说“一轮月亮”；“批”用于成组的人或物，不能计量月亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89894, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "批", "is_correct": true, "explanation": "正确答案：批（pī，第一声）是量词，用于分次出现、成组的人或物。"}, {"text": "拼", "is_correct": false, "explanation": "pīn 与 pī 只有韵尾不同（n 与零韵尾），声调相同，意思是拼合。"}, {"text": "疲", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，意思是疲劳、累。"}, {"text": "痞", "is_correct": false, "explanation": "pǐ（第三声）与 pī（第一声）声调不同，意思是痞子、无赖。"}, {"text": "僻", "is_correct": false, "explanation": "pì（第四声）与 pī（第一声）声调不同，意思是偏僻。"}], "explanations": {"批": "正确答案：批（pī，第一声）是量词，用于分次出现、成组的人或物。", "拼": "pīn 与 pī 只有韵尾不同（n 与零韵尾），声调相同，意思是拼合。", "疲": "pí（第二声）与 pī（第一声）声调不同，意思是疲劳、累。", "痞": "pǐ（第三声）与 pī（第一声）声调不同，意思是痞子、无赖。", "僻": "pì（第四声）与 pī（第一声）声调不同，意思是偏僻。"}, "sentence_index": null, "correct_answer": "批"}, "level_3": {"options": [{"text": "批", "is_correct": true, "explanation": "正确：「这批画」指成批的画，符合句中“送去展览”的语境。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，画不能用“首”计量。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄、有把手的物品，画不能用“把”计量。"}, {"text": "段", "is_correct": false, "explanation": "语义：“段”用于文字、时间或路程的一部分，不用于画。"}], "explanations": {"批": "正确：「这批画」指成批的画，符合句中“送去展览”的语境。", "首": "语义：“首”用于诗歌、歌曲，画不能用“首”计量。", "把": "搭配：“把”用于有柄、有把手的物品，画不能用“把”计量。", "段": "语义：“段”用于文字、时间或路程的一部分，不用于画。"}, "sentence_index": 6, "correct_answer": "批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他伸出一批手。", "explanation": "这里应该用〈双〉。手成对出现，要说“一双手”；“批”用于成批的人或货，这里不这么用。"}, {"text": "我倒了一批牛奶。", "explanation": "这里应该用〈杯〉。牛奶是液体，要按“杯”或“瓶”计量；“批”不能用来计量牛奶。"}, {"text": "她抬起一批胳膊。", "explanation": "这里应该用〈条〉。胳膊按“条”计量，说“一条胳膊”；“批”不用于计量身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些批新工人明天就要来报到。", "corrected_sentence": "这批新工人明天就要来报到。", "error_description": "错误形式“这些批”，正确形式“这批”。“批”本身是量词，已能表示数量，不能与“这些”同时使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校下周会收到一批的旧书。", "corrected_sentence": "学校下周会收到一批旧书。", "error_description": "错误形式“一批的”，正确形式“一批”。量词“批”后面直接接名词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
