INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89895, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很不容易做到。", "primary_collocate": null, "pronunciation": "nán yǐ", "ipa": "nan˧˥ i˨˩", "syllable_count": 2, "sentences": [{"text": "这件事太大，我一个人难以完成。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有朋友的帮助，他难以做到。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太冷了，大家难以入睡。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多作业，一晚上难以做完。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病很重，短时间内难以恢复。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心里太难过，他难以开口。", "target_word": "难以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上堵车，我们难以按时到学校。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人的力量太小，难以改变这件事。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他受了伤，几个月内难以参加比赛。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机会只有一次，错过了就难以再遇到。", "target_word": "难以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "難以", "label": "繁体"}, {"form": "难以置信", "label": "复合"}], "register": "书面", "sense_fingerprint": "很不容易做到（难以完成）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难以", "is_correct": true, "explanation": "“难以”表示很不容易做到，符合“这件事太大”的语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已经完成，与“这件事太大”的语境相矛盾。"}, {"text": "势必", "is_correct": false, "explanation": "语义：“势必”表示必然会发生，“我一个人势必完成”与“这件事太大”的困难语境相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻，与“太大”的语境相矛盾，不会立刻完成。"}], "explanations": {"难以": "“难以”表示很不容易做到，符合“这件事太大”的语境。", "已经": "语义：“已经”表示事情已经完成，与“这件事太大”的语境相矛盾。", "势必": "语义：“势必”表示必然会发生，“我一个人势必完成”与“这件事太大”的困难语境相矛盾。", "马上": "语义：“马上”表示立刻，与“太大”的语境相矛盾，不会立刻完成。"}, "sentence_index": 0, "correct_answer": "难以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的水平很高，每道题都难以做对。", "explanation": "这里应该用〈容易〉。“难以”表示很不容易，与“水平很高”的语义矛盾。"}, {"text": "这把椅子很轻，我一个人难以搬动。", "explanation": "这里应该用〈容易〉。“难以”表示很不容易，椅子很轻时不能说“难以搬动”。"}, {"text": "这份工作非常轻松，我们难以完成。", "explanation": "这里应该用〈容易〉。“难以”表示很不容易，与“非常轻松”的语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难以", "is_correct": true, "explanation": "“难以”表示很不容易做到，与“堵车”的语境一致，说明按时到达很困难。"}, {"text": "一定", "is_correct": false, "explanation": "语义：路上堵车时说“一定”按时到，不合常理，与语境矛盾。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与堵车导致迟到的语境不协调。"}, {"text": "不免", "is_correct": false, "explanation": "语义：“不免”表示免不了出现某种（多为不好的）结果，后面不接“按时到学校”这样的期望结果。"}], "explanations": {"难以": "“难以”表示很不容易做到，与“堵车”的语境一致，说明按时到达很困难。", "一定": "语义：路上堵车时说“一定”按时到，不合常理，与语境矛盾。", "竟然": "语义：“竟然”表示出乎意料，与堵车导致迟到的语境不协调。", "不免": "语义：“不免”表示免不了出现某种（多为不好的）结果，后面不接“按时到学校”这样的期望结果。"}, "sentence_index": 6, "correct_answer": "难以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题很简单，我难以回答。", "explanation": "语义：“很简单”与“难以”矛盾，“难以”表示很不容易做到，此处应改用“容易”。"}, {"text": "这所学校谁都能进，我们难以入学。", "explanation": "这里应该用〈容易〉。“难以”表示很不容易，与“谁都能进”的语义矛盾。"}, {"text": "这个活动只要举手就行，我们难以报上名。", "explanation": "这里应该用〈容易〉。“难以”表示很不容易，与“只要举手就行”的语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个任务太重，我一个人的难以承担。", "corrected_sentence": "这个任务太重，我一个人难以承担。", "error_description": "错误在“我一个人”和“难以”之间多加了“的”。“难以”是副词，直接修饰动词“承担”，前面不能加“的”，应说“难以承担”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们难以找不到合适的工作。", "corrected_sentence": "我们难以找到合适的工作。", "error_description": "错误只有一处：“难以”后面用了否定形式“找不到”。“难以”已表示很难做到，后面要接肯定的动词，应说“难以找到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提前", "is_correct": true, "explanation": "正确：延迟与提前互为反义，一个是把时间往后推，一个是把时间往前提。"}, {"text": "完成", "is_correct": false, "explanation": "完成是做完，与把时间往后推没有对立关系。"}, {"text": "取消", "is_correct": false, "explanation": "取消是不再进行，与把时间往后推不构成反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加是加入某项活动，与把时间往后推不构成反义关系。"}], "correct_answer": "提前", "explanations": {"提前": "正确：延迟与提前互为反义，一个是把时间往后推，一个是把时间往前提。", "完成": "完成是做完，与把时间往后推没有对立关系。", "取消": "取消是不再进行，与把时间往后推不构成反义关系。", "参加": "参加是加入某项活动，与把时间往后推不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "延迟是把时间往后推，比原来晚一点。", "primary_collocate": null, "pronunciation": "yán chí", "ipa": "jɛn˧˥ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "老师把考试延迟到下周。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定延迟上班时间。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，比赛延迟了一天。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把开会的时间延迟了半小时。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校延迟开学，因为天气太冷。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把旅行延迟到明年夏天。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说手术可以延迟几天。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把结婚的日子延迟了一个月。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身体不舒服，想延迟出发。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务把发工资的日子延迟到下个月了。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延迟了", "label": "体标"}, {"form": "延迟过", "label": "体标"}, {"form": "延遲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把原定的时间或日期往后推", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e68a7552-e561-4b72-8b96-81b1448aa4e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。延迟，yán chí，意思是把原定时间往后推。"}, {"text": "岩石", "is_correct": false, "explanation": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。岩石意思是岩石，与把时间往后推无关。"}, {"text": "研制", "is_correct": false, "explanation": "zhì（第四声）与 chí（第二声）声母和声调都不同。研制意思是研究制造。"}, {"text": "研习", "is_correct": false, "explanation": "xí（第二声）与 chí（第二声）声母不同：x 与 ch。研习意思是研究学习。"}], "explanations": {"延迟": "正确。延迟，yán chí，意思是把原定时间往后推。", "岩石": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。岩石意思是岩石，与把时间往后推无关。", "研制": "zhì（第四声）与 chí（第二声）声母和声调都不同。研制意思是研究制造。", "研习": "xí（第二声）与 chí（第二声）声母不同：x 与 ch。研习意思是研究学习。"}, "sentence_index": null, "correct_answer": "延迟"}, "level_3": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。“把考试……到下周”表示把原定时间往后推到下周。"}, {"text": "取消", "is_correct": false, "explanation": "语义：取消是不再举行，不能再把考试安排到下周。"}, {"text": "准备", "is_correct": false, "explanation": "搭配：“准备”的对象是要做的事情本身，不能与“把……到下周”这种时间移动的结构搭配。"}, {"text": "结束", "is_correct": false, "explanation": "配价：“结束”不能带“到下周”这种表示时间终点的补语。"}], "explanations": {"延迟": "正确。“把考试……到下周”表示把原定时间往后推到下周。", "取消": "语义：取消是不再举行，不能再把考试安排到下周。", "准备": "搭配：“准备”的对象是要做的事情本身，不能与“把……到下周”这种时间移动的结构搭配。", "结束": "配价：“结束”不能带“到下周”这种表示时间终点的补语。"}, "sentence_index": 0, "correct_answer": "延迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把椅子往后延迟了一点，好让我坐进去。", "explanation": "这里应该用〈推〉。延迟只用于把时间或日程往后推，不能用来说椅子这类物体在空间里的移动。"}, {"text": "这个会议的时长延迟了半小时。", "explanation": "这里应该用〈延长〉。延迟指把原定的时间往后推，说时长变多要用延长。"}, {"text": "他总是延迟，不肯早点开始写作业。", "explanation": "这里应该用〈拖延〉。延迟多指原定的时间或日程被推后，人磨蹭、拖拉要用拖延。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。延迟，yán chí，意思是把原定时间往后推。"}, {"text": "严实", "is_correct": false, "explanation": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。严实意思是严密、不透风。"}, {"text": "言辞", "is_correct": false, "explanation": "cí（第二声）与 chí（第二声）声母不同：c 与 ch。言辞意思是言语、措辞。"}, {"text": "言及", "is_correct": false, "explanation": "jí（第二声）与 chí（第二声）声母不同：j 与 ch。言及意思是提到、说到。"}], "explanations": {"延迟": "正确。延迟，yán chí，意思是把原定时间往后推。", "严实": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。严实意思是严密、不透风。", "言辞": "cí（第二声）与 chí（第二声）声母不同：c 与 ch。言辞意思是言语、措辞。", "言及": "jí（第二声）与 chí（第二声）声母不同：j 与 ch。言及意思是提到、说到。"}, "sentence_index": null, "correct_answer": "延迟"}, "level_3": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。“几天”表示推迟的时长，“延迟几天”指手术时间往后推几天。"}, {"text": "取消", "is_correct": false, "explanation": "语义：取消后手术就不再进行，不能表示持续或推迟几天。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”是一次性做完的动作，不能与表示时段的“几天”搭配。"}, {"text": "开始", "is_correct": false, "explanation": "配价：“开始”不能带“几天”这种时段词语作宾语或补语。"}], "explanations": {"延迟": "正确。“几天”表示推迟的时长，“延迟几天”指手术时间往后推几天。", "取消": "语义：取消后手术就不再进行，不能表示持续或推迟几天。", "完成": "搭配：“完成”是一次性做完的动作，不能与表示时段的“几天”搭配。", "开始": "配价：“开始”不能带“几天”这种时段词语作宾语或补语。"}, "sentence_index": 6, "correct_answer": "延迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我因为堵车延迟了二十分钟才到公司。", "explanation": "这里应该用〈迟到〉。延迟说的是事情或班次没有按时进行，人没按时到要说迟到。"}, {"text": "这辆车在红灯前延迟了速度，慢慢停了下来。", "explanation": "这里应该用〈减速〉。延迟指事情或时间往后推，不能用来说速度降低，车速变慢要用减速。"}, {"text": "他的名次一直延迟在前三名。", "explanation": "这里应该用〈保持〉。延迟只表示时间或日程往后推，不能用来说状态持续不变，名次稳定要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校方把体育课延迟在下周了。", "corrected_sentence": "校方把体育课延迟到下周了。", "error_description": "错误：“延迟”后引出时间终点应用“到”，不能用“在”。正确应为“延迟到下周”，“延迟到……”表示推迟到某个时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把会议延迟了了一天。", "corrected_sentence": "我们把会议延迟了一天。", "error_description": "错误：“了”重复出现。“延迟了”只需一个“了”，多出的“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准时", "is_correct": true, "explanation": "正确：延迟指没有按时进行，准时指按时进行，二者意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成是做完，与没有按时进行不构成反义关系。"}, {"text": "取消", "is_correct": false, "explanation": "取消是不再进行，与没有按时进行不构成反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加是加入某项活动，与没有按时进行不构成反义关系。"}], "correct_answer": "准时", "explanations": {"准时": "正确：延迟指没有按时进行，准时指按时进行，二者意思相反。", "完成": "完成是做完，与没有按时进行不构成反义关系。", "取消": "取消是不再进行，与没有按时进行不构成反义关系。", "参加": "参加是加入某项活动，与没有按时进行不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
