INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情或班次没有按时进行，比原定时间晚了，被往后拖延。", "primary_collocate": null, "pronunciation": "yán chí", "ipa": "jɛn˧˥ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "火车延迟了，我们在车站等了很久。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机因为大雪延迟起飞。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递延迟了两天才到。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出因为舞台出了故障，延迟了二十分钟才开始。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议延迟到三点才开始。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，航班延迟了很长时间。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，航班延迟了，乘客都不高兴。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为路上堵车，公交车延迟了十分钟。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁出了故障，很多列车都延迟了。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包裹在海关延迟了，到现在还没送到。", "target_word": "延迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延迟了", "label": "体标"}, {"form": "延迟过", "label": "体标"}, {"form": "延遲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情或班次没有按时进行而晚了、被拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e68a7552-e561-4b72-8b96-81b1448aa4e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。延迟，yán chí，意思是事情或班次没有按时进行而晚了。"}, {"text": "岩石", "is_correct": false, "explanation": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。岩石意思是岩石。"}, {"text": "研制", "is_correct": false, "explanation": "zhì（第四声）与 chí（第二声）声母和声调都不同。研制意思是研究制造。"}, {"text": "研习", "is_correct": false, "explanation": "xí（第二声）与 chí（第二声）声母不同：x 与 ch。研习意思是研究学习。"}], "explanations": {"延迟": "正确。延迟，yán chí，意思是事情或班次没有按时进行而晚了。", "岩石": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。岩石意思是岩石。", "研制": "zhì（第四声）与 chí（第二声）声母和声调都不同。研制意思是研究制造。", "研习": "xí（第二声）与 chí（第二声）声母不同：x 与 ch。研习意思是研究学习。"}, "sentence_index": null, "correct_answer": "延迟"}, "level_3": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。火车没有按时到站，所以晚了、被拖延。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象不是火车，“火车打扫了”不成句，不符合语境。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”指做完某件事，不能用来描述火车的运行状态。"}, {"text": "开始", "is_correct": false, "explanation": "配价：“开始”需要的对象是动作或事件，不能用来描述火车已经晚点。"}], "explanations": {"延迟": "正确。火车没有按时到站，所以晚了、被拖延。", "打扫": "语义：“打扫”的对象不是火车，“火车打扫了”不成句，不符合语境。", "完成": "搭配：“完成”指做完某件事，不能用来描述火车的运行状态。", "开始": "配价：“开始”需要的对象是动作或事件，不能用来描述火车已经晚点。"}, "sentence_index": 0, "correct_answer": "延迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把沙发往后延迟了一点，好让我走过去。", "explanation": "这里应该用〈推〉。延迟只用于把时间或日程往后推，不能用来说沙发这类物体在空间里的移动。"}, {"text": "这个会议的时长延迟了半小时。", "explanation": "这里应该用〈延长〉。延迟说的是事情没有按时进行而晚了，说时长变多要用延长。"}, {"text": "他的成绩一直延迟在前三名。", "explanation": "这里应该用〈保持〉。延迟只表示时间或日程往后推，不能用来说状态持续不变，成绩稳定在某个位置要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。延迟，yán chí，意思是事情没有按时进行而被拖延。"}, {"text": "严实", "is_correct": false, "explanation": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。严实意思是严密、不透风。"}, {"text": "言辞", "is_correct": false, "explanation": "cí（第二声）与 chí（第二声）声母不同：c 与 ch。言辞意思是言语、措辞。"}, {"text": "言及", "is_correct": false, "explanation": "jí（第二声）与 chí（第二声）声母不同：j 与 ch。言及意思是提到、说到。"}], "explanations": {"延迟": "正确。延迟，yán chí，意思是事情没有按时进行而被拖延。", "严实": "shí（第二声）与 chí（第二声）声母不同：sh 与 ch。严实意思是严密、不透风。", "言辞": "cí（第二声）与 chí（第二声）声母不同：c 与 ch。言辞意思是言语、措辞。", "言及": "jí（第二声）与 chí（第二声）声母不同：j 与 ch。言及意思是提到、说到。"}, "sentence_index": null, "correct_answer": "延迟"}, "level_3": {"options": [{"text": "延迟", "is_correct": true, "explanation": "正确。天气不好，航班没有按时起飞，晚了，所以乘客不高兴。"}, {"text": "准时", "is_correct": false, "explanation": "语义：航班准时的话乘客不会不高兴，与后半句矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是地方或房间，“航班打扫了”不成句。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”需要人作主语、带宾语，“航班喜欢了”不成句。"}], "explanations": {"延迟": "正确。天气不好，航班没有按时起飞，晚了，所以乘客不高兴。", "准时": "语义：航班准时的话乘客不会不高兴，与后半句矛盾。", "打扫": "语义：“打扫”的对象是地方或房间，“航班打扫了”不成句。", "喜欢": "配价：“喜欢”需要人作主语、带宾语，“航班喜欢了”不成句。"}, "sentence_index": 6, "correct_answer": "延迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我因为堵车延迟了二十分钟才到公司。", "explanation": "这里应该用〈迟到〉。延迟说的是事情或班次没有按时进行，人没按时到要说迟到。"}, {"text": "这辆自行车在下坡前延迟了速度，慢慢停了下来。", "explanation": "这里应该用〈减速〉。延迟指事情或时间往后推，不能用来说速度降低，车速变慢要用减速。"}, {"text": "他把电视的音量延迟了一点，我听不清楚。", "explanation": "这里应该用〈调低〉。延迟指事情或时间往后推，不能用来说音量变小，音量降低要用调低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "活动延迟着一周才开始。", "corrected_sentence": "活动延迟了一周才开始。", "error_description": "错误：“延迟”后用了“着”，“着”表示持续的状态，与已经发生的一周延误不符。正确应为“延迟了”，用“了”表示延误已经发生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公交车延迟得十分钟，我差点迟到。", "corrected_sentence": "公交车延迟了十分钟，我差点迟到。", "error_description": "错误：“延迟”后用了“得”作补语标记，句子不通。正确应为“延迟了”，用“了”表示延误已经发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
