INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89899, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从中间慢慢拉出来。", "primary_collocate": null, "pronunciation": "chōu", "ipa": "ʈʂʰou˥", "syllable_count": 1, "sentences": [{"text": "他慢慢抽出压在书下的纸。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从线团里慢慢抽出一根线。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小心地抽出夹在书里的信。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生慢慢把针从手臂里抽出来。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢地把卡在门缝里的纸条抽出来。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从桌布下慢慢抽出手。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你慢慢抽，别把纸拉破了。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从一叠纸中间慢慢抽出一张。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔术师慢慢抽出了长长的彩带。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我轻轻抽出压在盒子下的照片。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽出", "label": "复合"}, {"form": "抽出来", "label": "复合"}, {"form": "抽了", "label": "体标"}, {"form": "抽着", "label": "体标"}, {"form": "抽过", "label": "体标"}], "register": "中性", "sense_fingerprint": "抽：把夹在中间或压在下面的东西慢慢向外拉出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89899, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抽", "is_correct": true, "explanation": "抽：第一声，意思是把夹在中间或压在下面的东西慢慢拉出来。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 chōu 声母不同（sh 与 ch），意思是收起、收回，不是慢慢拉出。"}, {"text": "丑", "is_correct": false, "explanation": "chǒu（第三声）与 chōu 声调不同，意思是难看，与拉出无关。"}, {"text": "愁", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是忧愁。"}, {"text": "超", "is_correct": false, "explanation": "chāo（第一声）与 chōu 韵母不同（ao 与 ou），意思是超过。"}], "explanations": {"抽": "抽：第一声，意思是把夹在中间或压在下面的东西慢慢拉出来。", "收": "shōu（第一声）与 chōu 声母不同（sh 与 ch），意思是收起、收回，不是慢慢拉出。", "丑": "chǒu（第三声）与 chōu 声调不同，意思是难看，与拉出无关。", "愁": "chóu（第二声）与 chōu 声调不同，意思是忧愁。", "超": "chāo（第一声）与 chōu 韵母不同（ao 与 ou），意思是超过。"}, "sentence_index": null, "correct_answer": "抽"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写出”指写下来，不能用于把压在书下的纸拉出。"}, {"text": "印", "is_correct": false, "explanation": "语义：“印出”指印刷成型，与“压在书下的纸”被拉出的动作不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮出”用于煮出的成果或味道，不能与纸搭配。"}, {"text": "抽", "is_correct": true, "explanation": "抽：慢慢从中间拉出，与“慢慢”和“压在书下”的动作相符。"}], "explanations": {"写": "语义：“写出”指写下来，不能用于把压在书下的纸拉出。", "印": "语义：“印出”指印刷成型，与“压在书下的纸”被拉出的动作不符。", "煮": "搭配：“煮出”用于煮出的成果或味道，不能与纸搭配。", "抽": "抽：慢慢从中间拉出，与“慢慢”和“压在书下”的动作相符。"}, "sentence_index": 0, "correct_answer": "抽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牙医把那颗蛀牙抽出来了。", "explanation": "这里应该用〈拔〉。拔用于牙齿、钉子等连根或固定的东西，“抽出”在此只指从中间慢慢拉出，不能用于拔牙。"}, {"text": "他从牙膏管里抽出一点牙膏。", "explanation": "这里应该用〈挤〉。挤用于从软管或瓶子里压出膏状或液体，“抽”不能用于牙膏。"}, {"text": "他把眼镜抽下来放在桌上。", "explanation": "这里应该用〈摘〉。摘用于从头上或脸上取下眼镜、帽子等，不能说“抽下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89899, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抽", "is_correct": true, "explanation": "抽：第一声，意思是把夹在中间或压在下面的东西慢慢拉出来。"}, {"text": "周", "is_correct": false, "explanation": "zhōu（第一声）与 chōu 声母不同（zh 与 ch），意思是周围、一周。"}, {"text": "臭", "is_correct": false, "explanation": "chòu（第四声）与 chōu 声调不同，意思是气味难闻。"}, {"text": "稠", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是浓稠。"}, {"text": "仇", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是仇恨。"}], "explanations": {"抽": "抽：第一声，意思是把夹在中间或压在下面的东西慢慢拉出来。", "周": "zhōu（第一声）与 chōu 声母不同（zh 与 ch），意思是周围、一周。", "臭": "chòu（第四声）与 chōu 声调不同，意思是气味难闻。", "稠": "chóu（第二声）与 chōu 声调不同，意思是浓稠。", "仇": "chóu（第二声）与 chōu 声调不同，意思是仇恨。"}, "sentence_index": null, "correct_answer": "抽"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”指加热或燃烧，与“别把纸拉破了”的动作不符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流送出，与“拉破”的动作相矛盾。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”用于熬煮液体或药材，不能用于纸。"}, {"text": "抽", "is_correct": true, "explanation": "抽：慢慢从中间拉出，与“别把纸拉破了”的动作相符。"}], "explanations": {"烧": "语义：“烧”指加热或燃烧，与“别把纸拉破了”的动作不符。", "吹": "语义：“吹”指用气流送出，与“拉破”的动作相矛盾。", "熬": "搭配：“熬”用于熬煮液体或药材，不能用于纸。", "抽": "抽：慢慢从中间拉出，与“别把纸拉破了”的动作相符。"}, "sentence_index": 6, "correct_answer": "抽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从瓶子里抽出一点洗发水。", "explanation": "这里应该用〈挤〉。挤用于从瓶子或软管里压出膏状、液体的东西，抽在此义项指把夹在中间的东西慢慢拉出。"}, {"text": "他把帽子抽下来挂在墙上。", "explanation": "这里应该用〈摘〉。摘用于从头上取下帽子、眼镜，不能说“抽下来”。"}, {"text": "他把那棵小草连根抽了出来。", "explanation": "这里应该用〈拔〉。拔用于把长在土里或固定住的东西连根拉出，“连根”只能和拔搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从一本书里慢慢抽进一张纸。", "corrected_sentence": "他从一本书里慢慢抽出一张纸。", "error_description": "方向补语错误：纸是从书里向外拉出，应用“出”，不能用“进”。正确说法是“慢慢抽出一张纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从一叠书中间抽了出一本。", "corrected_sentence": "她从一叠书中间抽出了一本。", "error_description": "“了”位置错误：“抽出”是复合动词，“了”应放在“出”之后，说“抽了出”是错误的，正确说法是“抽出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
