INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从中取出；拔出。", "primary_collocate": null, "pronunciation": "chōu", "ipa": "ʈʂʰou˥", "syllable_count": 1, "sentences": [{"text": "他从盒子里抽了一张纸巾。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从这些卡片中抽一张。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从书架上抽出一本书。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏开始前，每人先抽一张卡。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抽出腰间的刀，对着敌人。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从钱包里抽出一百块钱。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从柜子里抽出一条毛巾。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，从袋子里抽了一个球。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从一堆文件里抽出了那份合同。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师抽一个同学回答问题。", "target_word": "抽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽出", "label": "复合"}, {"form": "抽到", "label": "复合"}, {"form": "抽了", "label": "体标"}, {"form": "抽过", "label": "体标"}], "register": "中性", "sense_fingerprint": "抽：从一堆或一组东西中取出一个，或把刀剑等拔出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抽", "is_correct": true, "explanation": "抽：第一声，意思是从一堆或一组东西中取出一个，或把刀剑等拔出。"}, {"text": "周", "is_correct": false, "explanation": "zhōu（第一声）与 chōu 声母不同（zh 与 ch），意思是周围、一周。"}, {"text": "臭", "is_correct": false, "explanation": "chòu（第四声）与 chōu 声调不同，意思是气味难闻。"}, {"text": "愁", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是忧愁。"}, {"text": "超", "is_correct": false, "explanation": "chāo（第一声）与 chōu 韵母不同（ao 与 ou），意思是超过。"}], "explanations": {"抽": "抽：第一声，意思是从一堆或一组东西中取出一个，或把刀剑等拔出。", "周": "zhōu（第一声）与 chōu 声母不同（zh 与 ch），意思是周围、一周。", "臭": "chòu（第四声）与 chōu 声调不同，意思是气味难闻。", "愁": "chóu（第二声）与 chōu 声调不同，意思是忧愁。", "超": "chāo（第一声）与 chōu 韵母不同（ao 与 ou），意思是超过。"}, "sentence_index": null, "correct_answer": "抽"}, "level_3": {"options": [{"text": "倒", "is_correct": false, "explanation": "语义：“倒”指倾倒液体，不能用于从盒子里取出纸巾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，与“从盒子里”取纸巾的动作不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”一般与饮品搭配，不能与纸巾搭配。"}, {"text": "抽", "is_correct": true, "explanation": "抽：从一组东西里取出一个，与“从盒子里”相符。"}], "explanations": {"倒": "语义：“倒”指倾倒液体，不能用于从盒子里取出纸巾。", "烧": "语义：“烧”指燃烧或加热，与“从盒子里”取纸巾的动作不符。", "喝": "搭配：“喝”一般与饮品搭配，不能与纸巾搭配。", "抽": "抽：从一组东西里取出一个，与“从盒子里”相符。"}, "sentence_index": 0, "correct_answer": "抽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把眼镜抽下来擦了擦。", "explanation": "这里应该用〈摘〉。摘用于从脸上、头上取下眼镜、帽子，不能说“抽下来”。"}, {"text": "他从牙膏管里抽出一点牙膏。", "explanation": "这里应该用〈挤〉。挤用于从软管里压出膏状物，抽不能用于牙膏。"}, {"text": "他把一碗汤抽进了锅里。", "explanation": "这里应该用〈倒〉。倒用于把液体从容器里倒出，抽不能用于把汤倒进锅里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89900, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抽", "is_correct": true, "explanation": "抽：第一声，意思是从一堆或一组东西中取出一个，或把刀剑等拔出。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 chōu 声母不同（sh 与 ch），意思是收起、收回。"}, {"text": "丑", "is_correct": false, "explanation": "chǒu（第三声）与 chōu 声调不同，意思是难看。"}, {"text": "稠", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是浓稠。"}, {"text": "仇", "is_correct": false, "explanation": "chóu（第二声）与 chōu 声调不同，意思是仇恨。"}], "explanations": {"抽": "抽：第一声，意思是从一堆或一组东西中取出一个，或把刀剑等拔出。", "收": "shōu（第一声）与 chōu 声母不同（sh 与 ch），意思是收起、收回。", "丑": "chǒu（第三声）与 chōu 声调不同，意思是难看。", "稠": "chóu（第二声）与 chōu 声调不同，意思是浓稠。", "仇": "chóu（第二声）与 chōu 声调不同，意思是仇恨。"}, "sentence_index": null, "correct_answer": "抽"}, "level_3": {"options": [{"text": "挤", "is_correct": false, "explanation": "语义：“挤”用于压出液体或膏状物，不能用于毛巾。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指加热食物，与从柜子里取出毛巾不符。"}, {"text": "印", "is_correct": false, "explanation": "搭配：“印出”指印刷成品，不能说“印出一条毛巾”。"}, {"text": "抽", "is_correct": true, "explanation": "抽出：从一堆东西中取出，与“从柜子里”相符。"}], "explanations": {"挤": "语义：“挤”用于压出液体或膏状物，不能用于毛巾。", "烤": "语义：“烤”指加热食物，与从柜子里取出毛巾不符。", "印": "搭配：“印出”指印刷成品，不能说“印出一条毛巾”。", "抽": "抽出：从一堆东西中取出，与“从柜子里”相符。"}, "sentence_index": 6, "correct_answer": "抽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用湿布把地板抽干净了。", "explanation": "这里应该用〈擦〉。擦地板要用擦，抽不能表示擦拭。"}, {"text": "他从软管里抽出一点颜料。", "explanation": "这里应该用〈挤〉。挤用于从软管或瓶子里压出颜料、膏状物，“抽”不能用于软管里的颜料。"}, {"text": "他把帽子抽下来放在桌上。", "explanation": "这里应该用〈摘〉。摘用于从头上取下帽子、眼镜，不能说“抽下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从一叠卡片里抽进了一张。", "corrected_sentence": "她从一叠卡片里抽出了一张。", "error_description": "方向补语错误：卡片是从一叠中向外取出，应用“出”，不能用“进”。正确说法是“抽出了一张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈从抽屉里抽了出一个本子。", "corrected_sentence": "妈妈从抽屉里抽出了一个本子。", "error_description": "“了”位置错误：“抽出”是复合动词，“了”应放在“出”之后，说“抽了出”是错误的，正确说法是“抽出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
