INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "户口是记着一家人住在哪里、有几个人的登记。", "primary_collocate": null, "pronunciation": "hù kǒu", "ipa": "xu˥˩ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家的户口在老家。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学要先看户口在哪里。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把我的户口迁到了新家。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户口上写着我们家有四口人。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生的宝宝还没有办户口。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有北京户口吗？", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在城里买房子，可是没有当地户口。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有户口的孩子上学会很难。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理入学时，需要提供孩子的户口。", "target_word": "户口", "complexity_tier": "T3", "furigana": "bàn lǐ rù xué shí, xū yào tí gōng hái zi de hù kǒu。", "sentence_source": "generated"}, {"text": "我们一家人的户口都在城里。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "户口本", "label": "复合"}, {"form": "户口簿", "label": "复合"}], "register": "中性", "sense_fingerprint": "记录一家人住址和人数的登记，日常办事常用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89903, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。hù kǒu 即户口，指记录一家人住址和人口的登记。"}, {"text": "虎口", "is_correct": false, "explanation": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}, {"text": "路口", "is_correct": false, "explanation": "路口（lù kǒu）第一个音节声母不同（l 对 h），意思是道路交叉的地方。"}, {"text": "渡口", "is_correct": false, "explanation": "渡口（dù kǒu）第一个音节声母不同（d 对 h），声调相同，意思是渡船停靠的地方。"}], "explanations": {"户口": "正确。hù kǒu 即户口，指记录一家人住址和人口的登记。", "虎口": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。", "路口": "路口（lù kǒu）第一个音节声母不同（l 对 h），意思是道路交叉的地方。", "渡口": "渡口（dù kǒu）第一个音节声母不同（d 对 h），声调相同，意思是渡船停靠的地方。"}, "sentence_index": null, "correct_answer": "户口"}, "level_3": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。户口登记在老家，“我家的户口在老家”合理。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能存放在某个地方，“我家的年龄在老家”说不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不能位于老家。"}, {"text": "颜色", "is_correct": false, "explanation": "配价：“在老家”要求主语是能处于某地的人或物，颜色是事物的属性，不能处于老家。"}], "explanations": {"户口": "正确。户口登记在老家，“我家的户口在老家”合理。", "年龄": "语义：年龄不能存放在某个地方，“我家的年龄在老家”说不通。", "星期": "语义：星期是时间单位，不能位于老家。", "颜色": "配价：“在老家”要求主语是能处于某地的人或物，颜色是事物的属性，不能处于老家。"}, "sentence_index": 0, "correct_answer": "户口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用户口在超市付了钱。", "explanation": "这里应该用〈银行卡〉。户口是户籍登记，不是支付工具，付款应说银行卡。"}, {"text": "我要去车管所考户口。", "explanation": "这里应该用〈驾照〉。车管所办理的是驾驶证件，考的是驾照，户口由派出所办理。"}, {"text": "我去超市买了一瓶户口。", "explanation": "这里应该用〈酸奶〉。“瓶”用于瓶装的饮品，超市卖的是酸奶；户口是登记，不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89903, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。hù kǒu 即户口，指记录一家人住址和人口的登记。"}, {"text": "糊口", "is_correct": false, "explanation": "糊口（hú kǒu）第一个音节声调不同（第二声 对 第四声），意思是勉强维持生计。"}, {"text": "入口", "is_correct": false, "explanation": "入口（rù kǒu）第一个音节声母不同（r 对 h），声调相同，意思是进入的通道。"}, {"text": "虎口", "is_correct": false, "explanation": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}], "explanations": {"户口": "正确。hù kǒu 即户口，指记录一家人住址和人口的登记。", "糊口": "糊口（hú kǒu）第一个音节声调不同（第二声 对 第四声），意思是勉强维持生计。", "入口": "入口（rù kǒu）第一个音节声母不同（r 对 h），声调相同，意思是进入的通道。", "虎口": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}, "sentence_index": null, "correct_answer": "户口"}, "level_3": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。买房子需要当地户口，所以“没有当地户口”合理。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“没有当地脾气”不成立，脾气不是按地方登记的东西。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不随地方而分，“没有当地体温”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“没有”后接的应是可登记、可领取的证件类词语，天气不能说没有当地天气。"}], "explanations": {"户口": "正确。买房子需要当地户口，所以“没有当地户口”合理。", "脾气": "语义：“没有当地脾气”不成立，脾气不是按地方登记的东西。", "体温": "语义：体温不随地方而分，“没有当地体温”说不通。", "天气": "搭配：“没有”后接的应是可登记、可领取的证件类词语，天气不能说没有当地天气。"}, "sentence_index": 6, "correct_answer": "户口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸是家里的户口，负责办理手续。", "explanation": "这里应该用〈户主〉。户主是一家之主，是人，户口只是登记，不能当人来说。"}, {"text": "出国旅游要带好户口。", "explanation": "这里应该用〈护照〉。出国要用护照，户口是国内的户籍登记，不能用于出境。"}, {"text": "他在河边钓了一条户口。", "explanation": "这里应该用〈鱼〉。钓到的是鱼，“条”用于鱼等细长的东西；户口是登记，不能钓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸已经把我的户口迁过了来。", "corrected_sentence": "爸爸已经把我的户口迁过来了。", "error_description": "趋向补语“过来”应紧跟动词，说“迁过来了”，不能说“迁过了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家的一口户口登记在派出所。", "corrected_sentence": "我们家的户口登记在派出所。", "error_description": "“口”是计算人口的量词，不能用来修饰户口，应直接说“我们家的户口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
