INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府登记的住户人口，也指登记簿册。", "primary_collocate": null, "pronunciation": "hù kǒu", "ipa": "xu˥˩ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府每年都会检查当地的户口。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察来我家查户口。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把户口交给工作人员登记。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村的户口都已经登记好了。", "target_word": "户口", "complexity_tier": "T3", "furigana": "zhè ge cūn de hù kǒu dōu yǐ jīng dēng jì hǎo le。", "sentence_source": "generated"}, {"text": "他的户口已经从农村迁出了。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办户口需要带身份证和证明。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在这座城市定居，户口却一直没办下来。", "target_word": "户口", "complexity_tier": "T3", "furigana": "tā xiǎng zài zhè zuò chéng shì dìng jū, hù kǒu què yì zhí méi bàn xià lai。", "sentence_source": "generated"}, {"text": "他去派出所登记了新生儿的户口。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一页户口上写着他的名字。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把外地人的户口也登记了。", "target_word": "户口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "户口本", "label": "复合"}, {"form": "户口簿", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府登记管理的住户人口，也指登记簿册", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84d87eb9-12aa-47b4-a5bd-1ef9cd759ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。hù kǒu 即户口，指政府登记管理的住户人口或登记簿册。"}, {"text": "虎口", "is_correct": false, "explanation": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}, {"text": "糊口", "is_correct": false, "explanation": "糊口（hú kǒu）第一个音节声调不同（第二声 对 第四声），意思是勉强维持生计。"}, {"text": "渡口", "is_correct": false, "explanation": "渡口（dù kǒu）第一个音节声母不同（d 对 h），声调相同，意思是渡船停靠的地方。"}], "explanations": {"户口": "正确。hù kǒu 即户口，指政府登记管理的住户人口或登记簿册。", "虎口": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。", "糊口": "糊口（hú kǒu）第一个音节声调不同（第二声 对 第四声），意思是勉强维持生计。", "渡口": "渡口（dù kǒu）第一个音节声母不同（d 对 h），声调相同，意思是渡船停靠的地方。"}, "sentence_index": null, "correct_answer": "户口"}, "level_3": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。政府每年检查的是当地的户口登记，“检查当地的户口”合理。"}, {"text": "心情", "is_correct": false, "explanation": "语义：政府不会去检查人的心情。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：政府不会去检查笑声。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“检查”不搭配“天气”，天气通常说观测或预报。"}], "explanations": {"户口": "正确。政府每年检查的是当地的户口登记，“检查当地的户口”合理。", "心情": "语义：政府不会去检查人的心情。", "笑声": "语义：政府不会去检查笑声。", "天气": "搭配：“检查”不搭配“天气”，天气通常说观测或预报。"}, "sentence_index": 0, "correct_answer": "户口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考了三次户口才通过。", "explanation": "这里应该用〈驾照〉。考试通过的是驾照，户口是登记，不用考。"}, {"text": "他去大使馆申请户口，准备到国外工作。", "explanation": "这里应该用〈签证〉。去国外工作要向大使馆申请签证，户口是国内的户籍登记，不能用来申请入境。"}, {"text": "我找到了一把户口。", "explanation": "这里应该用〈本〉。户口是册子，应说一本户口；“把”用于带柄的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。hù kǒu 即户口，指政府登记管理的住户人口或登记簿册。"}, {"text": "路口", "is_correct": false, "explanation": "路口（lù kǒu）第一个音节声母不同（l 对 h），意思是道路交叉的地方。"}, {"text": "入口", "is_correct": false, "explanation": "入口（rù kǒu）第一个音节声母不同（r 对 h），声调相同，意思是进入的通道。"}, {"text": "虎口", "is_correct": false, "explanation": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}], "explanations": {"户口": "正确。hù kǒu 即户口，指政府登记管理的住户人口或登记簿册。", "路口": "路口（lù kǒu）第一个音节声母不同（l 对 h），意思是道路交叉的地方。", "入口": "入口（rù kǒu）第一个音节声母不同（r 对 h），声调相同，意思是进入的通道。", "虎口": "虎口（hǔ kǒu）第一个音节声调不同（第三声 对 第四声），意思是老虎的嘴或手指间的虎口部位。"}, "sentence_index": null, "correct_answer": "户口"}, "level_3": {"options": [{"text": "户口", "is_correct": true, "explanation": "正确。定居需要办理户口，所以“户口却一直没办下来”合理。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以办理的手续，与定居的语境不合。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能“办下来”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“办”的对象是证件、手续，不能说“办脾气”。"}], "explanations": {"户口": "正确。定居需要办理户口，所以“户口却一直没办下来”合理。", "年龄": "语义：年龄不是可以办理的手续，与定居的语境不合。", "夏天": "语义：夏天是季节，不能“办下来”。", "脾气": "搭配：“办”的对象是证件、手续，不能说“办脾气”。"}, "sentence_index": 6, "correct_answer": "户口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们家的户口，大家都听他的。", "explanation": "这里应该用〈户主〉。户主是一家之主，是人；户口只是登记，不能指人。"}, {"text": "这张户口可以打八折。", "explanation": "这里应该用〈会员卡〉。会员卡可以打折，户口是户籍登记，不能用来打折。"}, {"text": "我从箱子里拿出了一块户口。", "explanation": "这里应该用〈本〉。户口是册子，应说一本户口，“块”用于成块的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从抽屉里拿出了一张户口。", "corrected_sentence": "他从抽屉里拿出了一本户口。", "error_description": "这里的“户口”指登记簿册，量词应用“本”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的户口一直没办下来了。", "corrected_sentence": "他的户口一直没办下来。", "error_description": "“没”否定动作的完成，不能再在句末加“了”，应说“一直没办下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8de6cf-5530-40d1-b7ea-7e2d1b37c9e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "掩盖", "is_correct": true, "explanation": "掩盖：把真相遮住，使人不知道，与“揭露”互为反义。"}, {"text": "保护", "is_correct": false, "explanation": "与“揭露”无反义关系，保护指照顾、防止受到伤害。"}, {"text": "修建", "is_correct": false, "explanation": "与“揭露”无反义关系，修建指建造房屋、道路等。"}, {"text": "欣赏", "is_correct": false, "explanation": "与“揭露”无反义关系，欣赏指赞美、喜爱。"}], "correct_answer": "掩盖", "explanations": {"掩盖": "掩盖：把真相遮住，使人不知道，与“揭露”互为反义。", "保护": "与“揭露”无反义关系，保护指照顾、防止受到伤害。", "修建": "与“揭露”无反义关系，修建指建造房屋、道路等。", "欣赏": "与“揭露”无反义关系，欣赏指赞美、喜爱。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
