INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把藏起来的坏事告诉大家。", "primary_collocate": null, "pronunciation": "jiē lù", "ipa": "tɕjɛ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "记者揭露了这家公司的秘密。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把工厂的问题揭露了出来。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸揭露了这个骗子的真面目。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她勇敢地揭露了学校里的问题。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章揭露了很多坏事。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不怕危险，揭露了老板的做法。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视台揭露过这家饭店的卫生问题。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的坏事终于有人揭露了。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要揭露骗人的广告。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把工厂排污的事揭露给大家。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "揭露了", "label": "体标"}, {"form": "揭露过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把别人隐藏的坏事公开告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "揭露", "is_correct": true, "explanation": "揭露：把隐藏的坏事公开告诉大家，正确答案。"}, {"text": "接力", "is_correct": false, "explanation": "lì 与 lù 的韵母不同（i 与 u），接力指接替传递，意思不同。"}, {"text": "节录", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，意思是摘录一部分。"}, {"text": "借路", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，意思是借道通过。"}], "explanations": {"揭露": "揭露：把隐藏的坏事公开告诉大家，正确答案。", "接力": "lì 与 lù 的韵母不同（i 与 u），接力指接替传递，意思不同。", "节录": "jié（第二声）与 jiē（第一声）声调不同，意思是摘录一部分。", "借路": "jiè（第四声）与 jiē（第一声）声调不同，意思是借道通过。"}, "sentence_index": null, "correct_answer": "揭露"}, "level_3": {"options": [{"text": "揭露", "is_correct": true, "explanation": "揭露：把隐藏的秘密公开，与“记者”和“秘密”的搭配相符，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能和“秘密”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物或机器，不能说修理秘密。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，记者不是在创造公司的秘密。"}], "explanations": {"揭露": "揭露：把隐藏的秘密公开，与“记者”和“秘密”的搭配相符，符合句意。", "增加": "搭配：“增加”说的是数量，不能和“秘密”搭配。", "修理": "搭配：“修理”用于器物或机器，不能说修理秘密。", "发明": "语义：“发明”指创造新事物，记者不是在创造公司的秘密。"}, "sentence_index": 0, "correct_answer": "揭露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市长揭露了新建的纪念碑。", "explanation": "这里应该用〈揭幕〉。揭露针对隐藏的坏事，为纪念碑、雕像等举行仪式揭开遮布要用揭幕。"}, {"text": "妈妈揭露了锅盖。", "explanation": "这里应该用〈揭开〉。揭露指把隐藏的坏事公开，掀开锅盖这类具体动作要用揭开。"}, {"text": "科学家揭露了一颗新行星。", "explanation": "这里应该用〈发现〉。揭露针对隐藏的坏事，发现新事物要用发现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揭露", "is_correct": true, "explanation": "揭露：把隐藏的卫生问题公开，与“电视台”和“过”相符，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用于卫生问题。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增多，与卫生问题无关。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”针对方案或物品，不能说设计卫生问题。"}], "explanations": {"揭露": "揭露：把隐藏的卫生问题公开，与“电视台”和“过”相符，符合句意。", "种植": "语义：“种植”指栽种植物，不能用于卫生问题。", "繁殖": "语义：“繁殖”指生物增多，与卫生问题无关。", "设计": "搭配：“设计”针对方案或物品，不能说设计卫生问题。"}, "sentence_index": 6, "correct_answer": "揭露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府揭露了放假的决定。", "explanation": "这里应该用〈宣布〉。揭露针对隐藏的坏事，宣布决定这类公开消息要用宣布。"}, {"text": "数学家揭露了这个定理。", "explanation": "这里应该用〈证明〉。揭露针对隐藏的坏事，证明定理要用证明。"}, {"text": "工程师揭露了一种新机器。", "explanation": "这里应该用〈发明〉。揭露针对隐藏的坏事，创造新事物要用发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查揭露了出公司的问题。", "corrected_sentence": "这次调查揭露出了公司的问题。", "error_description": "“揭露出”后面直接带宾语时，“了”要放在“出”之后，说“揭露出了公司的问题”。“揭露了出公司的问题”语序不对。（“揭露了出来”这种说法是正确的。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经揭露了过那个骗局。", "corrected_sentence": "他曾经揭露过那个骗局。", "error_description": "“过”表示曾经有过的经历，直接接在“揭露”后。“了”和“过”不能同时用，正确是“揭露过”，应删去多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
