INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89906, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使隐蔽的事情（多指坏事）显露出来。", "primary_collocate": null, "pronunciation": "jiē lù", "ipa": "tɕjɛ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这本书揭露了社会的黑暗面。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "调查揭露了一件多年前的大案。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事揭露了人心的自私。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者的报道揭露了药厂的假账。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事揭露出公司管理的问题。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的日记揭露了许多不为人知的事。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影揭露了战争背后的真相。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查揭露了不少问题。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想揭露这个行业的内幕。", "target_word": "揭露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻揭露了工厂污染河水的事实。", "target_word": "揭露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "揭露了", "label": "体标"}, {"form": "揭露过", "label": "体标"}], "register": "书面", "sense_fingerprint": "使隐蔽的坏事显露出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va