INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "揭露", "is_correct": true, "explanation": "揭露：使隐蔽的坏事显露出来，正确答案。"}, {"text": "接力", "is_correct": false, "explanation": "lì 与 lù 的韵母不同（i 与 u），接力指接替传递，意思不同。"}, {"text": "节录", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，意思是摘录一部分。"}, {"text": "借路", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，意思是借道通过。"}], "explanations": {"揭露": "揭露：使隐蔽的坏事显露出来，正确答案。", "接力": "lì 与 lù 的韵母不同（i 与 u），接力指接替传递，意思不同。", "节录": "jié（第二声）与 jiē（第一声）声调不同，意思是摘录一部分。", "借路": "jiè（第四声）与 jiē（第一声）声调不同，意思是借道通过。"}, "sentence_index": null, "correct_answer": "揭露"}, "level_3": {"options": [{"text": "揭露", "is_correct": true, "explanation": "揭露：使隐蔽的坏事显露出来，与“这本书”和“黑暗面”相符，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物或机器，不能说修理黑暗面。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，书不能发明社会的黑暗面。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，与社会的黑暗面无关。"}], "explanations": {"揭露": "揭露：使隐蔽的坏事显露出来，与“这本书”和“黑暗面”相符，符合句意。", "修理": "搭配：“修理”用于器物或机器，不能说修理黑暗面。", "发明": "语义：“发明”指创造新事物，书不能发明社会的黑暗面。", "种植": "语义：“种植”指栽种植物，与社会的黑暗面无关。"}, "sentence_index": 0, "correct_answer": "揭露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校揭露了一座新食堂。", "explanation": "这里应该用〈启用〉。揭露的对象是隐蔽的事情，新食堂是实体建筑，学校启用新食堂要用启用。"}, {"text": "小明揭露了盒子。", "explanation": "这里应该用〈揭开〉。揭露指把隐藏的坏事公开，打开盒子这类具体动作要用揭开。"}, {"text": "老师揭露了一棵大树。", "explanation": "这里应该用〈栽〉。揭露的对象是隐蔽的事情，大树是实体，栽树要用栽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, vali