INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房产是属于一个人的房子。", "primary_collocate": null, "pronunciation": "fáng chǎn", "ipa": "faŋ˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他父母在老家有一处房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用自己的名字买了房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把房产留给了女儿。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结婚前就有一套房产了。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房产在市中心，价格很高。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱他打算用来买房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们离婚后，房产分给了妻子。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷去世后，他继承了爷爷的房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在两个城市都有房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想卖掉房产，去国外生活。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处房产", "label": "量词"}, {"form": "一套房产", "label": "量词"}], "register": "中性", "sense_fingerprint": "属于个人的房子，常说买房产、继承房产、有房产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房产", "is_correct": true, "explanation": "房产：属于个人的房屋，与“一处”及“老家”的语境相符。"}, {"text": "伤口", "is_correct": false, "explanation": "语义：“伤口”指身体上的创伤，不是可以拥有的房屋财产。"}, {"text": "疼痛", "is_correct": false, "explanation": "搭配：“疼痛”是身体的感觉，不能用“一处”指老家拥有的东西。"}, {"text": "罪行", "is_correct": false, "explanation": "语义：“罪行”指犯罪的行为，与“父母在老家有”的语境不合。"}], "explanations": {"房产": "房产：属于个人的房屋，与“一处”及“老家”的语境相符。", "伤口": "语义：“伤口”指身体上的创伤，不是可以拥有的房屋财产。", "疼痛": "搭配：“疼痛”是身体的感觉，不能用“一处”指老家拥有的东西。", "罪行": "语义：“罪行”指犯罪的行为，与“父母在老家有”的语境不合。"}, "sentence_index": 0, "correct_answer": "房产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在租房产住。", "explanation": "这里应该用〈房子〉。房产指属于自己的房屋，租来住的要用房子。"}, {"text": "他每天都在房产里加班。", "explanation": "这里应该用〈办公室〉。房产是属于个人的房屋，不能当作工作场所。"}, {"text": "他每个月都要交一笔房产。", "explanation": "这里应该用〈房租〉。房产是房屋财产，每月要交的是房租，不能说交房产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房产", "is_correct": true, "explanation": "房产：属于个人的房屋财产，离婚后可以分给配偶，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是读书的花费，不是可以分配的财产，与句意不合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学习任务，与“离婚后分给妻子”的语境不合。"}, {"text": "户口", "is_correct": false, "explanation": "语义：“户口”是户籍登记，不是可以分给配偶的财产，与句意不合。"}], "explanations": {"房产": "房产：属于个人的房屋财产，离婚后可以分给配偶，符合句意。", "学费": "语义：“学费”是读书的花费，不是可以分配的财产，与句意不合。", "作业": "语义：“作业”指学习任务，与“离婚后分给妻子”的语境不合。", "户口": "语义：“户口”是户籍登记，不是可以分给配偶的财产，与句意不合。"}, "sentence_index": 6, "correct_answer": "房产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生的房产都花在了旅游上。", "explanation": "这里应该用〈积蓄〉。房产是房屋等财产，不能像积蓄一样拿来花费。"}, {"text": "他的房产都存在银行里。", "explanation": "这里应该用〈存款〉。房产是房屋，不能存进银行。"}, {"text": "他的房产主要是股票和债券。", "explanation": "这里应该用〈资产〉。房产指房屋等不动产，股票和债券不属于房产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了两只房产。", "corrected_sentence": "她买了两套房产。", "error_description": "错误在量词：“只”用于动物或单个器物，不能计量房产。正确形式是“两套房产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的房产们都在市中心。", "corrected_sentence": "他们的房产都在市中心。", "error_description": "错误在“房产们”：“们”只用于人或指人的名词，不能加在“房产”后。正确形式是“房产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
