INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "个人或单位拥有的房屋及其所属的财产。", "primary_collocate": null, "pronunciation": "fáng chǎn", "ipa": "faŋ˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司有很多房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的房产由专人管理。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行可以查到他名下的房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司把一部分房产租出去了。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的房产价值很高。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院查封了他的全部房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单位的房产要重新登记。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房产和存款都在妻子名下。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出售了位于市中心的房产。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清点房产时，他们发现少了一间房。", "target_word": "房产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处房产", "label": "量词"}, {"form": "一套房产", "label": "量词"}], "register": "中性", "sense_fingerprint": "个人或单位名下的房屋财产，常说名下的房产、查封房产、出售房产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房产", "is_correct": true, "explanation": "房产：公司拥有的房屋财产，与“很多”及句意相符。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：“蚊子”是昆虫，不是公司拥有的财产，句子不通。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：“疾病”指身体的病变，公司不能“有很多疾病”。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“雨水”是自然降水，不能与“公司有”搭配。"}], "explanations": {"房产": "房产：公司拥有的房屋财产，与“很多”及句意相符。", "蚊子": "语义：“蚊子”是昆虫，不是公司拥有的财产，句子不通。", "疾病": "语义：“疾病”指身体的病变，公司不能“有很多疾病”。", "雨水": "搭配：“雨水”是自然降水，不能与“公司有”搭配。"}, "sentence_index": 0, "correct_answer": "房产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批房产已经运到了港口。", "explanation": "这里应该用〈货物〉。房产是房屋和所属财产，不能像货物一样运到港口。"}, {"text": "这家公司的房产昨天请假了。", "explanation": "这里应该用〈职员〉。房产不能请假，请假的应是职员。"}, {"text": "这家公司的房产今年分了红。", "explanation": "这里应该用〈股东〉。分红是分给股东的，房产不能分红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房产", "is_correct": true, "explanation": "房产：单位拥有的房屋财产，需要重新登记，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，不需要登记，也不属于单位。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是餐食，不是需要重新登记的对象。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“重新登记”的对象多为证件、财产、人员，不能说“重新登记”水果。"}], "explanations": {"房产": "房产：单位拥有的房屋财产，需要重新登记，符合句意。", "天气": "语义：“天气”是气象状况，不需要登记，也不属于单位。", "午饭": "语义：“午饭”是餐食，不是需要重新登记的对象。", "水果": "搭配：“重新登记”的对象多为证件、财产、人员，不能说“重新登记”水果。"}, "sentence_index": 6, "correct_answer": "房产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的房产每天都在加班。", "explanation": "这里应该用〈员工〉。房产是建筑，不会加班，加班的应是员工。"}, {"text": "这家公司的房产少了两箱货。", "explanation": "这里应该用〈库存〉。房产指房屋财产，不能用来指货物的数量。"}, {"text": "查看房产余额，发现钱不够了。", "explanation": "这里应该用〈账户〉。“房产”指房屋财产，没有“余额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们公司买了两台房产。", "corrected_sentence": "他们公司买了两处房产。", "error_description": "错误在量词：“台”用于机器、仪器，不能计量房产。正确形式是“两处房产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的房产们都很值钱。", "corrected_sentence": "这家公司的房产都很值钱。", "error_description": "错误在“房产们”：“们”只用于人或指人的名词，不能加在“房产”后。正确形式是“房产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
