INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家里大家怎样选人、怎样一起决定大事。", "primary_collocate": null, "pronunciation": "zhèng zhì shēng huó", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ ʂɤŋ˥ xuo˧˥", "syllable_count": 4, "sentences": [{"text": "投票选领导人是民主国家政治生活的一部分。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举是一个国家政治生活中很重要的事。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，政治生活很民主，大事要大家一起决定。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了那个国家的政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个公民都有投票的权利，这是政治生活的基础。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是古代国家的政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王死了以后，国家的政治生活变了。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举结束后，国家的政治生活恢复了平静。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，每人一票是政治生活的重要原则。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会开会决定大事，是政治生活的一部分。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国家里选人和共同决定大事的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治生活", "is_correct": true, "explanation": "正确：“政治生活”指国家里选人、决定大事的方式，与“投票选领导人”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，与“投票选领导人”这类政治活动无关。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“投票选领导人”与饮食无关，句意不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲话，与句中正式的政治表述不协调。"}], "explanations": {"政治生活": "正确：“政治生活”指国家里选人、决定大事的方式，与“投票选领导人”相合。", "冰箱": "语义：冰箱是电器，与“投票选领导人”这类政治活动无关。", "饮食": "语义：“投票选领导人”与饮食无关，句意不通。", "八卦": "语域：“八卦”是口语化的闲话，与句中正式的政治表述不协调。"}, "sentence_index": 0, "correct_answer": "政治生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和同学的政治生活很简单，每天一起去食堂吃饭。", "explanation": "这里的“政治生活”指国家里选人和决定大事的方式，不指个人的日常交往。"}, {"text": "这家咖啡店每天卖政治生活，客人很多。", "explanation": "这里应该用〈饮料〉。政治生活指选人和决定大事的方式，是抽象的状况或制度，不是可以卖的东西，卖的应是饮料。"}, {"text": "这个国家的政治生活在选举中获得了多数席位。", "explanation": "这里应该用〈政党〉。政治生活指选人和决定大事的方式，本身不能获得席位，获得席位的是政党。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治生活", "is_correct": true, "explanation": "正确：“国家的政治生活”指国家里选人和决定大事的方式，国王去世后可以发生变化。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”属于个人身体指标，不能说“国家的体重”变了。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育运动，与“国王死了以后”引起的国家变化无关。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭属于日常饮食，句中的“国家的”变化不指它。"}], "explanations": {"政治生活": "正确：“国家的政治生活”指国家里选人和决定大事的方式，国王去世后可以发生变化。", "体重": "搭配：“体重”属于个人身体指标，不能说“国家的体重”变了。", "篮球": "语义：篮球是体育运动，与“国王死了以后”引起的国家变化无关。", "早饭": "语义：早饭属于日常饮食，句中的“国家的”变化不指它。"}, "sentence_index": 6, "correct_answer": "政治生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上大声朗读政治生活。", "explanation": "这里应该用〈文章〉。政治生活指选人和决定大事的方式，不是可以朗读的文字，朗读的应是文章或讲稿。"}, {"text": "这位医生每天精心做的是政治生活，患者都很满意。", "explanation": "这里应该用〈治疗〉。政治生活指选人和决定大事的方式，不是医生给病人做的工作，能够精心完成的是治疗。"}, {"text": "我家的政治生活很规律，早上六点起床，晚上十点睡觉。", "explanation": "这里的“政治生活”指国家里选人和决定大事的方式，不指个人的作息规律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家经过改革，进入了一颗新的政治生活。", "corrected_sentence": "这个国家经过改革，进入了一种新的政治生活。", "error_description": "错误在于量词：“政治生活”前应用“种”，写成“一颗”是错误的。“颗”用于粒状的小东西，不能修饰抽象的“生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们把政治生活看很重要。", "corrected_sentence": "人们把政治生活看得很重要。", "error_description": "补语漏“得”：“看”后面表示程度的“很重要”要用“得”连接，应说“看得很重要”，不能说“看很重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
