INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公民参与国家和社会公共事务的活动及相关状况。", "primary_collocate": null, "pronunciation": "zhèng zhì shēng huó", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ ʂɤŋ˥ xuo˧˥", "syllable_count": 4, "sentences": [{"text": "公民应该积极参加国家的政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时就开始参与政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天看报纸，关心国家的政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人对政治生活越来越有兴趣。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民可以自由地参加政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的活动让学生了解政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，女人也有权参加政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休以后，不再参加政治生活了。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸和网络让更多人关注政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小国，人人都可以参加政治生活。", "target_word": "政治生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "公民参与国家公共事务的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治生活", "is_correct": true, "explanation": "正确：“参加国家的政治生活”指公民参与国家公共事务。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是公民可以参加的公共事务。"}, {"text": "个人隐私", "is_correct": false, "explanation": "语义：隐私属于个人领域，与“国家”的公共事务正好相反。"}, {"text": "饭局", "is_correct": false, "explanation": "语域：“饭局”口语随意，与句子正式的政治表述不协调，“国家的饭局”搭配也不自然。"}], "explanations": {"政治生活": "正确：“参加国家的政治生活”指公民参与国家公共事务。", "厨房": "语义：厨房是做饭的地方，不是公民可以参加的公共事务。", "个人隐私": "语义：隐私属于个人领域，与“国家”的公共事务正好相反。", "饭局": "语域：“饭局”口语随意，与句子正式的政治表述不协调，“国家的饭局”搭配也不自然。"}, "sentence_index": 0, "correct_answer": "政治生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饮料厂的政治生活已经生产了十年。", "explanation": "这里应该用〈饮料〉。政治生活指公民参与公共事务的活动及相关状况，不是工厂生产的东西，生产的应是饮料。"}, {"text": "他和女朋友的政治生活很甜蜜。", "explanation": "这里的“政治生活”指公民参与国家公共事务的活动及相关状况，不能用来指私人的感情生活。"}, {"text": "他在超市买了一份政治生活，带回家读。", "explanation": "这里应该用〈报纸〉。政治生活指公民参与公共事务的状况或活动，不是可以买的东西，买的应是报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治生活", "is_correct": true, "explanation": "正确：“参加政治生活”指女性也有权参与国家公共事务。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“参加”多与活动、会议连用，“早餐”是饮食，不能说“参加早餐”。"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”不是可以参加的活动，句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动或组织，“地铁”是交通设施，不能作“参加”的宾语。"}], "explanations": {"政治生活": "正确：“参加政治生活”指女性也有权参与国家公共事务。", "早餐": "搭配：“参加”多与活动、会议连用，“早餐”是饮食，不能说“参加早餐”。", "梦": "语义：“梦”不是可以参加的活动，句意不通。", "地铁": "配价：“参加”的宾语应是活动或组织，“地铁”是交通设施，不能作“参加”的宾语。"}, "sentence_index": 6, "correct_answer": "政治生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他负责切社区的政治生活，大家都很爱吃。", "explanation": "这里应该用〈蛋糕〉。政治生活指公民参与公共事务的活动及相关状况，不是可以切开吃的东西，切来吃的应是蛋糕。"}, {"text": "他的政治生活得了九十分，老师很满意。", "explanation": "这里应该用〈成绩〉。政治生活指状况，不能用来得分，得分的应是考试成绩。"}, {"text": "他每天早上都在厨房里煮政治生活当早饭。", "explanation": "这里应该用〈粥〉。政治生活是抽象的状况，不能煮来吃，煮来当早饭的应是粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从二十岁起就投身于一只积极的政治生活。", "corrected_sentence": "他从二十岁起就投身于一种积极的政治生活。", "error_description": "错误在于量词：“政治生活”前应用“种”，写成“一只”是错误的。“只”用于动物或成对的物品，不能修饰抽象的“生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该关心国家的一种的政治生活。", "corrected_sentence": "我们应该关心国家的政治生活。", "error_description": "错误在于在“国家的”后多加了“一种的”：“一种”后不能再加“的”直接修饰名词，应直接说“国家的政治生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
