INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "所部是某个将领自己带领的队伍。", "primary_collocate": null, "pronunciation": "suǒ bù", "ipa": "suɔ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "将军检查了所部的武器。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的所部驻在山下的小村子里。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所部里有很多老兵。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到命令，所部马上上马出发。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让所部在树林里等着。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军带着所部打了很多胜仗。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗中，所部伤了不少人。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军夸奖了所部的士兵。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所部走了一天，终于到了山口。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请求皇上让所部留在北方。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "将领自己带领的队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所部", "is_correct": true, "explanation": "所部：将领自己带领的队伍，可以被检查武器，符合句意。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“武器”一般属于军队或士兵，不说粮食有武器。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林是自然景观，没有武器可以检查。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是队伍，不配备武器，句意不通。"}], "explanations": {"所部": "所部：将领自己带领的队伍，可以被检查武器，符合句意。", "粮食": "搭配：“武器”一般属于军队或士兵，不说粮食有武器。", "树林": "语义：树林是自然景观，没有武器可以检查。", "河流": "语义：河流不是队伍，不配备武器，句意不通。"}, "sentence_index": 0, "correct_answer": "所部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "所部每年都要缴纳税款。", "explanation": "这里应该用〈百姓〉。所部是军队，不缴纳税款。"}, {"text": "所部在田里种了很多麦子。", "explanation": "这里应该用〈农民〉。所部是将领带领的军队，不是种地的人。"}, {"text": "所部颁布了新的法令。", "explanation": "这里应该用〈官府〉。所部只是将领统率的部队，不能颁布法令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所部", "is_correct": true, "explanation": "所部：将领自己带领的队伍，战斗中可以伤人，符合句意。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本是记账的册子，不能伤人，句意不通。"}, {"text": "粮草", "is_correct": false, "explanation": "配价：“伤”需要能施加伤害的主语，粮草不能作为伤人的施事。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不是战斗中的施事，与“战斗中”的语境不合。"}], "explanations": {"所部": "所部：将领自己带领的队伍，战斗中可以伤人，符合句意。", "账本": "语义：账本是记账的册子，不能伤人，句意不通。", "粮草": "配价：“伤”需要能施加伤害的主语，粮草不能作为伤人的施事。", "河水": "语义：河水不是战斗中的施事，与“战斗中”的语境不合。"}, "sentence_index": 6, "correct_answer": "所部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "县令每天都要审理案件，所部也是如此。", "explanation": "这里应该用〈县令〉。所部是军队，不审理案件。"}, {"text": "所部在街上大声叫卖。", "explanation": "这里应该用〈商贩〉。所部是军队，不做买卖。"}, {"text": "所部在教室里认真读书。", "explanation": "这里应该用〈学生〉。所部指将领的部队，不指在校读书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带领一个所部驻扎在山下。", "corrected_sentence": "他带领所部驻扎在山下。", "error_description": "所部已指“他自己带领的队伍”，前面一般不加数量词，“一个所部”不对；去掉“一个”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的所部们都驻在城外。", "corrected_sentence": "他的所部都驻在城外。", "error_description": "词类错误：所部是集合名词，指整支队伍，不能加“们”表示复数，应说“所部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
