INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指所统率或所属的部队、部属。", "primary_collocate": null, "pronunciation": "suǒ bù", "ipa": "suɔ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "将军命令所部在河边休息。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着所部连夜赶到了城下。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，所部立刻准备作战。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军的所部有三千多人。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所部的士兵都很年轻。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所部分成两队，一队守城。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮前，所部就出发了。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军很爱护所部的每一个兵。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所部没有粮食，只好向后退。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨中，他率领所部过了河。", "target_word": "所部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某将领所统率或所属的部队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所部", "is_correct": true, "explanation": "所部：将军统率的部队，能接受命令、在河边休息，符合句意。"}, {"text": "营房", "is_correct": false, "explanation": "语义：营房是固定的建筑，不能接受命令去河边休息。"}, {"text": "公文", "is_correct": false, "explanation": "语义：公文是文件，不会在河边休息，句意不通。"}, {"text": "河床", "is_correct": false, "explanation": "搭配：“命令”的对象须是人或部队，不说命令河床。"}], "explanations": {"所部": "所部：将军统率的部队，能接受命令、在河边休息，符合句意。", "营房": "语义：营房是固定的建筑，不能接受命令去河边休息。", "公文": "语义：公文是文件，不会在河边休息，句意不通。", "河床": "搭配：“命令”的对象须是人或部队，不说命令河床。"}, "sentence_index": 0, "correct_answer": "所部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的所部很强大。", "explanation": "这里应该用〈军队〉。所部只指某位将领自己统率的队伍，不能指全国的武装力量。"}, {"text": "他带领一位所部冲上了山坡。", "explanation": "这里应该去掉〈一位〉。所部指自己统率的整支部队，不用数量词计数，“位”更只用于人。"}, {"text": "这个所部负责管理全城的档案。", "explanation": "这里应该用〈部门〉。所部是军事单位，不指负责档案的行政机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所部", "is_correct": true, "explanation": "所部：将军统率的部队，可以在天亮前出发，符合句意。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是食物，不会出发，句意荒谬。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是固定的构件，不能出发。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“出发”的主语须是人或队伍，不说河水出发。"}], "explanations": {"所部": "所部：将军统率的部队，可以在天亮前出发，符合句意。", "早饭": "语义：早饭是食物，不会出发，句意荒谬。", "窗户": "语义：窗户是固定的构件，不能出发。", "河水": "搭配：“出发”的主语须是人或队伍，不说河水出发。"}, "sentence_index": 6, "correct_answer": "所部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批所部是他从商店买来的。", "explanation": "这里应该用〈货物〉。所部指部队或部属，不指买来的商品。"}, {"text": "所部向全军下达了命令。", "explanation": "这里应该用〈上级〉。所部是被统率的部队，不能向全军下达命令。"}, {"text": "所部负责征收全县的赋税。", "explanation": "这里应该用〈税吏〉。所部是军队的单位，不负责征税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一个所部留在了城外。", "corrected_sentence": "他把所部留在了城外。", "error_description": "量词错误：所部指自己统率的部队，前面不加“一个”等数量词，应直接说“所部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他率领一位所部翻过了山岭。", "corrected_sentence": "他率领所部翻过了山岭。", "error_description": "量词错误：所部指部队，不能用“位”计量（“位”用于人），应直接说“所部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
