INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里的第几个月。", "primary_collocate": null, "pronunciation": "yuè fèn", "ipa": "ɥe˥˩ fən˥˩", "syllable_count": 2, "sentences": [{"text": "你的生日在几月份？", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "二月份只有二十八天或二十九天。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "三月份是春天，天气慢慢变暖了。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "我是十月份出生的。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "九月份学校开学。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "十二月份是一年里的最后一个月。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "五月份有劳动节，大家都放假。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "他八月份去北京，九月份回来。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "十二月份很冷，我常常在家看书。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}, {"text": "我们的比赛在七月份举行。", "target_word": "月份", "complexity_tier": "T3", "furigana": "yuè fèn", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "月份：一年里的第几个月，前面常带数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "约分", "is_correct": false, "explanation": "yuē fēn 与 yuè fèn 两个音节声调都不同，意思是数学中的约分，不是月份。"}, {"text": "月份", "is_correct": true, "explanation": "月份（yuè fèn）指一年里的第几个月。"}, {"text": "岳父", "is_correct": false, "explanation": "fù 与 fèn 韵母不同（n 换成 u），声调相同，意思是岳父。"}, {"text": "月费", "is_correct": false, "explanation": "fèi 与 fèn 韵尾不同（n 换成 i），声调相同，意思是每月的费用。"}], "explanations": {"约分": "yuē fēn 与 yuè fèn 两个音节声调都不同，意思是数学中的约分，不是月份。", "月份": "月份（yuè fèn）指一年里的第几个月。", "岳父": "fù 与 fèn 韵母不同（n 换成 u），声调相同，意思是岳父。", "月费": "fèi 与 fèn 韵尾不同（n 换成 i），声调相同，意思是每月的费用。"}, "sentence_index": null, "correct_answer": "月份"}, "level_3": {"options": [{"text": "月份", "is_correct": true, "explanation": "“几月份”问一年里的第几个月，与“生日在”搭配，符合句意。"}, {"text": "年", "is_correct": false, "explanation": "语义：“几年”指年数，不指一年中的第几个月，与此处所问不符。"}, {"text": "点", "is_correct": false, "explanation": "搭配：“几点”问钟点，生日不说“在几点”。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“几小时”表示时长，不能用来询问生日所在的月份。"}], "explanations": {"月份": "“几月份”问一年里的第几个月，与“生日在”搭配，符合句意。", "年": "语义：“几年”指年数，不指一年中的第几个月，与此处所问不符。", "点": "搭配：“几点”问钟点，生日不说“在几点”。", "小时": "语义：“几小时”表示时长，不能用来询问生日所在的月份。"}, "sentence_index": 0, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在国外待了三个月份。", "explanation": "这里“月份”用错了。“月份”指一年中的某个月，不表示一段时间；说待了多长时间，应改用“几个月”之类的说法。"}, {"text": "今晚的月份很圆，我们在院子里看。", "explanation": "这里应该用〈月亮〉。“月份”指一年中的某个月，不指天上的月亮。"}, {"text": "这本书的出版月份是一九九八年。", "explanation": "这里应该用〈年份〉。“月份”只能表示月，不能用来表示年份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世纪", "is_correct": false, "explanation": "语义：“五世纪”指公元五世纪，是很长的历史时期，不是一年中的某个月，与劳动节不符。"}, {"text": "月份", "is_correct": true, "explanation": "“五月份”指一年中的第五个月，劳动节在这个月，符合句意。"}, {"text": "分钟", "is_correct": false, "explanation": "语义：“五分钟”太短，不能说明节日所在的时间。"}, {"text": "季度", "is_correct": false, "explanation": "搭配：「季度」只用于一季度至四季度，没有「五季度」，句子不成立。"}], "explanations": {"世纪": "语义：“五世纪”指公元五世纪，是很长的历史时期，不是一年中的某个月，与劳动节不符。", "月份": "“五月份”指一年中的第五个月，劳动节在这个月，符合句意。", "分钟": "语义：“五分钟”太短，不能说明节日所在的时间。", "季度": "搭配：「季度」只用于一季度至四季度，没有「五季度」，句子不成立。"}, "sentence_index": 6, "correct_answer": "月份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的比赛月份定在七月十号。", "explanation": "这里应该用〈日期〉。“月份”指一个月，不能用来定下具体的某一天。"}, {"text": "比赛在下午三月份开始。", "explanation": "这里应该用〈三点〉。表示钟点要说“下午三点”；“三月份”指一年中的第三个月。"}, {"text": "这一张月份对我们很重要。", "explanation": "这里应该用〈个〉作量词。“月份”用“个”计量，“张”不能修饰“月份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友是三个月份结婚的。", "corrected_sentence": "我的朋友是三月份结婚的。", "error_description": "错误：数字与“月份”之间多加了量词“个”。“三月份”是固定说法，数字后直接接“月份”，不加量词，应说“三月份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份月份我们要开一次大会。", "corrected_sentence": "这个月份我们要开一次大会。", "error_description": "错误：量词用错。“月份”应与量词“个”搭配，说“这个月份”；“份”不能修饰“月份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
