INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把子是一把一把捆好的东西。", "primary_collocate": null, "pronunciation": "bǎ zi", "ipa": "pa˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他把干草捆成一个个把子，放在墙边。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些把子要放在太阳下晒干。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用绳子把柴火扎成了把子。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里堆着十几个把子。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着一个大把子上山了。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把子捆得太松，一拿就散了。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烧火时，爷爷一次放两个把子。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些把子搬到屋后去。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个把子都一样粗。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的把子被雨淋湿了。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "一把一把捆好的东西，如草、柴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89915, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：一把一把捆好的东西，如草、柴，与释义一致。"}, {"text": "耙子", "is_correct": false, "explanation": "声母与声调不同：耙 pá（第二声）与把 bǎ 只差声母送气与声调，意思是耙子。"}, {"text": "板子", "is_correct": false, "explanation": "韵母不同：板 bǎn 比把 bǎ 多一个 -n，意思是木板。"}, {"text": "把式", "is_correct": false, "explanation": "声母不同：把式的式与子只差声母（sh/z），意思是本领、套路。"}], "explanations": {"把子": "把子：一把一把捆好的东西，如草、柴，与释义一致。", "耙子": "声母与声调不同：耙 pá（第二声）与把 bǎ 只差声母送气与声调，意思是耙子。", "板子": "韵母不同：板 bǎn 比把 bǎ 多一个 -n，意思是木板。", "把式": "声母不同：把式的式与子只差声母（sh/z），意思是本领、套路。"}, "sentence_index": null, "correct_answer": "把子"}, "level_3": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：成捆的草柴，可以用干草捆成，符合句意。"}, {"text": "锅碗", "is_correct": false, "explanation": "语义：锅碗是餐具，不是干草捆成的东西。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块不能用干草捆成，句意不通。"}, {"text": "布匹", "is_correct": false, "explanation": "搭配：布匹一般说“卷”或“匹”，不说“捆成”一个个布匹。"}], "explanations": {"把子": "把子：成捆的草柴，可以用干草捆成，符合句意。", "锅碗": "语义：锅碗是餐具，不是干草捆成的东西。", "石块": "语义：石块不能用干草捆成，句意不通。", "布匹": "搭配：布匹一般说“卷”或“匹”，不说“捆成”一个个布匹。"}, "sentence_index": 0, "correct_answer": "把子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里堆着十几个把子，都是刚烧好的砖。", "explanation": "这里应该用〈砖垛〉。把子是捆好的草或柴，砖不能捆成把子。"}, {"text": "院子里堆着十几根把子。", "explanation": "这里应该用〈个〉或〈捆〉。把子是成捆的东西，不用“根”计量。"}, {"text": "院子里堆着十几张把子。", "explanation": "这里应该用〈个〉或〈捆〉。“张”用于平面的东西，不能用来数把子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89915, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：一把一把捆好的东西，如草、柴，与释义一致。"}, {"text": "坝子", "is_correct": false, "explanation": "声调不同：坝 bà（第四声）与把 bǎ（第三声）只差声调，意思是平地、堤坝。"}, {"text": "疤子", "is_correct": false, "explanation": "声调不同：疤 bā（第一声）与把 bǎ（第三声）只差声调，意思是伤疤。"}, {"text": "帕子", "is_correct": false, "explanation": "声母送气与声调不同：帕 pà（第四声）与把 bǎ（第三声）只差声母送气与声调，意思是手帕。"}], "explanations": {"把子": "把子：一把一把捆好的东西，如草、柴，与释义一致。", "坝子": "声调不同：坝 bà（第四声）与把 bǎ（第三声）只差声调，意思是平地、堤坝。", "疤子": "声调不同：疤 bā（第一声）与把 bǎ（第三声）只差声调，意思是伤疤。", "帕子": "声母送气与声调不同：帕 pà（第四声）与把 bǎ（第三声）只差声母送气与声调，意思是手帕。"}, "sentence_index": null, "correct_answer": "把子"}, "level_3": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：成捆的柴草，可以一次放两个进灶里烧火，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来烧火，句意不合。"}, {"text": "水桶", "is_correct": false, "explanation": "搭配：烧火要放的是燃料，水桶不能与“烧火”搭配。"}, {"text": "锅铲", "is_correct": false, "explanation": "语义：锅铲是炊具，不能当柴火放进灶里。"}], "explanations": {"把子": "把子：成捆的柴草，可以一次放两个进灶里烧火，符合句意。", "石头": "语义：石头不能用来烧火，句意不合。", "水桶": "搭配：烧火要放的是燃料，水桶不能与“烧火”搭配。", "锅铲": "语义：锅铲是炊具，不能当柴火放进灶里。"}, "sentence_index": 6, "correct_answer": "把子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地上躺着一只把子，被雨淋湿了。", "explanation": "这里应该用〈个〉或〈捆〉。“只”用于动物或成对的物件，不用来数把子。"}, {"text": "地上躺着一条把子，被雨淋湿了。", "explanation": "这里应该用〈捆〉。“条”用于长而窄的物件，成捆的草柴不说一条把子。"}, {"text": "地上躺着一颗把子，被雨淋湿了。", "explanation": "这里应该用〈捆〉。“颗”用于颗粒状或圆的东西，把子不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把柴火捆成了一根把子，放在门口。", "corrected_sentence": "他把柴火捆成了一个把子，放在门口。", "error_description": "量词错误：把子是成捆的东西，应用“个”计量，“根”用于细长的物件，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子抱起了两条把子。", "corrected_sentence": "他一下子抱起了两个把子。", "error_description": "量词错误：把子是成捆的东西，应用“个”计量，“条”用于长条形物件，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
