INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "器物上供手握持的部分，即把柄、把手。", "primary_collocate": null, "pronunciation": "bǎ zi", "ipa": "pa˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "锅的把子断了，不能用了。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一手抓住门的把子，用力一拉，门就开了。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个把子太滑，我拿不稳。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把子上有油，擦一擦吧。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把刀的把子是木头做的。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，水壶的把子很烫。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人给锄头换了新把子。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子的把子坏了，我提不起来。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抓着车上的把子，站得很稳。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把子松了，要拧紧一点。", "target_word": "把子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "器物上用手握持的部分，把柄、把手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e0884d8-666b-47f2-ad3a-c0e5471c2632') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：器物上用手握持的部分，如刀把、锅把，与释义一致。"}, {"text": "耙子", "is_correct": false, "explanation": "声母与声调不同：耙 pá（第二声）与把 bǎ 只差声母送气与声调，意思是耙子。"}, {"text": "板子", "is_correct": false, "explanation": "韵母不同：板 bǎn 比把 bǎ 多一个 -n，意思是木板。"}, {"text": "把式", "is_correct": false, "explanation": "声母不同：把式的式与子只差声母（sh/z），意思是本领、套路。"}], "explanations": {"把子": "把子：器物上用手握持的部分，如刀把、锅把，与释义一致。", "耙子": "声母与声调不同：耙 pá（第二声）与把 bǎ 只差声母送气与声调，意思是耙子。", "板子": "韵母不同：板 bǎn 比把 bǎ 多一个 -n，意思是木板。", "把式": "声母不同：把式的式与子只差声母（sh/z），意思是本领、套路。"}, "sentence_index": null, "correct_answer": "把子"}, "level_3": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：锅上用手握的部分，锅的把子断了就不能用，符合句意。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：树枝不是锅的部件，“锅的树枝断了”说不通。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：烟囱属于灶台，不属于锅，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“断”一般说物件折断，窗户不说“断”，常说“破”或“坏”。"}], "explanations": {"把子": "把子：锅上用手握的部分，锅的把子断了就不能用，符合句意。", "树枝": "语义：树枝不是锅的部件，“锅的树枝断了”说不通。", "烟囱": "语义：烟囱属于灶台，不属于锅，句意不通。", "窗户": "搭配：“断”一般说物件折断，窗户不说“断”，常说“破”或“坏”。"}, "sentence_index": 0, "correct_answer": "把子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那把刀的把子很锋利。", "explanation": "这里应该用〈刀刃〉。把子指器物上的握柄，刀刃才是锋利的部分，握柄不说锋利。"}, {"text": "这张把子上有油，擦一擦吧。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，把子不能用“张”计量。"}, {"text": "这座山的把子很高。", "explanation": "这里应该用〈山顶〉。把子指器物上的握柄，山没有握柄，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：器物上用手握持的部分，如刀把、锅把，与释义一致。"}, {"text": "坝子", "is_correct": false, "explanation": "声调不同：坝 bà（第四声）与把 bǎ（第三声）只差声调，意思是平地、堤坝。"}, {"text": "疤子", "is_correct": false, "explanation": "声调不同：疤 bā（第一声）与把 bǎ（第三声）只差声调，意思是伤疤。"}, {"text": "帕子", "is_correct": false, "explanation": "声母送气与声调不同：帕 pà（第四声）与把 bǎ（第三声）只差声母送气与声调，意思是手帕。"}], "explanations": {"把子": "把子：器物上用手握持的部分，如刀把、锅把，与释义一致。", "坝子": "声调不同：坝 bà（第四声）与把 bǎ（第三声）只差声调，意思是平地、堤坝。", "疤子": "声调不同：疤 bā（第一声）与把 bǎ（第三声）只差声调，意思是伤疤。", "帕子": "声母送气与声调不同：帕 pà（第四声）与把 bǎ（第三声）只差声母送气与声调，意思是手帕。"}, "sentence_index": null, "correct_answer": "把子"}, "level_3": {"options": [{"text": "把子", "is_correct": true, "explanation": "把子：锄头上用手握的部分，工人可以给锄头换新把子，符合句意。"}, {"text": "铁锈", "is_correct": false, "explanation": "搭配：“换”的对象须是可替换的部件，铁锈不能用“换”。"}, {"text": "草", "is_correct": false, "explanation": "语义：草不是锄头的部件，“换了新草”说不通。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不属于锄头，“给锄头换了新鞋”句意荒谬。"}], "explanations": {"把子": "把子：锄头上用手握的部分，工人可以给锄头换新把子，符合句意。", "铁锈": "搭配：“换”的对象须是可替换的部件，铁锈不能用“换”。", "草": "语义：草不是锄头的部件，“换了新草”说不通。", "鞋": "语义：鞋不属于锄头，“给锄头换了新鞋”句意荒谬。"}, "sentence_index": 6, "correct_answer": "把子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只把子松了，要拧紧一点。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的物件，不用来数把子。"}, {"text": "这颗把子松了，要拧紧一点。", "explanation": "这里应该用〈个〉。“颗”用于颗粒状的东西，把子不能用“颗”计量。"}, {"text": "这团把子松了，要拧紧一点。", "explanation": "这里应该用〈个〉。“团”指揉成的一团东西，器物的握柄不用“团”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张锅的把子太滑，我拿不稳。", "corrected_sentence": "这个锅的把子太滑，我拿不稳。", "error_description": "量词错误：把子是器物的握柄，应用“个”计量，“张”用于平面的东西，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人给这把锄头换了一条新把子。", "corrected_sentence": "工人给这把锄头换了一个新把子。", "error_description": "量词错误：把子是器物的握柄，应用“个”计量，“条”不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54519a74-c58a-4199-83b5-0caa5eeea762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧", "is_correct": true, "explanation": "正确。“紧”与“松”是反义词，指系、绑得结实不松。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度高，与“不紧”无关。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”指形状像圆圈，与“不紧”无关。"}, {"text": "高", "is_correct": false, "explanation": "“高”指位置或数值大，与“不紧”无关。"}], "correct_answer": "紧", "explanations": {"紧": "正确。“紧”与“松”是反义词，指系、绑得结实不松。", "快": "“快”指速度高，与“不紧”无关。", "圆": "“圆”指形状像圆圈，与“不紧”无关。", "高": "“高”指位置或数值大，与“不紧”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧", "is_correct": true, "explanation": "正确。“紧”与“松”是反义词，指系、绑得结实不松。"}, {"text": "红", "is_correct": false, "explanation": "“红”指颜色，与“不紧”无关。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”指味道，与“不紧”无关。"}, {"text": "湿", "is_correct": false, "explanation": "“湿”指含水多，与“不紧”无关。"}], "correct_answer": "紧", "explanations": {"紧": "正确。“紧”与“松”是反义词，指系、绑得结实不松。", "红": "“红”指颜色，与“不紧”无关。", "甜": "“甜”指味道，与“不紧”无关。", "湿": "“湿”指含水多，与“不紧”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不紧，一拉就开。", "primary_collocate": null, "pronunciation": "sōng", "ipa": "sʊŋ˥", "syllable_count": 1, "sentences": [{"text": "你的鞋带太松了，快系紧一点。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根绳子系得很松，一拉就开了。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螺丝有点松，桌子一动就响。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的领带打得太松，看起来不整齐。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶盖拧得很松，水都流出来了。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的腰带有点松，要换一条。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋口扎得太松，里面的米掉了出来。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表带子太松，一抬手就往下滑。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷的绳子绑得太松，风一吹就倒了。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的锁坏了，门把手也很松。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "松了", "label": "体标"}, {"form": "松开", "label": "复合词"}, {"form": "松垮", "label": "复合词"}, {"form": "鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "松·形容词·系、绑、拧得不紧，一拉就开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。松，sōng，意思是不紧、一拉就开。"}, {"text": "送", "is_correct": false, "explanation": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。"}, {"text": "葱", "is_correct": false, "explanation": "cōng 与 sōng 声母不同（c 与 s），意思是葱。"}, {"text": "桑", "is_correct": false, "explanation": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。"}, {"text": "搜", "is_correct": false, "explanation": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}], "explanations": {"松": "正确。松，sōng，意思是不紧、一拉就开。", "送": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。", "葱": "cōng 与 sōng 声母不同（c 与 s），意思是葱。", "桑": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。", "搜": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}, "sentence_index": null, "correct_answer": "松"}, "level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“你的鞋带太松了”中，“松”指鞋带不紧，与“快系紧一点”相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不说鞋带的松紧。"}, {"text": "紧", "is_correct": false, "explanation": "语义：“太紧了”与后半句“快系紧一点”矛盾，鞋带已经够紧就不用再系紧。"}, {"text": "高", "is_correct": false, "explanation": "搭配：鞋带说长短、松紧，不说高低。"}], "explanations": {"松": "正确。“你的鞋带太松了”中，“松”指鞋带不紧，与“快系紧一点”相符。", "甜": "搭配：“甜”说味道，不说鞋带的松紧。", "紧": "语义：“太紧了”与后半句“快系紧一点”矛盾，鞋带已经够紧就不用再系紧。", "高": "搭配：鞋带说长短、松紧，不说高低。"}, "sentence_index": 0, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜很松，孩子也能抱起来。", "explanation": "这里应该用〈轻〉。松指不紧，不能用来说重量，说重量小要用“轻”。"}, {"text": "这辆车开得很松，大家都跟着它走。", "explanation": "这里应该用〈慢〉。松不用来形容车速，开得慢要用“慢”。"}, {"text": "这个操场很松，孩子们可以随便跑。", "explanation": "这里应该用〈宽〉。松指不紧，说场地的大小要用“宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“袋口扎得太松，里面的米掉了出来”中，“松”指袋口扎得不紧。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“扎得太结实”说明扎得很紧，与“米掉了出来”矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“扎”后不接“亮”，不说“扎得太亮”。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”说潮湿，不说扎口的松紧。"}], "explanations": {"松": "正确。“袋口扎得太松，里面的米掉了出来”中，“松”指袋口扎得不紧。", "结实": "语义：“扎得太结实”说明扎得很紧，与“米掉了出来”矛盾。", "亮": "搭配：“扎”后不接“亮”，不说“扎得太亮”。", "湿": "搭配：“湿”说潮湿，不说扎口的松紧。"}, "sentence_index": 6, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很松，大家都冻得发抖。", "explanation": "这里应该用〈冷〉。松表示不紧，说屋里温度低要用“冷”。"}, {"text": "这个孩子很松，一学就会。", "explanation": "这里应该用〈聪明〉。松表示不紧，说人头脑灵活要用“聪明”。"}, {"text": "这碗汤很松，咸得大家都喝不下去。", "explanation": "这里应该用〈咸〉。松表示不紧，说汤的味道咸要用“咸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的鞋带系得松很，走路时总是开。", "corrected_sentence": "他的鞋带系得很松，走路时总是开。", "error_description": "错误形式“松很”，正确应为“很松”。形容词作补语时，程度副词“很”要放在形容词之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把包袱扎很松，东西都掉了出来。", "corrected_sentence": "他把包袱扎得很松，东西都掉了出来。", "error_description": "错误形式“扎很松”，正确应为“扎得很松”。动词与程度补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧", "is_correct": true, "explanation": "正确。“紧”与“松”是反义词，指不松散、结实。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指光线充足或明亮，与“不紧”无关。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”指形状像圆圈，与“不紧”无关。"}, {"text": "深", "is_correct": false, "explanation": "“深”指距离表面远，与“不紧”无关。"}], "correct_answer": "紧", "explanations": {"紧": "正确。“紧”与“松”是反义词，指不松散、结实。", "亮": "“亮”指光线充足或明亮，与“不紧”无关。", "圆": "“圆”指形状像圆圈，与“不紧”无关。", "深": "“深”指距离表面远，与“不紧”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧", "is_correct": true, "explanation": "正确。“紧”与“松”是反义词，指不松散、结实。"}, {"text": "红", "is_correct": false, "explanation": "“红”指颜色，与“不紧”无关。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”指味道，与“不紧”无关。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度低，与“不紧”无关。"}], "correct_answer": "紧", "explanations": {"紧": "正确。“紧”与“松”是反义词，指不松散、结实。", "红": "“红”指颜色，与“不紧”无关。", "甜": "“甜”指味道，与“不紧”无关。", "冷": "“冷”指温度低，与“不紧”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不紧；不紧密。", "primary_collocate": null, "pronunciation": "sōng", "ipa": "sʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这块地的土很松，种花很容易。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣织得太松，冬天穿不暖。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李包得太松，里面的东西乱动。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布织得很松，能看到后面的东西。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪刚下过，地上的雪很松，一脚踩下去很深。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子里的东西放得太松，还可以再放一些。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发编得有点松，看起来很轻。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕很松，口感很好。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这床棉被的棉花很松，盖起来很暖和。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子太松了，房子不能盖在上面。", "target_word": "松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "松了", "label": "体标"}, {"form": "松松的", "label": "重叠"}, {"form": "松软", "label": "复合词"}, {"form": "鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "松·形容词·质地、结构不紧密", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。松，sōng，意思是不紧。"}, {"text": "送", "is_correct": false, "explanation": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。"}, {"text": "葱", "is_correct": false, "explanation": "cōng 与 sōng 声母不同（c 与 s），意思是葱。"}, {"text": "桑", "is_correct": false, "explanation": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。"}, {"text": "搜", "is_correct": false, "explanation": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}], "explanations": {"松": "正确。松，sōng，意思是不紧。", "送": "sòng（第四声）与 sōng（第一声）声调不同，意思是送。", "葱": "cōng 与 sōng 声母不同（c 与 s），意思是葱。", "桑": "sāng 与 sōng 韵母不同（a 与 o），意思是桑树。", "搜": "sōu 与 sōng 韵尾不同（u 与 ng），意思是搜索。"}, "sentence_index": null, "correct_answer": "松"}, "level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“这块地的土很松，种花很容易”中，“松”指土质不紧实，便于种花。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地坚实，与“种花很容易”矛盾。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格，不说土的质地。"}, {"text": "紧", "is_correct": false, "explanation": "语义：“紧”指板结、密实，同样不利于种花，与“种花很容易”矛盾。"}], "explanations": {"松": "正确。“这块地的土很松，种花很容易”中，“松”指土质不紧实，便于种花。", "硬": "语义：“硬”指质地坚实，与“种花很容易”矛盾。", "贵": "搭配：“贵”说价格，不说土的质地。", "紧": "语义：“紧”指板结、密实，同样不利于种花，与“种花很容易”矛盾。"}, "sentence_index": 0, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子很松，我一个人能抬起来。", "explanation": "这里应该用〈轻〉。松指结构不紧，说重量小要用“轻”。"}, {"text": "他的动作很松，大家都在等他。", "explanation": "这里应该用〈慢〉。松不用来形容速度，动作慢要用“慢”。"}, {"text": "这条路很松，两辆车能并排走。", "explanation": "这里应该用〈宽〉。松指不紧，说路面的宽窄要用“宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "松", "is_correct": true, "explanation": "正确。“她的头发编得有点松，看起来很轻”中，“松”指编得不紧。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”指分量大，与“看起来很轻”矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“编”后不接“亮”，不说“编得有点亮”。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“编得”后不说“湿”，“湿”说潮湿，不说编织的松紧。"}], "explanations": {"松": "正确。“她的头发编得有点松，看起来很轻”中，“松”指编得不紧。", "重": "语义：“重”指分量大，与“看起来很轻”矛盾。", "亮": "搭配：“编”后不接“亮”，不说“编得有点亮”。", "湿": "搭配：“编得”后不说“湿”，“湿”说潮湿，不说编织的松紧。"}, "sentence_index": 6, "correct_answer": "松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小区很松，夜里大家都睡得很早。", "explanation": "这里应该用〈安静〉。松表示不紧，说环境清静、没有噪音要用“安静”。"}, {"text": "这辆车开得很松，一下就超过了大家。", "explanation": "这里应该用〈快〉。松表示不紧，说车速快要用“快”。"}, {"text": "这间屋子很松，大家都热得出汗。", "explanation": "这里应该用〈热〉。松表示不紧，说屋里温度高要用“热”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
