INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89919, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "捉是用手抓住，不让它跑掉。", "primary_collocate": null, "pronunciation": "zhuō", "ipa": "ʈʂwo˥", "syllable_count": 1, "sentences": [{"text": "他伸手捉那只青蛙。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑得很快，我捉不住它。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一把捉住了想跑出门的小狗。", "target_word": "捉", "complexity_tier": "T3", "furigana": "mā ma yì bǎ zhuō zhù le xiǎng pǎo chū mén de xiǎo gǒu", "sentence_source": "generated"}, {"text": "弟弟想捉住那只小鸟。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快把那只鸡捉住！", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里捉着一只蚂蚱。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我蹲在地上捉蚂蚁。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫想捉桌上的毛线球。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢走过去，捉住了那只蝴蝶。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常常在草地上捉蚱蜢。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捉了", "label": "体标（了）"}, {"form": "捉着", "label": "体标（着）"}, {"form": "捉过", "label": "体标（过）"}, {"form": "捉住", "label": "复合（结果补语）"}, {"form": "捉不住", "label": "可能补语"}], "register": "口语", "sense_fingerprint": "捉：伸手抓住，不让跑掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 蚱 (Zipf 1.7)','sentence 9 above tier T3: contains vocabulary far above tier T3: 蚱 (Zipf 1.7), 蜢 (Zipf 1.61)']::text[], 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89919, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戳", "is_correct": false, "explanation": "chuō（第一声）与 zhuō（第一声）声母不同（ch 与 zh），意思是用尖的东西刺。"}, {"text": "捉", "is_correct": true, "explanation": "捉（zhuō，第一声）：伸手抓住，不让它跑掉。"}, {"text": "卓", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是高而直、超出一般。"}, {"text": "镯", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是戴在手腕上的环形首饰。"}, {"text": "浊", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊。"}], "explanations": {"戳": "chuō（第一声）与 zhuō（第一声）声母不同（ch 与 zh），意思是用尖的东西刺。", "捉": "捉（zhuō，第一声）：伸手抓住，不让它跑掉。", "卓": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是高而直、超出一般。", "镯": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是戴在手腕上的环形首饰。", "浊": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊。"}, "sentence_index": null, "correct_answer": "捉"}, "level_3": {"options": [{"text": "谢", "is_correct": false, "explanation": "配价：“谢”通常接人作宾语，不能直接带“青蛙”。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”是看文字出声，与伸手的动作不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”接歌曲作宾语，不能带“青蛙”。"}, {"text": "捉", "is_correct": true, "explanation": "捉：伸手抓住那只青蛙，不让它跑掉，与句意相合。"}], "explanations": {"谢": "配价：“谢”通常接人作宾语，不能直接带“青蛙”。", "读": "语义：“读”是看文字出声，与伸手的动作不合。", "唱": "配价：“唱”接歌曲作宾语，不能带“青蛙”。", "捉": "捉：伸手抓住那只青蛙，不让它跑掉，与句意相合。"}, "sentence_index": 0, "correct_answer": "捉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟想捉住那首歌。", "explanation": "这里应该用〈学〉。“捉住”指伸手抓住实物，不能用于歌曲，学一首歌要用“学”。"}, {"text": "妈妈捉住了一个好主意。", "explanation": "这里应该用〈想出〉。“捉住”只用于抓实物或活物，想出的主意不能“捉住”。"}, {"text": "他捉住了那个问题的答案。", "explanation": "这里应该用〈找到〉。“捉住”指用手抓住实物，答案要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89919, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说", "is_correct": false, "explanation": "shuō（第一声）与 zhuō（第一声）声母不同（sh 与 zh），意思是讲话。"}, {"text": "捉", "is_correct": true, "explanation": "捉（zhuō，第一声）：伸手抓住，不让它跑掉。"}, {"text": "浊", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。"}, {"text": "酌", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是斟酒或考虑。"}], "explanations": {"说": "shuō（第一声）与 zhuō（第一声）声母不同（sh 与 zh），意思是讲话。", "捉": "捉（zhuō，第一声）：伸手抓住，不让它跑掉。", "浊": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。", "酌": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是斟酒或考虑。"}, "sentence_index": null, "correct_answer": "捉"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与蹲在地上的动作不合。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不能接“蚂蚁”作宾语。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”针对可以切开的东西，不能用于蚂蚁。"}, {"text": "捉", "is_correct": true, "explanation": "捉：蹲在地上用手抓住蚂蚁，与句意相合。"}], "explanations": {"写": "语义：“写”指书写文字，与蹲在地上的动作不合。", "修": "搭配：“修”不能接“蚂蚁”作宾语。", "切": "搭配：“切”针对可以切开的东西，不能用于蚂蚁。", "捉": "捉：蹲在地上用手抓住蚂蚁，与句意相合。"}, "sentence_index": 6, "correct_answer": "捉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候我常常在草地上捉野花。", "explanation": "这里应该用〈摘〉。“捉”用于活的动物或人，采野花要用“摘”。"}, {"text": "我去超市捉了一瓶牛奶。", "explanation": "这里应该用〈拿〉。牛奶不是活物，从货架上取一瓶牛奶要用“拿”。"}, {"text": "他把碗捉在手里，慢慢走过来。", "explanation": "这里应该用〈端〉。端碗是把碗托在手上，“捉”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他伸手捉了住那只蝴蝶。", "corrected_sentence": "他伸手捉住了那只蝴蝶。", "error_description": "错误在结果补语：“捉住”是复合词，“了”应放在“捉住”之后，应说“捉住了”，不能说“捉了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把那只鸡捉。", "corrected_sentence": "妈妈把那只鸡捉住了。", "error_description": "错误在把字句：“把”字句中的动词后要有补语或“了”等成分，单独的“捉”不能直接放在“把”后，应说“捉住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
