INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手握住或抓住；捕捉。", "primary_collocate": null, "pronunciation": "zhuō", "ipa": "ʈʂwo˥", "syllable_count": 1, "sentences": [{"text": "孩子们在河边捉鱼。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想捉一只蝴蝶。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫在院子里捉老鼠。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在花园里捉了一只虫子。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用网捉住了那只鸟。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察终于捉到了那个小偷。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里捉虫子。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你捉过螃蟹吗？", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们晚上去河里捉青蛙。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰飞下来捉小鸡。", "target_word": "捉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捉了", "label": "体标（了）"}, {"form": "捉着", "label": "体标（着）"}, {"form": "捉过", "label": "体标（过）"}, {"form": "捉住", "label": "复合（结果补语）"}, {"form": "捉到", "label": "复合（结果补语）"}], "register": "口语", "sense_fingerprint": "捉：捕捉动物或人，抓获", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =