INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89920, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戳", "is_correct": false, "explanation": "chuō（第一声）与 zhuō（第一声）声母不同（ch 与 zh），意思是用尖的东西刺或扎。"}, {"text": "捉", "is_correct": true, "explanation": "捉（zhuō，第一声）：用手握住或抓住，多指捕捉活的动物或人。"}, {"text": "卓", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是高而直、超出一般。"}, {"text": "镯", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是戴在手腕上的环形首饰。"}, {"text": "浊", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。"}], "explanations": {"戳": "chuō（第一声）与 zhuō（第一声）声母不同（ch 与 zh），意思是用尖的东西刺或扎。", "捉": "捉（zhuō，第一声）：用手握住或抓住，多指捕捉活的动物或人。", "卓": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是高而直、超出一般。", "镯": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是戴在手腕上的环形首饰。", "浊": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。"}, "sentence_index": null, "correct_answer": "捉"}, "level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "搭配：“修”用于器物或房屋，不能说修鱼。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”通常接歌曲作宾语，不能直接带“鱼”作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与河边抓鱼的情境完全不合。"}, {"text": "捉", "is_correct": true, "explanation": "捉：用手或工具抓住活的鱼，与“河边”和“鱼”的情境相合。"}], "explanations": {"修": "搭配：“修”用于器物或房屋，不能说修鱼。", "唱": "配价：“唱”通常接歌曲作宾语，不能直接带“鱼”作宾语。", "写": "语义：“写”指书写文字，与河边抓鱼的情境完全不合。", "捉": "捉：用手或工具抓住活的鱼，与“河边”和“鱼”的情境相合。"}, "sentence_index": 0, "correct_answer": "捉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于捉住了这次难得的机会。", "explanation": "这里应该用〈抓〉。“抓住机会”是固定搭配，“捉”多指捕捉活的动物或人，不能接“机会”。"}, {"text": "请你捉紧时间，别再拖了。", "explanation": "这里应该用〈抓〉。“抓紧时间”是固定说法，“捉”不能接“时间”。"}, {"text": "他把书捉起来放进了书包。", "explanation": "这里应该用〈抓〉。拿起一本书要用“抓”或“拿”，“捉”只用于捕捉活物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89920, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说", "is_correct": false, "explanation": "shuō（第一声）与 zhuō（第一声）声母不同（sh 与 zh），意思是讲话。"}, {"text": "捉", "is_correct": true, "explanation": "捉（zhuō，第一声）：用手握住或抓住，多指捕捉活的动物或人。"}, {"text": "浊", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。"}, {"text": "酌", "is_correct": false, "explanation": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是斟酒或考虑。"}], "explanations": {"说": "shuō（第一声）与 zhuō（第一声）声母不同（sh 与 zh），意思是讲话。", "捉": "捉（zhuō，第一声）：用手握住或抓住，多指捕捉活的动物或人。", "浊": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是浑浊、不清澈。", "酌": "zhuó（第二声）与 zhuō（第一声）声调不同，意思是斟酒或考虑。"}, "sentence_index": null, "correct_answer": "捉"}, "level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "搭配：“切”针对可以切开的东西，不能用于虫子。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭表面，不能说擦虫子。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是用针线连接布料，与田里的虫子无关。"}, {"text": "捉", "is_correct": true, "explanation": "捉：用手抓住田里的虫子，与“农民”和“田里”的情境相合。"}], "explanations": {"切": "搭配：“切”针对可以切开的东西，不能用于虫子。", "擦": "搭配：“擦”用于擦拭表面，不能说擦虫子。", "缝": "语义：“缝”是用针线连接布料，与田里的虫子无关。", "捉": "捉：用手抓住田里的虫子，与“农民”和“田里”的情境相合。"}, "sentence_index": 6, "correct_answer": "捉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从包里捉出一支笔。", "explanation": "这里应该用〈拿〉。“捉”一般用于活的动物或人，从包里取笔要用“拿”。"}, {"text": "妈妈在厨房里捉了一把菜刀。", "explanation": "这里应该用〈拿〉。菜刀不是活物，“捉”不能用于拿取工具，应说“拿”。"}, {"text": "她把碗捉在手里，慢慢走过来。", "explanation": "这里应该用〈端〉。端碗是把碗托在手上，“捉”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在河边捉了到一条鱼。", "corrected_sentence": "我们在河边捉到了一条鱼。", "error_description": "错误在结果补语“捉到”：“了”应放在复合词“捉到”之后，应说“捉到了”，不能拆成“捉了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快把那只老鼠捉！", "corrected_sentence": "快把那只老鼠捉住！", "error_description": "错误在“把”字句的补语：“把”字句中动词后要有结果补语，应说“快把那只老鼠捉住！”，不能只说“捉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歇业", "is_correct": true, "explanation": "正确：歇业指停止营业，与“营业”构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：散步与营业在任何义项上都不构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：游泳与营业在任何义项上都不构成反义。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：旅行与营业在任何义项上都不构成反义。"}], "correct_answer": "歇业", "explanations": {"歇业": "正确：歇业指停止营业，与“营业”构成反义关系。", "散步": "无反义关系：散步与营业在任何义项上都不构成反义。", "游泳": "无反义关系：游泳与营业在任何义项上都不构成反义。", "旅行": "无反义关系：旅行与营业在任何义项上都不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歇业", "is_correct": true, "explanation": "正确：歇业指停止营业，与“营业”构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌与营业在任何义项上都不构成反义。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：跑步与营业在任何义项上都不构成反义。"}, {"text": "读书", "is_correct": false, "explanation": "无反义关系：读书与营业在任何义项上都不构成反义。"}], "correct_answer": "歇业", "explanations": {"歇业": "正确：歇业指停止营业，与“营业”构成反义关系。", "唱歌": "无反义关系：唱歌与营业在任何义项上都不构成反义。", "跑步": "无反义关系：跑步与营业在任何义项上都不构成反义。", "读书": "无反义关系：读书与营业在任何义项上都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商店开着门卖东西给大家。", "primary_collocate": null, "pronunciation": "yíng yè", "ipa": "iŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这家超市每天早上八点开始营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店晚上十点才结束营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，今天饭馆不营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家水果店每天晚上九点以后就不营业了。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店营业到很晚，我常去买水。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，很多商店都照常营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店二十四小时营业，晚上也能买药。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店还没有营业，门是关着的。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的面包店明天开始营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的小卖部中午不营业。", "target_word": "营业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营业时间", "label": "复合词"}, {"form": "营业额", "label": "复合词"}], "register": "中性", "sense_fingerprint": "商店开门卖东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营业", "is_correct": true, "explanation": "正确：营业指商店开门对外做生意，“早上八点开始营业”符合语义。"}, {"text": "打烊", "is_correct": false, "explanation": "语义：打烊是收工关门，与“早上八点开始”矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：超市不能散步，“开始散步”的主语须是人。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：超市不能锻炼身体，“锻炼”的主语须是人。"}], "explanations": {"营业": "正确：营业指商店开门对外做生意，“早上八点开始营业”符合语义。", "打烊": "语义：打烊是收工关门，与“早上八点开始”矛盾。", "散步": "搭配：超市不能散步，“开始散步”的主语须是人。", "锻炼": "搭配：超市不能锻炼身体，“锻炼”的主语须是人。"}, "sentence_index": 0, "correct_answer": "营业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这个城市营业了十年。", "explanation": "这里“营业”指经营业务，是另一义项；本义项强调商店开门对外卖东西，不用来说某人在某地经营多少年。"}, {"text": "护士今晚通宵营业。", "explanation": "这里应该用〈值班〉。营业的主语须是商家，护士值班不说营业。"}, {"text": "妈妈每天早上在厨房营业。", "explanation": "这里应该用〈做饭〉。营业的主语须是对外卖东西的商店，妈妈在家做饭不说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营业", "is_correct": true, "explanation": "正确：营业指药店开门对外卖药，“二十四小时营业”符合语义。"}, {"text": "关门", "is_correct": false, "explanation": "语义：二十四小时关门与“晚上也能买药”矛盾。"}, {"text": "休息", "is_correct": false, "explanation": "语义：药店二十四小时休息，与“晚上也能买药”矛盾。"}, {"text": "罢工", "is_correct": false, "explanation": "搭配：“罢工”指职工停止工作，不说药店罢工。"}], "explanations": {"营业": "正确：营业指药店开门对外卖药，“二十四小时营业”符合语义。", "关门": "语义：二十四小时关门与“晚上也能买药”矛盾。", "休息": "语义：药店二十四小时休息，与“晚上也能买药”矛盾。", "罢工": "搭配：“罢工”指职工停止工作，不说药店罢工。"}, "sentence_index": 6, "correct_answer": "营业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位司机每天凌晨营业。", "explanation": "这里应该用〈出车〉。营业的主语须是商家，司机出车不说营业。"}, {"text": "这家工厂营业多年，产品很受欢迎。", "explanation": "这里“营业”指经营业务，是另一义项；本义项强调商店开门对外卖东西，不说工厂的生产经营。"}, {"text": "老师每天下午营业。", "explanation": "这里应该用〈上课〉。营业的主语是商家，不能指老师上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店学校旁边营业。", "corrected_sentence": "这家店在学校旁边营业。", "error_description": "介词遗漏：表示处所的“学校旁边”前要用介词“在”引出，应说“在学校旁边营业”，不说“学校旁边营业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店在学校门口还没营业了。", "corrected_sentence": "这家书店在学校门口还没营业。", "error_description": "体助词错误：“没”表示否定时句末不能再用“了”，应说“还没营业”，不说“还没营业了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接管是把别人管的事接过来自己管。", "primary_collocate": null, "pronunciation": "jiē guǎn", "ipa": "tɕje˥ kuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "经理出差了，他的工作由小王接管。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张退休后，儿子接管了他的小店。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病了，姐姐接管了家里的事。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请你接管这个项目。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走了，谁来接管这个班？", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工厂交给我，让我接管。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚接管这个部门，还不太熟。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店是她从父亲手里接管的。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走以后，谁来接管你的工作？", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天才接管这份工作，什么都不懂。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接管了", "label": "体标"}, {"form": "接管过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把别人原来负责的工作或事务接过来，由自己负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接管", "is_correct": true, "explanation": "正确：「接管」指接过别人负责的工作，「他的工作由小王接管」通顺。"}, {"text": "出差", "is_correct": false, "explanation": "配价：「出差」是不及物动词，不能用「由小王」接替「工作」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与交接工作无关，「他的工作由小王吃」不成立。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：「辞职」是离开职位，不是接过别人的工作，「由小王辞职」不通。"}], "explanations": {"接管": "正确：「接管」指接过别人负责的工作，「他的工作由小王接管」通顺。", "出差": "配价：「出差」是不及物动词，不能用「由小王」接替「工作」。", "吃": "语义：「吃」与交接工作无关，「他的工作由小王吃」不成立。", "辞职": "语义：「辞职」是离开职位，不是接过别人的工作，「由小王辞职」不通。"}, "sentence_index": 0, "correct_answer": "接管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去车站接管远方的朋友。", "explanation": "这里应该用〈接待〉。接待是迎接、招待客人；接管是接过事务来管，不能用于迎接人。"}, {"text": "他接管了我的道歉。", "explanation": "这里应该用〈接受〉。接受的是道歉、意见；接管是接过事务来管，不能用于道歉。"}, {"text": "学校接管了三名新生。", "explanation": "这里应该用〈接纳〉。接纳是收下、允许加入；接管是接过事务来管，不能指收下人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接管", "is_correct": true, "explanation": "正确：「他刚接管这个部门」指刚接过部门的管理，句子通顺。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」不能表示接手部门，「他刚洗这个部门」不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」与管理部门无关，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的宾语是歌曲、戏曲等，不能接「部门」。"}], "explanations": {"接管": "正确：「他刚接管这个部门」指刚接过部门的管理，句子通顺。", "洗": "语义：「洗」不能表示接手部门，「他刚洗这个部门」不成立。", "咬": "语义：「咬」与管理部门无关，句子不通。", "唱": "搭配：「唱」的宾语是歌曲、戏曲等，不能接「部门」。"}, "sentence_index": 6, "correct_answer": "接管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导今天上午接管了几位代表。", "explanation": "这里应该用〈接见〉。接见是会见人；接管是接过事务来管，不能用于人。"}, {"text": "他拿起手机，接管了一个电话。", "explanation": "这里应该用〈接〉。接电话是接听；接管不用于电话。"}, {"text": "他伸手接管了飞来的球。", "explanation": "这里应该用〈接住〉。用手接住飞来的东西要说接住；接管指接过事务来管。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很接管这家店。", "corrected_sentence": "她刚接管这家店。", "error_description": "副词错误：「很」是程度副词，不能修饰动作动词「接管」；表示刚发生的时间要用「刚」。应说：她刚接管这家店。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没接管了这家店。", "corrected_sentence": "他没接管这家店。", "error_description": "体标错误：「没」否定动作时，动词后不加「了」。应说：他没接管这家店。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
