INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89924, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "机构、政府或军队接收某个地方、单位或设施，并负责管理。", "primary_collocate": null, "pronunciation": "jiē guǎn", "ipa": "tɕje˥ kuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "战争结束后，政府接管了这座城市。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司破产后，银行接管了所有的工厂。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的公司接管了这家医院。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场由市政府接管，工人没有变。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察接管了现场，大家都往后退。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路已经由国家接管。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们接管了学校，开始重新管理。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板跑了，银行暂时接管了这家店。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队接管了这个地区的安全工作。", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园什么时候由市里接管？", "target_word": "接管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接管了", "label": "体标"}, {"form": "接管过", "label": "体标"}], "register": "中性", "sense_fingerprint": "机构、政府或军队接收某个地方、单位或设施，并负责管理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接管", "is_correct": true, "explanation": "正确：「政府接管了这座城市」指机构接收并管理城市，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能表示接收并管理城市，「政府吃了这座城市」不成立。"}, {"text": "失眠", "is_correct": false, "explanation": "配价：「失眠」是不及物动词，不能带「这座城市」作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」与接收、管理城市无关，句子不通。"}], "explanations": {"接管": "正确：「政府接管了这座城市」指机构接收并管理城市，句子通顺。", "吃": "语义：「吃」不能表示接收并管理城市，「政府吃了这座城市」不成立。", "失眠": "配价：「失眠」是不及物动词，不能带「这座城市」作宾语。", "洗": "语义：「洗」与接收、管理城市无关，句子不通。"}, "sentence_index": 0, "correct_answer": "接管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他接管了朋友送的一份礼物。", "explanation": "这里应该用〈接收〉。礼物是接收的对象；接管是接过事务来管，不能用于礼物。"}, {"text": "选手接管跑完了全程。", "explanation": "这里应该用〈接力〉。接力是一棒接一棒地传递；接管不能用于跑步。"}, {"text": "校长接管了远道而来的客人。", "explanation": "这里应该用〈接见〉。接见是会见客人；接管是接过事务来管，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接管", "is_correct": true, "explanation": "正确：「他们接管了学校，开始重新管理」指接收学校并负责管理，句子通顺。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」只指看一看，不含接收和管理，与后面的「开始重新管理」冲突。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的宾语是歌曲、戏曲等，不能是「学校」。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，不能带「学校」作宾语。"}], "explanations": {"接管": "正确：「他们接管了学校，开始重新管理」指接收学校并负责管理，句子通顺。", "参观": "语义：「参观」只指看一看，不含接收和管理，与后面的「开始重新管理」冲突。", "唱": "搭配：「唱」的宾语是歌曲、戏曲等，不能是「学校」。", "睡": "配价：「睡」是不及物动词，不能带「学校」作宾语。"}, "sentence_index": 6, "correct_answer": "接管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接管了我的话，继续说下去。", "explanation": "这里应该用〈接话〉。接话是接着别人的话往下说；接管不能用于话语。"}, {"text": "他轻松地接管了一个球。", "explanation": "这里应该用〈接球〉。接球是用手或身体接住球；接管是接过事务来管，不能用于球。"}, {"text": "孩子们今天去接管了疫苗。", "explanation": "这里应该用〈接种〉。接种指注射疫苗；接管是接过事务来管，不能用于疫苗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府去年很接管了这座城市。", "corrected_sentence": "政府去年接管了这座城市。", "error_description": "副词错误：「很」是程度副词，不能修饰动作动词「接管」，应删去「很」。应说：政府去年接管了这座城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板跑了，银行暂时没接管了这家店。", "corrected_sentence": "老板跑了，银行暂时没接管这家店。", "error_description": "体标错误：用「没」否定动作时，动词「接管」后不能再加「了」。应说：老板跑了，银行暂时没接管这家店。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
