INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用木头、纸等制成的片状物，可用来标示或做游戏。", "primary_collocate": null, "pronunciation": "pái", "ipa": "pʰai˧˥", "syllable_count": 1, "sentences": [{"text": "路边立着一块牌，上面写着“停”。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的牌上写着“请进”。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脚下有一块木头做的牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店门口挂着一块牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板旁挂了一块牌。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牌上的字太小，我看不清。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在草地上插了一块牌，写着“小心”。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用纸做了几张牌来玩游戏。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看墙上那块牌，上面说今天休息。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用木头做了一块牌，挂在门上。", "target_word": "牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "路牌", "label": "复合"}, {"form": "门牌", "label": "复合"}], "register": "中性", "sense_fingerprint": "牌：用木头或纸做的片状物，写上字用来标示，也可做游戏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89926, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌（pái）：用木头或纸做的片状物，写上字用来标示。"}, {"text": "拍", "is_correct": false, "explanation": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}, {"text": "派", "is_correct": false, "explanation": "pài（第四声）与 pái（第二声）声调不同，意思是派别或派遣。"}, {"text": "白", "is_correct": false, "explanation": "bái 与 pái 声母不同（b 与 p），意思是白色。"}, {"text": "盘", "is_correct": false, "explanation": "pán 与 pái 韵母不同（an 与 ai），意思是盘子。"}, {"text": "台", "is_correct": false, "explanation": "tái 与 pái 声母不同（t 与 p），意思是台子。"}], "explanations": {"牌": "正确。牌（pái）：用木头或纸做的片状物，写上字用来标示。", "拍": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打。", "派": "pài（第四声）与 pái（第二声）声调不同，意思是派别或派遣。", "白": "bái 与 pái 声母不同（b 与 p），意思是白色。", "盘": "pán 与 pái 韵母不同（an 与 ai），意思是盘子。", "台": "tái 与 pái 声母不同（t 与 p），意思是台子。"}, "sentence_index": null, "correct_answer": "牌"}, "level_3": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌：路边的标示牌，写着“停”，与“路边立着……上面写着”的语境相合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：「立着」用于能直立的物体，不能说“立着一块蛋糕”。"}, {"text": "豆腐", "is_correct": false, "explanation": "搭配：「立着」要求物体能直立，豆腐柔软，不能竖立。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：「立着」与「面包」不搭，面包不能竖立在路边。"}], "explanations": {"牌": "正确。牌：路边的标示牌，写着“停”，与“路边立着……上面写着”的语境相合。", "蛋糕": "搭配：「立着」用于能直立的物体，不能说“立着一块蛋糕”。", "豆腐": "搭配：「立着」要求物体能直立，豆腐柔软，不能竖立。", "面包": "搭配：「立着」与「面包」不搭，面包不能竖立在路边。"}, "sentence_index": 0, "correct_answer": "牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小店门口挂着一只牌。", "explanation": "这里应该用〈块〉。“只”用于动物等，“牌”应用“块”或“张”计量。"}, {"text": "小店门口飘着一张牌。", "explanation": "这里应该用〈旗子〉。“牌”指标示用的片状物，不指飘扬的旗子。"}, {"text": "他按了一下门口的牌。", "explanation": "这里应该用〈门铃〉。“牌”指标示用的片状物，不指按下发声的门铃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') 