INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89926, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌（pái）：用木头或纸做的片状物，写上字用来标示。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 pái 声母不同（c 与 p），意思是才能或刚刚。"}, {"text": "来", "is_correct": false, "explanation": "lái 与 pái 声母不同（l 与 p），意思是来到。"}, {"text": "埋", "is_correct": false, "explanation": "mái 与 pái 声母不同（m 与 p），意思是埋藏。"}, {"text": "孩", "is_correct": false, "explanation": "hái 与 pái 声母不同（h 与 p），意思是孩子。"}], "explanations": {"牌": "正确。牌（pái）：用木头或纸做的片状物，写上字用来标示。", "才": "cái 与 pái 声母不同（c 与 p），意思是才能或刚刚。", "来": "lái 与 pái 声母不同（l 与 p），意思是来到。", "埋": "mái 与 pái 声母不同（m 与 p），意思是埋藏。", "孩": "hái 与 pái 声母不同（h 与 p），意思是孩子。"}, "sentence_index": null, "correct_answer": "牌"}, "level_3": {"options": [{"text": "牌", "is_correct": true, "explanation": "正确。牌：写着“小心”的标示牌，与“在草地上插了一块……”的语境相合。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：「肥皂」是洗涤用品，不是草地上的标示物，与“写着‘小心’”的语境不合。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：「插」可以说“插牌子”，不能说“插饼干”。"}, {"text": "冰", "is_correct": false, "explanation": "语义：「冰」会融化，不能作为插在草地上的标示物，与“写着‘小心’”不合。"}], "explanations": {"牌": "正确。牌：写着“小心”的标示牌，与“在草地上插了一块……”的语境相合。", "肥皂": "语义：「肥皂」是洗涤用品，不是草地上的标示物，与“写着‘小心’”的语境不合。", "饼干": "搭配：「插」可以说“插牌子”，不能说“插饼干”。", "冰": "语义：「冰」会融化，不能作为插在草地上的标示物，与“写着‘小心’”不合。"}, "sentence_index": 6, "correct_answer": "牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刷了一张牌进门。", "explanation": "这里应该用〈卡〉。“牌”指标示用的片状物，不用于刷门。"}, {"text": "他把一块牌切开，当作点心吃了。", "explanation": "这里应该用〈蛋糕〉。“牌”是木或纸做的片状物，不能当作点心吃。"}, {"text": "他从口袋里掏出一块牌，用它打开了门锁。", "explanation": "这里应该用〈钥匙〉。“牌”是木或纸做的片状物，不能用来开锁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口挂着一只牌，写着“营业”。", "corrected_sentence": "门口挂着一块牌，写着“营业”。", "error_description": "“牌”的量词用错。“只”用于动物等，“牌”应用“块”，正确形式是“一块牌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这牌块很大。", "corrected_sentence": "这块牌很大。", "error_description": "量词位置颠倒：“块”应在“牌”前，正确形式是“这块牌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
