INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "摩托车是有两个轮子，用发动机开的车。", "primary_collocate": null, "pronunciation": "mó tuō chē", "ipa": "mwo˧˥ tʰwo˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "他每天骑摩托车去上班。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆摩托车有两个轮子。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸新买了一辆摩托车。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车的声音太大了。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有很多摩托车和汽车。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学开摩托车。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的摩托车是红色的。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，摩托车不能骑。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟坐在摩托车后面。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门口停着一辆摩托车。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "摩托车手", "label": "复合"}, {"form": "摩托車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有两个轮子、用发动机开的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩托车", "is_correct": true, "explanation": "摩托车：有两个轮子、用发动机开的车，人可以骑着去上班，符合句意。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：“骑”用于可跨坐或驾驭的车辆，不能说骑飞机。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是交通工具，不能骑着去上班。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：公交车要乘坐，不能说骑公交车。"}], "explanations": {"摩托车": "摩托车：有两个轮子、用发动机开的车，人可以骑着去上班，符合句意。", "飞机": "搭配：“骑”用于可跨坐或驾驭的车辆，不能说骑飞机。", "钢琴": "语义：钢琴不是交通工具，不能骑着去上班。", "公交车": "搭配：公交车要乘坐，不能说骑公交车。"}, "sentence_index": 0, "correct_answer": "摩托车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只摩托车。", "explanation": "这里应该用〈辆〉。摩托车是车辆，量词用辆，“只”多用于动物或成对的东西。"}, {"text": "我每天蹬摩托车去上班。", "explanation": "这里应该用〈骑〉。蹬靠脚踏板带动，多用于自行车；摩托车靠发动机行驶，要说骑摩托车。"}, {"text": "我买了一条摩托车。", "explanation": "这里应该用〈辆〉。“条”多用于细长的东西，如河、裤子，摩托车用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩托车", "is_correct": true, "explanation": "摩托车：可以是红色的车辆，与“他的”和“红色的”相符，符合句意。"}, {"text": "知识", "is_correct": false, "explanation": "语义：知识不能用颜色来形容，“他的知识是红色的”不合理。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，没有颜色，句子不成立。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”指多少，不能用“红色的”来描述。"}], "explanations": {"摩托车": "摩托车：可以是红色的车辆，与“他的”和“红色的”相符，符合句意。", "知识": "语义：知识不能用颜色来形容，“他的知识是红色的”不合理。", "星期": "语义：星期是时间单位，没有颜色，句子不成立。", "数量": "搭配：“数量”指多少，不能用“红色的”来描述。"}, "sentence_index": 6, "correct_answer": "摩托车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一张摩托车。", "explanation": "这里应该用〈辆〉。“张”多用于平面的东西，如桌子、纸，摩托车用“辆”。"}, {"text": "我买了一头摩托车。", "explanation": "这里应该用〈辆〉。“头”多用于牛、猪等牲畜，摩托车用“辆”。"}, {"text": "我买了一把摩托车。", "explanation": "这里应该用〈辆〉。“把”用于带柄的东西，如伞、刀，摩托车用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天用三只摩托车送货。", "corrected_sentence": "他每天用三辆摩托车送货。", "error_description": "“摩托车”的量词应为“辆”，“只”多用于动物或成对的东西。正确是“三辆摩托车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见一辆红色地摩托车。", "corrected_sentence": "我看见一辆红色的摩托车。", "error_description": "修饰语“红色”与“摩托车”之间应用“的”，正确是“红色的摩托车”；此处误用了“地”。“地”用于修饰动词或形容词，不用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
