INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装有发动机的两轮或三轮车辆。", "primary_collocate": null, "pronunciation": "mó tuō chē", "ipa": "mwo˧˥ tʰwo˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "这辆摩托车装有发动机，跑得很快。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车比自行车快多了。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑摩托车带我去了医院。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车没有油了，我们走路吧。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骑摩托车的人戴着帽子。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上不让摩托车进来。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把摩托车停在了楼下。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车修好了，明天可以骑。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥喜欢骑摩托车旅行。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车的轮子坏了。", "target_word": "摩托车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "摩托车手", "label": "复合"}, {"form": "摩托車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装有发动机的两轮或三轮车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩托车", "is_correct": true, "explanation": "摩托车：装有发动机、跑得很快的两轮或三轮车辆，符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“辆”用于车，电视用“台”，而且电视不会跑。"}, {"text": "洗衣机", "is_correct": false, "explanation": "搭配：“辆”用于车，不能说这辆洗衣机。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能装有发动机，也不能跑得很快。"}], "explanations": {"摩托车": "摩托车：装有发动机、跑得很快的两轮或三轮车辆，符合句意。", "电视": "搭配：“辆”用于车，电视用“台”，而且电视不会跑。", "洗衣机": "搭配：“辆”用于车，不能说这辆洗衣机。", "书包": "语义：书包不能装有发动机，也不能跑得很快。"}, "sentence_index": 0, "correct_answer": "摩托车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张摩托车。", "explanation": "这里应该用〈辆〉。“张”多用于平面的东西，摩托车用“辆”。"}, {"text": "他蹬摩托车去学校。", "explanation": "这里应该用〈骑〉。蹬用于靠脚踏板带动的自行车等，摩托车靠发动机，人要坐在上面骑，应说骑摩托车。"}, {"text": "我买了一座摩托车。", "explanation": "这里应该用〈辆〉。“座”多用于山、桥、楼等大而固定的东西，摩托车用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩托车", "is_correct": true, "explanation": "摩托车：可以停放在楼下的车辆，与“把”和“停”相符，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能停放，与“停在楼下”不相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“停”多用于车辆，不能说把桌子停在楼下。"}, {"text": "箱子", "is_correct": false, "explanation": "搭配：“停”用于车辆，箱子一般说放，不说停。"}], "explanations": {"摩托车": "摩托车：可以停放在楼下的车辆，与“把”和“停”相符，符合句意。", "蛋糕": "语义：蛋糕不能停放，与“停在楼下”不相符。", "桌子": "搭配：“停”多用于车辆，不能说把桌子停在楼下。", "箱子": "搭配：“停”用于车辆，箱子一般说放，不说停。"}, "sentence_index": 6, "correct_answer": "摩托车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条摩托车。", "explanation": "这里应该用〈辆〉。“条”多用于细长的东西，摩托车用“辆”。"}, {"text": "他骑着一把摩托车去上班。", "explanation": "这里应该用〈辆〉。“把”用于带柄的东西，如伞、刀，摩托车用“辆”。"}, {"text": "我买了一根摩托车。", "explanation": "这里应该用〈辆〉。“根”多用于细长的东西，如绳子、木头，摩托车用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
