INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日常使用的各种东西。", "primary_collocate": null, "pronunciation": "wù pǐn", "ipa": "u˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "超市里卖的日常物品很便宜。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里的物品都放得很整齐。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个柜子是用来放小物品的。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多生活物品回家。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把个人物品放在桌子上。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失物招领处有很多没人要的物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，旧物品太多了。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物品用完以后要放回原处。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的物品应该让他自己收拾。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家检查自己的物品。", "target_word": "物品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "样", "label": "量词"}], "register": "中性", "sense_fingerprint": "物品：日常生活中使用的各种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以在超市里出售的东西。"}, {"text": "物品", "is_correct": true, "explanation": "正确。超市里出售的日常用品用物品指称，与“很便宜”搭配自然。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不能在超市里卖，与“超市里卖的”矛盾。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“便宜”用于价格，不能用来形容感情。"}], "explanations": {"时间": "语义：时间不是可以在超市里出售的东西。", "物品": "正确。超市里出售的日常用品用物品指称，与“很便宜”搭配自然。", "房间": "语义：房间不能在超市里卖，与“超市里卖的”矛盾。", "感情": "搭配：“便宜”用于价格，不能用来形容感情。"}, "sentence_index": 0, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一辆物品回家。", "explanation": "这里应该用〈件〉。“辆”用于车辆，物品不能用“辆”计量。"}, {"text": "这只小猫是我最可爱的物品。", "explanation": "这里应该用〈宠物〉。宠物指人饲养的动物，物品指人们使用或买卖的东西，不能用来指活的动物。"}, {"text": "他对朋友的信任是一件珍贵的物品。", "explanation": "物品只指有形的东西，信任是抽象的情感，不能称为物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以搬走的东西，与搬家语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是人体器官，不能说“旧眼睛太多了”。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“搬家时”不能与节日这类时间事件搭配。"}, {"text": "物品", "is_correct": true, "explanation": "正确。搬家时要搬运的旧东西用物品指称，语境吻合。"}], "explanations": {"天空": "语义：天空不是可以搬走的东西，与搬家语境不符。", "眼睛": "语义：眼睛是人体器官，不能说“旧眼睛太多了”。", "节日": "搭配：“搬家时”不能与节日这类时间事件搭配。", "物品": "正确。搬家时要搬运的旧东西用物品指称，语境吻合。"}, "sentence_index": 6, "correct_answer": "物品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这部电影的主要物品。", "explanation": "这里应该用〈人物〉。人物指影视、小说中的角色，物品只指东西，不能用来指人。"}, {"text": "北京是我最想去的物品。", "explanation": "这里应该用〈城市〉。城市指人口聚集的地方，物品指人们使用或买卖的东西，不能用来指地方。"}, {"text": "这条河是一件美丽的物品。", "explanation": "这里应该用〈景观〉。景观指自然或人造的风景，物品指人们使用或买卖的东西，河流属于景观，不能称为物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个柜子里放着几本日常物品。", "corrected_sentence": "这个柜子里放着几件日常物品。", "error_description": "错误形式：“几本日常物品”；正确形式：“几件日常物品”。“本”用于书籍等，物品应用量词“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬家那天，我把很多旧物品们都扔掉了。", "corrected_sentence": "搬家那天，我把很多旧物品都扔掉了。", "error_description": "错误形式：“旧物品们”；正确形式：“旧物品”。“们”只用于指人的名词，物品是无生命的东西，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
