INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携手是手拉着手，一起去做事。", "primary_collocate": null, "pronunciation": "xié shǒu", "ipa": "ɕje˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "同学们携手完成了这个项目。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长携手帮助这个孩子。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市携手举办了这次比赛。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们携手走在海边，看着日落。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间应该携手面对困难。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和学校携手培养新人。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩携手走出了小山村。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望以后能和你携手做生意。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国人民携手抗击了这场洪水。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们携手把旧房子改成了咖啡店。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "携手并进", "label": "复合"}, {"form": "携手合作", "label": "复合"}], "register": "书面", "sense_fingerprint": "携手：手拉着手，一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携手", "is_correct": true, "explanation": "正确：句中要表示同学们一起动手完成项目，只有“携手”合适。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉完成了这个项目”不合常理，与句中表示共同做事的意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与完成项目无关，两者不能连用。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“哭泣”不能用来修饰“完成这个项目”。"}], "explanations": {"携手": "正确：句中要表示同学们一起动手完成项目，只有“携手”合适。", "睡觉": "语义：“睡觉完成了这个项目”不合常理，与句中表示共同做事的意思相反。", "唱歌": "语义：唱歌与完成项目无关，两者不能连用。", "哭泣": "搭配：“哭泣”不能用来修饰“完成这个项目”。"}, "sentence_index": 0, "correct_answer": "携手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人携手走回了宿舍。", "explanation": "这里应该用〈独自〉。携手要求两人或多人一起，一个人走路不能说携手。"}, {"text": "她在车窗前携手告别。", "explanation": "这里应该用〈挥手〉。携手指手拉着手，不指挥手告别。"}, {"text": "我一个人携手鼓了掌。", "explanation": "这里应该用〈拍手〉。携手要求两人或多人共同行动，一个人鼓掌只能说拍手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携手", "is_correct": true, "explanation": "正确：姐妹俩一起走出小山村，只有“携手”合适。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞走出了小山村”不合常理，与句意不符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”不能表示走出村子，语义冲突。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”不能表示走出村子，语义冲突。"}], "explanations": {"携手": "正确：姐妹俩一起走出小山村，只有“携手”合适。", "跳舞": "语义：“跳舞走出了小山村”不合常理，与句意不符。", "下棋": "语义：“下棋”不能表示走出村子，语义冲突。", "游泳": "语义：“游泳”不能表示走出村子，语义冲突。"}, "sentence_index": 6, "correct_answer": "携手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师一个人携手端上了菜。", "explanation": "这里应该用〈独自〉。携手要求两人或多人一起，一人端菜不能说携手。"}, {"text": "他携手拒绝了邀请。", "explanation": "这里应该用〈摆手〉。携手不表示摆手拒绝，拒绝的动作要说摆手。"}, {"text": "老人一个人携手祈祷。", "explanation": "这里应该用〈独自〉。携手要求两人或多人一起，单人祈祷不能说携手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个部门携手了解决难题。", "corrected_sentence": "两个部门携手解决难题。", "error_description": "错误形式：“携手了解决难题”；正确形式：“携手解决难题”。“了”不能插在“携手”和后面的动词之间，删去多余的“了”即为正确说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位工人携手了搬走那台旧机器。", "corrected_sentence": "两位工人携手搬走那台旧机器。", "error_description": "错误形式：“携手了搬走那台旧机器”；正确形式：“携手搬走那台旧机器”。“了”不能插在“携手”和后面的动词之间，删去多余的“了”即为正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
