INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "手拉着手；也比喻共同行动。", "primary_collocate": null, "pronunciation": "xié shǒu", "ipa": "ɕje˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两位老人携手走在公园里。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要携手把这件事做好。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司决定携手合作。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们携手走过了五十年。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们携手走进了教室。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让我们携手保护环境。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家携手应对这次困难。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和丈夫携手创办了这家小店。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家携手努力，一定能成功。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新郎新娘携手走上了舞台。", "target_word": "携手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "携手并进", "label": "复合"}, {"form": "携手合作", "label": "复合"}], "register": "书面", "sense_fingerprint": "携手：手拉着手，引申为共同行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携手", "is_correct": true, "explanation": "正确：句中要表示两位老人手拉着手一起走，只有“携手”合适。"}, {"text": "飞", "is_correct": false, "explanation": "语义：人不能像鸟一样飞走，“两位老人飞走在公园里”与常识相悖。"}, {"text": "跳", "is_correct": false, "explanation": "体貌：两位老人年迈，蹦跳着走不符合句中的人物情况。"}, {"text": "爬", "is_correct": false, "explanation": "体貌：“爬”指手脚并用，与老人在公园里正常散步的情景不符。"}], "explanations": {"携手": "正确：句中要表示两位老人手拉着手一起走，只有“携手”合适。", "飞": "语义：人不能像鸟一样飞走，“两位老人飞走在公园里”与常识相悖。", "跳": "体貌：两位老人年迈，蹦跳着走不符合句中的人物情况。", "爬": "体貌：“爬”指手脚并用，与老人在公园里正常散步的情景不符。"}, "sentence_index": 0, "correct_answer": "携手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人携手走进了办公室。", "explanation": "这里应该用〈独自〉。携手要求两人或多人一起，一个人走路不能说携手，应说独自走进。"}, {"text": "她一个人携手鼓了掌。", "explanation": "这里应该用〈拍手〉。携手要求两人或多人共同行动，一人鼓掌只能说拍手，不能说携手。"}, {"text": "她站在窗前携手告别。", "explanation": "这里应该用〈挥手〉。携手指手拉着手，不指挥手告别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携手", "is_correct": true, "explanation": "正确：“携手应对”表示两国共同面对困难，只有“携手”合适。"}, {"text": "对峙", "is_correct": false, "explanation": "语义：“对峙”指双方相持对抗，与共同应对困难的语境相反。"}, {"text": "争执", "is_correct": false, "explanation": "语义：“争执”指争论不休，不表示共同应对困难。"}, {"text": "推诿", "is_correct": false, "explanation": "搭配：“推诿”常说“推诿责任”，不与“应对困难”搭配。"}], "explanations": {"携手": "正确：“携手应对”表示两国共同面对困难，只有“携手”合适。", "对峙": "语义：“对峙”指双方相持对抗，与共同应对困难的语境相反。", "争执": "语义：“争执”指争论不休，不表示共同应对困难。", "推诿": "搭配：“推诿”常说“推诿责任”，不与“应对困难”搭配。"}, "sentence_index": 6, "correct_answer": "携手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她携手向大家致谢。", "explanation": "这里应该用〈拱手〉。携手需要两人或多人一起，句中只有“她”一人，携手的共同之义用不上；单人向大家致谢应说拱手。"}, {"text": "他携手拒绝了邀请。", "explanation": "这里应该用〈摆手〉。携手不表示摆手拒绝，拒绝的动作要说摆手。"}, {"text": "老人一个人携手祈祷。", "explanation": "这里应该用〈独自〉。携手要求两人或多人一起，单人祈祷不能说携手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位同事携手了走进会议室。", "corrected_sentence": "两位同事携手走进会议室。", "error_description": "错误形式：“携手了走进会议室”；正确形式：“携手走进会议室”。“了”不能插在“携手”和后面的动词之间，删去多余的“了”即为正确说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位医生携手了救治病人。", "corrected_sentence": "三位医生携手救治病人。", "error_description": "错误形式：“携手了救治病人”；正确形式：“携手救治病人”。“了”不能插在“携手”和后面的动词之间，删去多余的“了”即为正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。"}, {"text": "早上", "is_correct": false, "explanation": "无反义关系：早上是一天中的时段，与“当今”不构成反义。"}, {"text": "冬天", "is_correct": false, "explanation": "无反义关系：冬天是季节，与“当今”不构成反义。"}, {"text": "星期一", "is_correct": false, "explanation": "无反义关系：星期一是具体的日子，与“当今”不构成反义。"}], "correct_answer": "过去", "explanations": {"过去": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。", "早上": "无反义关系：早上是一天中的时段，与“当今”不构成反义。", "冬天": "无反义关系：冬天是季节，与“当今”不构成反义。", "星期一": "无反义关系：星期一是具体的日子，与“当今”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。"}, {"text": "夏天", "is_correct": false, "explanation": "无反义关系：夏天是季节，与“当今”不构成反义。"}, {"text": "下午", "is_correct": false, "explanation": "无反义关系：下午是一天中的时段，与“当今”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "无反义关系：周末是具体的时间段，与“当今”不构成反义。"}], "correct_answer": "过去", "explanations": {"过去": "反义：此义项的“当今”与“过去”相对，二者构成反义关系。", "夏天": "无反义关系：夏天是季节，与“当今”不构成反义。", "下午": "无反义关系：下午是一天中的时段，与“当今”不构成反义。", "周末": "无反义关系：周末是具体的时间段，与“当今”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在这个时候。", "primary_collocate": null, "pronunciation": "dāng jīn", "ipa": "tɑŋ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "当今的物价比十年前高多了。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的孩子都会用电脑。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的年轻人很少写信了。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的房价让很多人买不起房。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今最受欢迎的歌手是谁？", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太了解当今的流行音乐。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的医生有很多新办法。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，当今的生活比过去好。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的饭馆都可以用手机点菜。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关心当今的新闻。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当今：现在这个时候，与过去相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现在这个时候，与“物价比十年前高多了”的时间比较一致。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代与“比十年前高多了”的时间比较相矛盾。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“童年的物价”不是常用说法，且与“比十年前”的时间不合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子的物价”不成立，与“物价比十年前高多了”无法搭配。"}], "explanations": {"当今": "当今：现在这个时候，与“物价比十年前高多了”的时间比较一致。", "古代": "语义：古代与“比十年前高多了”的时间比较相矛盾。", "童年": "搭配：“童年的物价”不是常用说法，且与“比十年前”的时间不合。", "桌子": "搭配：“桌子的物价”不成立，与“物价比十年前高多了”无法搭配。"}, "sentence_index": 0, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我当今去过北京三次。", "explanation": "这里应该用〈曾经〉。当今指现在，不能与“去过”这种表示过去经历的说法搭配。"}, {"text": "我小时候当今很怕黑。", "explanation": "这里应该用〈从前〉。当今指现在这个时候，与“小时候”所指的过去时间矛盾。"}, {"text": "这台机器是当今那年买的。", "explanation": "这里应该用〈去年〉。当今指现在这个时候，与“那年”所指的过去时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现在这个时候，与“医生有很多新办法”的现代语境一致。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘不是人，不能说“棋盘的医生”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔的医生”不成立，铅笔与“医生有很多新办法”无法构成合理的修饰关系。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子与“医生”不能构成修饰关系，搭配不当。"}], "explanations": {"当今": "当今：现在这个时候，与“医生有很多新办法”的现代语境一致。", "棋盘": "语义：棋盘不是人，不能说“棋盘的医生”。", "铅笔": "语义：“铅笔的医生”不成立，铅笔与“医生有很多新办法”无法构成合理的修饰关系。", "桌子": "搭配：桌子与“医生”不能构成修饰关系，搭配不当。"}, "sentence_index": 6, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他当今出生在北京。", "explanation": "这里应该用〈当年〉。当今指现在这个时候，不能用来说明过去已经发生的出生。"}, {"text": "他当今十岁时很聪明。", "explanation": "这里应该用〈以前〉。当今指现在这个时候，与“十岁时”所指的过去时间矛盾。"}, {"text": "他1995年当今进入这家公司。", "explanation": "这里应该用〈那时候〉。当今指现在这个时候，不能与“1995年”这样的过去时间并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当今地学生都有手机。", "corrected_sentence": "当今的学生都有手机。", "error_description": "错误：“当今”修饰“学生”时应用“的”，“地”是状语标记，不能用在名词前。正确：“当今的学生都有手机。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当今了公交车越来越多了。", "corrected_sentence": "当今的公交车越来越多了。", "error_description": "错误：“当今”修饰“公交车”时应用“的”连接，“了”是动态助词，不能加在“当今”后面。正确：“当今的公交车越来越多了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
