INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现今；目前这个时代。", "primary_collocate": null, "pronunciation": "dāng jīn", "ipa": "tɑŋ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "当今社会，网络已经走进每个家庭。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今世界各国的联系越来越多。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今时代，学会一门外语很重要。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是当今最有名的京剧演员。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的科技发展得非常快。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是当今年轻人的生活。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今，手机已经成了必需品。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今中国的城市变化很大。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究当今世界的经济问题。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当今的学生比以前忙多了。", "target_word": "当今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当今：现今，指目前这个时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f0f2a5-5286-4660-975c-0ee659a6ac06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现今，指目前这个时代，与“社会……网络已经走进每个家庭”的语境一致。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代是很久以前的时代，与“网络已经走进每个家庭”的现状相矛盾。"}, {"text": "过去", "is_correct": false, "explanation": "语义：过去指以往，与“已经走进”描述的当前状态不符。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“童年社会”不是常用说法，也与网络走进家庭的现状不合。"}], "explanations": {"当今": "当今：现今，指目前这个时代，与“社会……网络已经走进每个家庭”的语境一致。", "古代": "语义：古代是很久以前的时代，与“网络已经走进每个家庭”的现状相矛盾。", "过去": "语义：过去指以往，与“已经走进”描述的当前状态不符。", "童年": "搭配：“童年社会”不是常用说法，也与网络走进家庭的现状不合。"}, "sentence_index": 0, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当今，我刚进入这家公司，什么都不懂。", "explanation": "这里应该用〈当时〉。当今指现在，与“刚进入”所描述的过去时间矛盾。"}, {"text": "我父亲当今在上海工作过。", "explanation": "这里应该用〈以前〉。当今指现在，不能与“工作过”这种表示过去经历的说法搭配。"}, {"text": "当今他在这所大学毕业，后来去了上海。", "explanation": "这里应该用〈当年〉。当今指现在，不能用来说明“毕业”这类已经结束的过去事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当今", "is_correct": true, "explanation": "当今：现今，与“手机已经成了必需品”的现状一致。"}, {"text": "从前", "is_correct": false, "explanation": "语义：从前指过去，与“手机已经成了必需品”的现状相矛盾。"}, {"text": "早年", "is_correct": false, "explanation": "语义：早年指早期的年代，与“手机已经成了必需品”的现状相矛盾。"}, {"text": "往昔", "is_correct": false, "explanation": "语义：往昔指过去的年代，与“手机已经成了必需品”描述的现状相矛盾（另因书面色彩较重，与“手机”这类现代词语的语体也不协调）。"}], "explanations": {"当今": "当今：现今，与“手机已经成了必需品”的现状一致。", "从前": "语义：从前指过去，与“手机已经成了必需品”的现状相矛盾。", "早年": "语义：早年指早期的年代，与“手机已经成了必需品”的现状相矛盾。", "往昔": "语义：往昔指过去的年代，与“手机已经成了必需品”描述的现状相矛盾（另因书面色彩较重，与“手机”这类现代词语的语体也不协调）。"}, "sentence_index": 6, "correct_answer": "当今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们当今去公园吧。", "explanation": "这里应该用〈现在〉。当今指现在这个时代，泛指一个时期，不能用来表示眼下、此刻的时间。"}, {"text": "当今，他曾经是班长。", "explanation": "这里应该用〈那时候〉。当今指现在，与“曾经”表示过去经历的说法矛盾。"}, {"text": "我当今去过北京。", "explanation": "这里应该用〈上个月〉。当今指现在这个时代，不能与“去过”这种表示已经发生的经历搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很关心当今地年轻人。", "corrected_sentence": "我很关心当今的年轻人。", "error_description": "错误：“当今”修饰名词时应用“的”，“地”是状语标记，不能用在名词前。正确：“当今的年轻人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当今了汽车越来越安全。", "corrected_sentence": "当今的汽车越来越安全。", "error_description": "错误：“当今”修饰“汽车”时应用“的”连接，“了”是动态助词，不能加在“当今”后面。正确：“当今的汽车越来越安全。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d51fab1-fede-4622-8e2e-8c354300328c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
