INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89935, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新思想是以前没有人想过的好想法。", "primary_collocate": null, "pronunciation": "xīn sī xiǎng", "ipa": "ɕin˥ sɿ˥ ɕjɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他的新思想让公司多赚了很多钱。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我有新思想，因为没人这样想过。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新思想很简单，却能解决大问题。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会上说出了一个新思想。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要新思想，不能总用老办法。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的新思想写在了本子上。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学生的新思想让大家都很吃惊。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给有新思想的人更多机会。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新思想是他想了一个晚上才有的。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的新思想，经理马上点头同意。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个新思想", "label": "量词"}, {"form": "一种新思想", "label": "量词"}], "register": "中性", "sense_fingerprint": "以前没人想过的好想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新思想", "is_correct": true, "explanation": "正确。“他的新思想”作主语，指他提出的好想法，能让公司多赚钱。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能让公司多赚钱，与句中“多赚了很多钱”冲突。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是个人的收入，不是能让公司多赚钱的东西。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“他的天空”不是自然的说法，“天空”也不能让公司赚钱。"}], "explanations": {"新思想": "正确。“他的新思想”作主语，指他提出的好想法，能让公司多赚钱。", "桌子": "语义：“桌子”是家具，不能让公司多赚钱，与句中“多赚了很多钱”冲突。", "工资": "语义：“工资”是个人的收入，不是能让公司多赚钱的东西。", "天空": "搭配：“他的天空”不是自然的说法，“天空”也不能让公司赚钱。"}, "sentence_index": 0, "correct_answer": "新思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的新思想在昨天的考试中得了满分。", "explanation": "语义：〈新思想〉是抽象的想法，不能参加考试、拿满分，这里应指参加考试的学生。"}, {"text": "我每天都要吃一顿新思想。", "explanation": "这里应该用〈提出〉或〈想〉。〈吃〉用于食物，〈新思想〉不能吃。"}, {"text": "他把这个新思想放进了冰箱。", "explanation": "语义：〈新思想〉是抽象的想法，不是实物，不能〈放进冰箱〉。可以说〈把这个新思想写在本子上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新思想", "is_correct": true, "explanation": "正确。“这位学生的新思想”作主语，指学生提出的新想法，能让大家吃惊。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有想法，不能让大家都很吃惊。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能使大家吃惊。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“学生的脚步”不是常见搭配，“脚步”也不宜作使人吃惊的主语。"}], "explanations": {"新思想": "正确。“这位学生的新思想”作主语，指学生提出的新想法，能让大家吃惊。", "石头": "语义：“石头”没有想法，不能让大家都很吃惊。", "窗户": "语义：“窗户”是建筑部件，不能使大家吃惊。", "脚步": "搭配：“学生的脚步”不是常见搭配，“脚步”也不宜作使人吃惊的主语。"}, "sentence_index": 6, "correct_answer": "新思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的新思想今天特别饿，要去吃午饭。", "explanation": "语义：〈新思想〉是想法，不会感到饿，也不能去吃午饭。"}, {"text": "我的新思想三岁了，还很会说话。", "explanation": "语义：〈新思想〉是想法，没有年龄，不能说它几岁了。"}, {"text": "他的新思想每天早上都要洗脸刷牙。", "explanation": "语义：〈新思想〉没有身体，不能做洗脸刷牙这样的日常动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很欣赏他提出的这只新思想。", "corrected_sentence": "老板很欣赏他提出的这个新思想。", "error_description": "错误：〈这只新思想〉。应为〈这个新思想〉。“思想”是抽象概念，量词用〈个〉或〈种〉，〈只〉用于动物或成对的器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在讨论一只新思想。", "corrected_sentence": "我们正在讨论一个新思想。", "error_description": "错误：〈一只新思想〉。应为〈一个新思想〉。〈只〉不用于抽象的想法，量词应用〈个〉或〈种〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧思想", "is_correct": true, "explanation": "反义词：〈旧思想〉与〈新思想〉相对，指旧的、过时的观念，与本义相反。"}, {"text": "大海", "is_correct": false, "explanation": "无关：〈大海〉是自然景物，与〈新思想〉的意义没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：〈桌子〉是家具，与〈新思想〉没有反义关系。"}, {"text": "老朋友", "is_correct": false, "explanation": "无关：〈老朋友〉指相识已久的人，与〈新思想〉的意义不相对。"}], "correct_answer": "旧思想", "explanations": {"旧思想": "反义词：〈旧思想〉与〈新思想〉相对，指旧的、过时的观念，与本义相反。", "大海": "无关：〈大海〉是自然景物，与〈新思想〉的意义没有反义关系。", "桌子": "无关：〈桌子〉是家具，与〈新思想〉没有反义关系。", "老朋友": "无关：〈老朋友〉指相识已久的人，与〈新思想〉的意义不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧思想", "is_correct": true, "explanation": "反义词：〈旧思想〉与〈新思想〉相对，指旧的、过时的观念，与本义相反。"}, {"text": "河流", "is_correct": false, "explanation": "无关：〈河流〉是自然景物，与〈新思想〉没有反义关系。"}, {"text": "木头", "is_correct": false, "explanation": "无关：〈木头〉是材料，与〈新思想〉没有反义关系。"}, {"text": "小狗", "is_correct": false, "explanation": "无关：〈小狗〉是动物，与〈新思想〉的意义不相对。"}], "correct_answer": "旧思想", "explanations": {"旧思想": "反义词：〈旧思想〉与〈新思想〉相对，指旧的、过时的观念，与本义相反。", "河流": "无关：〈河流〉是自然景物，与〈新思想〉没有反义关系。", "木头": "无关：〈木头〉是材料，与〈新思想〉没有反义关系。", "小狗": "无关：〈小狗〉是动物，与〈新思想〉的意义不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新出现的、有别于旧观念的思想。", "primary_collocate": null, "pronunciation": "xīn sī xiǎng", "ipa": "ɕin˥ sɿ˥ ɕjɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "一百年前，新思想从国外传进了中国。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人最先接受了这种新思想。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新思想改变了人们对家庭的看法。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得新思想和旧观念很不一样。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候报纸常常介绍新思想。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的新思想让父母很担心。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新思想一出现，旧观念就受到了挑战。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是那个时代的新思想。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，接触过各种新思想。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会变化很快，新思想一个接一个地出现。", "target_word": "新思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种新思想", "label": "量词"}], "register": "中性", "sense_fingerprint": "有别于旧观念的新出现的思想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新思想", "is_correct": true, "explanation": "正确。“新思想”作主语，指从国外传入的新观念，符合“传进”的语义。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是脚踩出的痕迹，不能从国外传进中国。"}, {"text": "影子", "is_correct": false, "explanation": "语义：“影子”是光照形成的暗影，不是可以传播的事物。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能与“从国外传进中国”搭配，“传进”需要可以传播的事物。"}], "explanations": {"新思想": "正确。“新思想”作主语，指从国外传入的新观念，符合“传进”的语义。", "脚印": "语义：“脚印”是脚踩出的痕迹，不能从国外传进中国。", "影子": "语义：“影子”是光照形成的暗影，不是可以传播的事物。", "心情": "搭配：“心情”不能与“从国外传进中国”搭配，“传进”需要可以传播的事物。"}, "sentence_index": 0, "correct_answer": "新思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的新思想在比赛中拿到了第一名。", "explanation": "语义：〈新思想〉是抽象的观念，不能参加比赛、拿名次，这里应指参赛的人。"}, {"text": "爷爷每天都要喝新思想。", "explanation": "这里应该用〈接受〉或〈学习〉。〈喝〉只用于液体，思想不能喝。"}, {"text": "这张饭桌是一种新思想。", "explanation": "语义：〈饭桌〉是家具，不是思想。〈新思想〉指一种观念，不能说成家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新思想", "is_correct": true, "explanation": "正确。“新思想”作主语，“一出现”就使旧观念受挑战，语义通顺。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”不是观念，“一出现”就使旧观念受挑战，于理不通。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”是植物的部分，“一出现”就使旧观念受挑战，于理不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是矿物，不能使旧观念受到挑战，句子于理不通。"}], "explanations": {"新思想": "正确。“新思想”作主语，“一出现”就使旧观念受挑战，语义通顺。", "饼干": "语义：“饼干”不是观念，“一出现”就使旧观念受挑战，于理不通。", "树叶": "语义：“树叶”是植物的部分，“一出现”就使旧观念受挑战，于理不通。", "石头": "语义：“石头”是矿物，不能使旧观念受到挑战，句子于理不通。"}, "sentence_index": 6, "correct_answer": "新思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的新思想脸很圆，看起来很可爱。", "explanation": "体貌：〈新思想〉没有脸，不能用来描述外貌。"}, {"text": "新思想今年五岁，已经上小学了。", "explanation": "语义：〈新思想〉是想法，没有年龄，不能说它上小学。"}, {"text": "我把新思想的脚扭伤了。", "explanation": "语义：〈新思想〉没有身体，不会扭伤脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师讲了一只新思想。", "corrected_sentence": "这位老师讲了一种新思想。", "error_description": "错误：〈一只新思想〉。应为〈一种新思想〉。〈只〉用于动物或成对的器物，抽象的想法应用〈种〉或〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他接受了一只新思想。", "corrected_sentence": "他接受了一种新思想。", "error_description": "错误：〈一只新思想〉。应为〈一种新思想〉。〈只〉不用于抽象的想法，应用〈种〉或〈个〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
