INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "平民；普通民众。", "primary_collocate": null, "pronunciation": "bǎi xìng", "ipa": "pai˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这位官员很关心百姓的生活。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "百姓都希望过上好日子。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "新路修好了，百姓出门方便多了。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "古时候，百姓住的房子很简单。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "市长常常走进百姓的家里。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "这个办法对百姓很有好处。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "百姓们都来看热闹。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "好官为百姓做了很多事。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "这几年，百姓的收入越来越高。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}, {"text": "战争结束后，百姓终于能安心生活了。", "target_word": "百姓", "complexity_tier": "T3", "furigana": "bǎi xìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "老百姓", "label": "复合"}], "register": "中性", "sense_fingerprint": "百姓：平民，普通民众，常与官员、政府相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：“生活”的主体是人，食物不能“过生活”，句子不通。"}, {"text": "百姓", "is_correct": true, "explanation": "“百姓”指普通民众，与“官员”相对，是“关心”的对象，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是物，没有“生活”，不能说“关心汽车的生活”。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张没有生活，不能被“关心”其“生活”。"}], "explanations": {"食物": "语义：“生活”的主体是人，食物不能“过生活”，句子不通。", "百姓": "“百姓”指普通民众，与“官员”相对，是“关心”的对象，符合句意。", "汽车": "语义：汽车是物，没有“生活”，不能说“关心汽车的生活”。", "纸张": "语义：纸张没有生活，不能被“关心”其“生活”。"}, "sentence_index": 0, "correct_answer": "百姓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里站着三条百姓。", "explanation": "这里应该用〈群〉。“百姓”指人，不用“条”计量；成群时说“一群百姓”。"}, {"text": "这位百姓是我们的市长。", "explanation": "“百姓”指普通民众，与官员相对；市长属于官员，不能用“百姓”指称。"}, {"text": "尊敬的百姓同学们，欢迎大家。", "explanation": "语域：“百姓”指普通民众，不用于敬称或称呼，这种场合应使用“各位”之类的敬称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "配价：“看热闹”要求有生命的主语，桌子不能“来看”热闹。"}, {"text": "百姓", "is_correct": true, "explanation": "“百姓们”指普通民众，会来看热闹，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有“来看热闹”的行为，句子不成立。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不能“来看热闹”，与句子语义冲突。"}], "explanations": {"桌子": "配价：“看热闹”要求有生命的主语，桌子不能“来看”热闹。", "百姓": "“百姓们”指普通民众，会来看热闹，符合句意。", "石头": "语义：石头没有“来看热闹”的行为，句子不成立。", "文件": "语义：文件不能“来看热闹”，与句子语义冲突。"}, "sentence_index": 6, "correct_answer": "百姓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要走百姓路线。", "explanation": "这里应该用〈群众〉。“群众路线”是固定说法，“百姓”不能替换其中的“群众”。"}, {"text": "这家公司的百姓都能分到年终奖。", "explanation": "这里应该用〈员工〉。“百姓”指普通民众，不指公司职工。"}, {"text": "我们用的是百姓币。", "explanation": "这里应该用〈人民〉。“人民币”是固定名称，不能换成“百姓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处走来一只百姓。", "corrected_sentence": "远处走来一群百姓。", "error_description": "错误：量词用错。成群的人用“群”，应说“一群百姓”；“只”用于动物等，不能用于“百姓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个百姓们来到了村口。", "corrected_sentence": "三个百姓来到了村口。", "error_description": "错误：“三个”已表示确定数量，后面的“百姓”不能再加复数词尾“们”，应说“三个百姓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
