INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旅游城市是有很多好玩的地方，别处的人爱去的城市。", "primary_collocate": null, "pronunciation": "lǚ yóu chéng shì", "ipa": "ly²¹⁴ joʊ̯³⁵ ʈʂʰɤŋ³⁵ ʂɻ̩⁵¹", "syllable_count": 4, "sentences": [{"text": "桂林是一座很有名的旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，这个旅游城市有很多外地人。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去一个安静的旅游城市过周末。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三亚是冬天最热闹的旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旅游城市有海，有山，还有老街。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我和家人去了一个南方的旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为是旅游城市，这里的酒店特别多。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个旅游城市工作，每天都见到游客。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丽江这个旅游城市，晚上的小路很漂亮。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢哪个旅游城市？", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "旅遊城市", "label": "繁体"}], "register": "中性", "sense_fingerprint": "好玩的地方多、外地人爱去的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅游城市", "is_correct": true, "explanation": "正确：桂林是风景名胜多、外地人爱去的城市，符合“旅游城市”的意思。"}, {"text": "广场", "is_correct": false, "explanation": "语义：“广场”是公共空地，不能说桂林是一座广场。"}, {"text": "大桥", "is_correct": false, "explanation": "语义：“大桥”是跨越河流的建筑，桂林不是桥，句子不通。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是一栋高的建筑，桂林是城市，不是一座大楼。"}], "explanations": {"旅游城市": "正确：桂林是风景名胜多、外地人爱去的城市，符合“旅游城市”的意思。", "广场": "语义：“广场”是公共空地，不能说桂林是一座广场。", "大桥": "语义：“大桥”是跨越河流的建筑，桂林不是桥，句子不通。", "大楼": "语义：“大楼”是一栋高的建筑，桂林是城市，不是一座大楼。"}, "sentence_index": 0, "correct_answer": "旅游城市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅是很有名的旅游城市，每天都排很长的队。", "explanation": "这里应该用〈网红餐厅〉。旅游城市指一座城市，一家餐厅不是城市，不能这样说。"}, {"text": "这座寺庙是很有名的旅游城市，香火很旺。", "explanation": "这里应该用〈旅游景点〉。旅游城市指一座城市，单个寺庙要用〈旅游景点〉。"}, {"text": "这片海滩是冬天最热闹的旅游城市。", "explanation": "这里应该用〈度假地〉。旅游城市指城市，不能用来指海滩这样的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅游城市", "is_correct": true, "explanation": "正确：“因为是旅游城市”说明游客多，所以酒店多，因果合理。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是售书的地方，“因为是书店，这里的酒店特别多”没有因果联系，与句意不符。"}, {"text": "农村", "is_correct": false, "explanation": "语义：农村一般游客少，用“因为是农村”不能解释酒店特别多。"}, {"text": "小区", "is_correct": false, "explanation": "语义：小区是居民住宅区，“因为是小区，这里的酒店特别多”没有因果联系，与句意不符。"}], "explanations": {"旅游城市": "正确：“因为是旅游城市”说明游客多，所以酒店多，因果合理。", "书店": "语义：书店是售书的地方，“因为是书店，这里的酒店特别多”没有因果联系，与句意不符。", "农村": "语义：农村一般游客少，用“因为是农村”不能解释酒店特别多。", "小区": "语义：小区是居民住宅区，“因为是小区，这里的酒店特别多”没有因果联系，与句意不符。"}, "sentence_index": 6, "correct_answer": "旅游城市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅游城市很愉快，我们玩得很开心。", "explanation": "这里应该用〈旅行〉。旅游城市指城市，不指出行的活动。"}, {"text": "旅游城市是这座城市的重要收入来源。", "explanation": "这里应该用〈旅游业〉。旅游城市是一座城市，不能作为收入的来源。"}, {"text": "这座城市每年要接待很多旅游城市。", "explanation": "这里应该用〈游客〉。旅游城市指城市，不能用来指被接待的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所旅游城市的海边很漂亮。", "corrected_sentence": "这座旅游城市的海边很漂亮。", "error_description": "量词错误：城市应用〈座〉，〈所〉用于学校、医院等，不能用于城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想在一块旅游城市开一家书店。", "corrected_sentence": "我想在一座旅游城市开一家书店。", "error_description": "量词错误：城市应用〈座〉，〈块〉用于片状的东西，不能用于城市。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
