INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以旅游业为重要产业、风景名胜较多的城市。", "primary_collocate": null, "pronunciation": "lǚ yóu chéng shì", "ipa": "ly²¹⁴ joʊ̯³⁵ ʈʂʰɤŋ³⁵ ʂɻ̩⁵¹", "syllable_count": 4, "sentences": [{"text": "杭州是以西湖闻名的旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旅游城市的收入主要靠游客。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为旅游城市，西安有很多古迹。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄山脚下的小城是有名的旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旅游城市每年要接待上千万游客。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游城市的房价常常比别的城市高。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青岛是北方的一座旅游城市，海边风景很美。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想把这里建成国际旅游城市。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多旅游城市在假期会特别拥挤。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个海边的旅游城市开了一家小店。", "target_word": "旅游城市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "旅遊城市", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以旅游业为重要产业、名胜多的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅游城市", "is_correct": true, "explanation": "正确：杭州以西湖闻名，风景名胜多，是旅游城市，与句意相符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不以风景闻名，“以西湖闻名”的主体不能是工厂。"}, {"text": "工业区", "is_correct": false, "explanation": "语义：工业区与西湖没有关系，不能说以西湖闻名。"}, {"text": "矿区", "is_correct": false, "explanation": "语义：矿区是开采矿产的地方，杭州不是矿区，也不以西湖作为矿区闻名。"}], "explanations": {"旅游城市": "正确：杭州以西湖闻名，风景名胜多，是旅游城市，与句意相符。", "工厂": "语义：工厂不以风景闻名，“以西湖闻名”的主体不能是工厂。", "工业区": "语义：工业区与西湖没有关系，不能说以西湖闻名。", "矿区": "语义：矿区是开采矿产的地方，杭州不是矿区，也不以西湖作为矿区闻名。"}, "sentence_index": 0, "correct_answer": "旅游城市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家酒店是黄山脚下有名的旅游城市，房间很多。", "explanation": "这里应该用〈度假酒店〉。旅游城市指一座城市，一家酒店不是城市。"}, {"text": "这座博物馆是有名的旅游城市，每天都有很多游客。", "explanation": "这里应该用〈旅游景点〉。旅游城市指一座城市，单个博物馆要用〈旅游景点〉。"}, {"text": "这条河的旅游城市很美，吸引了很多人来拍照。", "explanation": "这里应该用〈景观〉。旅游城市指城市，不能用来形容一条河的景色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅游城市", "is_correct": true, "explanation": "正确：青岛是北方的一座旅游城市，海边风景美，句意通顺。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是宗教场所，青岛不是寺庙，句子不通。"}, {"text": "大厦", "is_correct": false, "explanation": "语义：大厦是高层建筑，青岛不是大厦，与“海边风景很美”也不协调。"}, {"text": "山", "is_correct": false, "explanation": "语义：青岛是城市，不是一座山，与“海边风景很美”也不协调。"}], "explanations": {"旅游城市": "正确：青岛是北方的一座旅游城市，海边风景美，句意通顺。", "寺庙": "语义：寺庙是宗教场所，青岛不是寺庙，句子不通。", "大厦": "语义：大厦是高层建筑，青岛不是大厦，与“海边风景很美”也不协调。", "山": "语义：青岛是城市，不是一座山，与“海边风景很美”也不协调。"}, "sentence_index": 6, "correct_answer": "旅游城市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个旅游城市带我们去了三个景点，很有意思。", "explanation": "这里应该用〈旅游团〉。旅游城市指地方，不能带领游客去景点。"}, {"text": "这个旅游城市在海边开了一家分店。", "explanation": "这里应该用〈旅行社〉。旅游城市是城市，不能开分店。"}, {"text": "这片古迹是有名的旅游城市，每年有很多人来参观。", "explanation": "这里应该用〈名胜〉。旅游城市指城市，古迹是景点，不是城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块旅游城市的酒店价格在夏天会上涨。", "corrected_sentence": "这座旅游城市的酒店价格在夏天会上涨。", "error_description": "量词错误：城市应用〈座〉，〈块〉用于片状的东西，不能用于城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长希望把这座小镇发展成一块国际旅游城市。", "corrected_sentence": "市长希望把这座小镇发展成一座国际旅游城市。", "error_description": "量词错误：城市应用〈座〉，〈块〉用于片状的东西，不能用于城市。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
