INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人留在某地住下来工作。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "记者在当地驻了一年，每天写报道。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}, {"text": "公司派来的人在北京驻了两年。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}, {"text": "这位医生曾在山村驻过三年。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "他在国外驻了多年，很少回家。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}, {"text": "工作人员在工地上驻了下来。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}, {"text": "他们曾在这里驻过，帮助当地人。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "我们的代表曾驻过上海。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "志愿者在小镇上驻过一年，教孩子们读书。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "他在山里驻了多年，每天照看林子。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}, {"text": "他在国外驻了十年，一直做翻译工作。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù le", "sentence_source": "generated"}], "morphological_forms": [{"form": "駐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人留在某地住下来工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻”（zhù，第四声）意思是留在某地住下来工作。"}, {"text": "株", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是植物的量词“株”。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮。"}], "explanations": {"驻": "正确：“驻”（zhù，第四声）意思是留在某地住下来工作。", "株": "zhū（第一声）与 zhù（第四声）声调不同，意思是植物的量词“株”。", "竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。", "煮": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮。"}, "sentence_index": null, "correct_answer": "驻"}, "level_3": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻了一年”表示长期留在当地工作，与“写报道”一致。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”指逃跑，与“每天写报道”的工作状态不符。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡了一年”说的是睡觉，与“每天写报道”的工作描述不相搭配。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示伤心流泪，与“写报道”不相容。"}], "explanations": {"驻": "正确：“驻了一年”表示长期留在当地工作，与“写报道”一致。", "逃": "语义：“逃”指逃跑，与“每天写报道”的工作状态不符。", "睡": "搭配：“睡了一年”说的是睡觉，与“每天写报道”的工作描述不相搭配。", "哭": "语义：“哭”表示伤心流泪，与“写报道”不相容。"}, "sentence_index": 0, "correct_answer": "驻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在图书馆驻了一会儿，就去上课了。", "explanation": "这里应该用〈待〉。驻指长期留在某地工作，只停留一会儿要用〈待〉。"}, {"text": "他驻北京出差三天，很快就回来了。", "explanation": "这里应该用〈去〉。驻指长期留在某地工作，短期出差应用〈去〉。"}, {"text": "他把书驻在桌子上。", "explanation": "这里应该用〈放〉。驻指人留在某地住下来，书是物品，只能用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻”（zhù，第四声）意思是留在某地住下来工作。"}, {"text": "处", "is_correct": false, "explanation": "chù 与 zhù 声母不同（ch 与 zh），意思是地方或处理。"}, {"text": "树", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），意思是树木。"}, {"text": "数", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），意思是数字或计算。"}], "explanations": {"驻": "正确：“驻”（zhù，第四声）意思是留在某地住下来工作。", "处": "chù 与 zhù 声母不同（ch 与 zh），意思是地方或处理。", "树": "shù 与 zhù 声母不同（sh 与 zh），意思是树木。", "数": "shù 与 zhù 声母不同（sh 与 zh），意思是数字或计算。"}, "sentence_index": null, "correct_answer": "驻"}, "level_3": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“曾驻过上海”表示代表曾在此长期工作，与句意一致。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”指躲藏，与代表的正式身份和工作不符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指撞击或打碎，与“代表”和城市的关系不符。"}, {"text": "扎", "is_correct": false, "explanation": "搭配：“扎”多用于“扎根”“扎营”，不说“扎过上海”。"}], "explanations": {"驻": "正确：“曾驻过上海”表示代表曾在此长期工作，与句意一致。", "躲": "语义：“躲”指躲藏，与代表的正式身份和工作不符。", "砸": "语义：“砸”指撞击或打碎，与“代表”和城市的关系不符。", "扎": "搭配：“扎”多用于“扎根”“扎营”，不说“扎过上海”。"}, "sentence_index": 6, "correct_answer": "驻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这所学校驻了十年书，很受欢迎。", "explanation": "这里应该用〈教〉。驻指留在某地工作，不能带“书”作宾语，教书要用〈教〉。"}, {"text": "这只小狗驻在我家门口，每天都不走。", "explanation": "这里应该用〈趴〉。驻的主体是人或部队，且指留下工作，小狗在门口趴着应用〈趴〉。"}, {"text": "孩子们在院子里驻了一下午，天黑才回家。", "explanation": "这里应该用〈玩〉。驻指人留在某地住下来或长期工作，不指孩子在院子里游玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山上驻了起来。", "corrected_sentence": "他们在山上驻了下来。", "error_description": "补语错误：“驻”表示留下来住下，应说“驻了下来”，“驻了起来”的“起来”不表示留下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他山村驻了十年。", "corrected_sentence": "他在山村驻了十年。", "error_description": "介词错误：“驻”后的处所要用“在”引出，应说“他在山村驻了十年”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
