INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "停留在某地;驻扎。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "这座山脚下曾驻过一支部队。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "这片边境驻着军队已经三年了。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}, {"text": "这个小城驻着一支部队。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}, {"text": "河边驻着一支队伍。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}, {"text": "山上驻着一支部队。", "target_word": "驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子外面驻着一批士兵。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}, {"text": "海边驻着一支部队，保护这里的人。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}, {"text": "那年冬天，北方曾驻过一支军队。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "我爷爷的部队曾驻过这个地方。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù guo", "sentence_source": "generated"}, {"text": "车站驻着几名警察，保护大家。", "target_word": "驻", "complexity_tier": "T3", "furigana": "zhù zhe", "sentence_source": "generated"}], "morphological_forms": [{"form": "駐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "部队停留在某地驻扎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a1acd7f-9bfc-4b98-ad63-703ed02b600a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻”（zhù，第四声）意思是停留、驻扎。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮。"}], "explanations": {"驻": "正确：“驻”（zhù，第四声）意思是停留、驻扎。", "主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。", "竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。", "猪": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。", "煮": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是煮。"}, "sentence_index": null, "correct_answer": "驻"}, "level_3": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻过”表示部队曾在此驻扎，与“山脚下”搭配。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中行动，与部队驻在山脚下的语境不符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多指搬运物品或搬家，部队应说“调”或“驻”，不说“搬部队”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，与部队驻守在山脚下的意思不符。"}], "explanations": {"驻": "正确：“驻过”表示部队曾在此驻扎，与“山脚下”搭配。", "游": "语义：“游”指在水中行动，与部队驻在山脚下的语境不符。", "搬": "搭配：“搬”多指搬运物品或搬家，部队应说“调”或“驻”，不说“搬部队”。", "挖": "语义：“挖”指挖掘，与部队驻守在山脚下的意思不符。"}, "sentence_index": 0, "correct_answer": "驻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家人驻在河边的小屋里。", "explanation": "这里应该用〈住〉。驻多用于军队或机构的派驻，普通家庭住下用〈住〉。"}, {"text": "这辆车驻在河边。", "explanation": "这里应该用〈停〉。驻指部队或人员长期驻扎，车辆停放应用〈停〉。"}, {"text": "他驻进了房间，大声喊叫。", "explanation": "这里应该用〈冲〉。驻强调留在某地或驻扎，不能表示突然闯入，“大声喊叫”也与停留的意思不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻”（zhù，第四声）意思是停留、驻扎。"}, {"text": "处", "is_correct": false, "explanation": "chù 与 zhù 声母不同（ch 与 zh），意思是地方或处理。"}, {"text": "树", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），意思是树木。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是追逐、逐渐。"}], "explanations": {"驻": "正确：“驻”（zhù，第四声）意思是停留、驻扎。", "处": "chù 与 zhù 声母不同（ch 与 zh），意思是地方或处理。", "树": "shù 与 zhù 声母不同（sh 与 zh），意思是树木。", "逐": "zhú（第二声）与 zhù（第四声）声调不同，意思是追逐、逐渐。"}, "sentence_index": null, "correct_answer": "驻"}, "level_3": {"options": [{"text": "驻", "is_correct": true, "explanation": "正确：“驻着”表示部队在海边驻守，与“保护这里的人”一致。"}, {"text": "驶", "is_correct": false, "explanation": "语义：“驶”指车船行驶，部队不能“驶着”停在海边。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”多用于物品，不说“扛着一支部队”。"}, {"text": "抬", "is_correct": false, "explanation": "语义：“抬”是用手或肩举起物品，与“海边”和“保护这里的人”不符。"}], "explanations": {"驻": "正确：“驻着”表示部队在海边驻守，与“保护这里的人”一致。", "驶": "语义：“驶”指车船行驶，部队不能“驶着”停在海边。", "扛": "搭配：“扛”多用于物品，不说“扛着一支部队”。", "抬": "语义：“抬”是用手或肩举起物品，与“海边”和“保护这里的人”不符。"}, "sentence_index": 6, "correct_answer": "驻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家驻到了河边的小屋。", "explanation": "这里应该用〈搬〉。驻指部队或机构的驻扎，家庭搬迁应用〈搬〉。"}, {"text": "我们驻在河边的长椅上。", "explanation": "这里应该用〈坐〉。驻指部队或人员长期驻扎，人坐在长椅上应用〈坐〉。"}, {"text": "他在操场上驻了三圈，满头大汗。", "explanation": "这里应该用〈跑〉。驻指留在某地或驻扎，不能表示绕场奔跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市曾驻过着一支部队。", "corrected_sentence": "这座城市曾驻过一支部队。", "error_description": "体标错误：“过”与“着”不能同时出现，应删去“着”，说“这座城市曾驻过一支部队。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车站驻得几名警察。", "corrected_sentence": "火车站驻着几名警察。", "error_description": "体标错误：表示驻扎的状态在持续，「驻」后面要用「着」，不能用「得」，应说「火车站驻着几名警察。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c18c43b-2458-476e-93cd-dc5556f824be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
