INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圆圆平平的碟子，用来放吃的。", "primary_collocate": null, "pronunciation": "pán", "ipa": "pʰan˧˥", "syllable_count": 1, "sentences": [{"text": "盘里放着三个红苹果。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盘又圆又平，可以放水果。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把炒好的菜倒进盘里。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一个白盘，盘里是饺子。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完了，盘里一点儿菜也没有。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个大一点的盘，放整条鱼。", "target_word": "盘", "complexity_tier": "T3", "furigana": "wǒ xiǎng mǎi yí gè dà yì diǎn de pán, fàng zhěng tiáo yú.", "sentence_source": "generated"}, {"text": "蛋糕放在盘里了，请大家慢慢吃。", "target_word": "盘", "complexity_tier": "T3", "furigana": "dàn gāo fàng zài pán lǐ le, qǐng dà jiā màn màn chī.", "sentence_source": "generated"}, {"text": "洗完的盘要放在架子上。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘边放着一把小勺子。", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的盘空了，要不要再来一点饭？", "target_word": "盘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "盘子", "label": "复合词"}, {"form": "果盘", "label": "复合词"}, {"form": "盤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "盘·名词·又圆又平、用来放食物的碟子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盘", "is_correct": true, "explanation": "盘（pán，第二声）：盛放食物的扁平器皿，正确答案。"}, {"text": "盼", "is_correct": false, "explanation": "盼（pàn，第四声）与盘（pán，第二声）声调不同，意思是盼望、期待。"}, {"text": "判", "is_correct": false, "explanation": "判（pàn，第四声）与盘（pán，第二声）声调不同，意思是判断。"}, {"text": "攀", "is_correct": false, "explanation": "攀（pān，第一声）与盘（pán，第二声）声调不同，意思是攀登。"}, {"text": "畔", "is_correct": false, "explanation": "畔（pàn，第四声）与盘（pán，第二声）声调不同，意思是边沿。"}, {"text": "旁", "is_correct": false, "explanation": "旁（páng）与盘的韵母不同（an 与 ang），声调相同，意思是旁边。"}], "explanations": {"盘": "盘（pán，第二声）：盛放食物的扁平器皿，正确答案。", "盼": "盼（pàn，第四声）与盘（pán，第二声）声调不同，意思是盼望、期待。", "判": "判（pàn，第四声）与盘（pán，第二声）声调不同，意思是判断。", "攀": "攀（pān，第一声）与盘（pán，第二声）声调不同，意思是攀登。", "畔": "畔（pàn，第四声）与盘（pán，第二声）声调不同，意思是边沿。", "旁": "旁（páng）与盘的韵母不同（an 与 ang），声调相同，意思是旁边。"}, "sentence_index": null, "correct_answer": "盘"}, "level_3": {"options": [{"text": "盘", "is_correct": true, "explanation": "盘：圆平的盘子，正好用来放三个苹果。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子用来盛饮料，装不下三个红苹果，不能说“杯里放着三个红苹果”。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶口窄，三个苹果放不进去，与“放着三个红苹果”不符。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“放……里”要求容器，花不能用来装苹果。"}], "explanations": {"盘": "盘：圆平的盘子，正好用来放三个苹果。", "杯": "语义：杯子用来盛饮料，装不下三个红苹果，不能说“杯里放着三个红苹果”。", "瓶": "语义：瓶口窄，三个苹果放不进去，与“放着三个红苹果”不符。", "花": "搭配：“放……里”要求容器，花不能用来装苹果。"}, "sentence_index": 0, "correct_answer": "盘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用盘喝粥。", "explanation": "这里应该用〈碗〉。喝粥要用碗，盘子平而浅，装不住粥。"}, {"text": "小猫盘着身子睡在沙发上。", "explanation": "这里的“盘”是动词“盘着身子”，指身体蜷曲，与盛食物的盘子无关。"}, {"text": "下雨了，我拿着盘出门挡雨。", "explanation": "这里应该用〈伞〉。盘是放食物的器皿，不是挡雨用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89943, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盘", "is_correct": true, "explanation": "盘（pán，第二声）：盛放食物的扁平器皿，正确答案。"}, {"text": "叛", "is_correct": false, "explanation": "叛（pàn，第四声）与盘（pán，第二声）声调不同，意思是背叛。"}, {"text": "庞", "is_correct": false, "explanation": "庞（páng）与盘的韵母不同（an 与 ang），意思是庞大。"}, {"text": "盆", "is_correct": false, "explanation": "盆（pén）与盘的韵母不同（an 与 en），意思是盛物或盛水的器皿。"}], "explanations": {"盘": "盘（pán，第二声）：盛放食物的扁平器皿，正确答案。", "叛": "叛（pàn，第四声）与盘（pán，第二声）声调不同，意思是背叛。", "庞": "庞（páng）与盘的韵母不同（an 与 ang），意思是庞大。", "盆": "盆（pén）与盘的韵母不同（an 与 en），意思是盛物或盛水的器皿。"}, "sentence_index": null, "correct_answer": "盘"}, "level_3": {"options": [{"text": "盘", "is_correct": true, "explanation": "盘：盛放食物的盘子，蛋糕放在盘里正合适。"}, {"text": "水", "is_correct": false, "explanation": "语义：蛋糕泡在水里不能吃，与“请大家慢慢吃”矛盾。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：鞋不是放食物的地方，不能说“蛋糕放在鞋里”。"}, {"text": "酒", "is_correct": false, "explanation": "语义：蛋糕泡在酒里不能直接吃，与“请大家慢慢吃”不符。"}], "explanations": {"盘": "盘：盛放食物的盘子，蛋糕放在盘里正合适。", "水": "语义：蛋糕泡在水里不能吃，与“请大家慢慢吃”矛盾。", "鞋": "搭配：鞋不是放食物的地方，不能说“蛋糕放在鞋里”。", "酒": "语义：蛋糕泡在酒里不能直接吃，与“请大家慢慢吃”不符。"}, "sentence_index": 6, "correct_answer": "盘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用盘盛汤。", "explanation": "这里应该用〈碗〉。盛汤要用碗，盘子平而浅，汤会流出来。"}, {"text": "警察在门口盘问了每一个人。", "explanation": "这里的“盘”是动词“盘问”，指反复追问，与盛食物的盘子无关。"}, {"text": "他用盘喝了一大口水。", "explanation": "这里应该用〈杯子〉。盘子又平又浅，是放食物的，不能用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一张盘，用来放水果。", "corrected_sentence": "我买了一个盘，用来放水果。", "error_description": "“盘”前的量词应用“个”，不说“张”（“张”多用于纸、桌子等平面的东西）。错误形式：一张盘；正确形式：一个盘。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈洗干净了一条盘。", "corrected_sentence": "妈妈洗干净了一个盘。", "error_description": "“盘”前的量词应用“个”，不说“条”（“条”多用于细长的东西）。错误形式：一条盘；正确形式：一个盘。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
