INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89945, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "比平时的时间早一些做某事。", "primary_collocate": null, "pronunciation": "zǎo diǎn", "ipa": "tsɑʊ˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我平时八点到，今天早点到了。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天早点下班，去看朋友。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周五商店早点关门。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天早点吃早饭，好吗？", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，你早点走。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的电影八点开始，我们早点去。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，早点穿上大衣。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家早点到教室。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点把作业做完。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时十点睡，今晚他早点睡了。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "比平时的时间早一些做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89945, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确答案：早点（zǎo diǎn），表示比平时的时间早一些做某事。"}, {"text": "好点", "is_correct": false, "explanation": "hǎo（第三声）与 zǎo（第三声）声母不同（h 与 z），意思是“好一点”，不是更早。"}, {"text": "找点", "is_correct": false, "explanation": "zhǎo（第三声）与 zǎo（第三声）声母不同（zh 与 z），意思是“找一些”。"}, {"text": "扫点", "is_correct": false, "explanation": "sǎo（第三声）与 zǎo（第三声）声母不同（s 与 z），意思是“扫一些”。"}, {"text": "造点", "is_correct": false, "explanation": "zào（第四声）与 zǎo（第三声）声调不同，意思是“造一些”。"}], "explanations": {"早点": "正确答案：早点（zǎo diǎn），表示比平时的时间早一些做某事。", "好点": "hǎo（第三声）与 zǎo（第三声）声母不同（h 与 z），意思是“好一点”，不是更早。", "找点": "zhǎo（第三声）与 zǎo（第三声）声母不同（zh 与 z），意思是“找一些”。", "扫点": "sǎo（第三声）与 zǎo（第三声）声母不同（s 与 z），意思是“扫一些”。", "造点": "zào（第四声）与 zǎo（第三声）声调不同，意思是“造一些”。"}, "sentence_index": null, "correct_answer": "早点"}, "level_3": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确：“早点”表示比平时的时间早到，与“我平时八点到，今天早点到了”的对比相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示低频发生，与“今天”这一次具体的到达事件冲突。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示习惯性反复，与“今天”这一次的情况矛盾。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多个主体，这里的主语是“我”一人，不能说“我……一起到了”。"}], "explanations": {"早点": "正确：“早点”表示比平时的时间早到，与“我平时八点到，今天早点到了”的对比相符。", "偶尔": "语义：“偶尔”表示低频发生，与“今天”这一次具体的到达事件冲突。", "常常": "语义：“常常”表示习惯性反复，与“今天”这一次的情况矛盾。", "一起": "搭配：“一起”需要多个主体，这里的主语是“我”一人，不能说“我……一起到了”。"}, "sentence_index": 0, "correct_answer": "早点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他早点比我到了。", "explanation": "这里语序错误：比较结构应为〈比我早点到〉，“早点”须位于“比”字结构之后。"}, {"text": "放假早点到了下周一。", "explanation": "这里应用〈提前〉。提前可用于日程安排，如“放假提前到下周一”；早点不用来说日期的前移。"}, {"text": "妹妹早点上学了两年。", "explanation": "这里应该用〈早〉。“早”可以带具体年数，如“早上学两年”；“早点”只表示稍微提前，不能带年数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确：“早点”表示比平时更早穿上衣服，与“外面很冷”需要提前添衣的语境相符。"}, {"text": "晚点", "is_correct": false, "explanation": "语义：“晚点”表示比平时晚，与“外面很冷”要求早些添衣的语境相反。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示不需要，与“外面很冷”的语境矛盾。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然，与“穿上大衣”这一合理动作不合。"}], "explanations": {"早点": "正确：“早点”表示比平时更早穿上衣服，与“外面很冷”需要提前添衣的语境相符。", "晚点": "语义：“晚点”表示比平时晚，与“外面很冷”要求早些添衣的语境相反。", "不必": "语义：“不必”表示不需要，与“外面很冷”的语境矛盾。", "白白": "语义：“白白”表示徒然，与“穿上大衣”这一合理动作不合。"}, "sentence_index": 6, "correct_answer": "早点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议早点三天召开。", "explanation": "这里应该用〈早〉：“早”可带具体时段，如“早三天召开”；“早点”只表示稍微提前，不能带时段。"}, {"text": "演出早点到了周末。", "explanation": "这里应用〈提前〉。提前可用于安排的时间前移，如“演出提前到周末”；早点只说某个动作比平时早，不能把日期前移。"}, {"text": "我早点比他下班了。", "explanation": "这里语序错误：比较结构应为〈比他早点下班〉，“早点”须位于“比”字结构之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我想早点的起床。", "corrected_sentence": "明天我想早点起床。", "error_description": "错误：“早点”是副词，后面直接接动词，不能加“的”；应说“早点起床”，不说“早点的起床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们早点地见面吧。", "corrected_sentence": "周末我们早点见面吧。", "error_description": "错误：“早点”是副词，后面直接接动词，不能加“地”；应说“早点见面”，不说“早点地见面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
