INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89946, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "稍微提前一些；表示时间更早。", "primary_collocate": null, "pronunciation": "zǎo diǎn", "ipa": "tsɑʊ˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "明天要考试，你早点睡吧。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请早点来，我们六点开始。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天有雨，我想早点回家。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你早点告诉我就好了。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上要出门，我得早点起床。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后他早点去接孩子。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末人多，我们早点出门吧。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，今晚早点吃饭。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你病了，应该早点休息。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点买票，价钱会便宜一些。", "target_word": "早点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做事的时间稍微提前，多用于建议和打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确答案：早点（zǎo diǎn），表示比平时或预定的时间稍早一些。"}, {"text": "好点", "is_correct": false, "explanation": "hǎo（第三声）与 zǎo（第三声）声母不同（h 与 z），意思是“好一点”，不是更早。"}, {"text": "找点", "is_correct": false, "explanation": "zhǎo（第三声）与 zǎo（第三声）声母不同（zh 与 z），意思是“找一些”。"}, {"text": "扫点", "is_correct": false, "explanation": "sǎo（第三声）与 zǎo（第三声）声母不同（s 与 z），意思是“扫一些”。"}, {"text": "造点", "is_correct": false, "explanation": "zào（第四声）与 zǎo（第三声）声调不同，意思是“造一些”。"}], "explanations": {"早点": "正确答案：早点（zǎo diǎn），表示比平时或预定的时间稍早一些。", "好点": "hǎo（第三声）与 zǎo（第三声）声母不同（h 与 z），意思是“好一点”，不是更早。", "找点": "zhǎo（第三声）与 zǎo（第三声）声母不同（zh 与 z），意思是“找一些”。", "扫点": "sǎo（第三声）与 zǎo（第三声）声母不同（s 与 z），意思是“扫一些”。", "造点": "zào（第四声）与 zǎo（第三声）声调不同，意思是“造一些”。"}, "sentence_index": null, "correct_answer": "早点"}, "level_3": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确：“早点”表示比平时或预定的时间更早，与明天考试、要早睡的语境相符。"}, {"text": "晚点", "is_correct": false, "explanation": "语义：“晚点”表示比预定时间迟，与“明天要考试”要求提前休息的语境相反。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示低频发生，与这里一次性的叮嘱“你……吧”不合。"}, {"text": "常常", "is_correct": false, "explanation": "搭配：“常常”表示习惯性反复，不与针对明天的一次性建议搭配。"}], "explanations": {"早点": "正确：“早点”表示比平时或预定的时间更早，与明天考试、要早睡的语境相符。", "晚点": "语义：“晚点”表示比预定时间迟，与“明天要考试”要求提前休息的语境相反。", "偶尔": "语义：“偶尔”表示低频发生，与这里一次性的叮嘱“你……吧”不合。", "常常": "搭配：“常常”表示习惯性反复，不与针对明天的一次性建议搭配。"}, "sentence_index": 0, "correct_answer": "早点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早点比他到了。", "explanation": "这里语序错误：比较结构应为〈比他早点到〉，“早点”须位于“比”字结构之后。"}, {"text": "会议早点到了星期五。", "explanation": "这里应用〈提前〉。提前可以说日程向前调整，如“会议提前到星期五”；早点只修饰动作发生的时间早晚，不能用来说日期本身提前。"}, {"text": "他早点出生了三年。", "explanation": "这里应该用〈早〉。“早”可以带具体年数，如“早出生三年”；“早点”只表示稍微提前，不能带年数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早点", "is_correct": true, "explanation": "正确：“早点”表示比平时更早出门，与周末人多、需要提前出发的语境相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚过去的时间，与“我们……吧”的提议语气不合，也不表示提前。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，“我们一直出门吧”前后不通，与一次性的提议及“周末人多”的语境都不合。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然，与“我们……吧”的提议不合，也与提前出门的意思无关。"}], "explanations": {"早点": "正确：“早点”表示比平时更早出门，与周末人多、需要提前出发的语境相符。", "刚刚": "语义：“刚刚”指刚过去的时间，与“我们……吧”的提议语气不合，也不表示提前。", "一直": "语义：“一直”表示持续不断，“我们一直出门吧”前后不通，与一次性的提议及“周末人多”的语境都不合。", "白白": "语义：“白白”表示徒然，与“我们……吧”的提议不合，也与提前出门的意思无关。"}, "sentence_index": 6, "correct_answer": "早点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演出早点两天开始。", "explanation": "这里应该用〈早〉：“早”可带具体时段，如“早两天开始”；“早点”只表示稍微提前，不能带时段。"}, {"text": "开学典礼早点到了九月。", "explanation": "这里应用〈提前〉。提前可用于日程的向前调整，如“开学典礼提前到九月”；早点只说动作的时间较平时早，不能让日期本身前移。"}, {"text": "他早点比我起床了。", "explanation": "这里语序错误：比较结构应为〈比我早点起床〉，“早点”须位于“比”字结构之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们早点地回去。", "corrected_sentence": "老师让我们早点回去。", "error_description": "错误：“早点”是副词，修饰动词时后面不加“地”，应说“早点回去”；加“地”的“早点地回去”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想早点地去车站，别迟到了。", "corrected_sentence": "我想早点去车站，别迟到了。", "error_description": "错误：“早点”是副词，后面不加“地”，应说“早点去车站”；加“地”的“早点地去车站”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
