INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人出门了，留在家里看着不让坏人进来。", "primary_collocate": null, "pronunciation": "kān jiā", "ipa": "kʰan⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们去旅游时，爷爷替我们看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近小区有小偷，大家出门都请人看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家去海边了，只有大黄狗在看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们放心去玩，我在这里替你们看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王出远门，请邻居帮忙看家，别让小偷进来。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上家里没人，得有人看家才安全。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班很忙，就养了一条狗来看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都去看电影了，我一个人留下看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条狗又大又凶，看家最合适。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节时，爸爸出门，哥哥留下看家，防着坏人。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了家", "label": "体标"}, {"form": "看过家", "label": "体标"}, {"form": "看家狗", "label": "复合"}], "register": "口语", "sense_fingerprint": "家人外出时留守家中、防止坏人进入(动词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：看家指留守家中，替全家守门户，与“我们去旅游时”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是婚姻大事，不能替别人去做，句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“替”后面一般接可以代替的动作，“生病”不能替别人进行。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是个人的事，不能替别人去做，句意荒谬。"}], "explanations": {"看家": "正确：看家指留守家中，替全家守门户，与“我们去旅游时”的语境相符。", "结婚": "语义：结婚是婚姻大事，不能替别人去做，句子不通。", "生病": "搭配：“替”后面一般接可以代替的动作，“生病”不能替别人进行。", "睡觉": "语义：睡觉是个人的事，不能替别人去做，句意荒谬。"}, "sentence_index": 0, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在这里替你们看家，这里是一家饭店。", "explanation": "语境错误：〈看家〉指守护住宅，这里是饭店，不是住宅，应说〈看店〉。"}, {"text": "我在学校替你们看家，每天都很认真。", "explanation": "场所错误：〈看家〉指留在自己家中守门户，在学校不能说看家，应说〈值班〉。"}, {"text": "我在这里替你们看家你们的花。", "explanation": "配价错误：〈看家〉本身已含宾语“家”，不能再带别的对象；照料花应说〈照顾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：养狗来看家，即让狗守护门户防贼，与“上班很忙”的原因相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是考核学习，养狗不能替代，句意不通。"}, {"text": "绣花", "is_correct": false, "explanation": "语义：绣花是手工活动，与养狗的目的无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“养狗来唱歌”搭配不当，狗不能代替人唱歌。"}], "explanations": {"看家": "正确：养狗来看家，即让狗守护门户防贼，与“上班很忙”的原因相符。", "考试": "语义：考试是考核学习，养狗不能替代，句意不通。", "绣花": "语义：绣花是手工活动，与养狗的目的无关。", "唱歌": "搭配：“养狗来唱歌”搭配不当，狗不能代替人唱歌。"}, "sentence_index": 6, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过节时，爸爸出门，哥哥在公园看家。", "explanation": "场所错误：〈看家〉指留在家中守门户，公园不是家，不能说看家。"}, {"text": "过节时，爸爸出门，哥哥出去看家。", "explanation": "用法错误：〈看家〉指留在家中守门户，“出去”与之矛盾。"}, {"text": "过节时，爸爸出门，哥哥在海边看家。", "explanation": "场所错误：〈看家〉指留在家中守门户，海边的守卫应说〈看守〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们出门时，奶奶留在家里被我们看家。", "corrected_sentence": "我们出门时，奶奶留在家里替我们看家。", "error_description": "错误：“被”应为“替”。“替我们看家”表示为我们守家，“被我们看家”是被动，意思不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸出门，哥哥留下看家们。", "corrected_sentence": "爸爸出门，哥哥留下看家。", "error_description": "多余的“们”：“看家”是动词，不能加“们”表示复数，正确为“哥哥留下看家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
