INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在家照看门户。", "primary_collocate": null, "pronunciation": "kān jiā", "ipa": "kʰan⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们都出去玩，只有小明留下来看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈去上班，奶奶负责看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年回老家，邻居帮我们看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚我要出门，你来看家吧。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗很会看家，有人来就叫。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人看家，觉得有点无聊。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我们去旅游，请朋友来看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟今天不想出去，他说要看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出差一周，我负责看家和喂猫。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家养了一只猫，不过它不会看家。", "target_word": "看家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了家", "label": "体标"}, {"form": "看过家", "label": "体标"}, {"form": "看家狗", "label": "复合"}], "register": "口语", "sense_fingerprint": "留在家中照看门户(动词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：看家指留在家中照看门户，与“我们都出去玩”形成对照。"}, {"text": "出门", "is_correct": false, "explanation": "语义：出门是外出，与“留下来”意思相反，句子前后矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学是去学校，与“留下来”的留守含义不一致。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”是因工作外出，不能与“留下来”搭配，句意矛盾。"}], "explanations": {"看家": "正确：看家指留在家中照看门户，与“我们都出去玩”形成对照。", "出门": "语义：出门是外出，与“留下来”意思相反，句子前后矛盾。", "上学": "语义：上学是去学校，与“留下来”的留守含义不一致。", "出差": "搭配：“出差”是因工作外出，不能与“留下来”搭配，句意矛盾。"}, "sentence_index": 0, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我去医院看家。", "explanation": "场所错误：〈看家〉指留在自己家中守门户，去医院应说〈陪床〉或〈看护〉。"}, {"text": "我们在饭店看家，客人很多。", "explanation": "场所错误：饭店是营业场所，应说〈看店〉；〈看家〉只指在家中守门户。"}, {"text": "我每天在公司看家，很认真。", "explanation": "场所错误：〈看家〉指留在家中守门户，公司应说〈看守〉或〈值班〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看家", "is_correct": true, "explanation": "正确：看家指留在家中照看门户，与“暑假去旅游，请朋友帮忙”的语境相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班是去工作，不能请朋友来代替，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是人生大事，与“旅游时请人帮忙”的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”是学习的活动，不能与“请朋友来”搭配。"}], "explanations": {"看家": "正确：看家指留在家中照看门户，与“暑假去旅游，请朋友帮忙”的语境相符。", "上班": "语义：上班是去工作，不能请朋友来代替，句意不通。", "结婚": "语义：结婚是人生大事，与“旅游时请人帮忙”的语境不符。", "考试": "搭配：“考试”是学习的活动，不能与“请朋友来”搭配。"}, "sentence_index": 6, "correct_answer": "看家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天给花看家，很认真。", "explanation": "配价错误：〈看家〉是不及物动词，不能带“花”这样的对象；照料花应说〈照顾〉。"}, {"text": "我们每天都在河边看家。", "explanation": "场所错误：〈看家〉指留守家中门户，河边的守卫应说〈看守〉。"}, {"text": "我每天在图书馆看家。", "explanation": "场所错误：〈看家〉指留在家中守门户，图书馆应说〈值班〉或〈看管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我出门，弟弟在家看家过。", "corrected_sentence": "今天我出门，弟弟在家看家。", "error_description": "错误：多余的“过”。“过”不能放在“看家”之后表示这一动作，应直接说“弟弟在家看家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人在家看家们。", "corrected_sentence": "他一个人在家看家。", "error_description": "多余的“们”：“看家”是动词，不能加“们”表示复数，正确为“他一个人在家看家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昨日", "is_correct": true, "explanation": "反义词：〈昨日〉指今天之前的一天，与〈明日〉指向相反的时间，是一对反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：〈桌子〉是家具，与〈明日〉没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：〈河流〉是自然景物，与〈明日〉没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "无关：〈老师〉指教书的人，与〈明日〉没有反义关系。"}], "correct_answer": "昨日", "explanations": {"昨日": "反义词：〈昨日〉指今天之前的一天，与〈明日〉指向相反的时间，是一对反义词。", "桌子": "无关：〈桌子〉是家具，与〈明日〉没有反义关系。", "河流": "无关：〈河流〉是自然景物，与〈明日〉没有反义关系。", "老师": "无关：〈老师〉指教书的人，与〈明日〉没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昨日", "is_correct": true, "explanation": "反义词：〈昨日〉指今天之前的一天，与〈明日〉指向相反的时间，是一对反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：〈窗户〉是建筑部件，与〈明日〉没有反义关系。"}, {"text": "树林", "is_correct": false, "explanation": "无关：〈树林〉是自然景物，与〈明日〉没有反义关系。"}, {"text": "医生", "is_correct": false, "explanation": "无关：〈医生〉指治病的人，与〈明日〉没有反义关系。"}], "correct_answer": "昨日", "explanations": {"昨日": "反义词：〈昨日〉指今天之前的一天，与〈明日〉指向相反的时间，是一对反义词。", "窗户": "无关：〈窗户〉是建筑部件，与〈明日〉没有反义关系。", "树林": "无关：〈树林〉是自然景物，与〈明日〉没有反义关系。", "医生": "无关：〈医生〉指治病的人，与〈明日〉没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "明日就是明天，是今天过去后的那一天。", "primary_collocate": null, "pronunciation": "míng rì", "ipa": "miŋ˧˥ ʐɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "明日天气晴朗，适合出行。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日上午九点，我们在门口见面。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家明日准时到会。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明日就要离开这座城市。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日事今日毕，不要拖到明日。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日的比赛，我们一定要赢。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日将有大雨，请注意带伞。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日是周末，公司不上班。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师通知，明日不用交作业。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日清晨，我们就坐火车出发。", "target_word": "明日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "今天之后的那一天（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明日", "is_correct": true, "explanation": "正确。“明日天气晴朗，适合出行”指明天的天气，与“适合出行”的未来语气一致。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不能有天气，句子说的是天气晴朗。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“钢笔”不是天气，无法作“天气晴朗”的主语。"}, {"text": "黄瓜", "is_correct": false, "explanation": "搭配：“黄瓜天气晴朗”不是自然的搭配，“黄瓜”也不能“适合出行”。"}], "explanations": {"明日": "正确。“明日天气晴朗，适合出行”指明天的天气，与“适合出行”的未来语气一致。", "桌子": "语义：“桌子”不能有天气，句子说的是天气晴朗。", "钢笔": "语义：“钢笔”不是天气，无法作“天气晴朗”的主语。", "黄瓜": "搭配：“黄瓜天气晴朗”不是自然的搭配，“黄瓜”也不能“适合出行”。"}, "sentence_index": 0, "correct_answer": "明日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈住在明日，离我家很远。", "explanation": "语义：〈明日〉指时间，不指地方。这里应该用〈北京〉之类的地名。"}, {"text": "这盆花很漂亮，每天都要浇明日。", "explanation": "搭配：〈浇〉的对象是植物或土地，〈明日〉是时间，不能浇。这里应该用〈水〉。"}, {"text": "我的明日很大，像一座山。", "explanation": "体貌：〈明日〉是时间词，没有大小，不能用来描述事物的体积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明日", "is_correct": true, "explanation": "正确。“明日将有大雨，请注意带伞”是对明天的天气提醒，与“将”的未来语气一致。"}, {"text": "昨日", "is_correct": false, "explanation": "语义：“昨日”指过去，与“将有大雨”的未来语气冲突。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去，与“将”表示的未来不一致。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘将有大雨”不是自然说法，“窗帘”不能作时间状语。"}], "explanations": {"明日": "正确。“明日将有大雨，请注意带伞”是对明天的天气提醒，与“将”的未来语气一致。", "昨日": "语义：“昨日”指过去，与“将有大雨”的未来语气冲突。", "上周": "语义：“上周”指过去，与“将”表示的未来不一致。", "窗帘": "搭配：“窗帘将有大雨”不是自然说法，“窗帘”不能作时间状语。"}, "sentence_index": 6, "correct_answer": "明日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一斤明日，准备煮汤。", "explanation": "语义：这里把〈明日〉当成了可以称重购买的食材，但它是时间词，不能买，也不能用〈斤〉计量。"}, {"text": "弟弟的明日很喜欢吃糖。", "explanation": "语义：这里把〈明日〉当成了人，说它有喜好、会吃糖，但它是时间词，没有喜好和口味。"}, {"text": "这把椅子的明日很结实。", "explanation": "语义：这里把〈明日〉当成了形容物品质地的词，但它只是时间词，不能用来说椅子结不结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天明日去跑步。", "corrected_sentence": "我明日去跑步。", "error_description": "错误：“每天”与将来时间词“明日”矛盾，二者不能同现。删去“每天”即可，应为“我明日去跑步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明日一早去过北京。", "corrected_sentence": "我们明日一早去北京。", "error_description": "经历标记错误：“过”表示已经发生的经历，与将来时间词“明日”矛盾，应说“我们明日一早去北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
