INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下月是这个月的后一个月。", "primary_collocate": null, "pronunciation": "xià yuè", "ipa": "ɕja˥˩ ɥœ˥˩", "syllable_count": 2, "sentences": [{"text": "今天是三月，下月是四月。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月的第一天是星期一。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月有三十天，下月有三十一天。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想下月买一台新电脑。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月老师要去上海开会。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月我哥哥结婚。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你下月把钱还给我。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下月的工作已经安排好了。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说下月有时间。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下月再决定吧。", "target_word": "下月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下个月", "label": "复合"}], "register": "中性", "sense_fingerprint": "下月:这个月的后一个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6007777f-108d-4907-92d2-9664a290c7b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下月", "is_correct": true, "explanation": "正确。“下月”指这个月之后的那个月，三月之后正是四月。"}, {"text": "上月", "is_correct": false, "explanation": "语义：“上月”指上个月，应是二月，与“是四月”冲突。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指过去的整一年，不能与“三月”“四月”这样的月份对应。"}, {"text": "本月", "is_correct": false, "explanation": "语义：「本月」指这个月，即三月，与「是四月」冲突。"}], "explanations": {"下月": "正确。“下月”指这个月之后的那个月，三月之后正是四月。", "上月": "语义：“上月”指上个月，应是二月，与“是四月”冲突。", "去年": "语义：“去年”指过去的整一年，不能与“三月”“四月”这样的月份对应。", "本月": "语义：「本月」指这个月，即三月，与「是四月」冲突。"}, "sentence_index": 0, "correct_answer": "下月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试是下月举行的。", "explanation": "这里应该用〈上月〉。“是……的”强调已经发生的事，“下月”指将来，不能用于已经举行过的考试。"}, {"text": "今天是三月，下月是二月。", "explanation": "“下月”指这个月之后的那个月，应是四月，不能是二月。"}, {"text": "这本书是下月买的。", "explanation": "这里应该用〈上月〉。“是……的”强调已经发生的事，“下月”指将来，不能用来说已经买下的书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下月", "is_correct": true, "explanation": "正确。“请你下月把钱还给我”是对将来的请求，与“下月”相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，不能用来请求对方在将来还钱。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”已经过去，与请对方将来还钱的语境冲突。"}, {"text": "上月", "is_correct": false, "explanation": "语义：「上月」指过去的月份，与请对方将来还钱的语境冲突。"}], "explanations": {"下月": "正确。“请你下月把钱还给我”是对将来的请求，与“下月”相符。", "昨天": "语义：“昨天”指过去，不能用来请求对方在将来还钱。", "前年": "语义：“前年”已经过去，与请对方将来还钱的语境冲突。", "上月": "语义：「上月」指过去的月份，与请对方将来还钱的语境冲突。"}, "sentence_index": 6, "correct_answer": "下月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们前年下月再决定吧。", "explanation": "“下月”指将来，不能与“前年”这样已经过去的时间并用。"}, {"text": "我们这个星期下月再决定吧。", "explanation": "“下月”是以月为单位的时间，不能与“这个星期”并用。"}, {"text": "我们这个月下月再决定吧。", "explanation": "“下月”指这个月之后的那个月，不能与“这个月”同时出现在一个时间短语里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下月的在家休息。", "corrected_sentence": "我们下月在家休息。", "error_description": "错误：“下月”作状语修饰动词时，后面不能加“的”，“的”只用于名词前。正确：“我们下月在家休息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下月了我们再去看看吧。", "corrected_sentence": "下月我们再去看看吧。", "error_description": "错误：“下月”是将来的时间词，后面不能加“了”，“了”表示完成，与将来的邀请不符。正确：“下月我们再去看看吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59756732-85a5-467a-977f-dc355d4da8be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
