INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89953, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人聚在一起，做成一个新的队。", "primary_collocate": null, "pronunciation": "zǔ jiàn", "ipa": "tsu˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "学校打算组建一支新的足球队。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个朋友想组建一个乐队。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年组建了一支篮球队。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在组建一个新的工作小组。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们组建一个学习小组。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要组建一支强队，先要找好队员。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组建过一个小乐队，后来分开了。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起组建一个跑步小队吧。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想组建一支女子篮球队。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了比赛，学校组建了新队伍。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组建了", "label": "体标"}, {"form": "组建过", "label": "体标"}, {"form": "組建", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把人聚在一起成立新的队伍或小组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89953, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：组建，意思是把人聚在一起，成立新的队伍或团体。"}, {"text": "主见", "is_correct": false, "explanation": "zhǔ jiàn（第三声）与 zǔ jiàn 声母不同（zh 与 z），意思是有自己的看法。"}, {"text": "举荐", "is_correct": false, "explanation": "jǔ jiàn（第三声）与 zǔ jiàn 声母不同（j 与 z），意思是推荐、举荐。"}, {"text": "足见", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）声调不同，意思是可以看出、足以显示。"}], "explanations": {"组建": "正确：组建，意思是把人聚在一起，成立新的队伍或团体。", "主见": "zhǔ jiàn（第三声）与 zǔ jiàn 声母不同（zh 与 z），意思是有自己的看法。", "举荐": "jǔ jiàn（第三声）与 zǔ jiàn 声母不同（j 与 z），意思是推荐、举荐。", "足见": "zú（第二声）与 zǔ（第三声）声调不同，意思是可以看出、足以显示。"}, "sentence_index": null, "correct_answer": "组建"}, "level_3": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：“学校打算组建一支新的足球队”，指把人聚成新的队。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃一支足球队”。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语应是歌曲，“足球队”不能作它的宾语。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污渍，与“成立一支新队”无关。"}], "explanations": {"组建": "正确：“学校打算组建一支新的足球队”，指把人聚成新的队。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃一支足球队”。", "唱": "配价：“唱”的宾语应是歌曲，“足球队”不能作它的宾语。", "擦": "语义：“擦”指抹去污渍，与“成立一支新队”无关。"}, "sentence_index": 0, "correct_answer": "组建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校组建了一次郊游，大家都很开心。", "explanation": "这里应该用〈组织〉。组建指把人聚成新的队伍，郊游是一次活动，不能用“组建”。"}, {"text": "工人们组建了一座新的桥。", "explanation": "这里应该用〈建造〉。组建针对人组成的队伍，不能用于桥梁等实体建筑。"}, {"text": "电视台组建了一个新的节目。", "explanation": "这里应该用〈制作〉。组建用于人员组成的队伍，节目是制作出来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：“他们组建过一个小乐队”，指他们曾经把人聚成一个乐队。"}, {"text": "演奏", "is_correct": false, "explanation": "配价：“演奏”的宾语是乐曲或乐器，不能以“乐队”作宾语。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”用于给人或动物吃东西，不能指组成乐队。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，不能说“烤一个小乐队”。"}], "explanations": {"组建": "正确：“他们组建过一个小乐队”，指他们曾经把人聚成一个乐队。", "演奏": "配价：“演奏”的宾语是乐曲或乐器，不能以“乐队”作宾语。", "喂": "语义：“喂”用于给人或动物吃东西，不能指组成乐队。", "烤": "搭配：“烤”的对象是食物，不能说“烤一个小乐队”。"}, "sentence_index": 6, "correct_answer": "组建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校注重组建人才，让学生全面发展。", "explanation": "这里应该用〈培养〉。“组建”针对人员组成的队伍，不能用于“人才”这种需要长期培育的对象。"}, {"text": "工人把零件组建成一台机器。", "explanation": "这里应该用〈组装〉。组建用于人员组成的队伍或机构，机器要用“组装”。"}, {"text": "学校组建了一个奖学金，鼓励优秀学生。", "explanation": "这里应该用〈设立〉。奖学金是设立的，不能用“组建”，组建针对人员组成的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师希望我们组建一只自己的队伍。", "corrected_sentence": "老师希望我们组建一支自己的队伍。", "error_description": "量词错误：“队伍”应用“支”，写成“一只自己的队伍”不对，“只”多用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想组建过一个新的摇滚乐队。", "corrected_sentence": "他们想组建一个新的摇滚乐队。", "error_description": "“过”用错：“想”表示打算，“过”表示已经经历的动作，不能说“想组建过”，应说“想组建”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
