INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "组织并建立。", "primary_collocate": null, "pronunciation": "zǔ jiàn", "ipa": "tsu˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "政府决定组建一个新的部门。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司去年组建了研究中心。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表一起组建了工作委员会。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在组建一家新的公司。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总理很快组建了新政府。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校组建学生会，需要老师同意。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府组建了新的交通管理局。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先组建一个办事机构。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两地政府想组建一个联合管理机构。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组建过一个小型研究所。", "target_word": "组建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组建了", "label": "体标"}, {"form": "组建过", "label": "体标"}, {"form": "組建", "label": "繁体"}], "register": "中性", "sense_fingerprint": "组织并建立机构、政府或公司等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：组建，意思是组织并建立机构、政府或公司。"}, {"text": "主见", "is_correct": false, "explanation": "zhǔ jiàn（第三声）与 zǔ jiàn 声母不同（zh 与 z），意思是有自己的看法。"}, {"text": "举荐", "is_correct": false, "explanation": "jǔ jiàn（第三声）与 zǔ jiàn 声母不同（j 与 z），意思是推荐、举荐。"}, {"text": "足见", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）声调不同，意思是可以看出、足以显示。"}], "explanations": {"组建": "正确：组建，意思是组织并建立机构、政府或公司。", "主见": "zhǔ jiàn（第三声）与 zǔ jiàn 声母不同（zh 与 z），意思是有自己的看法。", "举荐": "jǔ jiàn（第三声）与 zǔ jiàn 声母不同（j 与 z），意思是推荐、举荐。", "足见": "zú（第二声）与 zǔ（第三声）声调不同，意思是可以看出、足以显示。"}, "sentence_index": null, "correct_answer": "组建"}, "level_3": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：“政府决定组建一个新的部门”，指组织并建立新机构。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃一个部门”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能说“喝一个部门”。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打，与“设立机构”无关，句意不通。"}], "explanations": {"组建": "正确：“政府决定组建一个新的部门”，指组织并建立新机构。", "吃": "搭配：“吃”的宾语是食物，不能说“吃一个部门”。", "喝": "搭配：“喝”的宾语是饮品，不能说“喝一个部门”。", "打": "语义：“打”指击打，与“设立机构”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "组建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府正在组建一座新的图书馆。", "explanation": "这里应该用〈修建〉。组建针对人员组成的团体或机构，不能用于图书馆这类建筑。"}, {"text": "农民正在组建一片新的树林。", "explanation": "这里应该用〈种植〉。组建指组织人员成立机构或团体，树林是种出来的，不能说“组建”。"}, {"text": "作家正在组建一本新的书。", "explanation": "这里应该用〈写〉。“组建”不能用于书籍这类作品，应说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组建", "is_correct": true, "explanation": "正确：“市政府组建了新的交通管理局”，指组织并建立新机构。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语应是歌曲，“管理局”不能作它的宾语。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污渍，与“设立机构”无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象应是食物或可咬的东西，不能说“咬了交通管理局”。"}], "explanations": {"组建": "正确：“市政府组建了新的交通管理局”，指组织并建立新机构。", "唱": "配价：“唱”的宾语应是歌曲，“管理局”不能作它的宾语。", "擦": "语义：“擦”指抹去污渍，与“设立机构”无关。", "咬": "搭配：“咬”的对象应是食物或可咬的东西，不能说“咬了交通管理局”。"}, "sentence_index": 6, "correct_answer": "组建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈组建了一锅汤，大家都很喜欢。", "explanation": "这里应该用〈熬〉。组建针对人员或机构，汤是熬出来的，不能用“组建”。"}, {"text": "他在课堂上组建了一首歌。", "explanation": "这里应该用〈唱〉。“组建”不能用于歌曲，歌曲是唱出来的。"}, {"text": "工人们组建了一台新机器。", "explanation": "这里应该用〈组装〉。组建用于人员或机构，机器要用“组装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府决定组建着一个新的委员会。", "corrected_sentence": "市政府决定组建一个新的委员会。", "error_description": "“着”用错：“决定”后的动作尚未发生，“组建”后不能加“着”表示进行，应去掉“着”，说“决定组建一个新的委员会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新政府很快组建了政策。", "corrected_sentence": "新政府很快组建了内阁。", "error_description": "宾语搭配错误：“组建”用于机构或团体，“政策”不能被组建，应改为“内阁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "晚上好是晚上见面时，大家互相打招呼说的话。", "primary_collocate": null, "pronunciation": "wǎn shang hǎo", "ipa": "wan˨˩ ʂɑŋ xɑʊ˨˩", "syllable_count": 3, "sentences": [{"text": "晚上好，好久不见！", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们晚饭后在小区里碰到，互相说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "furigana": "tóng shì men wǎn fàn hòu zài xiǎo qū lǐ pèng dào, hù xiāng shuō wǎn shang hǎo.", "sentence_source": "generated"}, {"text": "门口的保安对每个人都说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打电话给我，第一句是晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上好，今天的月亮真圆。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在楼下遇到，互相说了晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，晚上见面常说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明大声说：“晚上好，奶奶！”", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上好，你吃饭了吗？", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台里，女主播说：“听众朋友们，晚上好！”", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "晚上见面时互相打招呼的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚上好", "is_correct": true, "explanation": "见面时的问候语，与“好久不见”的重逢语境相合。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”用于分别，与“好久不见”的重逢语境冲突。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是睡前道别的话，不能用于久别重逢的问候。"}, {"text": "拜拜", "is_correct": false, "explanation": "语义：“拜拜”是告别语，与“好久不见”的重逢语境冲突。"}], "explanations": {"晚上好": "见面时的问候语，与“好久不见”的重逢语境相合。", "再见": "语义：“再见”用于分别，与“好久不见”的重逢语境冲突。", "晚安": "语义：“晚安”是睡前道别的话，不能用于久别重逢的问候。", "拜拜": "语义：“拜拜”是告别语，与“好久不见”的重逢语境冲突。"}, "sentence_index": 0, "correct_answer": "晚上好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "散场时，大家走出礼堂，一边挥手一边说：“晚上好。”", "explanation": "这里应该用〈再见〉。晚上好用于见面打招呼，分别时要说再见。"}, {"text": "他帮我修好了自行车，我连声说：“晚上好。”", "explanation": "这里应该用〈谢谢〉。晚上好只用于见面问候，不能用来表示感谢。"}, {"text": "妈妈给我盖好被子，我小声说：“晚上好。”", "explanation": "这里应该用〈晚安〉。晚上好用于见面，睡前要说晚安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚上好", "is_correct": true, "explanation": "见面时的问候语，与句中的“晚上见面”一致。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：“早上好”用于早上见面，与句中的“晚上见面”冲突。"}, {"text": "早安", "is_correct": false, "explanation": "语义：“早安”是早晨的问候，与“晚上见面”的时间不合。"}, {"text": "哎呀", "is_correct": false, "explanation": "语域：“哎呀”是惊讶或疼痛时的感叹，不是见面时的问候语。"}], "explanations": {"晚上好": "见面时的问候语，与句中的“晚上见面”一致。", "早上好": "语义：“早上好”用于早上见面，与句中的“晚上见面”冲突。", "早安": "语义：“早安”是早晨的问候，与“晚上见面”的时间不合。", "哎呀": "语域：“哎呀”是惊讶或疼痛时的感叹，不是见面时的问候语。"}, "sentence_index": 6, "correct_answer": "晚上好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上我在公司门口碰到同事，我们互相说了晚上好。", "explanation": "这里应该用〈早上好〉。晚上好只用于晚上见面，早上见面要说早上好。"}, {"text": "下午三点，电话里的客户对我说：“晚上好！”", "explanation": "这里应该用〈下午好〉。晚上好只用于晚上见面，下午要说下午好。"}, {"text": "上午十点，老师走进教室，笑着说：“晚上好。”", "explanation": "这里应该用〈上午好〉。晚上好只用于晚上见面，上午见面要说上午好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上好了，欢迎大家回家。", "corrected_sentence": "晚上好，欢迎大家回家。", "error_description": "“晚上好”是固定问候语，后面不能加“了”。应改为“晚上好，欢迎大家回家。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在走廊里碰到邻居，我笑着说：“很晚上好。”", "corrected_sentence": "在走廊里碰到邻居，我笑着说：“晚上好。”", "error_description": "“晚上好”是固定问候语，前面不能加程度副词“很”修饰。应删去“很”，改为“晚上好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
