INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89956, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "晚上见面时使用的问候语。", "primary_collocate": null, "pronunciation": "wǎn shang hǎo", "ipa": "wan˨˩ ʂɑŋ xɑʊ˨˩", "syllable_count": 3, "sentences": [{"text": "晚上好，欢迎来到我们的节目。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进教室，笑着说：“晚上好！”", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电梯里对邻居说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上好，你今天过得怎么样？", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员看见我们，说：“晚上好，几位？”", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居在楼道里碰到我，笑着说：“晚上好！”", "target_word": "晚上好", "complexity_tier": "T3", "furigana": "lín jū zài lóu dào lǐ pèng dào wǒ, xiào zhe shuō: “wǎn shang hǎo!”", "sentence_source": "generated"}, {"text": "晚上好，请问这里有人坐吗？", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九点以后见面，我们一般说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人微笑着对大家说晚上好。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上好，我是今天的司机，我姓王。", "target_word": "晚上好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "晚上见面时打招呼的固定问候语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚上好", "is_correct": true, "explanation": "见面时的问候语，与“欢迎来到我们的节目”搭配，用于晚间节目开场。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”用于分别时告别，与“欢迎来到”的开场语境相反。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是睡前或分别时说的话，不能用于节目开场的欢迎。"}, {"text": "拜拜", "is_correct": false, "explanation": "语义：“拜拜”是告别语，与节目开场的欢迎语境冲突。"}], "explanations": {"晚上好": "见面时的问候语，与“欢迎来到我们的节目”搭配，用于晚间节目开场。", "再见": "语义：“再见”用于分别时告别，与“欢迎来到”的开场语境相反。", "晚安": "语义：“晚安”是睡前或分别时说的话，不能用于节目开场的欢迎。", "拜拜": "语义：“拜拜”是告别语，与节目开场的欢迎语境冲突。"}, "sentence_index": 0, "correct_answer": "晚上好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同事问我：“你今天过得怎么样？”我想了想，回答说：“晚上好。”", "explanation": "这里应该用〈还不错〉。晚上好是问候语，不能用来回答对方的近况。"}, {"text": "他帮我拿了行李，我连忙说：“晚上好。”", "explanation": "这里应该用〈谢谢〉。晚上好只用于见面问候，不能用来表示感谢。"}, {"text": "我洗完澡，对妈妈说了一句晚上好，就去睡觉了。", "explanation": "这里应该用〈晚安〉。晚上好用于见面，睡前道别要说晚安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚上好", "is_correct": true, "explanation": "见面时的问候语，可以放在“请问这里有人坐吗”之前，是礼貌开口。"}, {"text": "谢谢", "is_correct": false, "explanation": "语义：“谢谢”是感谢用语，不能用来开口搭话。"}, {"text": "不客气", "is_correct": false, "explanation": "语义：“不客气”是回应感谢的用语，不能用来开口搭话。"}, {"text": "没关系", "is_correct": false, "explanation": "语义：“没关系”是对歉意的回应，不能用来开口搭话。"}], "explanations": {"晚上好": "见面时的问候语，可以放在“请问这里有人坐吗”之前，是礼貌开口。", "谢谢": "语义：“谢谢”是感谢用语，不能用来开口搭话。", "不客气": "语义：“不客气”是回应感谢的用语，不能用来开口搭话。", "没关系": "语义：“没关系”是对歉意的回应，不能用来开口搭话。"}, "sentence_index": 6, "correct_answer": "晚上好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上午十点，他走进会议室，对大家说：“晚上好。”", "explanation": "这里应该用〈上午好〉。晚上好只用于晚上见面，上午见面要说上午好。"}, {"text": "下午三点，经理走进办公室，大家齐声说：“晚上好！”", "explanation": "这里应该用〈下午好〉。晚上好只用于晚上见面，下午见面要说下午好。"}, {"text": "中午我在食堂碰到老师，我微笑着对他说：“晚上好。”", "explanation": "这里应该用〈你好〉。晚上好只用于晚上见面，中午遇到老师用你好更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上好了，大家辛苦了。", "corrected_sentence": "晚上好，大家辛苦了。", "error_description": "“晚上好”是固定问候语，后面不能加“了”表示完成。应改为“晚上好，大家辛苦了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各位同学，很晚上好！", "corrected_sentence": "各位同学，晚上好！", "error_description": "“晚上好”是固定问候语，前面不能加程度副词“很”修饰。应删去“很”，改为“各位同学，晚上好！”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可能", "is_correct": true, "explanation": "“可能”与“不可能”互为反义，表示有可能发生，与句中“明天不可能下雨”的推断相反。"}, {"text": "敢", "is_correct": false, "explanation": "“敢”表示有胆量，与“不可能”没有反义关系。"}, {"text": "必须", "is_correct": false, "explanation": "“必须”表示义务或要求，与“不可能”没有反义关系。"}, {"text": "愿意", "is_correct": false, "explanation": "“愿意”表示意愿，与“不可能”没有反义关系。"}], "correct_answer": "可能", "explanations": {"可能": "“可能”与“不可能”互为反义，表示有可能发生，与句中“明天不可能下雨”的推断相反。", "敢": "“敢”表示有胆量，与“不可能”没有反义关系。", "必须": "“必须”表示义务或要求，与“不可能”没有反义关系。", "愿意": "“愿意”表示意愿，与“不可能”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可能", "is_correct": true, "explanation": "“可能”与“不可能”互为反义，表示有可能发生，与句中“不可能喝醉”的推断相反。"}, {"text": "敢", "is_correct": false, "explanation": "“敢”表示有胆量，与“不可能”没有反义关系。"}, {"text": "要", "is_correct": false, "explanation": "“要”表示意愿或将来，与“不可能”没有反义关系。"}, {"text": "肯", "is_correct": false, "explanation": "“肯”表示愿意，与“不可能”没有反义关系。"}], "correct_answer": "可能", "explanations": {"可能": "“可能”与“不可能”互为反义，表示有可能发生，与句中“不可能喝醉”的推断相反。", "敢": "“敢”表示有胆量，与“不可能”没有反义关系。", "要": "“要”表示意愿或将来，与“不可能”没有反义关系。", "肯": "“肯”表示愿意，与“不可能”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "property", "definition": "不可能是说一定不会发生。", "primary_collocate": null, "pronunciation": "bù kě néng", "ipa": "pu˥˩ kʰɤ˨˩˦ nəŋ˧˥", "syllable_count": 3, "sentences": [{"text": "他昨天就走了，今天不可能在这里。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在才六点，商店不可能开门。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很爱干净，不可能把房间弄得这么乱。", "target_word": "不可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么好，明天不可能下雨。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是中国人，不可能听不懂这句话。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你刚吃过饭，不可能饿。", "target_word": "不可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙放在桌子上了，不可能找不到。", "target_word": "不可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的题，他不可能做错。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈今天出差了，她不可能来接你。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不喝酒，不可能喝醉。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "推断：说话人认为某事一定不会发生，后接动词或短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可能", "is_correct": true, "explanation": "“不可能”表示推断某事一定不会发生。“昨天就走了”说明他已离开，所以今天不在这里是可以推断的，句意完整。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示肯定会发生，得出“今天一定在这里”，与“昨天就走了”的推断相反，句中要的是“不可能”。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量去做某事，不能用来对“今天他在不在这里”作推断，句意不通。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示情愿、主动，句中要的是对事实的推断；“今天愿意在这里”不符合“昨天就走了”的语境。"}], "explanations": {"不可能": "“不可能”表示推断某事一定不会发生。“昨天就走了”说明他已离开，所以今天不在这里是可以推断的，句意完整。", "一定": "语义：“一定”表示肯定会发生，得出“今天一定在这里”，与“昨天就走了”的推断相反，句中要的是“不可能”。", "敢": "语义：“敢”表示有胆量去做某事，不能用来对“今天他在不在这里”作推断，句意不通。", "愿意": "语义：“愿意”表示情愿、主动，句中要的是对事实的推断；“今天愿意在这里”不符合“昨天就走了”的语境。"}, "sentence_index": 0, "correct_answer": "不可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你不可能走太快，我们跟不上。", "explanation": "这里应该用〈不要〉。“不可能”是推断，不能用于请求的语气；应说“请你不要走太快”。"}, {"text": "请你不可能慢点走，我们都在等你。", "explanation": "这里应该用〈不要〉。“不可能”是推断，不能用于劝阻或请求的语气；劝人慢走应说“请你不要走太快”。"}, {"text": "他的字很不可能，老师表扬了他。", "explanation": "这里应该用〈好〉。“不可能”表示推断或办不到，不能用来评价字的好坏，应说“字写得很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可能", "is_correct": true, "explanation": "“不可能找不到”即“一定能找到”，符合“不可能”推断的用法，钥匙放在桌子上，句意完整。"}, {"text": "想", "is_correct": false, "explanation": "搭配：“想”后接的应是希望去做的动作，不能与“找不到”这种已经发生的结果搭配，句意不通。"}, {"text": "该", "is_correct": false, "explanation": "语义：“该”表示应当或轮到，表示责任或义务，不能用来推断“钥匙找不到”的结果，句意不通。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示愿意去做某事，用在此处与钥匙的位置无关，句意不通。"}], "explanations": {"不可能": "“不可能找不到”即“一定能找到”，符合“不可能”推断的用法，钥匙放在桌子上，句意完整。", "想": "搭配：“想”后接的应是希望去做的动作，不能与“找不到”这种已经发生的结果搭配，句意不通。", "该": "语义：“该”表示应当或轮到，表示责任或义务，不能用来推断“钥匙找不到”的结果，句意不通。", "肯": "语义：“肯”表示愿意去做某事，用在此处与钥匙的位置无关，句意不通。"}, "sentence_index": 6, "correct_answer": "不可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天不可能下雨，你带伞吧。", "explanation": "这里应该用〈也许〉。“不可能”表示一定不会发生，与“也许”（表示有可能）意思相反，这里应说“明天也许下雨，你带伞吧”。"}, {"text": "我们的球队很不可能，所以常常输球。", "explanation": "这里应该用〈差〉。“不可能”用于说事情办不到，不能用来形容球队的水平。"}, {"text": "请你不可能坐下，我们都在等你。", "explanation": "这里应该用〈不要〉。“不可能”是推断，不能用于请求或禁止的语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这么怕黑，晚上不可能的一个人出门。", "corrected_sentence": "他这么怕黑，晚上不可能一个人出门。", "error_description": "错误：“不可能”作情态词时后面不能加“的”。“不可能的一个人”不通，应改为“不可能一个人出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么大的雨，他不可能的骑车来。", "corrected_sentence": "这么大的雨，他不可能骑车来。", "error_description": "错误：“不可能”作情态词后面不能加“的”。“不可能的骑车来”语序不通，应改为“他不可能骑车来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可能", "is_correct": true, "explanation": "“可能”与“不可能”互为反义，表示能办到，与“不可能的任务”相反。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“不可能”没有反义关系，不能用来形容任务。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”与“不可能”没有反义关系，只用来形容外貌。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“不可能”没有反义关系，只用来形容光线。"}], "correct_answer": "可能", "explanations": {"可能": "“可能”与“不可能”互为反义，表示能办到，与“不可能的任务”相反。", "安静": "“安静”与“不可能”没有反义关系，不能用来形容任务。", "美丽": "“美丽”与“不可能”没有反义关系，只用来形容外貌。", "明亮": "“明亮”与“不可能”没有反义关系，只用来形容光线。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可能", "is_correct": true, "explanation": "“可能”与“不可能”互为反义，表示能办到，与“几乎不可能”的意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“不可能”没有反义关系，只用来形容外貌。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“不可能”没有反义关系，只用来形容明白的程度。"}, {"text": "可爱", "is_correct": false, "explanation": "“可爱”与“不可能”没有反义关系，只用来形容人或小事物的样子。"}], "correct_answer": "可能", "explanations": {"可能": "“可能”与“不可能”互为反义，表示能办到，与“几乎不可能”的意思相反。", "漂亮": "“漂亮”与“不可能”没有反义关系，只用来形容外貌。", "清楚": "“清楚”与“不可能”没有反义关系，只用来形容明白的程度。", "可爱": "“可爱”与“不可能”没有反义关系，只用来形容人或小事物的样子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有可能发生的；办不到的。", "primary_collocate": null, "pronunciation": "bù kě néng", "ipa": "pu˥˩ kʰɤ˨˩˦ nəŋ˧˥", "syllable_count": 3, "sentences": [{"text": "一天学会一千个汉字是不可能的。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一件不可能的事。", "target_word": "不可能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个人搬走这张大桌子，对我来说不可能。", "target_word": "不可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一个不可能的任务。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要在十分钟内到机场，完全不可能。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "让时间回到过去是不可能的。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想一天看完三本书，这几乎不可能。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都认为这件事是不可能的。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别想了，这个要求是不可能的。", "target_word": "不可能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对他来说，不让孩子玩手机几乎是不可能的。", "target_word": "不可能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可能的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "办不到：某事没有实现的可能，作谓语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可能", "is_correct": true, "explanation": "“不可能”表示办不到，与“一天学会一千个汉字”的难度相合，句意完整。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或状态寂静，不能用来说“学会汉字”这件事的难度，句意不通。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”一般形容外貌或事物的好看，不与“学会汉字”这类行为搭配。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，用在此处句意不通。"}], "explanations": {"不可能": "“不可能”表示办不到，与“一天学会一千个汉字”的难度相合，句意完整。", "安静": "语义：“安静”形容环境或状态寂静，不能用来说“学会汉字”这件事的难度，句意不通。", "美丽": "搭配：“美丽”一般形容外貌或事物的好看，不与“学会汉字”这类行为搭配。", "明亮": "语义：“明亮”形容光线或颜色，用在此处句意不通。"}, "sentence_index": 0, "correct_answer": "不可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很不可能，我试着做了一下。", "explanation": "这里应该用〈困难〉。“不可能”表示办不到，不能用“很”修饰题目的难度，应说“很困难”。"}, {"text": "这件事不可能，但我们可以做到。", "explanation": "这里应该用〈不容易〉。“不可能”表示办不到，语气很绝对；后面接“但我们可以做到”，前后矛盾。“不容易”表示困难但能完成。"}, {"text": "这个孩子很不可能，老师很喜欢他。", "explanation": "这里应该用〈聪明〉。“不可能”只用来说事情办不到，不能用来形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可能", "is_correct": true, "explanation": "“不可能”表示办不到。“几乎”加上“一天看完三本书”的语境，指几乎办不到，句意完整。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白或分明，与“看完三本书”能否办到无关，句意不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或事物好看，不能用来评价“看完三本书”的可能性。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”多形容人或小事物的样子，不与“几乎”构成对事情可能性的判断。"}], "explanations": {"不可能": "“不可能”表示办不到。“几乎”加上“一天看完三本书”的语境，指几乎办不到，句意完整。", "清楚": "语义：“清楚”形容明白或分明，与“看完三本书”能否办到无关，句意不通。", "漂亮": "语义：“漂亮”形容外貌或事物好看，不能用来评价“看完三本书”的可能性。", "可爱": "搭配：“可爱”多形容人或小事物的样子，不与“几乎”构成对事情可能性的判断。"}, "sentence_index": 6, "correct_answer": "不可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你不可能大声说话，这里是图书馆。", "explanation": "这里应该用〈不要〉。“不可能”表示推断或办不到，不能用于劝阻的语气；劝人小声应说“请你不要大声说话”。"}, {"text": "这次考试的分数不可能，他很伤心。", "explanation": "这里应该用〈低〉。“不可能”表示办不到，不能用来形容分数的高低。"}, {"text": "这个问题对他来说不可能，他很快就解决了。", "explanation": "这里应该用〈简单〉。“不可能”表示办不到，与“很简单”意思相反；后面说“很快就解决了”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划对我们来说是个不可能目标。", "corrected_sentence": "这个计划对我们来说是个不可能的目标。", "error_description": "错误：“不可能”修饰名词“目标”时，中间要加“的”，应说“不可能的目标”，漏掉“的”不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对他来说，这个愿望是不可能了实现的。", "corrected_sentence": "对他来说，这个愿望是不可能实现的。", "error_description": "错误：“了”不能插在“不可能”和“实现”之间，“了”应放在动词后面，应去掉“了”，说“是不可能实现的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "更名是把名字换成另一个名字。", "primary_collocate": null, "pronunciation": "gēng míng", "ipa": "kɤŋ˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小王的名字不好听，他想更名。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手更名后，出了一张新专辑。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家老饭店上个月更名了。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区更名为“幸福花园”。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的网名太长了，所以更名了。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你的微信昵称可以更名吗？", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥以前叫旧桥，现在更名为“友谊桥”。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件更名以后，很多人都不知道了。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的店更名为“小王书店”。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所大学更名过一次，现在叫师范大学。", "target_word": "更名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更名了", "label": "体标（了）"}, {"form": "更名过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "更名：把原来的名字换成新名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更名", "is_correct": true, "explanation": "正确。“名字不好听”是想换名字的原因，“他想更名”符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“名字不好听”是想换名字的原因，“他想结婚”与之不合。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”指完成学业，不能用于名字。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指失去工作，与名字无关，句意前后不通。"}], "explanations": {"更名": "正确。“名字不好听”是想换名字的原因，“他想更名”符合句意。", "结婚": "语义：“名字不好听”是想换名字的原因，“他想结婚”与之不合。", "毕业": "搭配：“毕业”指完成学业，不能用于名字。", "失业": "语义：“失业”指失去工作，与名字无关，句意前后不通。"}, "sentence_index": 0, "correct_answer": "更名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他更名了那辆旧自行车。", "explanation": "这里应该用〈修理〉。更名是改换名字，自行车坏了要修理。"}, {"text": "我更名了新家。", "explanation": "这里应该用〈搬〉。更名是改换名字，搬进新家不能说更名。"}, {"text": "这条河的水更名了。", "explanation": "这里应该用〈变化〉。水不是名字，不能更名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更名", "is_correct": true, "explanation": "正确。“以前叫旧桥，现在更名为友谊桥”说明名字被改换，符合句意。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”针对尚未建成的东西，与“以前叫旧桥”的已有桥不合。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：“焊接为”指把材料焊成某物，不能表示改换名字。"}, {"text": "漆", "is_correct": false, "explanation": "语义：“漆为”指涂成某种颜色，不能用来表示改换名字。"}], "explanations": {"更名": "正确。“以前叫旧桥，现在更名为友谊桥”说明名字被改换，符合句意。", "设计": "搭配：“设计”针对尚未建成的东西，与“以前叫旧桥”的已有桥不合。", "焊接": "语义：“焊接为”指把材料焊成某物，不能表示改换名字。", "漆": "语义：“漆为”指涂成某种颜色，不能用来表示改换名字。"}, "sentence_index": 6, "correct_answer": "更名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他更名了手机。", "explanation": "这里应该用〈更换〉。更名只用于改换名字，手机是实物，要说更换。"}, {"text": "公司更名了计划。", "explanation": "这里应该用〈调整〉。更名是改换名称，计划要调整。"}, {"text": "这棵树更名了。", "explanation": "这里应该用〈长高〉。更名是改换名称，树木只会长高，不会更名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店上个月更名为了“阅读园”。", "corrected_sentence": "这家书店上个月更名为“阅读园”。", "error_description": "错误形式：“更名为了”；正确形式：“更名为”。“为了”表示目的，这里的“为”是引出新名称，不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家剧院更名了过两次。", "corrected_sentence": "这家剧院更名过两次。", "error_description": "错误形式：“更名了过两次”；正确形式：“更名过两次”。“了”和“过”不能同时用在同一动词后，表示经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "线下", "is_correct": true, "explanation": "线下：不在网络上、面对面进行，与“线上”相对。"}, {"text": "屋里", "is_correct": false, "explanation": "屋里指室内，与“线上”没有反义关系。"}, {"text": "外面", "is_correct": false, "explanation": "外面指室外，与“线上”没有反义关系。"}, {"text": "墙角", "is_correct": false, "explanation": "墙角指墙与墙相交的地方，与“线上”没有反义关系。"}], "correct_answer": "线下", "explanations": {"线下": "线下：不在网络上、面对面进行，与“线上”相对。", "屋里": "屋里指室内，与“线上”没有反义关系。", "外面": "外面指室外，与“线上”没有反义关系。", "墙角": "墙角指墙与墙相交的地方，与“线上”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "线下", "is_correct": true, "explanation": "线下：不在网络上、面对面进行，与“线上”相对。"}, {"text": "家里", "is_correct": false, "explanation": "家里指家中，与“线上”没有反义关系。"}, {"text": "河边", "is_correct": false, "explanation": "河边指河的旁边，与“线上”没有反义关系。"}, {"text": "树下", "is_correct": false, "explanation": "树下指树的下方，与“线上”没有反义关系。"}], "correct_answer": "线下", "explanations": {"线下": "线下：不在网络上、面对面进行，与“线上”相对。", "家里": "家里指家中，与“线上”没有反义关系。", "河边": "河边指河的旁边，与“线上”没有反义关系。", "树下": "树下指树的下方，与“线上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在网络上，用电脑或手机连着网。", "primary_collocate": null, "pronunciation": "xiàn shàng", "ipa": "ɕiɛn˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "今晚我们在线上见面吧，我不出门了。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在线上玩游戏。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在线上买了一双鞋。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在线上聊了一个小时。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在在线上吗？我有事找你。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机在线上交了作业。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师今天在线上讲课。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在线上认识了很多朋友。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在线上给奶奶订了蛋糕。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在线上看电影，不去电影院了。", "target_word": "线上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線上", "label": "繁体"}], "register": "中性", "sense_fingerprint": "线上：在网络上（处所），连着网做某事或处于联网状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：在网络上，与“我不出门了”相符，说明是网上见面。"}, {"text": "线下", "is_correct": false, "explanation": "语义：线下见面要出门，与“我不出门了”矛盾。"}, {"text": "外面", "is_correct": false, "explanation": "语义：去外面见面需要出门，与“我不出门了”矛盾。"}, {"text": "桌下", "is_correct": false, "explanation": "搭配：见面不说在“桌下”，地点搭配不当。"}], "explanations": {"线上": "线上：在网络上，与“我不出门了”相符，说明是网上见面。", "线下": "语义：线下见面要出门，与“我不出门了”矛盾。", "外面": "语义：去外面见面需要出门，与“我不出门了”矛盾。", "桌下": "搭配：见面不说在“桌下”，地点搭配不当。"}, "sentence_index": 0, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晚上在线上踢了一场足球。", "explanation": "这里的“线上”指通过网络，踢足球要在场地上进行，不能在网上踢。"}, {"text": "他在线上刷了一面墙。", "explanation": "这里的“线上”指通过网络，刷墙要在墙面上进行，不能在网上完成。"}, {"text": "他在线上洗了一个热水澡。", "explanation": "这里的“线上”指通过网络，洗澡要在浴室里进行，不能在网上完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线上", "is_correct": true, "explanation": "线上：在网络上，与“老师讲课”的远程方式相符。"}, {"text": "床下", "is_correct": false, "explanation": "语义：床下不是讲课的地方，与“讲课”不符。"}, {"text": "水里", "is_correct": false, "explanation": "语义：人不能在水里讲课，句子不成立。"}, {"text": "冰箱里", "is_correct": false, "explanation": "语义：冰箱里不是讲课的地方，句子不成立。"}], "explanations": {"线上": "线上：在网络上，与“老师讲课”的远程方式相符。", "床下": "语义：床下不是讲课的地方，与“讲课”不符。", "水里": "语义：人不能在水里讲课，句子不成立。", "冰箱里": "语义：冰箱里不是讲课的地方，句子不成立。"}, "sentence_index": 6, "correct_answer": "线上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在线上打扫了房间。", "explanation": "这里的“线上”指通过网络，打扫房间要在现场进行，不能在网上完成。"}, {"text": "我每天都在线上洗碗。", "explanation": "这里的“线上”指通过网络，洗碗要在厨房里进行，不能在网上完成。"}, {"text": "他在线上吃了一个苹果。", "explanation": "这里的“线上”指通过网络，吃苹果要在现场进行，不能在网上完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晚上在一个线上订了一张票。", "corrected_sentence": "他晚上在线上订了一张票。", "error_description": "表示网络这一处所的“线上”不能受数量词“一个”修饰，应说“在线上订了一张票”，不说“在一个线上订了一张票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥在线上的买了一本书。", "corrected_sentence": "哥哥在线上买了一本书。", "error_description": "表示网上这一处所的“在线上”是状语，直接放在动词前，中间不加“的”。应说“在线上买了一本书”，不说“在线上的买了一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
