INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "月令是说每个月该做什么事、有什么天气。", "primary_collocate": null, "pronunciation": "yuè lìng", "ipa": "ɥe˥˩ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "月令说，二月要开始春耕。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲解了月令的主要内容。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇月令写了十二个月的天气。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看月令就知道三月该做什么。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月令里说，六月天气很热。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常按月令安排家里的事。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到了一篇月令。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月令把一年分成十二个月来写。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十月的月令说，天气开始变冷。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们读月令时，能知道每个月该做什么。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "讲每个月该做的事和天气的说法或文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：讲每个月该做的事和天气的说法或文章。"}, {"text": "月历", "is_correct": false, "explanation": "lì（第四声）与 lìng（第四声）韵尾不同，少了 ng，意思是日历，不是讲每月事务的月令。"}, {"text": "月龄", "is_correct": false, "explanation": "líng（第二声）与 lìng（第四声）声调不同，意思是按月计算的年龄。"}, {"text": "越岭", "is_correct": false, "explanation": "lǐng（第三声）与 lìng（第四声）声调不同，意思是翻越山岭。"}, {"text": "越境", "is_correct": false, "explanation": "jìng 与 lìng 声母不同（j 与 l），意思是越过国界。"}], "explanations": {"月令": "月令：讲每个月该做的事和天气的说法或文章。", "月历": "lì（第四声）与 lìng（第四声）韵尾不同，少了 ng，意思是日历，不是讲每月事务的月令。", "月龄": "líng（第二声）与 lìng（第四声）声调不同，意思是按月计算的年龄。", "越岭": "lǐng（第三声）与 lìng（第四声）声调不同，意思是翻越山岭。", "越境": "jìng 与 lìng 声母不同（j 与 l），意思是越过国界。"}, "sentence_index": null, "correct_answer": "月令"}, "level_3": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：讲每个月该做的事和天气，可以用来说明二月春耕。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只报时，不会说二月要开始春耕。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是刷牙的用具，不会说二月要开始春耕。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“说”要求能说话的主体，“脸色”不能说话。"}], "explanations": {"月令": "月令：讲每个月该做的事和天气，可以用来说明二月春耕。", "闹钟": "语义：闹钟只报时，不会说二月要开始春耕。", "牙刷": "语义：牙刷是刷牙的用具，不会说二月要开始春耕。", "脸色": "搭配：“说”要求能说话的主体，“脸色”不能说话。"}, "sentence_index": 0, "correct_answer": "月令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门前我总要带上月令，证明我是这里的居民。", "explanation": "这里应该用〈户口本〉。月令记录每月的事务和天气，不能用来证明居民身份。"}, {"text": "这本月令告诉我们怎么做红烧肉。", "explanation": "这里应该用〈食谱〉。月令讲的是按月的农事和气候，不讲菜的做法。"}, {"text": "我每天晚饭后吃一粒月令，帮助睡眠。", "explanation": "这里应该用〈安眠药〉。月令是记载事务和天气的文字，不是药品，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：讲每个月事务的文章，可以用量词“篇”来数。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：量词“篇”不搭配“口号”，应说“一句口号”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是实物，不是文章，书里读不到。"}, {"text": "扇子", "is_correct": false, "explanation": "语义：扇子是实物，不是文章，不能在书里读到。"}], "explanations": {"月令": "月令：讲每个月事务的文章，可以用量词“篇”来数。", "口号": "搭配：量词“篇”不搭配“口号”，应说“一句口号”。", "钥匙": "语义：钥匙是实物，不是文章，书里读不到。", "扇子": "语义：扇子是实物，不是文章，不能在书里读到。"}, "sentence_index": 6, "correct_answer": "月令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月令告诉我们每天的课程安排。", "explanation": "这里应该用〈课表〉。月令讲的是按月的事务，不用来安排每天的课程。"}, {"text": "饭店的月令列出了今天的菜。", "explanation": "这里应该用〈菜单〉。月令讲按月的农事和气候，不列菜品。"}, {"text": "这位厨师用月令做了一道菜。", "explanation": "这里应该用〈食材〉。月令是记载每月农事和气候的文字，不是能用来做菜的食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前读过一篇月令过。", "corrected_sentence": "我以前读过一篇月令。", "error_description": "“过”重复：“读过”已带“过”，句末不能再加“过”，应说“我以前读过一篇月令。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇月令我看了懂。", "corrected_sentence": "这篇月令我看懂了。", "error_description": "补语位置错误：应说“看懂了”，“看了懂”的语序是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
