INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代指按月分列的气候和农事、政令；也指某月的气候和物产。", "primary_collocate": null, "pronunciation": "yuè lìng", "ipa": "ɥe˥˩ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "古人按月令安排农事。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "《礼记》里有一篇讲月令的文章。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月令里写着每个月的气候。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的皇帝要按月令发布政令。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民看月令，知道什么时候种地。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书专门讲古代的月令。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月令告诉人们五月该做什么。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过《月令》里关于春天的内容。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按月令来说，七月天气很热。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人相信顺着月令做事，一年会平安。", "target_word": "月令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古代按月记录气候、农事和政令的安排，也指某个月的气候物产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89964, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：古代按月分列的气候、农事和政令，这是本词的意思。"}, {"text": "月历", "is_correct": false, "explanation": "lì（第四声）与 lìng（第四声）韵尾不同，少了 ng，意思是日历，不是古代按月分列的月令。"}, {"text": "月龄", "is_correct": false, "explanation": "líng（第二声）与 lìng（第四声）声调不同，意思是按月计算的年龄。"}, {"text": "越岭", "is_correct": false, "explanation": "lǐng（第三声）与 lìng（第四声）声调不同，意思是翻越山岭。"}, {"text": "越境", "is_correct": false, "explanation": "jìng 与 lìng 声母不同（j 与 l），意思是越过国界。"}], "explanations": {"月令": "月令：古代按月分列的气候、农事和政令，这是本词的意思。", "月历": "lì（第四声）与 lìng（第四声）韵尾不同，少了 ng，意思是日历，不是古代按月分列的月令。", "月龄": "líng（第二声）与 lìng（第四声）声调不同，意思是按月计算的年龄。", "越岭": "lǐng（第三声）与 lìng（第四声）声调不同，意思是翻越山岭。", "越境": "jìng 与 lìng 声母不同（j 与 l），意思是越过国界。"}, "sentence_index": null, "correct_answer": "月令"}, "level_3": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：古代按月的气候、农事和政令，可以据此安排农事。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“菜谱”是做菜用的，不能说“按菜谱安排农事”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古人没有手机，不能按它安排农事。"}, {"text": "药方", "is_correct": false, "explanation": "语义：药方是用来开药的，不能用来安排农事。"}], "explanations": {"月令": "月令：古代按月的气候、农事和政令，可以据此安排农事。", "菜谱": "搭配：“菜谱”是做菜用的，不能说“按菜谱安排农事”。", "手机": "语义：古人没有手机，不能按它安排农事。", "药方": "语义：药方是用来开药的，不能用来安排农事。"}, "sentence_index": 0, "correct_answer": "月令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "翻开月令，看看今天是星期几。", "explanation": "这里应该用〈日历〉。月令记录古代按月分列的气候、农事和政令，查某一天是星期几要用日历。"}, {"text": "我在厨房里用月令烧水。", "explanation": "这里应该用〈水壶〉。月令是记载农事和气候的文字，不是烧水的器具。"}, {"text": "这本月令是我今天买的笔记本。", "explanation": "这里应该用〈笔记本〉。月令是记载农事和气候的文字，不是用来写字的本子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月令", "is_correct": true, "explanation": "月令：说明每个月该做什么的文字，正是告诉人们月份事务的依据。"}, {"text": "药方", "is_correct": false, "explanation": "语义：药方是开药用的，不用来告诉人们五月该做什么。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能提醒时间，不能告诉人们五月该做什么。"}, {"text": "段子", "is_correct": false, "explanation": "语域：“段子”是口语化的笑话，不适合用来说明月份的事务。"}], "explanations": {"月令": "月令：说明每个月该做什么的文字，正是告诉人们月份事务的依据。", "药方": "语义：药方是开药用的，不用来告诉人们五月该做什么。", "闹钟": "语义：闹钟只能提醒时间，不能告诉人们五月该做什么。", "段子": "语域：“段子”是口语化的笑话，不适合用来说明月份的事务。"}, "sentence_index": 6, "correct_answer": "月令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每个月都要交一份月令。", "explanation": "这里应该用〈月报〉。月令是古代按月分列的气候、农事和政令，不是工作报告。"}, {"text": "这份月令是我们班的值日表。", "explanation": "这里应该用〈值日表〉。月令记录每月的农事、气候和政令，不用来安排班级值日。"}, {"text": "这本月令记录了去年的经济数据。", "explanation": "这里应该用〈年鉴〉。月令记录的是按月的气候和农事，不记录经济数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候读过月令过。", "corrected_sentence": "我小时候读过月令。", "error_description": "“过”重复：“读过”已带“过”，末尾不能再加“过”，应说“我小时候读过月令。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇月令我读了懂。", "corrected_sentence": "这篇月令我读懂了。", "error_description": "补语位置错误：应说“读懂了”，“读了懂”的语序是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
