INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做错事以后，决心变好。", "primary_collocate": null, "pronunciation": "zì xīn", "ipa": "tsɨ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他犯了错，决心自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了他一次自新的机会。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷被警察抓住以后，表示要自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥做错事后，在家人帮助下自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想再骗人，一心想自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你愿意自新，大家就会原谅你。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都相信他能够自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯错的人愿意自新，应该得到帮助。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信里写道，自己一定会自新。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后悔了，想自新，可是没人相信。", "target_word": "自新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改过自新", "label": "成语"}], "register": "书面语", "sense_fingerprint": "做错事后决心变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51f2d4c-4300-4b9b-afac-e322d926561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89965, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自新", "is_correct": true, "explanation": "正确答案。自新：做错事后决心变好。"}, {"text": "自信", "is_correct": false, "explanation": "声调不同：xìn（第四声）与 xīn（第一声），意思是对自己有信心。"}, {"text": "质心", "is_correct": false, "explanation": "声母不同：zhì 与 zì 只差声母 zh/z，意思是物体的质量中心。"}, {"text": "资信", "is_correct": false, "explanation": "声调不同：zī xìn 与 zì xīn 声母韵母相同，两个字的声调都不同。资信的意思是资金和信用状况。"}, {"text": "自省", "is_correct": false, "explanation": "读音相近：xǐng 与 xīn 的韵母（ing/in）和声调都不同。自省的意思是自我反省。"}], "explanations": {"自新": "正确答案。自新：做错事后决心变好。", "自信": "声调不同：xìn（第四声）与 xīn（第一声），意思是对自己有信心。", "质心": "声母不同：zhì 与 zì 只差声母 zh/z，意思是物体的质量中心。", "资信": "声调不同：zī xìn 与 zì xīn 声母韵母相同，两个字的声调都不同。资信的意思是资金和信用状况。", "自省": "读音相近：xǐng 与 xīn 的韵母（ing/in）和声调都不同。自省的意思是自我反省。"}, "sentence_index": null, "correct_answer": "自新"}, "level_3": {"options": [{"text": "自新", "is_correct": true, "explanation": "正确答案。自新：做错事后改过变好，与“犯了错”“决心”的语境吻合。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“决心”表示下定决心去做，“发愁”是忧虑，两者语义冲突。"}, {"text": "闲逛", "is_correct": false, "explanation": "语义：“决心”指积极的行动目标，“闲逛”是无所事事，与“决心”不搭。"}, {"text": "感化", "is_correct": false, "explanation": "配价：“感化”是及物动词，需要带宾语（感化某人），这里没有宾语，句子不成立。"}], "explanations": {"自新": "正确答案。自新：做错事后改过变好，与“犯了错”“决心”的语境吻合。", "发愁": "语义：“决心”表示下定决心去做，“发愁”是忧虑，两者语义冲突。", "闲逛": "语义：“决心”指积极的行动目标，“闲逛”是无所事事，与“决心”不搭。", "感化": "配价：“感化”是及物动词，需要带宾语（感化某人），这里没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "自新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种蜥蜴断了尾巴，过几周尾巴又自新了。", "explanation": "这里应该用〈再生〉。自新指做错事的人改过变好，不指身体部位长出新的部分；蜥蜴断尾后长出新尾用“再生”。"}, {"text": "这次比赛输了，我决心自新。", "explanation": "这里应该用〈振作〉。自新指做错事后改过向善，比赛失利不是犯错，应说“振作”。"}, {"text": "这台旧电脑终于自新了。", "explanation": "这里应该用〈修好〉。自新只用于犯错后决心改变的人，机器不能自新，应说“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自新", "is_correct": true, "explanation": "正确答案。自新：能够改正错误、重新做人，与“朋友们都相信”的语境吻合。"}, {"text": "说谎", "is_correct": false, "explanation": "语义：“相信他能够”表示对他的正面期待，“说谎”是负面行为，不能用来表示被相信的能力。"}, {"text": "堕落", "is_correct": false, "explanation": "语义：“相信他能够”说的是对他改好的期待，“堕落”与之相反，语境不通。"}, {"text": "救助", "is_correct": false, "explanation": "配价：“救助”是及物动词，需要带宾语（救助某人），这里没有宾语。"}], "explanations": {"自新": "正确答案。自新：能够改正错误、重新做人，与“朋友们都相信”的语境吻合。", "说谎": "语义：“相信他能够”表示对他的正面期待，“说谎”是负面行为，不能用来表示被相信的能力。", "堕落": "语义：“相信他能够”说的是对他改好的期待，“堕落”与之相反，语境不通。", "救助": "配价：“救助”是及物动词，需要带宾语（救助某人），这里没有宾语。"}, "sentence_index": 6, "correct_answer": "自新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒以后，身体很快就自新了。", "explanation": "这里应该用〈恢复〉。自新指做错事的人改过变好，不指身体康复；病后身体好转应说“恢复”。"}, {"text": "他向受害者自新，可是没人相信。", "explanation": "这里应该用〈赔罪〉。自新不带对象，不是向某人道歉；要说向谁赔罪。"}, {"text": "这台冰箱决心自新。", "explanation": "这里应该用〈更新〉。自新只指犯过错的人改过向善，冰箱不能犯错，也不能自新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被自新了。", "corrected_sentence": "他自新了。", "error_description": "“自新”是不及物动词，不能用于“被”字句；应说“他自新了”，不说“他被自新了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他自新很彻底。", "corrected_sentence": "他自新得很彻底。", "error_description": "补语标记“得”缺失：“自新”后带程度补语时要用“得”，应说“自新得很彻底”，不能省掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4d3f1c-e8d9-4fb5-b8ad-e16820abebe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
