INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89967, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "之中是在某个地方的里面。", "primary_collocate": null, "pronunciation": "zhī zhōng", "ipa": "ʈʂɨ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他的家在大山之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小鸟飞进了树林之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在人群之中玩游戏。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座小房子藏在花园之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人住在湖边的竹林之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在人群之中找到了朋友。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船行驶在河水之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进了雨林之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子就在这片田野之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多房子隐藏在雾气之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之中:某个地方的里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之中", "is_correct": true, "explanation": "之中表示在某个地点的里面，与“大山”的位置相符。"}, {"text": "之久", "is_correct": false, "explanation": "语义：“之久”指时间的长久，用于“大山”这样的地点不通，句意不通。"}, {"text": "之首", "is_correct": false, "explanation": "语义：“之首”表示位于最前、居首，“家”不能位于大山的首位。"}, {"text": "之时", "is_correct": false, "explanation": "语义：“之时”表示时间点，“家在大山之时”把地点说成时间，句意不通。"}], "explanations": {"之中": "之中表示在某个地点的里面，与“大山”的位置相符。", "之久": "语义：“之久”指时间的长久，用于“大山”这样的地点不通，句意不通。", "之首": "语义：“之首”表示位于最前、居首，“家”不能位于大山的首位。", "之时": "语义：“之时”表示时间点，“家在大山之时”把地点说成时间，句意不通。"}, "sentence_index": 0, "correct_answer": "之中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小鸟飞出了树林之中。", "explanation": "这里应该用〈之外〉。“飞出”表示离开，“之中”指在里面，与“飞出”矛盾，应说“树林之外”。"}, {"text": "村子建在山顶之中。", "explanation": "这里应该用〈之上〉。建在山顶应说“山顶之上”，“山顶之中”指在山顶的内部，意思不对。"}, {"text": "这座小楼坐落在湖边之中。", "explanation": "这里应该用〈湖边〉。小楼坐落在湖边应直接说“湖边”，“湖边之中”不是自然的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之中", "is_correct": true, "explanation": "之中表示在某个范围的里面，与“河水”的位置相符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：“之外”表示在范围以外，船行驶在河水之外，与句意矛盾。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”表示时间或前方，“行驶在河水之前”不表示地点，句意不通。"}, {"text": "之下", "is_correct": false, "explanation": "语义：“之下”表示位于下方，小船行驶在水面之下不合常理，句意不通。"}], "explanations": {"之中": "之中表示在某个范围的里面，与“河水”的位置相符。", "之外": "语义：“之外”表示在范围以外，船行驶在河水之外，与句意矛盾。", "之前": "语义：“之前”表示时间或前方，“行驶在河水之前”不表示地点，句意不通。", "之下": "语义：“之下”表示位于下方，小船行驶在水面之下不合常理，句意不通。"}, "sentence_index": 6, "correct_answer": "之中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小船在河水之中停在岸上。", "explanation": "这里应该用〈岸边〉。小船停在岸边应说“岸边”，“河水之中”指在水里，两者矛盾。"}, {"text": "鱼在水面之中游动。", "explanation": "这里应该用〈之下〉。鱼在水面之下游动，“水面之中”指在水面的内部，与“水面”的位置不符。"}, {"text": "他把书放在桌子之中。", "explanation": "这里应该用〈上〉。书放在桌面上，应说“桌子上”；桌子不是可以进入的空间，“之中”指在里面，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子藏在山谷里之中。", "corrected_sentence": "这个村子藏在山谷之中。", "error_description": "错误：在“之中”前多加了“里”。“之中”本身已表示“在……里面”，不能再加“里”，应说“这个村子藏在山谷之中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们藏树林之中。", "corrected_sentence": "他们藏在树林之中。", "error_description": "错误：漏掉介词“在”。“藏”后面表示地点要用“在”引出，应说“他们藏在树林之中”，不能说“藏树林之中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
