INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在某个范围或状态的里面。", "primary_collocate": null, "pronunciation": "zhī zhōng", "ipa": "ʈʂɨ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他生活在幸福之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都沉浸在快乐之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的好坏,就在你的选择之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们成长在爱之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市在雨声之中慢慢醒来。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陷入了深深的回忆之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在紧张的气氛之中,大家都不说话。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在忙碌之中忘了吃饭。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正处在变化之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案还在讨论之中。", "target_word": "之中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之中:处在某种范围或状态里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85beadd-467a-48ea-b48a-dbf1be933464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之中", "is_correct": true, "explanation": "之中表示处于某种状态或范围的里面，与“生活在幸福”的意思相符。"}, {"text": "之上", "is_correct": false, "explanation": "语义：“之上”表示位置在某物的上方，幸福是状态，不能处于其上方。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”表示时间先后，“生活在幸福之前”指时间，不指状态范围。"}, {"text": "之间", "is_correct": false, "explanation": "配价：“之间”需要两个或以上的对象，“幸福”只是一个状态，无法构成“之间”。"}], "explanations": {"之中": "之中表示处于某种状态或范围的里面，与“生活在幸福”的意思相符。", "之上": "语义：“之上”表示位置在某物的上方，幸福是状态，不能处于其上方。", "之前": "语义：“之前”表示时间先后，“生活在幸福之前”指时间，不指状态范围。", "之间": "配价：“之间”需要两个或以上的对象，“幸福”只是一个状态，无法构成“之间”。"}, "sentence_index": 0, "correct_answer": "之中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他之中的误会很快就解开了。", "explanation": "这里应该用〈之间〉。之间表示两者之间的关系，“我和他”是两人，不能用“之中”指某个范围的内部。"}, {"text": "比赛结束之中，大家都很激动。", "explanation": "这里应该用〈之后〉。“比赛结束”是时间点，应说“比赛结束之后”；之中指在某状态里面，与时间点不合。"}, {"text": "这个结果完全出乎意料，它在预料之中。", "explanation": "这里应该用〈之外〉。“出乎意料”说明没有想到，应说“在预料之外”；“在预料之中”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之中", "is_correct": true, "explanation": "之中表示处于某种气氛或状态的里面，与“紧张的气氛”相符。"}, {"text": "之首", "is_correct": false, "explanation": "语义：“之首”表示位于最前、居首，“气氛”没有首位，句意不通。"}, {"text": "之旁", "is_correct": false, "explanation": "搭配：“之旁”多指具体事物的一侧，不与“气氛”这类抽象状态搭配。"}, {"text": "之北", "is_correct": false, "explanation": "语义：“之北”表示方位，“气氛”没有方位，句意不通。"}], "explanations": {"之中": "之中表示处于某种气氛或状态的里面，与“紧张的气氛”相符。", "之首": "语义：“之首”表示位于最前、居首，“气氛”没有首位，句意不通。", "之旁": "搭配：“之旁”多指具体事物的一侧，不与“气氛”这类抽象状态搭配。", "之北": "语义：“之北”表示方位，“气氛”没有方位，句意不通。"}, "sentence_index": 6, "correct_answer": "之中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事超出了大家的想象之中。", "explanation": "这里应该用〈之外〉。“超出……之外”是固定说法，“之中”与“超出”矛盾，不能表示超出。"}, {"text": "他把书放在我的眼睛之中。", "explanation": "这里应该用〈面前〉。把书放在眼前应说“我的面前”；“之中”指在里面，书不能放进眼睛里。"}, {"text": "他在考试开始之中就交了卷。", "explanation": "这里应该用〈之前〉。“考试开始”之前交卷才合理，“之中”指在某状态里面，与时间顺序矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们生活在和平的之中。", "corrected_sentence": "他们生活在和平之中。", "error_description": "错误：“和平”与“之中”之间多了“的”。“之中”前面直接接名词，不能加“的”，应说“他们生活在和平之中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她沉思之中。", "corrected_sentence": "她陷入沉思之中。", "error_description": "错误：缺少“陷入”。“沉思之中”前需要“陷入”等动词，单说“她沉思之中”句子不完整，应说“她陷入沉思之中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36226843-0f42-4aed-a91d-7b97d5171281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
