INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "板块是像大木板一样的一大块地。", "primary_collocate": null, "pronunciation": "bǎn kuài", "ipa": "pan˨˩˦ kʰuai˥˩", "syllable_count": 2, "sentences": [{"text": "地球的表面是由几块大板块组成的。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个板块碰到一起，山就会长高。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块板块很大，也很厚。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海底的板块慢慢地往北走。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震常常发生在板块的边上。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上画出了欧亚板块。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山是两个板块一起挤出来的。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "板块每年只动几厘米。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的地下有一个很大的板块。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太平洋板块在海的下面。", "target_word": "板块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块板块", "label": "量词"}, {"form": "大板块", "label": "复合"}], "register": "中性", "sense_fingerprint": "像大木板一样又平又大的一整块陆地或地壳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "板块", "is_correct": true, "explanation": "板块（bǎn kuài）指像大木板一样又平又大的一整块陆地或地壳，正是本题的目标词。"}, {"text": "赶快", "is_correct": false, "explanation": "gǎn 与 bǎn 声母不同（g 与 b），意思是“赶快、加紧”，与地壳无关。"}, {"text": "百块", "is_correct": false, "explanation": "bǎi 与 bǎn 韵母不同（ai 与 an），意思是“一百块（钱）”。"}, {"text": "半块", "is_correct": false, "explanation": "bàn 与 bǎn 声调不同（第四声与第三声），意思是“半块、一半”。"}, {"text": "眼快", "is_correct": false, "explanation": "yǎn 与 bǎn 声母不同（零声母 y 与 b），意思是“看得快、眼疾手快”。"}], "explanations": {"板块": "板块（bǎn kuài）指像大木板一样又平又大的一整块陆地或地壳，正是本题的目标词。", "赶快": "gǎn 与 bǎn 声母不同（g 与 b），意思是“赶快、加紧”，与地壳无关。", "百块": "bǎi 与 bǎn 韵母不同（ai 与 an），意思是“一百块（钱）”。", "半块": "bàn 与 bǎn 声调不同（第四声与第三声），意思是“半块、一半”。", "眼快": "yǎn 与 bǎn 声母不同（零声母 y 与 b），意思是“看得快、眼疾手快”。"}, "sentence_index": null, "correct_answer": "板块"}, "level_3": {"options": [{"text": "板块", "is_correct": true, "explanation": "板块指地壳中巨大的岩石块，与“几块大”和“组成”搭配，符合句意。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想是抽象的，不能作为地球表面的一块块来组成地表。"}, {"text": "句子", "is_correct": false, "explanation": "搭配：“块”不能计量句子，“几块大句子”说不通。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：乐趣是心里的感受，不是构成地表的部分。"}], "explanations": {"板块": "板块指地壳中巨大的岩石块，与“几块大”和“组成”搭配，符合句意。", "思想": "语义：思想是抽象的，不能作为地球表面的一块块来组成地表。", "句子": "搭配：“块”不能计量句子，“几块大句子”说不通。", "乐趣": "语义：乐趣是心里的感受，不是构成地表的部分。"}, "sentence_index": 0, "correct_answer": "板块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山上摘了一大块板块，做成了果酱。", "explanation": "这里应该用〈水果〉。板块是一大片地或岩块，摘不下来，也做不成果酱。"}, {"text": "他把这块板块放进了冰箱。", "explanation": "这里应该用〈冰块〉。板块是一大片地，放不进冰箱；应说“一块冰”。"}, {"text": "板块卷走了很多房子。", "explanation": "这里应该用〈海啸〉。板块是地壳中的岩块，不会卷走房屋；卷走房屋的是海啸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "板块", "is_correct": true, "explanation": "板块指地壳中的大块岩层，两个板块挤在一起可以“挤出”山，符合句意。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不能被挤出一座山，“两个人挤出来的山”与常识相反。"}, {"text": "水", "is_correct": false, "explanation": "搭配：物质名词“水”不能直接用“两个”计数，数量搭配不当。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能被挤压成山，句意荒谬。"}], "explanations": {"板块": "板块指地壳中的大块岩层，两个板块挤在一起可以“挤出”山，符合句意。", "人": "语义：人不能被挤出一座山，“两个人挤出来的山”与常识相反。", "水": "搭配：物质名词“水”不能直接用“两个”计数，数量搭配不当。", "蛋糕": "语义：蛋糕不能被挤压成山，句意荒谬。"}, "sentence_index": 6, "correct_answer": "板块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把这块板块穿在身上，去地里干活。", "explanation": "这里应该用〈衣服〉。板块是一大片地，不能穿在身上；应说“穿上衣服”。"}, {"text": "海底的板块很好吃，很多人爱买。", "explanation": "这里应该用〈海鲜〉。板块是一大片地或岩块，不是食物，不能说“好吃”。"}, {"text": "这个板块每天早上都去跑步。", "explanation": "这里应该用〈运动员〉。板块是一大块地，不会跑步，应指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球表面分成了好几块大板块们，它们每年都在移动。", "corrected_sentence": "地球表面分成了好几块大板块，它们每年都在移动。", "error_description": "后缀错误：「们」只加在指人的名词后，「板块」指地壳中的大岩块，不能加「们」。应说：地球表面分成了好几块大板块，它们每年都在移动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一大根板块在海底慢慢往北走。", "corrected_sentence": "这一大块板块在海底慢慢往北走。", "error_description": "错误：量词“根”用于细长的东西，板块应用量词“块”。正确说法是“一大块板块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
