INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "（书面）表示禁止或劝阻，相当于“不要”。", "primary_collocate": null, "pronunciation": "mò", "ipa": "mwo˥˩", "syllable_count": 1, "sentences": [{"text": "闲人莫入。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危险区域，游客莫靠近。", "target_word": "莫", "complexity_tier": "T3", "furigana": "wēixiǎn qūyù yóukè mò kàojìn", "sentence_source": "generated"}, {"text": "车厢内，乘客莫大声通话。", "target_word": "莫", "complexity_tier": "T3", "furigana": "chēxiāng nèi chéngkè mò dàshēng tōnghuà", "sentence_source": "generated"}, {"text": "展品易碎，莫用手触摸。", "target_word": "莫", "complexity_tier": "T3", "furigana": "zhǎnpǐn yì suì mò yòng shǒu chùmō", "sentence_source": "generated"}, {"text": "公共场所，莫乱扔垃圾。", "target_word": "莫", "complexity_tier": "T3", "furigana": "gōnggòng chǎngsuǒ mò luàn rēng lājī", "sentence_source": "generated"}, {"text": "池边路滑，儿童莫独自玩耍。", "target_word": "莫", "complexity_tier": "T3", "furigana": "chí biān lù huá értóng mò dúzì wánshuǎ", "sentence_source": "generated"}, {"text": "会场内，观众莫随意走动。", "target_word": "莫", "complexity_tier": "T3", "furigana": "huìchǎng nèi guānzhòng mò suíyì zǒudòng", "sentence_source": "generated"}, {"text": "此处施工，行人莫入。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆内，读者莫高声喧哗。", "target_word": "莫", "complexity_tier": "T3", "furigana": "túshūguǎn nèi dúzhě mò gāoshēng xuānhuá", "sentence_source": "generated"}, {"text": "遇事应冷静，莫冲动行事。", "target_word": "莫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "莫要", "label": "复合"}], "register": "书面", "sense_fingerprint": "莫：书面语中用于告示、劝诫，表示禁止或劝阻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d6f595-c5fd-45de-a729-3a0510ed58f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：书面语，表示禁止或劝阻。"}, {"text": "破", "is_correct": false, "explanation": "pò 与 mò 声母不同（p 与 m），意思是破损。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 mò 韵母不同（u 与 o），意思是树木。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mò 韵母不同（a 与 o），意思是责骂。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。"}, {"text": "磨", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。"}], "explanations": {"莫": "正确。莫（mò）：书面语，表示禁止或劝阻。", "破": "pò 与 mò 声母不同（p 与 m），意思是破损。", "木": "mù 与 mò 韵母不同（u 与 o），意思是树木。", "骂": "mà 与 mò 韵母不同（a 与 o），意思是责骂。", "摸": "mō（第一声）与 mò（第四声）声调不同，意思是用手触碰。", "磨": "mó（第二声）与 mò（第四声）声调不同，意思是研磨。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：书面语中表示禁止，与“闲人……入”的告示语境相合。"}, {"text": "才", "is_correct": false, "explanation": "语义：「才」表示限定，“闲人才入”与告示禁止闲人入内的意思相反。"}, {"text": "都", "is_correct": false, "explanation": "语义：「都」表示全部，“闲人都入”与告示的禁止意思相悖。"}, {"text": "偏", "is_correct": false, "explanation": "语域：「偏」偏口语，与告示的书面语体不符；且「偏」表示故意，与禁止的语境不合。"}], "explanations": {"莫": "正确。莫：书面语中表示禁止，与“闲人……入”的告示语境相合。", "才": "语义：「才」表示限定，“闲人才入”与告示禁止闲人入内的意思相反。", "都": "语义：「都」表示全部，“闲人都入”与告示的禁止意思相悖。", "偏": "语域：「偏」偏口语，与告示的书面语体不符；且「偏」表示故意，与禁止的语境不合。"}, "sentence_index": 0, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我莫想来参加会议。", "explanation": "这里应该用〈不想〉。莫表示禁止，不能用来否定“想”。"}, {"text": "我莫明白他的意思。", "explanation": "这里应该用〈不明白〉。莫表示禁止，不能用来否定“明白”。"}, {"text": "这份报告莫写完了。", "explanation": "这里应该用〈没〉，表示已经完成的事。“莫”只用于禁止或劝阻，不能陈述已完成的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫（mò）：书面语，表示禁止或劝阻。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。"}, {"text": "握", "is_correct": false, "explanation": "wò 与 mò 声母不同（w 与 m），意思是握住。"}, {"text": "模", "is_correct": false, "explanation": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}], "explanations": {"莫": "正确。莫（mò）：书面语，表示禁止或劝阻。", "妈": "mā（第一声）与 mò（第四声）声调不同，意思是母亲。", "马": "mǎ（第三声）与 mò（第四声）声调不同，意思是马匹。", "握": "wò 与 mò 声母不同（w 与 m），意思是握住。", "模": "mó（第二声）与 mò（第四声）声调不同，意思是模样或模型。"}, "sentence_index": null, "correct_answer": "莫"}, "level_3": {"options": [{"text": "莫", "is_correct": true, "explanation": "正确。莫：书面语中表示禁止，与“观众……随意走动”的会场规定相合。"}, {"text": "竟", "is_correct": false, "explanation": "语义：「竟」表示出乎意料，与会场规定观众不得随意走动的语境相悖。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，与会场内的禁止语境不协调。"}, {"text": "又", "is_correct": false, "explanation": "体貌：「又」表示重复发生，与“莫……”的劝阻语境不合。"}], "explanations": {"莫": "正确。莫：书面语中表示禁止，与“观众……随意走动”的会场规定相合。", "竟": "语义：「竟」表示出乎意料，与会场规定观众不得随意走动的语境相悖。", "却": "语义：「却」表示转折，与会场内的禁止语境不协调。", "又": "体貌：「又」表示重复发生，与“莫……”的劝阻语境不合。"}, "sentence_index": 6, "correct_answer": "莫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天莫来上班。", "explanation": "这里应该用〈没〉，表示否定已经发生的事。莫只用于劝阻，不能用于过去。"}, {"text": "这张书桌莫正好放我的电脑。", "explanation": "这里应该删去〈莫〉。“莫”表示禁止，不能修饰“正好”。"}, {"text": "她莫会开车。", "explanation": "这里应该用〈不会〉。莫表示禁止，不能用于说明能力上的否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请乘客不莫随意开门。", "corrected_sentence": "请乘客莫随意开门。", "error_description": "多余的“不”与“莫”重复否定。“莫”已表示禁止，不能再加“不”，正确形式是“请乘客莫随意开门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展厅内，游客莫的随意触碰展品。", "corrected_sentence": "展厅内，游客莫随意触碰展品。", "error_description": "助词错误：“莫”后不能加“的”，“莫的随意”不通。正确形式是“游客莫随意触碰展品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e60c1cb-fc65-4ced-92f8-7f2dd24eff26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "从前", "is_correct": true, "explanation": "反义：“从前”指过去，与“如今”所指的现在相对。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：“海洋”指大面积的咸水，与“如今”的时间意义没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”指房屋上透光通风的开口，与“如今”没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”指背在身上装书的包，与“如今”没有反义关系。"}], "correct_answer": "从前", "explanations": {"从前": "反义：“从前”指过去，与“如今”所指的现在相对。", "海洋": "无关：“海洋”指大面积的咸水，与“如今”的时间意义没有反义关系。", "窗户": "无关：“窗户”指房屋上透光通风的开口，与“如今”没有反义关系。", "书包": "无关：“书包”指背在身上装书的包，与“如今”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "反义：“以前”指过去的时候，与“如今”所指的现在相对。"}, {"text": "树林", "is_correct": false, "explanation": "无关：“树林”指成片生长的树，与“如今”没有反义关系。"}, {"text": "钢笔", "is_correct": false, "explanation": "无关：“钢笔”是用来写字的工具，与“如今”没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：“厨房”是做饭的房间，与“如今”没有反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "反义：“以前”指过去的时候，与“如今”所指的现在相对。", "树林": "无关：“树林”指成片生长的树，与“如今”没有反义关系。", "钢笔": "无关：“钢笔”是用来写字的工具，与“如今”没有反义关系。", "厨房": "无关：“厨房”是做饭的房间，与“如今”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "如今是现在这个时候。", "primary_collocate": null, "pronunciation": "rú jīn", "ipa": "ɻu˧˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "如今的城市和过去很不一样。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他如今住在上海。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如今很多人用手机买东西。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子如今变得很漂亮。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如今的孩子都喜欢玩电脑游戏。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前他很穷，如今他有了自己的公司。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如今的生活比以前方便多了。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，如今的水果真便宜。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她如今是一名老师。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如今坐火车去北京只要四个小时。", "target_word": "如今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "如今：指现在这个时候，常与过去对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如今", "is_correct": true, "explanation": "正确：“如今”指现在，与句中的“过去”形成对比。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去的时候，与句中用来对比的“过去”同指，不能描述现在的城市。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指某个过去的年份，与“过去”一样指向以往，无法表示现在。"}, {"text": "昔日", "is_correct": false, "explanation": "语域：“昔日”是书面语，与句子的口语语域不协调，而且指过去，无法表示现在。"}], "explanations": {"如今": "正确：“如今”指现在，与句中的“过去”形成对比。", "从前": "语义：“从前”指过去的时候，与句中用来对比的“过去”同指，不能描述现在的城市。", "当年": "语义：“当年”指某个过去的年份，与“过去”一样指向以往，无法表示现在。", "昔日": "语域：“昔日”是书面语，与句子的口语语域不协调，而且指过去，无法表示现在。"}, "sentence_index": 0, "correct_answer": "如今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我如今明年要去中国留学。", "explanation": "〈如今〉指说话时的现在，不能与“明年”这样的未来时间搭配；这里应直接去掉〈如今〉，说“我明年要去中国留学”。"}, {"text": "那一年夏天，我如今在北京打工。", "explanation": "〈如今〉指说话时的现在，不能用于“那一年夏天”这样的过去时间，这里应改用“那时”。"}, {"text": "我如今上周才到北京。", "explanation": "〈如今〉指说话时的现在，不能用于“上周”这样的过去时间；这里应直接去掉〈如今〉，说“我上周才到北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如今", "is_correct": true, "explanation": "正确：“如今”指现在，与“比以前方便”的现在状况相符。"}, {"text": "往昔", "is_correct": false, "explanation": "语义：“往昔”指过去，与句中“以前”同指，无法表示现在的生活。"}, {"text": "古时", "is_correct": false, "explanation": "语义：“古时”指遥远的古代，与句中用来比较的“以前”不相符。"}, {"text": "当初", "is_correct": false, "explanation": "语义：“当初”指事情开始的时候，无法与“现在的生活比以前方便”对应。"}], "explanations": {"如今": "正确：“如今”指现在，与“比以前方便”的现在状况相符。", "往昔": "语义：“往昔”指过去，与句中“以前”同指，无法表示现在的生活。", "古时": "语义：“古时”指遥远的古代，与句中用来比较的“以前”不相符。", "当初": "语义：“当初”指事情开始的时候，无法与“现在的生活比以前方便”对应。"}, "sentence_index": 6, "correct_answer": "如今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她如今曾经是一名老师。", "explanation": "〈如今〉指现在的情况，句中“如今”与“曾经”所指的过去相互矛盾，把现在与过去混在一起，语义自相矛盾。"}, {"text": "小时候他如今就很爱读书。", "explanation": "〈如今〉指现在，不能用于“小时候”这样的过去时间；说过去的情况要用〈当年〉或〈以前〉。"}, {"text": "这座房子如今在十年前就盖好了。", "explanation": "〈如今〉指现在的状况，不能用来说明过去完成的动作发生在哪一年；说过去的事要用〈当时〉或〈那时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "如今地老人都会用智能手机。", "corrected_sentence": "如今的老人都会用智能手机。", "error_description": "结构助词错误：“如今”修饰名词“老人”时应用“的”，“地”用于修饰动词，不能用在名词前。正确说法是“如今的老人都会用智能手机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "如今地村子变得很安静。", "corrected_sentence": "如今的村子变得很安静。", "error_description": "结构助词错误：“如今”修饰名词“村子”时应用“的”，“地”用于修饰动词，不能用在名词前。正确说法是“如今的村子变得很安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
