INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "业主是房子或店铺的主人。", "primary_collocate": null, "pronunciation": "yè zhǔ", "ipa": "jɛ⁵¹ ʈʂu²¹⁴", "syllable_count": 2, "sentences": [{"text": "这间店铺的业主住在国外。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主打算把房子卖掉。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先问问业主同不同意。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主每个月都来收一次房租。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的业主换了人。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的业主开了一个会。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主把钥匙交给了租房的人。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子的业主正在门口等着。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主说，这个铺子不能再便宜了。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这套房子的业主。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "房子或店铺的主人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”是乘车的人，店铺的所有人不会是乘客。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”与店铺的所有权无关，句中“住在国外”也不符合学生的身份。"}, {"text": "住户", "is_correct": false, "explanation": "搭配：“住户”指住在房屋里的人，店铺的所有人不说“住户”。"}, {"text": "业主", "is_correct": true, "explanation": "业主指房屋或店铺的所有人，与“这间店铺的”搭配，可以住在国外。"}], "explanations": {"乘客": "语义：“乘客”是乘车的人，店铺的所有人不会是乘客。", "学生": "语义：“学生”与店铺的所有权无关，句中“住在国外”也不符合学生的身份。", "住户": "搭配：“住户”指住在房屋里的人，店铺的所有人不说“住户”。", "业主": "业主指房屋或店铺的所有人，与“这间店铺的”搭配，可以住在国外。"}, "sentence_index": 0, "correct_answer": "业主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的业主每天都来检查工作。", "explanation": "这里应该用〈老板〉。业主指房屋或店铺的所有人，公司里检查工作的上司要说老板。"}, {"text": "这位业主每天吹哨，负责判罚比赛。", "explanation": "这里应该用〈裁判〉。业主指房屋或店铺的所有人，吹哨判罚比赛的人要说裁判。"}, {"text": "班里的业主每天都来点名，很严格。", "explanation": "这里应该用〈班主任〉。业主指房屋或店铺的所有人，管理班级的老师要说班主任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "配价：“交给”要求能够施事的人作主语，“椅子”不能把钥匙交给别人。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是来买东西的人，不会把店铺或房屋的钥匙交给租房的人。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客只是来参观的人，与房屋钥匙的交接没有关系。"}, {"text": "业主", "is_correct": true, "explanation": "业主是房屋的所有人，才能把钥匙交给租房的人。"}], "explanations": {"椅子": "配价：“交给”要求能够施事的人作主语，“椅子”不能把钥匙交给别人。", "顾客": "语义：顾客是来买东西的人，不会把店铺或房屋的钥匙交给租房的人。", "游客": "语义：游客只是来参观的人，与房屋钥匙的交接没有关系。", "业主": "业主是房屋的所有人，才能把钥匙交给租房的人。"}, "sentence_index": 6, "correct_answer": "业主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的业主每天都教我打球。", "explanation": "这里应该用〈教练〉。业主指房屋或店铺的所有人，教人打球的要说教练。"}, {"text": "这辆车的业主很爱干净。", "explanation": "这里应该用〈车主〉。业主不指车辆的所有者，车的主人要说车主。"}, {"text": "今晚晚会的业主是一位明星，大家都认识他。", "explanation": "这里应该用〈主持人〉。业主指房屋或店铺的所有人，主持晚会的人要说主持人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅的一只业主昨天来过一次。", "corrected_sentence": "这家餐厅的一位业主昨天来过一次。", "error_description": "量词用错：“业主”指人，应用量词“位”，“只”不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一座业主正在门口等我们。", "corrected_sentence": "一位业主正在门口等我们。", "error_description": "量词用错：“业主”指人，应用量词“位”；“座”用于楼房、山等，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
