INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拥有房屋或产业的人。", "primary_collocate": null, "pronunciation": "yè zhǔ", "ipa": "jɛ⁵¹ ʈʂu²¹⁴", "syllable_count": 2, "sentences": [{"text": "他买了这里的房子，成了新业主。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主们都希望小区环境好一点。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位业主在城东还有三套房子。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子漏水了，业主得自己修。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里的业主都认识他。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请业主带着身份证来办手续。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有业主才能在这里停车。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子的业主是一位老先生。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是这栋楼的业主？", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业主去年把房子租给了学生。", "target_word": "业主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "拥有房屋或产业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：买房子不会让人成为学生，“成了新学生”与句意不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：买下房子与成为医生无关，“成了新医生”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“成了新”后接的是身份或称谓，不说“成了新房子”。"}, {"text": "业主", "is_correct": true, "explanation": "业主指房屋的所有人，买下房子后就成了新业主。"}], "explanations": {"学生": "语义：买房子不会让人成为学生，“成了新学生”与句意不符。", "医生": "语义：买下房子与成为医生无关，“成了新医生”说不通。", "房子": "搭配：“成了新”后接的是身份或称谓，不说“成了新房子”。", "业主": "业主指房屋的所有人，买下房子后就成了新业主。"}, "sentence_index": 0, "correct_answer": "业主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这匹马的业主每天都来喂它。", "explanation": "这里应该用〈主人〉。业主多指房屋或产业的所有人，马的主人要说主人。"}, {"text": "我的业主每天都来公司检查工作。", "explanation": "这里应该用〈老板〉。业主指拥有房屋或产业的人，公司里检查工作的上司要说老板。"}, {"text": "这位业主在大学里教我们历史，很有名。", "explanation": "这里应该用〈教授〉。业主指拥有房屋或产业的人，在大学任教的人要说教授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空调", "is_correct": false, "explanation": "配价：“停车”要求能开车的人作主语，“空调”不能停车。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是搭车的人，不会因为是乘客就有在这里停车的资格。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不会开车，与停车的资格无关，句意不通。"}, {"text": "业主", "is_correct": true, "explanation": "业主有房屋或车位的权利，所以“只有业主才能在这里停车”成立。"}], "explanations": {"空调": "配价：“停车”要求能开车的人作主语，“空调”不能停车。", "乘客": "语义：乘客是搭车的人，不会因为是乘客就有在这里停车的资格。", "孩子": "语义：孩子不会开车，与停车的资格无关，句意不通。", "业主": "业主有房屋或车位的权利，所以“只有业主才能在这里停车”成立。"}, "sentence_index": 6, "correct_answer": "业主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位业主每天都来学校上课，教我们数学。", "explanation": "这里应该用〈老师〉。业主指拥有房屋或产业的人，在学校上课的人要说老师。"}, {"text": "这辆车的业主去年把车卖给了学生。", "explanation": "这里应该用〈车主〉。业主指拥有房屋或产业的人，车辆的所有者要说车主。"}, {"text": "这场比赛的业主吹哨判罚，大家都服气。", "explanation": "这里应该用〈裁判〉。业主指拥有房屋或产业的人，吹哨判罚比赛的人要说裁判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套房子的一只新业主刚搬进来。", "corrected_sentence": "这套房子的一位新业主刚搬进来。", "error_description": "量词用错：“业主”指人，应用量词“位”，“只”不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的一条业主昨天搬走了。", "corrected_sentence": "这栋楼的一位业主昨天搬走了。", "error_description": "量词用错：“业主”指人，应用量词“位”，“条”用于细长的东西，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
