INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感情深厚、关系亲近的。", "primary_collocate": null, "pronunciation": "qīn ài", "ipa": "tɕʰin ai", "syllable_count": 2, "sentences": [{"text": "亲爱的祖国，我为你骄傲。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我最亲爱的朋友。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都爱我们亲爱的老师。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想念亲爱的家人。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常想起亲爱的战友们。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握着亲爱的外婆的手，不想松开。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是我最亲爱的人。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，他抱了抱亲爱的女儿。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有我亲爱的同事们。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给亲爱的弟弟买了一份礼物。", "target_word": "亲爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲爱的", "label": "定语形式"}, {"form": "最亲爱的", "label": "最高程度形式"}, {"form": "親愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修饰人或事物，表示感情深厚、关系亲近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与“祖国”和“我为你骄傲”的情感相冲突，句子语义不通。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“祖国”，表示感情深厚，与“为你骄傲”的情感一致。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”说的是味道，不能用来修饰“祖国”。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：“废弃”指被弃置的东西，与“祖国”和“为你骄傲”的语境相矛盾。"}], "explanations": {"冷漠": "语义：“冷漠”与“祖国”和“我为你骄傲”的情感相冲突，句子语义不通。", "亲爱": "“亲爱”修饰“祖国”，表示感情深厚，与“为你骄傲”的情感一致。", "咸": "搭配：“咸”说的是味道，不能用来修饰“祖国”。", "废弃": "语义：“废弃”指被弃置的东西，与“祖国”和“为你骄傲”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务很亲爱。", "explanation": "这里应该用〈亲切〉。“亲爱”不用来形容服务，形容服务态度要用“亲切”。"}, {"text": "我们要打倒亲爱的敌人。", "explanation": "这里应该用〈可恨〉。「亲爱」表示感情深厚，用来修饰敌人不合逻辑，形容敌人应说「可恨的敌人」。"}, {"text": "我和同桌的关系很亲爱。", "explanation": "这里应该用〈亲密〉。“亲爱”侧重人的感情或称呼，描述关系要用“亲密”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": false, "explanation": "语义：“奶奶”是亲人，“最陌生的人”与前半句的亲近关系相矛盾。"}, {"text": "亲爱", "is_correct": true, "explanation": "“亲爱”修饰“人”，表示感情深厚，与“奶奶是我最……的人”的语境一致。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“炎热”描写天气，不用来形容人与人之间的关系。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”表示不熟悉，与“奶奶”的亲近关系相矛盾。"}], "explanations": {"陌生": "语义：“奶奶”是亲人，“最陌生的人”与前半句的亲近关系相矛盾。", "亲爱": "“亲爱”修饰“人”，表示感情深厚，与“奶奶是我最……的人”的语境一致。", "炎热": "搭配：“炎热”描写天气，不用来形容人与人之间的关系。", "生疏": "语义：“生疏”表示不熟悉，与“奶奶”的亲近关系相矛盾。"}, "sentence_index": 6, "correct_answer": "亲爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很亲爱。", "explanation": "这里应该用〈便宜〉。“亲爱”不用来形容价格，说价格低要用“便宜”。"}, {"text": "这件衣服的颜色很亲爱。", "explanation": "这里应该用〈鲜艳〉。“亲爱”不用来形容颜色，说颜色醒目要用“鲜艳”。"}, {"text": "他对陌生人很亲爱。", "explanation": "这里应该用〈友善〉。“亲爱”表示对亲近者的深厚感情，对陌生人应该说“友善”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "亲爱故乡，我为你骄傲。", "corrected_sentence": "亲爱的故乡，我为你骄傲。", "error_description": "错误：“亲爱故乡”漏掉了“的”。正确：“亲爱的故乡”。“亲爱”作定语修饰名词时，后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "亲爱地家人，请回家吃饭。", "corrected_sentence": "亲爱的家人，请回家吃饭。", "error_description": "错误：“亲爱地家人”用了“地”。正确：“亲爱的家人”。“地”修饰动词，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
