INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帝国是由皇帝管着的、很大的国家。", "primary_collocate": null, "pronunciation": "dì guó", "ipa": "ti˥˩ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这个帝国有两千多年的历史。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的罗马帝国非常大。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝住在帝国的首都。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个帝国后来被别的国家打败了。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帝国的土地很大，人也很多。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位皇帝管理着一个大帝国。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里读到了一个古老帝国的故事。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帝国的军队走过很多地方。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年以前，这个帝国很有名。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帝国的皇帝每天都很忙。", "target_word": "帝国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个帝国", "label": "量词"}, {"form": "帝國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帝国：皇帝统治的大国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帝国", "is_correct": true, "explanation": "正确：“帝国”指由皇帝统治的大国，可以有两千多年的历史。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是现代的经济组织，不可能有两千多年的历史。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“历史”一般用于国家、文化等，不能说“手机有两千多年的历史”。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是二十世纪才出现的，不可能有两千多年的历史。"}], "explanations": {"帝国": "正确：“帝国”指由皇帝统治的大国，可以有两千多年的历史。", "公司": "语义：公司是现代的经济组织，不可能有两千多年的历史。", "手机": "搭配：“历史”一般用于国家、文化等，不能说“手机有两千多年的历史”。", "电视": "语义：电视是二十世纪才出现的，不可能有两千多年的历史。"}, "sentence_index": 0, "correct_answer": "帝国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在市场买了一个帝国。", "explanation": "〈帝国〉指国家，不是可以买卖的物品，“买了一个帝国”不通，这里应改用具体的物品名称。"}, {"text": "这个帝国只有三十个人，很小。", "explanation": "〈帝国〉指疆域广大、由皇帝统治的国家，不能用来形容只有三十个人的地方，这里应改用〈小国〉。"}, {"text": "这个帝国每天早上七点开始上课。", "explanation": "〈帝国〉指国家，不能上课，上课的是学校，这里应改用〈学校〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帝国", "is_correct": true, "explanation": "正确：“帝国”是古代由皇帝统治的大国，可以有古老的故事。"}, {"text": "打开", "is_correct": false, "explanation": "语法：“打开”是动词，不能放在“古老”后面当名词用。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，“一个古老便宜的故事”不通。"}, {"text": "很快", "is_correct": false, "explanation": "语法：“很快”是副词短语，不能作“故事”的定语中心。"}], "explanations": {"帝国": "正确：“帝国”是古代由皇帝统治的大国，可以有古老的故事。", "打开": "语法：“打开”是动词，不能放在“古老”后面当名词用。", "便宜": "语法：“便宜”是形容词，“一个古老便宜的故事”不通。", "很快": "语法：“很快”是副词短语，不能作“故事”的定语中心。"}, "sentence_index": 6, "correct_answer": "帝国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个帝国每四年选一次总统。", "explanation": "〈帝国〉由皇帝统治，不通过选举产生总统，这里应该用〈共和国〉。"}, {"text": "这个帝国只有一个村子，全部人口只有几百人。", "explanation": "〈帝国〉指疆域广大、由皇帝统治的国家，不能用来形容只有一个村子的地方，这里应改用〈部落〉。"}, {"text": "大英帝国是一支很有名的足球队。", "explanation": "〈帝国〉指由皇帝统治的国家，不指体育团体，这里应改用〈俱乐部〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古代的中国曾经是一只强大的帝国。", "corrected_sentence": "古代的中国曾经是一个强大的帝国。", "error_description": "量词错误：“帝国”应该用量词“个”，“只”用于动物等，不能用于国家。正确说法是“一个强大的帝国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个帝国地边境很长。", "corrected_sentence": "这个帝国的边境很长。", "error_description": "结构助词错误：“帝国”修饰名词“边境”时应用“的”，“地”用于修饰动词，不能用在名词前。正确说法是“这个帝国的边境很长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
