INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标准间是旅馆里有两张床的普通房间。", "primary_collocate": null, "pronunciation": "biāo zhǔn jiān", "ipa": "piau˥ ʈʂuən˨˩˦ tɕjɛn˥", "syllable_count": 3, "sentences": [{"text": "我们订了一个标准间。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准间一晚多少钱？", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家旅馆的标准间很干净。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友住标准间，有两张床。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准间里有电视和空调。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我们一间标准间。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准间不大，但是很舒服。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的标准间在三楼。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出差时总是住标准间。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标准间有一个小窗户。", "target_word": "标准间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "双人标准间", "label": "复合"}], "register": "中性", "sense_fingerprint": "旅馆里有两张床的普通房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准间", "is_correct": true, "explanation": "正确：标准间指旅馆里有两张床的普通房间，可以订，与“一个”搭配。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是公共场所，不能像旅馆房间一样“订一个”来住。"}, {"text": "床", "is_correct": false, "explanation": "搭配：床的量词是“张”，不说“一个床”，也不说订床。"}, {"text": "客厅", "is_correct": false, "explanation": "语义：客厅是家里的起居室，不是旅馆里可以订的房间。"}], "explanations": {"标准间": "正确：标准间指旅馆里有两张床的普通房间，可以订，与“一个”搭配。", "公园": "语义：公园是公共场所，不能像旅馆房间一样“订一个”来住。", "床": "搭配：床的量词是“张”，不说“一个床”，也不说订床。", "客厅": "语义：客厅是家里的起居室，不是旅馆里可以订的房间。"}, "sentence_index": 0, "correct_answer": "标准间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们订了一间标准间，有客厅和厨房。", "explanation": "这里应该用〈套房〉。标准间是两张床的普通房间，没有客厅；有客厅的房间要说套房。"}, {"text": "我一个人出差，订了一间标准间，只有一张单人床。", "explanation": "这里应该用〈单人间〉。标准间有两张床；只有一张单人床的房间要说单人间。"}, {"text": "这间标准间只有一张很大的床，很适合情侣。", "explanation": "这里应该用〈大床房〉。标准间配两张床；只有一张大床、适合情侣的房间要说大床房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准间", "is_correct": true, "explanation": "正确：标准间指普通客房，“不大”形容空间，“很舒服”形容住的感受，二者都说得通。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是印刷品，不能用“不大”形容空间，也谈不上“很舒服”的居住感受。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“很舒服”说住处或感受，不与“作业”搭配。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是小物件，句子说的是住处，钥匙不能“很舒服”。"}], "explanations": {"标准间": "正确：标准间指普通客房，“不大”形容空间，“很舒服”形容住的感受，二者都说得通。", "报纸": "语义：报纸是印刷品，不能用“不大”形容空间，也谈不上“很舒服”的居住感受。", "作业": "搭配：“很舒服”说住处或感受，不与“作业”搭配。", "钥匙": "语义：钥匙是小物件，句子说的是住处，钥匙不能“很舒服”。"}, "sentence_index": 6, "correct_answer": "标准间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间标准间里住了四个学生，每人一个衣柜。", "explanation": "这里应该用〈多人间〉。标准间是两张床的普通房间，不会住四个人；四人合住的房间要说多人间。"}, {"text": "这间标准间带有独立办公室，适合经常出差的商务人士。", "explanation": "这里应该用〈商务间〉。标准间是两张床的普通房间，没有独立办公室；带办公室的房间要说商务间。"}, {"text": "这间标准间有一个大厨房，可以自己做饭。", "explanation": "这里应该用〈公寓〉。标准间是两张床的普通房间，没有完整的厨房；能自己做饭的房间要说公寓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家旅馆还有一张标准间。", "corrected_sentence": "这家旅馆还有一间标准间。", "error_description": "“标准间”是房间，量词应用“间”，不用“张”（“张”多用于床、桌子等）。正确说法：这家旅馆还有一间标准间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家旅馆又加了两只标准间。", "corrected_sentence": "这家旅馆又加了两间标准间。", "error_description": "“标准间”是房间，量词应用“间”，不用“只”（“只”多用于动物等）。正确说法：这家旅馆又加了两间标准间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
