INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "撞击;使受到挫折或损害。", "primary_collocate": null, "pronunciation": "dǎ jī", "ipa": "ta˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "暴雨猛烈地打击着屋顶。", "target_word": "打击", "complexity_tier": "T3", "furigana": "bào yǔ měng liè de dǎ jī zhe wū dǐng", "sentence_source": "generated"}, {"text": "连续的裁员打击了员工的积极性。", "target_word": "打击", "complexity_tier": "T3", "furigana": "lián xù de cái yuán dǎ jī le yuán gōng de jī jí xìng", "sentence_source": "generated"}, {"text": "这场大雨严重打击了果农。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疫情打击了很多小饭馆的生意。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次失败严重打击了球队的士气。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海浪不停地打击着岩石。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰雹打击着窗户,声音很大。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气打击过这个小镇的旅游业。", "target_word": "打击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震严重打击了当地的经济。", "target_word": "打击", "complexity_tier": "T3", "furigana": "zhè cì dì zhèn yán zhòng dǎ jī le dāng dì de jīng jì", "sentence_source": "generated"}, {"text": "价格战打击了小商店,有的关门了。", "target_word": "打击", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打击了", "label": "完成体"}, {"form": "打击着", "label": "进行体"}, {"form": "打击过", "label": "经历体"}, {"form": "打擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打击:撞击;使受损害,严厉制止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c4d128-43e8-4390-b92a-c10afdd8f3f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89986, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打击", "is_correct": true, "explanation": "正确答案。打击，dǎjī，意思是撞击，或使受到挫折、损害。"}, {"text": "打气", "is_correct": false, "explanation": "声母与声调都不同（qì 与 jī），意思是打气、鼓劲。"}, {"text": "打进", "is_correct": false, "explanation": "jìn（第四声）与 jī（第一声）韵母不同，意思是打入、打进。"}, {"text": "大吉", "is_correct": false, "explanation": "dà jí 与 dǎ jī 两个音节声调都不同，意思是大吉、运气好。"}, {"text": "大计", "is_correct": false, "explanation": "dà jì 与 dǎ jī 两个音节声调都不同，意思是重大的计划。"}], "explanations": {"打击": "正确答案。打击，dǎjī，意思是撞击，或使受到挫折、损害。", "打气": "声母与声调都不同（qì 与 jī），意思是打气、鼓劲。", "打进": "jìn（第四声）与 jī（第一声）韵母不同，意思是打入、打进。", "大吉": "dà jí 与 dǎ jī 两个音节声调都不同，意思是大吉、运气好。", "大计": "dà jì 与 dǎ jī 两个音节声调都不同，意思是重大的计划。"}, "sentence_index": null, "correct_answer": "打击"}, "level_3": {"options": [{"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”需要人有意地去擦，暴雨不会擦拭屋顶。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”是修复破损，与“猛烈地”所描述的破坏性动作不符。"}, {"text": "抚摸", "is_correct": false, "explanation": "语义：“抚摸”是轻柔的动作，与“猛烈地”矛盾。"}, {"text": "打击", "is_correct": true, "explanation": "正确答案。“暴雨猛烈地打击着屋顶”表示暴雨不停地撞击屋顶。"}], "explanations": {"擦拭": "搭配：“擦拭”需要人有意地去擦，暴雨不会擦拭屋顶。", "修补": "语义：“修补”是修复破损，与“猛烈地”所描述的破坏性动作不符。", "抚摸": "语义：“抚摸”是轻柔的动作，与“猛烈地”矛盾。", "打击": "正确答案。“暴雨猛烈地打击着屋顶”表示暴雨不停地撞击屋顶。"}, "sentence_index": 0, "correct_answer": "打击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天打击两次药。", "explanation": "这里应该用〈服〉。打击不能用于药物，每天吃两次药要说“服药”。"}, {"text": "美丽的风景打击了许多游客。", "explanation": "这里应该用〈吸引〉。打击表示撞击，或使人受挫、受损，不能表示吸引游客。"}, {"text": "他打击了一锅汤，汤很好喝。", "explanation": "这里应该用〈煮〉。打击不能用于烹饪，做汤要用“煮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89986, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打击", "is_correct": true, "explanation": "正确答案。打击，dǎjī，意思是撞击，或使受到挫折、损害。"}, {"text": "打劫", "is_correct": false, "explanation": "jié（第二声）与 jī（第一声）韵母与声调都不同，意思是抢劫。"}, {"text": "搭机", "is_correct": false, "explanation": "dā jī 与 dǎ jī 第一个音节声调不同（第一声与第三声），意思是坐飞机。"}, {"text": "打酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jī 韵母不同，意思是去买酒。"}], "explanations": {"打击": "正确答案。打击，dǎjī，意思是撞击，或使受到挫折、损害。", "打劫": "jié（第二声）与 jī（第一声）韵母与声调都不同，意思是抢劫。", "搭机": "dā jī 与 dǎ jī 第一个音节声调不同（第一声与第三声），意思是坐飞机。", "打酒": "jiǔ（第三声）与 jī 韵母不同，意思是去买酒。"}, "sentence_index": null, "correct_answer": "打击"}, "level_3": {"options": [{"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”要由人涂抹，冰雹不会粉刷窗户。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化，与“声音很大”的句意不符。"}, {"text": "安抚", "is_correct": false, "explanation": "语义：“安抚”是使人或事物平静下来，与“声音很大”的句意矛盾。"}, {"text": "打击", "is_correct": true, "explanation": "正确答案。“冰雹打击着窗户，声音很大”表示冰雹不停地撞击窗户。"}], "explanations": {"粉刷": "搭配：“粉刷”要由人涂抹，冰雹不会粉刷窗户。", "装饰": "语义：“装饰”指美化，与“声音很大”的句意不符。", "安抚": "语义：“安抚”是使人或事物平静下来，与“声音很大”的句意矛盾。", "打击": "正确答案。“冰雹打击着窗户，声音很大”表示冰雹不停地撞击窗户。"}, "sentence_index": 6, "correct_answer": "打击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书打击了三天。", "explanation": "这里应该用〈读〉。打击不能用于书籍，读书要用“读”。"}, {"text": "他每天打击三顿饭。", "explanation": "这里应该用〈吃〉。打击不能用于饭食，吃饭要用“吃”。"}, {"text": "他用剪刀打击了我的头发。", "explanation": "这里应该用〈剪〉。打击不用于修整头发，剪头发要用“剪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天的台风打击了着沿海的渔业。", "corrected_sentence": "昨天的台风打击了沿海的渔业。", "error_description": "错误：“打击”后同时用了“了”和“着”，二者不能同时出现在同一动词后。正确：只用“了”，即“昨天的台风打击了沿海的渔业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场台风把沿海的渔业打击很惨。", "corrected_sentence": "这场台风把沿海的渔业打击得很惨。", "error_description": "错误：“把”字句中动词后的补语前漏了“得”。正确：应为“把……打击得很惨”。“得”用来引出补语，漏掉就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
