INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌声是人唱歌时发出的声音。", "primary_collocate": null, "pronunciation": "gē shēng", "ipa": "kɤ˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "山谷里到处都是欢乐的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声很大，邻居都听见了。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在房间里听见了楼下的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手的歌声很有力量。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笑声和歌声一起传到很远的地方。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的歌声温柔，孩子听着听着就睡了。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里放着音乐，也有爸爸的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，我常常想起你的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的歌声有点儿沙哑。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢她的歌声，买了她的音乐会票。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵歌声", "label": "量词"}], "register": "中性", "sense_fingerprint": "人唱歌时发出的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌声", "is_correct": true, "explanation": "指唱歌的声音，与“欢乐的”搭配，描写山谷里的欢乐气氛。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“欢乐的”修饰声音或气氛，不能修饰墙壁。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：哭声表示悲伤，与“欢乐的”的意思相反。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：叹息表示忧伤，与“欢乐的”的语气冲突。"}], "explanations": {"歌声": "指唱歌的声音，与“欢乐的”搭配，描写山谷里的欢乐气氛。", "墙壁": "搭配：“欢乐的”修饰声音或气氛，不能修饰墙壁。", "哭声": "语义：哭声表示悲伤，与“欢乐的”的意思相反。", "叹息": "语义：叹息表示忧伤，与“欢乐的”的语气冲突。"}, "sentence_index": 0, "correct_answer": "歌声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车的歌声很响，大家都被吓了一跳。", "explanation": "这里应该用〈汽笛声〉。歌声指人唱歌的声音，火车发出的声音要说汽笛声。"}, {"text": "他对着电话大声吵架，歌声传遍了整个走廊。", "explanation": "这里应该用〈吵嚷声〉。歌声只用于唱歌，吵架的声音不是歌声。"}, {"text": "妈妈在厨房里切菜，菜刀敲在案板上的歌声很响。", "explanation": "这里应该用〈敲击声〉。歌声只指唱歌的声音，菜刀敲击案板的声音不是唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌声", "is_correct": true, "explanation": "指唱歌的声音，与“车里放着音乐”的语境相合，是爸爸唱的歌。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：车里不会传出脚步声，与语境不合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是车里能听到或存在的东西，与语境不合。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：面容是外貌，不能像声音一样从车里传出来。"}], "explanations": {"歌声": "指唱歌的声音，与“车里放着音乐”的语境相合，是爸爸唱的歌。", "脚步": "语义：车里不会传出脚步声，与语境不合。", "年龄": "语义：年龄不是车里能听到或存在的东西，与语境不合。", "面容": "体貌：面容是外貌，不能像声音一样从车里传出来。"}, "sentence_index": 6, "correct_answer": "歌声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外面下大雨，窗户上全是雨点的歌声。", "explanation": "这里应该用〈雨声〉。歌声指人唱歌的声音，雨点打窗户的声音不是歌声。"}, {"text": "门铃的歌声响了，我赶快去开门。", "explanation": "这里应该用〈铃声〉。门铃发出的是铃声，不是人唱歌的声音。"}, {"text": "他生气地拍桌子，歌声把大家吓了一跳。", "explanation": "这里应该用〈响声〉。拍桌子的声音不是唱歌，不能说歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈歌声把孩子哄睡了。", "corrected_sentence": "妈妈的歌声把孩子哄睡了。", "error_description": "名词修饰“歌声”时要加“的”，不能说“妈妈歌声”。应改为“妈妈的歌声把孩子哄睡了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在操场上听见一个歌声。", "corrected_sentence": "我们在操场上听见一阵歌声。", "error_description": "“歌声”不用“个”计量，应改为“阵”：“我们在操场上听见一阵歌声。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
