INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "唱歌的声音。", "primary_collocate": null, "pronunciation": "gē shēng", "ipa": "kɤ˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "她的歌声很好听。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处传来一阵歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声让我很感动。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里传出了孩子们的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到她的歌声，大家都安静下来。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声像小鸟一样清脆。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，河边响起了歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢听妈妈的歌声。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌声从窗户里飘了出来。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一开口，美丽的歌声就响起来了。", "target_word": "歌声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵歌声", "label": "量词"}], "register": "中性", "sense_fingerprint": "唱歌时发出的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌声", "is_correct": true, "explanation": "指唱歌的声音，与“很好听”搭配，形容歌声动听。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“很好听”形容声音，不能用来形容脚步。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：哭声是悲伤时发出的声音，不能说好听。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“身材”要说好看或挺拔，不说好听。"}], "explanations": {"歌声": "指唱歌的声音，与“很好听”搭配，形容歌声动听。", "脚步": "搭配：“很好听”形容声音，不能用来形容脚步。", "哭声": "语义：哭声是悲伤时发出的声音，不能说好听。", "身材": "搭配：“身材”要说好看或挺拔，不说好听。"}, "sentence_index": 0, "correct_answer": "歌声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师讲课时的歌声很大，全班都听见了。", "explanation": "这里应该用〈声音〉。歌声专指唱歌的声音，老师讲课是说话，要说声音。"}, {"text": "婴儿的歌声很响，吵得整层楼的人都睡不着。", "explanation": "这里应该用〈哭声〉。歌声指唱歌的声音，婴儿啼哭不是唱歌，要说哭声。"}, {"text": "汽车的歌声太吵了，我关上了窗户。", "explanation": "这里应该用〈喇叭声〉。歌声指人唱歌的声音，汽车发出的声音不是歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌声", "is_correct": true, "explanation": "指唱歌的声音，与“响起了”搭配，符合河边传来声音的语境。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光不是声音，不能说“响起了”。"}, {"text": "花香", "is_correct": false, "explanation": "搭配：“响起”不搭配气味，气味应说飘散。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“脚印”是留下的痕迹，不会“响起”。"}], "explanations": {"歌声": "指唱歌的声音，与“响起了”搭配，符合河边传来声音的语境。", "灯光": "语义：灯光不是声音，不能说“响起了”。", "花香": "搭配：“响起”不搭配气味，气味应说飘散。", "脚印": "搭配：“脚印”是留下的痕迹，不会“响起”。"}, "sentence_index": 6, "correct_answer": "歌声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，一直咳嗽，屋里全是他的歌声。", "explanation": "这里应该用〈咳嗽声〉。歌声指唱歌的声音，咳嗽的声音不能说歌声。"}, {"text": "妈妈在厨房里大声喊我吃饭，我听见了她的歌声。", "explanation": "这里应该用〈喊声〉。歌声只用于唱歌，大声喊叫不算唱歌。"}, {"text": "他躺在沙发上打呼，歌声从屋里传出来。", "explanation": "这里应该用〈鼾声〉。打呼发出的声音不是唱歌，不能说歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里飘来一首歌声。", "corrected_sentence": "院子里飘来一阵歌声。", "error_description": "“歌声”不用“首”计量（“首”用于歌曲）。应改为“阵”：“院子里飘来一阵歌声。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们歌声在操场上回荡。", "corrected_sentence": "孩子们的歌声在操场上回荡。", "error_description": "名词修饰“歌声”时要加“的”，少了“的”不自然。应改为“孩子们的歌声在操场上回荡。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
