INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说某人做得好。", "primary_collocate": null, "pronunciation": "zàn", "ipa": "tsan˥˩", "syllable_count": 1, "sentences": [{"text": "同学们都赞他跑得快。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板赞她工作认真。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸赞我把房间收拾得很干净。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着全班同学赞了他。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家赞他唱得好，他很高兴。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老奶奶赞这个小姑娘手巧。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人赞他，他也继续努力。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友赞我做的蛋糕很好吃。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我赞你一句，这次做得真棒！", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练赞过他几次，他更努力了。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞了", "label": "体标"}, {"form": "赞过", "label": "体标"}, {"form": "点赞", "label": "复合"}, {"form": "贊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赞：对某人的行为或表现说好话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赞", "is_correct": true, "explanation": "赞（第四声 zàn）：对某人的做法说好话，是本义。"}, {"text": "咱", "is_correct": false, "explanation": "zán（第二声）与 zàn（第四声）声调不同，意思是咱们。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn（第三声）与 zàn（第四声）声调不同，意思是积存，如攒钱。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zàn 声母不同（zh 与 z），意思是站立。"}, {"text": "葬", "is_correct": false, "explanation": "zàng 与 zàn 韵母不同（ng 与 n），意思是埋葬。"}], "explanations": {"赞": "赞（第四声 zàn）：对某人的做法说好话，是本义。", "咱": "zán（第二声）与 zàn（第四声）声调不同，意思是咱们。", "攒": "zǎn（第三声）与 zàn（第四声）声调不同，意思是积存，如攒钱。", "站": "zhàn 与 zàn 声母不同（zh 与 z），意思是站立。", "葬": "zàng 与 zàn 韵母不同（ng 与 n），意思是埋葬。"}, "sentence_index": null, "correct_answer": "赞"}, "level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含讥讽义，与“跑得快”的称赞语境相反。"}, {"text": "赞", "is_correct": true, "explanation": "赞：说好话称赞，与“跑得快”的评价相符。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”是指责，与“跑得快”的肯定评价相反。"}, {"text": "吵", "is_correct": false, "explanation": "配价：“吵”不能带“他跑得快”这样的小句作宾语，句子不成立。"}], "explanations": {"嘲笑": "语义：“嘲笑”含讥讽义，与“跑得快”的称赞语境相反。", "赞": "赞：说好话称赞，与“跑得快”的评价相符。", "责怪": "语义：“责怪”是指责，与“跑得快”的肯定评价相反。", "吵": "配价：“吵”不能带“他跑得快”这样的小句作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "赞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司赞了学校的运动会。", "explanation": "这里应该用〈赞助〉。赞表示称赞或赞同，资金和物资支持活动要说赞助，不能说“赞”。"}, {"text": "这位老板赞了他一大笔钱，帮他开店。", "explanation": "这里应该用〈资助〉。赞表示说某人做得好，拿钱帮人要说“资助”，不能用“赞”。"}, {"text": "我每个月赞一点钱，准备买电脑。", "explanation": "这里应该用〈攒〉。赞是说别人做得好，积存钱要说“攒钱”，不能用“赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89989, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赞", "is_correct": true, "explanation": "赞（第四声 zàn）：对某人的做法说好话，是本义。"}, {"text": "散", "is_correct": false, "explanation": "sàn 与 zàn 声母不同（s 与 z），意思是散开。"}, {"text": "簪", "is_correct": false, "explanation": "zān（第一声）与 zàn（第四声）声调不同，意思是簪子。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 zàn 韵母不同（i 与 n），意思是再次。"}, {"text": "灿", "is_correct": false, "explanation": "càn 与 zàn 声母不同（c 送气，z 不送气），意思是灿烂。"}], "explanations": {"赞": "赞（第四声 zàn）：对某人的做法说好话，是本义。", "散": "sàn 与 zàn 声母不同（s 与 z），意思是散开。", "簪": "zān（第一声）与 zàn（第四声）声调不同，意思是簪子。", "再": "zài 与 zàn 韵母不同（i 与 n），意思是再次。", "灿": "càn 与 zàn 声母不同（c 送气，z 不送气），意思是灿烂。"}, "sentence_index": null, "correct_answer": "赞"}, "level_3": {"options": [{"text": "夸大", "is_correct": false, "explanation": "搭配：“夸大”多用于事情、成绩，不直接带“他”作宾语。"}, {"text": "赞", "is_correct": true, "explanation": "赞：说好话称赞，与“没人”后的语境相符。"}, {"text": "叹", "is_correct": false, "explanation": "配价：“叹”是不及物动词，一般不带“他”作宾语，“没人叹他”不成立。"}, {"text": "解释", "is_correct": false, "explanation": "搭配：“解释”的宾语多为事情或道理，不直接带“他”作宾语。"}], "explanations": {"夸大": "搭配：“夸大”多用于事情、成绩，不直接带“他”作宾语。", "赞": "赞：说好话称赞，与“没人”后的语境相符。", "叹": "配价：“叹”是不及物动词，一般不带“他”作宾语，“没人叹他”不成立。", "解释": "搭配：“解释”的宾语多为事情或道理，不直接带“他”作宾语。"}, "sentence_index": 6, "correct_answer": "赞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板赞了我的请假。", "explanation": "这里应该用〈批准〉。赞表示称赞或赞同，不能用来表示批准请假。"}, {"text": "他赞了我的错误，我很感动。", "explanation": "这里应该用〈原谅〉。赞是称赞、夸奖，不能用来表示原谅别人的错误。"}, {"text": "我下周一定赞还你的钱。", "explanation": "这里应该用〈还〉。赞表示称赞或赞同，不能用来表示归还钱款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都赞了过他唱得好。", "corrected_sentence": "大家都赞过他唱得好。", "error_description": "“赞了过”错误：“了”和“过”不能同时用在同一个动词后面，应说“赞过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天老师赞着他一次，他很高兴。", "corrected_sentence": "昨天老师赞了他一次，他很高兴。", "error_description": "体标误用：“赞”是已完成的一次动作，应用“了”，不能用表示持续的“着”，应说“赞了他一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
