INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "称赞；夸奖。", "primary_collocate": null, "pronunciation": "zàn", "ipa": "tsan˥˩", "syllable_count": 1, "sentences": [{"text": "老师赞他画得好。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都赞这道菜好吃。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都赞这个孩子懂事。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人尝了一口，忍不住赞了一句。", "target_word": "赞", "complexity_tier": "T3", "furigana": "kè rén cháng le yì kǒu, rěn bú zhù zàn le yí jù.", "sentence_source": "generated"}, {"text": "谁看了这幅画，都要赞几句。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈赞过我的字写得漂亮。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会做饭，朋友们都赞他。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都赞他心好。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们赞这里的风景像画一样美。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理当面赞了他的工作。", "target_word": "赞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞了", "label": "体标"}, {"form": "赞过", "label": "体标"}, {"form": "赞美", "label": "复合"}, {"form": "赞扬", "label": "复合"}, {"form": "贊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赞：称赞、夸奖，说别人或事物好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赞", "is_correct": true, "explanation": "赞（第四声 zàn）：称赞、夸奖，是本义。"}, {"text": "咱", "is_correct": false, "explanation": "zán（第二声）与 zàn（第四声）声调不同，意思是咱们。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn（第三声）与 zàn（第四声）声调不同，意思是积存，如攒钱。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zàn 声母不同（zh 与 z），意思是站立。"}, {"text": "葬", "is_correct": false, "explanation": "zàng 与 zàn 韵母不同（ng 与 n），意思是埋葬。"}], "explanations": {"赞": "赞（第四声 zàn）：称赞、夸奖，是本义。", "咱": "zán（第二声）与 zàn（第四声）声调不同，意思是咱们。", "攒": "zǎn（第三声）与 zàn（第四声）声调不同，意思是积存，如攒钱。", "站": "zhàn 与 zàn 声母不同（zh 与 z），意思是站立。", "葬": "zàng 与 zàn 韵母不同（ng 与 n），意思是埋葬。"}, "sentence_index": null, "correct_answer": "赞"}, "level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "语义：“批评”含否定义，与“画得好”的称赞语境相矛盾。"}, {"text": "赞", "is_correct": true, "explanation": "赞：称赞、夸奖，与“画得好”的评价相符。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”表示不满，与“画得好”的肯定评价相反。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”含斥责义，与“画得好”的称赞语境相反。"}], "explanations": {"批评": "语义：“批评”含否定义，与“画得好”的称赞语境相矛盾。", "赞": "赞：称赞、夸奖，与“画得好”的评价相符。", "嫌": "语义：“嫌”表示不满，与“画得好”的肯定评价相反。", "骂": "语义：“骂”含斥责义，与“画得好”的称赞语境相反。"}, "sentence_index": 0, "correct_answer": "赞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司赞了学校的运动会。", "explanation": "这里应该用〈赞助〉。赞表示称赞或赞同，资金和物资支持活动要说赞助，不能说“赞”。"}, {"text": "这位老板赞了他一大笔钱，帮他开店。", "explanation": "这里应该用〈资助〉。赞表示称赞，拿钱帮人要说“资助”，不能用“赞”。"}, {"text": "他把零花钱都赞起来，准备买自行车。", "explanation": "这里应该用〈攒〉。赞是称赞、夸奖，积存钱要说“攒钱”，不能用“赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赞", "is_correct": true, "explanation": "赞（第四声 zàn）：称赞、夸奖，是本义。"}, {"text": "散", "is_correct": false, "explanation": "sàn 与 zàn 声母不同（s 与 z），意思是散开。"}, {"text": "簪", "is_correct": false, "explanation": "zān（第一声）与 zàn（第四声）声调不同，意思是簪子。"}, {"text": "再", "is_correct": false, "explanation": "zài 与 zàn 韵母不同（i 与 n），意思是再次。"}, {"text": "灿", "is_correct": false, "explanation": "càn 与 zàn 声母不同（c 送气，z 不送气），意思是灿烂。"}], "explanations": {"赞": "赞（第四声 zàn）：称赞、夸奖，是本义。", "散": "sàn 与 zàn 声母不同（s 与 z），意思是散开。", "簪": "zān（第一声）与 zàn（第四声）声调不同，意思是簪子。", "再": "zài 与 zàn 韵母不同（i 与 n），意思是再次。", "灿": "càn 与 zàn 声母不同（c 送气，z 不送气），意思是灿烂。"}, "sentence_index": null, "correct_answer": "赞"}, "level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含讥讽义，与“很会做饭”的肯定相冲突。"}, {"text": "赞", "is_correct": true, "explanation": "赞：称赞、夸奖，与“很会做饭”的评价相符。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：“讽刺”是挖苦，与前文对他的肯定不合。"}, {"text": "夸大", "is_correct": false, "explanation": "搭配：“夸大”多用于事情、成绩，不直接带“他”作宾语。"}], "explanations": {"嘲笑": "语义：“嘲笑”含讥讽义，与“很会做饭”的肯定相冲突。", "赞": "赞：称赞、夸奖，与“很会做饭”的评价相符。", "讽刺": "语义：“讽刺”是挖苦，与前文对他的肯定不合。", "夸大": "搭配：“夸大”多用于事情、成绩，不直接带“他”作宾语。"}, "sentence_index": 6, "correct_answer": "赞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板赞了我的请假。", "explanation": "这里应该用〈批准〉。赞表示称赞或赞同，不能用来表示批准请假。"}, {"text": "他赞了我的错误，我很感动。", "explanation": "这里应该用〈原谅〉。赞是称赞、夸奖，不能用来表示原谅别人的错误。"}, {"text": "我下周一定赞还你的钱。", "explanation": "这里应该用〈还〉。赞表示称赞或赞同，不能用来表示归还钱款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们都了赞我的字写得好。", "corrected_sentence": "同学们都赞我的字写得好。", "error_description": "“了”位置错误：“了”不能放在动词“赞”之前，应说“都赞我的字写得好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们都他赞手艺好。", "corrected_sentence": "朋友们都赞他手艺好。", "error_description": "语序错误：“赞”后面带宾语“他”时，宾语应放在“赞”之后，应说“赞他”，不能说“他赞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
