INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时日是一段日子。", "primary_collocate": null, "pronunciation": "shí rì", "ipa": "ʂɨ˧˥ ʐɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这些时日，我天天都在加班。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前些时日，天气一直很冷。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些时日，我们住在小村子里。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外的时日里，他学会了做饭。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段时日，公司的事特别多。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的时日，他一直很辛苦。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈住院的时日，我每天都去看她。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北京的那些时日，我常想起家人。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近些时日，城里下了好几场大雪。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回想大学的时日，我觉得非常快乐。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指过去或最近的一段日子，常与这些、前些、近些连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时日", "is_correct": true, "explanation": "正确：“这些时日”指近来的一段日子，与“天天都在加班”相合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」是报酬，不指一段日子，「这些工资，我天天都在加班」句意不通。"}, {"text": "饭钱", "is_correct": false, "explanation": "语义：「饭钱」是钱，不指一段时间，与「这些」连用句意不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：「水果」是食物，不指一段日子，「这些水果，我天天都在加班」句意不通。"}], "explanations": {"时日": "正确：“这些时日”指近来的一段日子，与“天天都在加班”相合。", "工资": "语义：「工资」是报酬，不指一段日子，「这些工资，我天天都在加班」句意不通。", "饭钱": "语义：「饭钱」是钱，不指一段时间，与「这些」连用句意不通。", "水果": "语义：「水果」是食物，不指一段日子，「这些水果，我天天都在加班」句意不通。"}, "sentence_index": 0, "correct_answer": "时日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很快就走完了那段路，却用了好些时日。", "explanation": "这里应该用〈一会儿〉。时日指一段较长的日子，与“很快”的短暂时间矛盾。"}, {"text": "吃饭的时日，他总爱说话。", "explanation": "这里应该用〈时候〉。时日指较长的一段日子，不用来说吃饭这一顿的时间。"}, {"text": "我只等了两秒钟的时日，车就来了。", "explanation": "这里应该用〈工夫〉。时日指较长的一段日子，与“两秒钟”的极短时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时日", "is_correct": true, "explanation": "正确：“时日”指较长的一段时间，与“妈妈住院的”搭配，说住院的那段日子。"}, {"text": "学费", "is_correct": false, "explanation": "语义：「学费」是钱，不指一段时间，与「住院」的时段无关，句意不通。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是喜事，与“住院”不合。"}, {"text": "药费", "is_correct": false, "explanation": "语义：「药费」是钱，不指一段时间，「妈妈住院的药费，我每天都去看她」句意不通。"}], "explanations": {"时日": "正确：“时日”指较长的一段时间，与“妈妈住院的”搭配，说住院的那段日子。", "学费": "语义：「学费」是钱，不指一段时间，与「住院」的时段无关，句意不通。", "婚礼": "语义：“婚礼”是喜事，与“住院”不合。", "药费": "语义：「药费」是钱，不指一段时间，「妈妈住院的药费，我每天都去看她」句意不通。"}, "sentence_index": 6, "correct_answer": "时日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试时日，请大家保持安静。", "explanation": "这里应该用〈期间〉。时日指较长的一段时光，不用于考试这种短暂的时段。"}, {"text": "他只等了三分钟的时日，就走了。", "explanation": "这里应该用〈时长〉。时日指较长的一段日子，与“三分钟”的短暂时段矛盾。"}, {"text": "他只用了一眨眼的时日就做完了。", "explanation": "这里应该用〈工夫〉。时日指较长的一段时间，与“一眨眼”的极短时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在北京工作了一个时日。", "corrected_sentence": "我们在北京工作了一段时日。", "error_description": "量词错误：“时日”前应用“段”（一段时日），不用“个”（一个时日）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈住院的那个时日，我每天都去看她。", "corrected_sentence": "妈妈住院的那段时日，我每天都去看她。", "error_description": "量词错误：“时日”前用“段”（那段时日），不用“个”（那个时日）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
