INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间和日子;较长的一段时间。", "primary_collocate": null, "pronunciation": "shí rì", "ipa": "ʂɨ˧˥ ʐɨ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说，他的时日不多了。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事已经拖了不少时日。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假以时日，你一定能学好汉语。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修好这座老桥，要花很多时日。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家乡已有时日，很想念亲人。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太长，走完要费不少时日。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人自知时日不多，把话都说清楚了。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一些时日的练习，她唱得更好了。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事过去好些时日了，大家都忘了。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等上一些时日，伤口就会慢慢好起来。", "target_word": "时日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "较长的一段时间，常与不多、已久、假以连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时日", "is_correct": true, "explanation": "正确：“时日”指较长的一段时间，与“不多”搭配，说剩下的日子不多。"}, {"text": "病情", "is_correct": false, "explanation": "语义：“病情”说轻重好坏，不指可以计算多少的时间，与“不多”不合。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说高低，不说“不多”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说好坏、大小，不说“不多”，句子不通。"}], "explanations": {"时日": "正确：“时日”指较长的一段时间，与“不多”搭配，说剩下的日子不多。", "病情": "语义：“病情”说轻重好坏，不指可以计算多少的时间，与“不多”不合。", "体温": "搭配：“体温”说高低，不说“不多”。", "脾气": "搭配：“脾气”说好坏、大小，不说“不多”，句子不通。"}, "sentence_index": 0, "correct_answer": "时日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天花很多时日在路上。", "explanation": "这里应该用〈时间〉。时日指较长的一段时间，多用于书面，不用来说每天上下班路上的日常时长。"}, {"text": "会议时日，请大家保持安静。", "explanation": "这里应该用〈期间〉。时日指较长的一段时光，不用来说会议这种时长有限的时段。"}, {"text": "我出门的时日正下着雨。", "explanation": "这里应该用〈时候〉。时日指较长的一段时间，不用来指出门那一刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时日", "is_correct": true, "explanation": "正确：“时日”指较长的一段时间，与“不多”搭配，说老人剩下的日子不多。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」说高矮，不说「不多」，「老人自知身高不多」句意不通。"}, {"text": "血压", "is_correct": false, "explanation": "搭配：“血压”说高低，不说“不多”。"}, {"text": "岁数", "is_correct": false, "explanation": "语义：“岁数不多”指年纪轻，与“老人”相矛盾。"}], "explanations": {"时日": "正确：“时日”指较长的一段时间，与“不多”搭配，说老人剩下的日子不多。", "身高": "搭配：「身高」说高矮，不说「不多」，「老人自知身高不多」句意不通。", "血压": "搭配：“血压”说高低，不说“不多”。", "岁数": "语义：“岁数不多”指年纪轻，与“老人”相矛盾。"}, "sentence_index": 6, "correct_answer": "时日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快就把话说完了，却用了很多时日。", "explanation": "这里应该用〈一会儿〉。时日指较长的一段时间，与“很快”的短时间矛盾。"}, {"text": "这段视频的时日是三分钟。", "explanation": "这里应该用〈时长〉。时日指较长的时间，不用来精确说明短视频的长度。"}, {"text": "他只用了几分钟的时日就背完了课文。", "explanation": "这里应该用〈工夫〉。时日指较长的一段时间，与“几分钟”的短时段矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分开以后，又过了一个时日才见面。", "corrected_sentence": "我们分开以后，又过了一段时日才见面。", "error_description": "量词错误：“时日”前用“段”（一段时日），不用“个”（一个时日）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行，我们在路上耽误了很时日。", "corrected_sentence": "这次旅行，我们在路上耽误了很多时日。", "error_description": "修饰语错误：“时日”前应用“很多”，单用“很”不能修饰这个名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
