INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89995, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "僵尸是故事里死了又会动的可怕东西。", "primary_collocate": null, "pronunciation": "jiāng shī", "ipa": "tɕjɑŋ˥ ʂʐ̩˥", "syllable_count": 2, "sentences": [{"text": "这部电影里有很多僵尸。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我不敢看僵尸电影。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在万圣节穿成了僵尸。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的僵尸晚上会从墓地出来。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "僵尸的样子把弟弟吓哭了。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里的僵尸走得很慢。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起玩打僵尸的游戏吧。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一个很可怕的僵尸。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的僵尸怕太阳。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们过节时扮成僵尸去敲门。", "target_word": "僵尸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个僵尸", "label": "量词（个）"}, {"form": "一只僵尸", "label": "量词（只）"}, {"form": "僵尸片", "label": "复合词"}, {"form": "僵尸电影", "label": "复合词"}], "register": "中性", "sense_fingerprint": "僵尸：故事、电影、游戏里死后又会动的怪物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "讲师", "is_correct": false, "explanation": "jiǎngshī 的第一个音节 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲课的老师。"}, {"text": "僵尸", "is_correct": true, "explanation": "僵尸（jiāngshī）：故事、电影、游戏里死后又会动的怪物。"}, {"text": "姜汁", "is_correct": false, "explanation": "第二个音节 zhī 与 shī 声母不同（zh 与 sh），意思是姜的汁液。"}, {"text": "将士", "is_correct": false, "explanation": "jiàngshì 两个音节的声调都与 jiāngshī 不同，意思是将领和士兵。"}], "explanations": {"讲师": "jiǎngshī 的第一个音节 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲课的老师。", "僵尸": "僵尸（jiāngshī）：故事、电影、游戏里死后又会动的怪物。", "姜汁": "第二个音节 zhī 与 shī 声母不同（zh 与 sh），意思是姜的汁液。", "将士": "jiàngshì 两个音节的声调都与 jiāngshī 不同，意思是将领和士兵。"}, "sentence_index": null, "correct_answer": "僵尸"}, "level_3": {"options": [{"text": "可怕", "is_correct": false, "explanation": "词类：“可怕”是形容词，不能放在“有很多”后作宾语。"}, {"text": "好看", "is_correct": false, "explanation": "词类：“好看”是形容词，不能放在“有很多”后作宾语。"}, {"text": "吓人", "is_correct": false, "explanation": "词类：“吓人”是形容词，不能放在“有很多”后作宾语。"}, {"text": "僵尸", "is_correct": true, "explanation": "僵尸：故事或电影中死后又会动的怪物，与“电影里有很多”相合。"}], "explanations": {"可怕": "词类：“可怕”是形容词，不能放在“有很多”后作宾语。", "好看": "词类：“好看”是形容词，不能放在“有很多”后作宾语。", "吓人": "词类：“吓人”是形容词，不能放在“有很多”后作宾语。", "僵尸": "僵尸：故事或电影中死后又会动的怪物，与“电影里有很多”相合。"}, "sentence_index": 0, "correct_answer": "僵尸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在解剖室里检查了一具僵尸。", "explanation": "这里应该用〈尸体〉。僵尸指传说中死后会动的可怕怪物，解剖室里的普通尸体不能叫僵尸。"}, {"text": "奶奶身体硬朗，每天去广场跳舞，真是个僵尸。", "explanation": "这里应该用〈有活力〉。僵尸指死后会动的可怕怪物，不能用来形容身体硬朗、精力充沛的人。"}, {"text": "这个小男孩活泼爱笑，跑来跑去不停歇，真是个僵尸。", "explanation": "这里应该用〈活泼〉。僵尸指死后会动的可怕怪物，不能形容活泼好动的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“打鸡蛋”指打碎蛋液，不能作游戏的对象。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“打电话”是通话，不是游戏的内容，不能说打电话的游戏。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，不是可以“打”来玩的游戏对象。"}, {"text": "僵尸", "is_correct": true, "explanation": "僵尸：打僵尸是常见的游戏内容，与“打……的游戏”相合。"}], "explanations": {"鸡蛋": "搭配：“打鸡蛋”指打碎蛋液，不能作游戏的对象。", "电话": "搭配：“打电话”是通话，不是游戏的内容，不能说打电话的游戏。", "面粉": "语义：面粉是食材，不是可以“打”来玩的游戏对象。", "僵尸": "僵尸：打僵尸是常见的游戏内容，与“打……的游戏”相合。"}, "sentence_index": 6, "correct_answer": "僵尸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院的太平间里放着一具僵尸。", "explanation": "这里应该用〈尸体〉。僵尸是故事里会动的怪物，真实的死人要叫尸体。"}, {"text": "我奶奶七十岁了还天天跑步，真是个僵尸。", "explanation": "这里应该用〈老当益壮〉。僵尸指死后会动的可怕怪物，不能形容健康有活力的老人。"}, {"text": "这位歌手唱得很好，大家都叫他僵尸。", "explanation": "这里应该用〈歌王〉。僵尸是可怕的怪物，不能用来称赞唱歌好的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电影里出现了一条僵尸。", "corrected_sentence": "电影里出现了一个僵尸。", "error_description": "错误在量词：“僵尸”是人形怪物，应用量词“个”，“条”用于细长物体，不能说“一条僵尸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游戏里突然跑出来一台僵尸。", "corrected_sentence": "游戏里突然跑出来一个僵尸。", "error_description": "错误在量词：“台”用于机器，僵尸是人形怪物，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "反义：“底气不足”与“底气很足”相对，符合本句语境。"}, {"text": "热烈", "is_correct": false, "explanation": "无反义关系：“热烈”形容气氛或感情强烈，与“底气”不相对。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”形容清洁，与“底气”无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌或事物美观，与“底气”不相对。"}], "correct_answer": "不足", "explanations": {"不足": "反义：“底气不足”与“底气很足”相对，符合本句语境。", "热烈": "无反义关系：“热烈”形容气氛或感情强烈，与“底气”不相对。", "干净": "无反义关系：“干净”形容清洁，与“底气”无关。", "漂亮": "无反义关系：“漂亮”形容外貌或事物美观，与“底气”不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "反义：“灯光不足”与“灯光很足”相对，符合本句语境。"}, {"text": "轻松", "is_correct": false, "explanation": "无反义关系：“轻松”形容心情或事情不费力，与灯光无关。"}, {"text": "宽敞", "is_correct": false, "explanation": "无反义关系：“宽敞”形容空间大，与“灯光”的充足与否无关。"}, {"text": "厚实", "is_correct": false, "explanation": "无反义关系：“厚实”形容物体厚，与灯光不相对。"}], "correct_answer": "不足", "explanations": {"不足": "反义：“灯光不足”与“灯光很足”相对，符合本句语境。", "轻松": "无反义关系：“轻松”形容心情或事情不费力，与灯光无关。", "宽敞": "无反义关系：“宽敞”形容空间大，与“灯光”的充足与否无关。", "厚实": "无反义关系：“厚实”形容物体厚，与灯光不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "够了，不缺。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "这间屋子阳光很足，冬天也很暖和。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的劲头很足，跑了一上午也不累。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的电还很足，不用着急充电。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天底气很足，说话声音特别大。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤料很足，里面有肉也有菜。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货源很足，你想买多少都有。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开车还早，时间很足，慢慢走吧。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这次考试信心很足。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地里的水很足，今年不会缺水。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的灯光很足，看书不累眼睛。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "充足", "label": "复合"}, {"form": "足够", "label": "复合"}, {"form": "十足", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：数量或程度已经够了、不缺（劲头足、电足）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "足", "is_correct": true, "explanation": "足，zú（第二声），意思是够、不缺，即本题目标词。"}, {"text": "组", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是组。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。"}, {"text": "竹", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是竹子。"}, {"text": "俗", "is_correct": false, "explanation": "sú 与 zú 声母不同（s 与 z），意思是风俗。"}], "explanations": {"足": "足，zú（第二声），意思是够、不缺，即本题目标词。", "组": "zǔ（第三声）与 zú（第二声）声调不同，意思是组。", "祖": "zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。", "竹": "zhú 与 zú 声母不同（zh 与 z），意思是竹子。", "俗": "sú 与 zú 声母不同（s 与 z），意思是风俗。"}, "sentence_index": null, "correct_answer": "足"}, "level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "足，表示充足、不缺，与“阳光很足”搭配，也与后句“冬天也很暖和”相符。"}, {"text": "冷", "is_correct": false, "explanation": "语义：阳光是暖的，“阳光很冷”与后句“冬天也很暖和”矛盾。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说的是东西的厚度，不能用来形容阳光。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容人或动物不胖，不能用来形容阳光。"}], "explanations": {"足": "足，表示充足、不缺，与“阳光很足”搭配，也与后句“冬天也很暖和”相符。", "冷": "语义：阳光是暖的，“阳光很冷”与后句“冬天也很暖和”矛盾。", "厚": "搭配：“厚”说的是东西的厚度，不能用来形容阳光。", "瘦": "搭配：“瘦”形容人或动物不胖，不能用来形容阳光。"}, "sentence_index": 0, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里离车站很足，走过去要半个小时。", "explanation": "这里应该用〈远〉。足表示够、不缺，多用于资源、数量、信心等，不能用来说距离；说距离远要用“远”。"}, {"text": "他的个子很足，比我高一个头。", "explanation": "这里应该用〈高〉。足表示够、不缺，不能用来说个子的高矮；说个子高要用“高”。"}, {"text": "这次考试的成绩很足。", "explanation": "这里应该用〈好〉。足表示够、不缺，多用于资源、数量、信心等，不能用来评价成绩；评价成绩要说“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "足", "is_correct": true, "explanation": "足，zú（第二声），意思是够、不缺，即本题目标词。"}, {"text": "阻", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是阻挡。"}, {"text": "租", "is_correct": false, "explanation": "zū（第一声）与 zú（第二声）声调不同，意思是租用。"}, {"text": "烛", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是蜡烛。"}, {"text": "逐", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是追逐。"}], "explanations": {"足": "足，zú（第二声），意思是够、不缺，即本题目标词。", "阻": "zǔ（第三声）与 zú（第二声）声调不同，意思是阻挡。", "租": "zū（第一声）与 zú（第二声）声调不同，意思是租用。", "烛": "zhú 与 zú 声母不同（zh 与 z），意思是蜡烛。", "逐": "zhú 与 zú 声母不同（zh 与 z），意思是追逐。"}, "sentence_index": null, "correct_answer": "足"}, "level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "足，表示充足、够，与“时间很足”搭配，也与“离开车还早”相符。"}, {"text": "短", "is_correct": false, "explanation": "语义：“离开车还早”说明时间充裕，“时间很短”与前句矛盾。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”说的是物体含水，不能用来形容时间。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体的质地，时间不能说“硬”。"}], "explanations": {"足": "足，表示充足、够，与“时间很足”搭配，也与“离开车还早”相符。", "短": "语义：“离开车还早”说明时间充裕，“时间很短”与前句矛盾。", "湿": "搭配：“湿”说的是物体含水，不能用来形容时间。", "硬": "搭配：“硬”形容物体的质地，时间不能说“硬”。"}, "sentence_index": 6, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很足，我一个人搬不动。", "explanation": "这里应该用〈重〉。足表示够、不缺，不能用来说东西的轻重；说箱子重要用“重”。"}, {"text": "这位老人的年纪很足，已经八十岁了。", "explanation": "这里应该用〈大〉。足表示够、不缺，不能用来说年纪；说年纪大要用“大”。"}, {"text": "今天的温度很足，我们都热得出汗了。", "explanation": "这里应该用〈高〉。足表示够、不缺，不能用来说温度的高低；说温度高要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仓库的米没足，够吃一年。", "corrected_sentence": "这个仓库的米很足，够吃一年。", "error_description": "否定形式错误：“没足”应改为“很足”。“足”是形容词，不能用“没”否定；表示程度要说“很足”，表示不够才说“不足”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的光线足很，拍照很清楚。", "corrected_sentence": "今天的光线很足，拍照很清楚。", "error_description": "语序错误：程度副词“很”应放在“足”前面，说“很足”，不能说“足很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "反义：“营养不足”与“营养要足”相对，符合本句语境。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白、分明，与营养无关。"}, {"text": "结实", "is_correct": false, "explanation": "无反义关系：“结实”形容身体强壮或物体牢固，与“足”不相对。"}, {"text": "精致", "is_correct": false, "explanation": "无反义关系：“精致”形容做工细巧，与营养无关。"}], "correct_answer": "不足", "explanations": {"不足": "反义：“营养不足”与“营养要足”相对，符合本句语境。", "清楚": "无反义关系：“清楚”形容明白、分明，与营养无关。", "结实": "无反义关系：“结实”形容身体强壮或物体牢固，与“足”不相对。", "精致": "无反义关系：“精致”形容做工细巧，与营养无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "反义：“人手不足”与“人手很足”相对，符合本句语境。"}, {"text": "轻快", "is_correct": false, "explanation": "无反义关系：“轻快”形容动作或节奏轻松灵活，与人手无关。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”形容环境无声，与“人手”的多少无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列有序，与“足”不相对。"}], "correct_answer": "不足", "explanations": {"不足": "反义：“人手不足”与“人手很足”相对，符合本句语境。", "轻快": "无反义关系：“轻快”形容动作或节奏轻松灵活，与人手无关。", "安静": "无反义关系：“安静”形容环境无声，与“人手”的多少无关。", "整齐": "无反义关系：“整齐”形容排列有序，与“足”不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "充足；足够。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "今年雨水很足，庄稼长得特别好。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的预算还很足，可以多买点东西。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天的睡眠很足，所以白天很有精神。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的营养要足，才会长得高。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车油很足，可以开到下一个城市。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里的米很足，不用担心。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌时气要足，声音才好听。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑内存很足，玩游戏也不卡。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梨水分很足，咬一口全是汁。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人手很足，这点活儿一会儿就干完了。", "target_word": "足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "充足", "label": "复合"}, {"form": "足够", "label": "复合"}, {"form": "十足", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：量充足、足够（雨水足、睡得足）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "足", "is_correct": true, "explanation": "足，zú（第二声），意思是充足、足够，即本题目标词。"}, {"text": "组", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是组。"}, {"text": "竹", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是竹子。"}, {"text": "俗", "is_correct": false, "explanation": "sú 与 zú 声母不同（s 与 z），意思是风俗。"}, {"text": "租", "is_correct": false, "explanation": "zū（第一声）与 zú（第二声）声调不同，意思是租用。"}], "explanations": {"足": "足，zú（第二声），意思是充足、足够，即本题目标词。", "组": "zǔ（第三声）与 zú（第二声）声调不同，意思是组。", "竹": "zhú 与 zú 声母不同（zh 与 z），意思是竹子。", "俗": "sú 与 zú 声母不同（s 与 z），意思是风俗。", "租": "zū（第一声）与 zú（第二声）声调不同，意思是租用。"}, "sentence_index": null, "correct_answer": "足"}, "level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "足，表示充足、够，与“雨水很足”搭配，也与后句“庄稼长得特别好”相符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体的质地，不能用来形容雨水。"}, {"text": "尖", "is_correct": false, "explanation": "搭配：“尖”形容物体的末端，雨水不能说“尖”。"}, {"text": "贫乏", "is_correct": false, "explanation": "语义：“贫乏”指缺少，与后句“庄稼长得特别好”相矛盾。"}], "explanations": {"足": "足，表示充足、够，与“雨水很足”搭配，也与后句“庄稼长得特别好”相符。", "硬": "搭配：“硬”形容物体的质地，不能用来形容雨水。", "尖": "搭配：“尖”形容物体的末端，雨水不能说“尖”。", "贫乏": "语义：“贫乏”指缺少，与后句“庄稼长得特别好”相矛盾。"}, "sentence_index": 0, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的高度很足，爬了一上午才到顶。", "explanation": "这里应该用〈高〉。足表示充足、够，不能用来说高度；说高度要用“高”。"}, {"text": "这条裙子的颜色很足，非常好看。", "explanation": "这里应该用〈鲜艳〉。足表示充足、够，不能用来形容颜色好看；说颜色好看要用“鲜艳”。"}, {"text": "他的脸色很足，看起来很健康。", "explanation": "这里应该用〈红润〉。足表示充足、够，不能用来形容脸色；说脸色好要用“红润”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "足", "is_correct": true, "explanation": "足，zú（第二声），意思是充足、足够，即本题目标词。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。"}, {"text": "烛", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是蜡烛。"}, {"text": "逐", "is_correct": false, "explanation": "zhú 与 zú 声母不同（zh 与 z），意思是追逐。"}, {"text": "阻", "is_correct": false, "explanation": "zǔ（第三声）与 zú（第二声）声调不同，意思是阻挡。"}], "explanations": {"足": "足，zú（第二声），意思是充足、足够，即本题目标词。", "祖": "zǔ（第三声）与 zú（第二声）声调不同，意思是祖先。", "烛": "zhú 与 zú 声母不同（zh 与 z），意思是蜡烛。", "逐": "zhú 与 zú 声母不同（zh 与 z），意思是追逐。", "阻": "zǔ（第三声）与 zú（第二声）声调不同，意思是阻挡。"}, "sentence_index": null, "correct_answer": "足"}, "level_3": {"options": [{"text": "足", "is_correct": true, "explanation": "足，表示够、充足，与“气要足”搭配，也与“声音才好听”相符。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：“薄”形容物体的厚度，不能用来形容气息。"}, {"text": "乱", "is_correct": false, "explanation": "语义：气息乱则唱不稳，与“声音才好听”矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”形容温度，气息不说“冷”，此处说不通。"}], "explanations": {"足": "足，表示够、充足，与“气要足”搭配，也与“声音才好听”相符。", "薄": "搭配：“薄”形容物体的厚度，不能用来形容气息。", "乱": "语义：气息乱则唱不稳，与“声音才好听”矛盾。", "冷": "搭配：“冷”形容温度，气息不说“冷”，此处说不通。"}, "sentence_index": 6, "correct_answer": "足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很足，我们在家里看书。", "explanation": "这里应该用〈好〉。足表示充足、够，不能用来形容天气；说天气好要用“好”。"}, {"text": "这个孩子的个子很足，比同班同学高一截。", "explanation": "这里应该用〈高〉。足表示充足、够，不能用来形容个子；说个子高要用“高”。"}, {"text": "这间屋子的墙很足，很结实。", "explanation": "这里应该用〈厚〉。足表示充足、够，不能用来形容墙的厚薄；说墙厚要用“厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店的货物没足，顾客可以放心买。", "corrected_sentence": "这家商店的货物很足，顾客可以放心买。", "error_description": "否定形式错误：“没足”应改为“很足”。“足”是形容词，不能用“没”否定；表示程度要说“很足”，表示不够才说“不足”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
