INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比重是一部分在整体里占的多少。", "primary_collocate": null, "pronunciation": "bǐ zhòng", "ipa": "pi²¹⁴ ʈʂʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个月房租在我的收入里比重很大。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习在他的生活中占很大的比重。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蔬菜在我们的饮食中比重太小了。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司女员工的比重已经超过一半。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，口语考试的比重是百分之三十。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市老年人的比重越来越高。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资里，吃饭的比重最大。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生在游客中的比重不到十分之一。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想提高运动在一天里的比重。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西的比重今年又变大了。", "target_word": "比重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一部分在整体里占的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比重", "is_correct": true, "explanation": "比重：部分在整体中所占的份量，此处指房租在收入中所占的份额大"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”只用于人，不能说收入里的人数很大"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热程度，与收入中的占比无关"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的色彩，放进收入里说不通"}], "explanations": {"比重": "比重：部分在整体中所占的份量，此处指房租在收入中所占的份额大", "人数": "搭配：“人数”只用于人，不能说收入里的人数很大", "温度": "语义：温度指冷热程度，与收入中的占比无关", "颜色": "语义：颜色是事物的色彩，放进收入里说不通"}, "sentence_index": 0, "correct_answer": "比重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的师生比重是一比十五。", "explanation": "这里应该用〈比率〉。比重表示部分占整体的份额，不用于“一比十五”这样的两数相比"}, {"text": "工资涨了，房租也成比重地涨了。", "explanation": "这里应该用〈比例〉。“成比例”是固定说法，比重不能这样修饰增长"}, {"text": "这两个数的比重是二。", "explanation": "这里应该用〈比值〉。比重说的是部分在整体中的份额，不用于两个独立数字的比值"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比重", "is_correct": true, "explanation": "比重：此处指吃饭的开支在工资中所占的份额最大"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的冷热，与工资里的开支无关"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的身体高度，不能用来说吃饭的开支"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指人的容貌形象，不能用来说开支在工资里占多少"}], "explanations": {"比重": "比重：此处指吃饭的开支在工资中所占的份额最大", "体温": "语义：体温指身体的冷热，与工资里的开支无关", "身高": "语义：身高指人的身体高度，不能用来说吃饭的开支", "外貌": "语义：外貌指人的容貌形象，不能用来说开支在工资里占多少"}, "sentence_index": 6, "correct_answer": "比重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天那场足球比赛的比重是三比一。", "explanation": "这里应该用〈比分〉。比赛双方的得分叫比分，比重是部分在整体里占的多少"}, {"text": "这张地图的比重是一比一万。", "explanation": "这里应该用〈比例尺〉。地图上距离和实际距离的比叫比例尺，不能说比重"}, {"text": "妈妈按照二比一的比重把水和米放进锅里。", "explanation": "这里应该用〈比例〉。两样东西按几比几来配，用比例，不用比重"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年网上购物在日常消费中的比重增加了到四成。", "corrected_sentence": "今年网上购物在日常消费中的比重增加到了四成。", "error_description": "补语位置错误：“增加到”的“到”是补语，“了”要放在“到”之后，说“增加到了四成”，不能说“增加了到四成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近来，阅读在我生活里的比重明显增加得。", "corrected_sentence": "近来，阅读在我生活里的比重明显增加了。", "error_description": "错误形式：“明显增加得”；正确形式：“明显增加了”。“了”表示变化已经完成，“增加得”后面要接补语（如“增加得很快”），这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
